# -*- coding: utf-8 -*-
"""СТРАТЕГИЯ ПОИСКА В ЖИВОЙ ИГРЕ (2.10, §50): мост исполняет найденное симулятором сам.

Зачем (игрок 2.10, вариант 2). Проверка 1 показала: найденное поиском уходило модели
ТЕКСТОМ подсказки, и модель исполняла его по-своему — mil.1 к 8:09 вместо 3:00 (золото
ушло, шахт золота не было до 7-8 минут), к 5:00 девять бойцов против тридцати у той же
стратегии в симуляторе. Правило проекта: подсказка несёт состояние, процедура — ключом
моста (память coss3-hint-state-not-procedure). Здесь процедура целиком — ключом.

Как: тот же класс `sim/поиск_стратегии.Стратегия`, что играл в симуляторе (ярус 1 +
прокачки + волны + тактика), получает живое состояние и отдаёт команды словарями моста;
они идут модельным путём (`to_commands` и все вмешательства моста), так что в трассе
решение стратегии выглядит как ответ модели с `model = "стратегия"`. Дебют — мостовой
`debut.py` длиной `n` из стратегии: тот же код, что дебют яруса 1 в симуляторе.

Приказы волне, которая УЖЕ В ПОЛЕ (3.10, задание игрока). Блок менять не понадобилось:
`_ВПЕРЁД` и `_НА_КЛЕТКУ` уходят режимом `engage`, `_К_СВОИМ`, `_СТОЙ` и `_ОТРЯД` — отходом
`retreat` с целью-КЛЕТКОЙ. Что именно умеет игра и чем это отличается от симулятора —
в `_в_мостовые`; проверка — `selftest_wave_orders.py`.

Чего живая игра по-прежнему не умеет (пропускается и считается вслух): `_ЗАПАС` (найм
только сверх запаса еды) и точное «стоять на месте» — `_СТОЙ` исполняется приближением.

    python llm_policy.py --human ... --strategy sim/поиск/игрок_эко_s1.json --every 5
"""
import collections
import json
import math
import os
import sys

_ЗДЕСЬ = os.path.dirname(os.path.abspath(__file__))
if os.path.join(_ЗДЕСЬ, "sim") not in sys.path:
    sys.path.insert(0, os.path.join(_ЗДЕСЬ, "sim"))


ДЕРЕВО_ПЕРВЫМ = os.environ.get("COSS3_WOOD_FIRST", "0") == "1"   # §64: по умолчанию выкл — в симуляторе не лучше
ЗАПАС_ЕДЫ_ДЕРЕВУ = float(os.environ.get("COSS3_WOOD_FOOD", "1000"))
ПОТОЛОК_КОМАНД = 50   # сколько команд стратегии уходит в игру за такт
# 1.11, СЛОВО ИГРОКА «увеличь количество команд чтения до 50». Было 12, и это СРЕЗАЛО УДАР:
# живая партия дала 37 тактов подряд со строкой «команд в ответе 14, мост читает первые 12 —
# не ушли: STAGE, ATTACK». ATTACK дописывается в список последним, поэтому из всех команд
# терялась именно та, без которой армия не делает ничего — и ветка стены блока (97) не
# вызывалась ни раз. Мост говорил это вслух всю партию, в поле `rejected` трассы.
# ПОЧЕМУ 50 БЕЗОПАСНО: предела у блока НЕТ. Файл приказа несёт `orders = N` и поля `<i>_...`,
# а блок крутит `for haoi := 0 to haon-1` без зажима (block_hcmd.inc:1600-1673). Правка
# питонова, .inc не тронут.
# §147б: пол еды моста (`--food-floor`, llm_policy.ЕДА_ПОРОГ) — до 5:00 при бойцах < 20 мост берёт mil.1 только при еде
# ≥ пол + 750. Мост ставит сюда свой ключ при старте; двойник читает ту же переменную окружения, что `sim.ПОЛ_ЕДЫ_МОСТА`.
ПОЛ_ЕДЫ = float(os.environ.get("COSS3_FOOD_FLOOR", "800"))

# ЖИВОЙ МОСТ, а не симулятор. Ставится в `ЖиваяСтратегия.__init__` и больше нигде:
# от него зависит ровно одно — переводить ли внутренние приказы симулятора в мостовые
# (`_в_мостовые`). В симуляторе они исполняются своим кодом и точнее, поэтому там
# перевод не нужен и вреден.
ЖИВОЙ_МОСТ = False


def _клетка(st: dict, x: float, z: float) -> tuple:
    """Мировые координаты → клетка сетки 16x16, той же, что в `ocells` и `ecells`."""
    ш = float(st.get("map_w") or 256) / 16.0
    в = float(st.get("map_h") or 256) / 16.0
    return (max(0, min(15, int(float(x) // ш))), max(0, min(15, int(float(z) // в))))


def _список(st: dict, ключ: str, разбор):
    """Поле клеток или зданий СПИСКОМ, как бы оно ни пришло.

    Куплено живой игрой 3.10 (`smoke_net/1`): в ЧАСТОМ СНИМКЕ эти поля уже списки
    словарей, а в ЖИВОМ СОСТОЯНИИ — строки вида «x,y,...;...». Я написал обход по
    `st.get("obuild")` напрямую — и в партии на каждом внутреннем приказе получал
    `AttributeError: 'str' object has no attribute 'get'`: строка обходится по
    символам. Такт при этом не пропадал (ловится «стратегия упала, запасная»), то
    есть ошибка была ТИХОЙ. Разбор — тот же, которым пользуется весь проект
    (`coss3_map`), а не свой.
    """
    v = st.get(ключ)
    if isinstance(v, list):
        return [c for c in v if isinstance(c, dict)]
    try:
        import coss3_map
        return разбор(st)
    except Exception:
        return []


def _группы(st: dict) -> list:
    """Наши группы с номерами из состояния — тем же разбором, что и весь проект."""
    import coss3_map
    v = st.get("groups")
    if isinstance(v, list):
        return [г for г in v if isinstance(г, dict)]
    try:
        return coss3_map.наши_группы(st)
    except Exception:
        return []


def _его_с_лагерем(его: dict, цель, st: dict, п: dict) -> tuple:
    """§170ж (30.10, партия с Польшей): ПРОГНОЗ НЕ МЕНЬШЕ ЛАГЕРЯ. Анализ видел «ЛАГЕРЬ его 221 (пик 221) в (8,9), 4 кл. от ратуши»,
    а прогнозы удара по лагерю и ручейка считали бой с 13–82 (состав по клетке/окну, лагерь стоял шире) и давали R 3–7: 27, потом
    105 и 109 человек ушли в 221 пику и легли (потери 193 против 97). Ключ `прогноз_по_лагерю` 1: если в 2 клетках от цели есть лагерь
    анализа крупнее состава из клеток, его состав берётся по лагерю (пик/стрелков из находки, остаток — пики). 0 — как было.
    Возвращает (состав, пометка)."""
    try:
        if not int(float((п or {}).get("прогноз_по_лагерю", 0) or 0)) or цель is None:
            return его, ""
        import анализ_врага as _АВ
        находки = (_АВ.текущий(st) or {}).get("находки") or []
    except Exception:
        return его, ""
    лаг = []
    for н in находки:
        try:
            if н.get("вид") == "лагерь" and max(abs(int(н["центр"][0]) - int(цель[0])), abs(int(н["центр"][1]) - int(цель[1]))) <= 2:
                лаг.append(н)
        except (TypeError, ValueError, KeyError):
            continue
    if not лаг:
        return его, ""
    л = max(лаг, key=lambda н: float(н.get("n") or 0))
    n = float(л.get("n") or 0)
    было = sum(float(v or 0) for v in (его or {}).values())
    if n <= было:
        return его, ""
    пк, ст = float(л.get("пик") or 0), float(л.get("стрелков") or 0)
    кн = max(0.0, n - пк - ст)
    if пк + ст + кн < 1:
        пк = n
    новый = {"infantry17": пк, "musk17": ст, "dragoon17": кн}
    return новый, f" (его по лагерю {n:.0f}, в клетке было {было:.0f})"


def _свободный_номер(st: dict) -> int:
    """Номер группы, которого в состоянии нет. 0 — все шестнадцать заняты.

    Предел шестнадцать стоит в блоке состояния (`groups`), и больше номеров он
    просто не прочитает.
    """
    занято = {int(г.get("id") or 0) for г in _группы(st) if int(г.get("n") or 0) > 0}
    for i in range(1, 17):
        if i not in занято:
            return i
    return 0


def _дом(st: dict) -> tuple:
    """Клетка нашей ратуши. Берётся из `obuild` — там наши здания с координатами."""
    import coss3_map
    for b in _список(st, "obuild", coss3_map.наши_здания):
        if str(b.get("тип") or "") == "center":
            return _клетка(st, b.get("x") or 0, b.get("z") or 0)
    return (8, 8)


def _куда_смотреть(st: dict):
    """Клетка ЕГО БЛИЖАЙШЕЙ КУЧИ от нашего дома, либо None (5.10, §98).

    Зачем вообще. До 5.10 направление строя в приказах моста было константой
    0,1: каждый наш строй смотрел к +Z карты независимо ни от чего, и в проверке
    5 (наша база (12,13), его (1,2)) это было в сторону НАШЕЙ базы — игрок
    подтвердил глазами, что стояли спиной к врагу. Теперь блок считает
    направление сам, от центра посылаемых к точке цели, а поле `face` его
    перебивает.

    Где перебивать СТОИТ: у ОТХОДА. Блок для отхода ищет ближайшего вражеского
    БОЙЦА своим обходом объектов, а стратегия знает `ecells` — кучи с числами, —
    и может назвать ту, что действительно опасна. Своего счёта тут не держим:
    клетки берутся у `coss3_map`, тем же разбором, которым их читает всё
    остальное."""
    import coss3_map
    его = [к for к in _список(st, "ecells", coss3_map.его_клетки)
           if int(к.get("n") or 0) > 0]
    if not его:
        return None          # его армии в поле нет вовсе — законный случай
    дом = _дом(st)
    к = min(его, key=lambda к: max(abs(int(к["x"]) - дом[0]),
                                   abs(int(к["y"]) - дом[1])))
    return (int(к["x"]), int(к["y"]))


def _в_мостовые(c: dict, cmd: str, st: dict):
    """Внутренний приказ симулятора → мостовой, или None, если мост так не умеет.

    ЧТО УМЕЕТ ИГРА, проверено по блоку (`block_hcmd.inc`, ветка файла приказа). Отбор
    бойцов и назначение блок читает ПОРОЗНЬ: `retreat` и `engage` берут всех дальше одной клетки
    от ратуши, чем бы они ни были заняты (волну в поле, раненых — всех), а цель `cell`
    ведёт их в центр названной клетки. Отсюда:

    * `_К_СВОИМ` -> RETREAT в клетку ближайшей своей кучи (ходом БЕЗ боя). Если ближайшая
      своя — дом, это обычный RETREAT домой, как и в симуляторе;
    * `_СТОЙ`    -> RETREAT в клетку, где волна СТОИТ СЕЙЧАС. Это ПРИБЛИЖЕНИЕ: бойцы
      дойдут до центра своей клетки и встанут, а не замрут на месте. Точного «стоять»
      у моста нет — для него нужен блок (`_squad_holdmode` либо обнуление приказа);
    * `_ВПЕРЁД` -> ENGAGE на ту же цель: отменяет отход и разворачивает в бой;
    * `_ОТРЯД`  -> RETREAT долей бойцов в клетку `aim` (отделение части волны).

    ЧЕМ ЭТО ОТЛИЧАЕТСЯ ОТ СИМУЛЯТОРА, и это надо знать до разбора: симулятор водит
    ГРУППАМИ и выбирает, какая именно идёт (`_К_СВОИМ` берёт самую дальнюю от дома,
    `_ОТРЯД` — самую большую). Мост групп не различает: он берёт ПЕРВЫХ `count` бойцов
    дальше одной клетки от ратуши в порядке движка. Поэтому при одной куче в поле поведение
    совпадает, а при двух и больше приказ может достаться не той.
    """
    import coss3_map
    кучи = [k for k in _список(st, "ocells", coss3_map.наши_клетки)
            if int(k.get("n") or 0) > 0]
    дом = _дом(st)

    def _поле(x, y):
        # МЕРКА БЛОКА (мак 5.10, по замечанию Windows к §99): дальше ДОМАШНЕГО РАДИУСА от
        # клетки ратуши по Чебышёву — `coss3_map.в_поле`, одно число с блоком. Без `my_cx`
        # в состоянии мерки нет — тогда как было: «не клетка ратуши».
        if coss3_map.дом_клетка(st) is not None:
            return coss3_map.в_поле(st, int(x), int(y))
        return (int(x), int(y)) != дом
    поле = [k for k in кучи if _поле(k.get("x") or 0, k.get("y") or 0)]
    # «В ПОЛЕ» СПРАШИВАЕМ У БЛОКА, а не судим сами. С 5.10 (§99) блок мерит поле
    # КЛЕТКАМИ той же сетки 16x16: боец в поле, если его клетка дальше одной
    # от клетки ратуши по Чебышёву (`block_hcmd.inc` и `block_hstate.inc`, одно
    # число на двоих, сторож — `selftest_field_cells`). До этого порогом было 60
    # единиц, и стоявшая в трёх клетках куча 74 была недоступна ни одному
    # приказу.
    #
    # СЧИТАЕМ ВСЁ РАВНО ПО `mil_away`, а не по кучам: поле отдаёт тот же
    # блок, что и отбирает бойцов, и два своих суждения расходятся молча. Без
    # этой проверки приказ уехал бы и получил отказ «в поле никого нет» —
    # отказ честный, но приказ бессмысленный, а §51 требует гасить такие до
    # отправки. Список `поле` ниже — для ВЫБОРА клетки назначения — с 5.10 той
    # же меркой, что у блока (`_поле`): раньше он был на клетку шире и при двух
    # кучах мог указать на ту, которую блок двигать не станет (замечание Windows).
    вдали = int(float(st.get("mil_away") or 0))
    if вдали <= 0:
        return None
    if cmd == "_ВПЕРЁД":
        цель = str(c.get("target") or "army")
        # Адресно, если группы есть: разворачиваем в бой САМУЮ ДАЛЬНЮЮ свою группу,
        # а не всех дальних сразу — иначе приказ задел бы и подмогу, которая ещё идёт.
        _гр = [г for г in _группы(st) if int(г.get("n") or 0) > 0
               and _поле(г["cx"], г["cy"])]
        if _гр and цель != "cell":
            г = max(_гр, key=lambda г: (int(г["cx"]) - дом[0]) ** 2 + (int(г["cy"]) - дом[1]) ** 2)
            return {"cmd": "ENGAGE", "count": 0, "target": цель, "group": int(г["id"])}
        из = {"cmd": "ENGAGE", "count": 200, "target": цель}
        aim = c.get("aim")
        if цель == "cell" and isinstance(aim, (list, tuple)) and len(aim) >= 2:
            из.update(cx=int(aim[0]), cy=int(aim[1]))
        elif цель == "cell":
            return None
        return из
    if cmd == "_НА_КЛЕТКУ":
        # Все, кто в поле, — на клетку, В БОЙ (решение сети «на_меньшую»: идти на меньшую
        # его кучу). Та же дорога, что у `_ВПЕРЁД`, только цель названа клеткой.
        aim = c.get("aim")
        if not поле or not isinstance(aim, (list, tuple)) or len(aim) < 2:
            return None
        return {"cmd": "ENGAGE", "count": 200, "target": "cell",
                "cx": int(aim[0]), "cy": int(aim[1])}
    if cmd == "_К_СВОИМ":
        # ЕСЛИ У НАС ЕСТЬ НОМЕРНЫЕ ГРУППЫ — идём к своим АДРЕСНО и сливаемся
        # (цель `group`, 4.10). Это точнее клетки: группа-получатель может
        # сдвинуться, и тогда клетка приведёт в опустевшее место — именно это
        # случилось в живой партии 4.10 с первым приказом слияния. Повторять
        # приказ, пока клетки не совпадут, умеет `ЖиваяСтратегия.ответ`.
        группы = [г for г in _группы(st) if int(г.get("n") or 0) > 0]
        if len(группы) >= 2:
            гол = max(группы, key=lambda г: (int(г["cx"]) - дом[0]) ** 2
                      + (int(г["cy"]) - дом[1]) ** 2)
            прочие = [г for г in группы if г is not гол]
            цель = min(прочие, key=lambda г: (int(г["cx"]) - int(гол["cx"])) ** 2
                       + (int(г["cy"]) - int(гол["cy"])) ** 2)
            if (int(гол["cx"]), int(гол["cy"])) != (int(цель["cx"]), int(цель["cy"])):
                return {"cmd": "RETREAT", "count": 0, "target": "group",
                        "group": int(гол["id"]), "gid": int(цель["id"])}
            return None            # уже в одной клетке: слиёт блок состояния
        if not поле:
            return None            # волны в поле нет — приказ бессмысленный, §51
        голова = max(поле, key=lambda k: (int(k["x"]) - дом[0]) ** 2 + (int(k["y"]) - дом[1]) ** 2)
        свои = [k for k in кучи if k is not голова]
        if not свои:
            return None
        к = min(свои, key=lambda k: (int(k["x"]) - int(голова["x"])) ** 2
                + (int(k["y"]) - int(голова["y"])) ** 2)
        цx, цy = int(к["x"]), int(к["y"])
        счёт = max(1, min(вдали, int(голова.get("n") or 1)))
        if (цx, цy) == дом:
            return {"cmd": "RETREAT", "count": счёт}      # ближайшая своя — дом
        return {"cmd": "RETREAT", "count": счёт, "target": "cell", "cx": цx, "cy": цy}
    if cmd == "_СТОЙ":
        # Адресно, если группы есть: стоять велят ТОЙ группе, что в поле, а не
        # всем дальше одной клетки от ратуши. Приказ ей самой — в её же клетку.
        группы = [г for г in _группы(st) if int(г.get("n") or 0) > 0]
        вполе = [г for г in группы if _поле(г["cx"], г["cy"])]
        if вполе:
            г = max(вполе, key=lambda г: int(г.get("n") or 0))
            return {"cmd": "RETREAT", "count": 0, "target": "cell",
                    "cx": int(г["cx"]), "cy": int(г["cy"]), "group": int(г["id"])}
        if not поле:
            return None
        большая = max(поле, key=lambda k: int(k.get("n") or 0))
        return {"cmd": "RETREAT", "count": max(1, min(вдали, int(большая.get("n") or 1))),
                "target": "cell", "cx": int(большая["x"]), "cy": int(большая["y"])}
    if cmd == "_ОТРЯД":
        aim = c.get("aim")
        if not поле or not isinstance(aim, (list, tuple)) or len(aim) < 2:
            return None
        большая = max(поле, key=lambda k: int(k.get("n") or 0))
        доля = min(max(float(c.get("share") or 0.25), 0.05), 0.95)
        счёт = max(1, min(вдали, int(round(int(большая.get("n") or 1) * доля))))
        return {"cmd": "RETREAT", "count": счёт, "target": "cell",
                "cx": int(aim[0]), "cy": int(aim[1])}
    return None


def _лицом_к_врагу(приказ, st: dict):
    """Доклеить `face` отходу — ОДНИМ местом на все его ветки (5.10, §98).

    Ветвей отхода в `_в_мостовые` пять (`_К_СВОИМ` двумя путями, `_СТОЙ` двумя,
    `_ОТРЯД`), и дописывать поле в каждую значило бы повторить ошибку, которая
    в этом проекте случалась трижды: поле добавляют в одну ветку из нескольких,
    и в остальных оно молча пропадает. Поэтому доклейка стоит ЗА `_в_мостовые`,
    на единственном пути всех его ответов.

    Удару `face` не нужен: блок и так ставит строй лицом к точке цели, а цель
    удара — та самая его куча."""
    if not приказ or приказ.get("cmd") != "RETREAT" or приказ.get("face"):
        return приказ
    кл = _куда_смотреть(st)
    if кл:
        приказ["face"] = [кл[0], кл[1]]
    return приказ


# --- КОНТРАКТ ВОЛНЫ (5.10, задание игрока) -----------------------------------
#
# ЧЕМ КУПЛЕН. Живая партия 4.10 против невозможного ИИ, 15:08. Хозяйство вышло
# хорошим — 79 крестьян, 135 пехоты, три шахты золота, ноль потерянных
# крестьян, — а бой не состоялся: из 95 боевых приказов на базу врага ушёл
# РОВНО ОДИН (7:08, 28 бойцов против 6), остальные 94 были «подмога к своей
# волне». Волна и была всей армией, и все шестнадцать номеров групп выгорели на
# ней же: группа 1 на 43 бойца, группа 4 на 49, группа 5 на 44 — одни и те же
# люди. К 11:33 номера кончились, второй удар (T2 = 11:23) не ушёл вовсе, а 128
# бойцов простояли партию в клетке (5,2) рядом с ратушей.
#
# ПОЧЕМУ ИМЕННО КОНТРАКТ, А НЕ ЕЩЁ ОДНО ПРАВИЛО ШТУРМА. Оба дефекта — следствие
# того, что у волны не было ни личности, ни состояния: номер назначался каждый
# такт заново, а приказ «к волне» не отличался от приказа «стоять». Поэтому
# здесь не порог, а три вещи: ОДНА волна = ОДНА устойчивая группа, одна
# активная миссия на волну, и явный переход «собрано -> бить», когда ждать
# больше нечего. Отказ всегда НАЗВАН: молчание моста неотличимо от «приказ не
# дошёл», и разбор 4.10 стоил ровно этого — 94 повтора вместо одной записи.
СОСТОЯНИЯ_ВОЛНЫ = ("СБОР", "ГОТОВА", "В_БОЮ", "КОНЧЕНА")

# Причины бездействия. Их список закрыт нарочно: «нет приказа» без причины —
# это то самое молчание, которое пришлось разбирать руками по 95 приказам.
ПРИЧИНЫ = ("НЕТ_ЦЕЛИ", "МАЛО_СИЛ", "БОЙ_ИДЁТ", "ЦЕЛЬ_НЕДОСТИЖИМА",
           "ЖДЁМ_РЕШЕНИЯ")

ПОТОЛОК_ГРУПП = 16    # предел блока состояния (`groups`), больше он не прочитает

# СКОЛЬКО ТАКТОВ БЕЗ РОСТА СЧИТАТЬ «СОБРАНО». Такт стратегии — пять игровых
# секунд, значит три такта это пятнадцать секунд без единого новобранца. Число
# взято из партии 4.10: волна встала на 59 бойцах на 11:02 и не прибавила ни
# одного до 14:58 — четыре минуты ожидания, которое ничего не меняло. Меньше
# трёх брать нельзя: подмога идёт по карте, и один такт её пути — не «собрано».
ТАКТОВ_БЕЗ_РОСТА = 3

# СКОЛЬКО ТАКТОВ ЖДАТЬ, ПОКА ВОЛНА РОДИТСЯ В ИГРЕ. Приказ уходит файлом, блок
# читает его следующим тиком, бойцы собираются и идут — группа появляется не
# мгновенно. Шесть тактов это тридцать игровых секунд: столько волна имеет право
# не существовать, прежде чем считать приказ неисполненным.
ТАКТОВ_НА_РОЖДЕНИЕ = 6


class Волна:
    """Одна волна: личность (id), номер группы в игре и состояние.

    `номер` — это номер группы, которым волне приказывают. Он берётся ОДИН раз,
    при рождении, и держится до конца жизни волны: именно пересоздание номера
    каждый такт выжгло 16 из 16 в партии 4.10.
    """

    __slots__ = ("id", "номер", "рождена", "сбор", "цель", "состояние", "размер",
                 "ударов", "причина", "не_растёт", "подтверждена", "тактов",
                 "цель_клетка")

    def __init__(self, id: str, номер: int, рождена: float, сбор: tuple, цель: str = ""):
        self.id = id
        self.номер = int(номер)
        self.рождена = float(рождена)
        self.сбор = tuple(сбор) if сбор else (0, 0)
        self.цель = цель or ""
        self.состояние = "СБОР"
        self.размер = 0
        self.ударов = 0
        self.причина = ""
        # Сколько тактов подряд волна НЕ РАСТЁТ. Это и есть признак «собрано»,
        # когда подмога законна и потому не отвергается: в партии 4.10 волна
        # стояла на 59 бойцах с 11:02 до 14:58, а приказы подмоги уезжали честно
        # и каждый такт — ждать было уже нечего, но сказать это было нечем.
        self.не_растёт = 0
        # ПОДТВЕРЖДЕНА — значит группа с этим номером ПОЯВИЛАСЬ В ИГРЕ. Пока
        # приказ не исполнен, группы нет, и считать волну погибшей нельзя:
        # живая партия 5.10 с первым контрактом делала ровно это и заводила
        # новую волну каждый такт — W41, W42, ... W53 к 8:26, при том что из
        # дома не ушёл ни один боец (`mil_away` = 0 всю партию).
        self.подтверждена = False
        self.тактов = 0
        # КУДА ПОСЛАНА. Нужна, чтобы отличить «идёт» от «пришла и стоит»: живая
        # партия 5.10 показала, что без этого волна остаётся в В_БОЮ навсегда —
        # W1 ушла в 1:29, дошла до клетки (7,6), и с 1:29 до 8:07 стояла там и
        # росла, пока его кучи стояли в (3,2), (2,3) и (4,4).
        self.цель_клетка = None

    def __repr__(self):
        return (f"Волна({self.id}, группа {self.номер}, {self.состояние}, "
                f"{self.размер} бойцов, клетка {self.сбор})")


class РеестрВолн:
    """Реестр волн: кто живой, кто собрался, кто в бою. Меры считает сам.

    Мера, которой не было и из-за которой простой 4.10 пришлось вскрывать
    руками: `простой_готовой` — сколько ТАКТОВ боеспособная волна стояла без
    приказа. Число приказов её не заменяет: 94 повтора и 94 такта простоя — это
    одно и то же событие, но лечится только второе.
    """

    def __init__(self):
        self.волны: list = []
        self.счёт = 0
        self.мера = collections.Counter()
        self.простой_готовой = 0      # ВСЕГО тактов простоя готовой волны за эпизод
        self.подряд = 0               # сколько тактов подряд простой идёт сейчас
        self.первый_удар = None       # игровое время первого ATTACK по врагу
        self.записи: list = []        # строки такта для `why`

    # --- жизнь волн ---------------------------------------------------------
    def живые(self) -> list:
        return [в for в in self.волны if в.состояние != "КОНЧЕНА"]

    def активная(self):
        """Волна, которой сейчас принадлежит миссия. Одна на весь реестр."""
        ж = self.живые()
        return ж[0] if ж else None

    def обновить(self, st: dict) -> None:
        """Сверить реестр с игрой: кто ещё есть, где стоит, кого уже нет."""
        места = {int(г.get("id") or 0): г for г in _группы(st)
                 if int(г.get("n") or 0) > 0}
        for в in self.живые():
            в.тактов += 1
            г = места.get(в.номер)
            if г is None:
                if в.подтверждена:
                    # Группа БЫЛА и исчезла: бойцы погибли или влились в чужую.
                    в.состояние = "КОНЧЕНА"
                    self.мера["волн кончилось"] += 1
                    self.записи.append(f"WAVE_DONE {в.id} группа {в.номер}")
                elif в.тактов > ТАКТОВ_НА_РОЖДЕНИЕ:
                    # Приказ так и не исполнился: волна не родилась. Закрываем,
                    # но ВСЛУХ и один раз, а не заводим новую каждый такт.
                    в.состояние = "КОНЧЕНА"
                    self.мера["волна не родилась"] += 1
                    self.записи.append(
                        f"WAVE_DONE {в.id} группа {в.номер} (не родилась за "
                        f"{в.тактов} тактов)")
                continue
            в.подтверждена = True
            было = int(в.размер or 0)
            в.размер = int(г.get("n") or 0)
            в.сбор = (int(г.get("cx") or 0), int(г.get("cy") or 0))
            в.не_растёт = 0 if в.размер > было else в.не_растёт + 1

    def родить(self, st: dict, цель: str):
        """Новая волна — ТОЛЬКО если живой нет. Иначе бойцы входят в живую."""
        if self.активная() is not None:
            return None
        номер = _свободный_номер(st)
        if not номер:
            self.мера["номера кончились"] += 1
            return None
        self.счёт += 1
        в = Волна(f"W{self.счёт}", номер, float(st.get("gametime") or 0),
                  _дом(st), цель)
        self.волны.append(в)
        self.мера["волн заведено"] += 1
        self.записи.append(f"WAVE_CREATED {в.id} группа {номер} "
                           f"t={_мин(в.рождена)} цель={цель or '-'}")
        return в


def _мин(с) -> str:
    """Игровые секунды как время партии: разбор 4.10 читался по минутам."""
    try:
        с = int(float(с or 0))
    except (TypeError, ValueError):
        return "?"
    return f"{с // 60}:{с % 60:02d}"


РАДИУС_ДОМА = 2       # §170г: клеток от ратуши, что считается домом (как РАДИУС_БАЗЫ глаз `угрозы`)


def _до_отрезка(p, a, b) -> float:
    """Расстояние от точки p до отрезка a–b в клетках (§170у: лагерь в коридоре дом→цель)."""
    ax, ay = float(a[0]), float(a[1]); bx, by = float(b[0]), float(b[1]); px, py = float(p[0]), float(p[1])
    dx, dy = bx - ax, by - ay
    L2 = dx * dx + dy * dy
    t = 0.0 if L2 <= 0 else max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / L2))
    qx, qy = ax + t * dx, ay + t * dy
    return max(abs(px - qx), abs(py - qy))


def домашних_бойцов(st: dict) -> int:
    """Сколько бойцов ДОМА, то есть кого ещё можно послать подмогой.

    Без этого числа приказ «к волне» неотличим от приказа «стоять»: в партии
    4.10 вся армия уже стояла в клетке волны, и 94 приказа подмоги не двинули
    никого. `mil_away` даёт ушедших, остальное — дом.
    """
    ч = lambda к: float(st.get(к) or 0)
    всего = ч("mil_inf") + ч("mil_shooters") + ч("mil_cav")
    # §170г (22.10, Д11): ДОМ — ратуша и две клетки вокруг, не одна. Блок меряет `mil_away` по cHmHome = 1, а кулак
    # встречи §170б стоит на шаг от ратуши и сам шагает в соседнюю клетку навстречу вошедшему (Д11: 122 в (4,2) при ратуше
    # (2,2) — «дома 21», и `выход_к` считал силу по 19–48 из 200). Считаем по клеткам, где они есть; иначе как прежде.
    дома = всего - ч("mil_away")
    try:
        import coss3_map as _КМ
        if ч("mil_away") > 0:
            д = _дом(st)
            # блок считает «ушедшими» всех дальше одной клетки; клетки на расстоянии ровно РАДИУС_ДОМА возвращаем домой
            # (сложением, а не пересчётом по клеткам: в синтетике селфтестов `ocells` неполные)
            дома += sum(int(c.get("n") or 0) for c in _список(st, "ocells", _КМ.наши_клетки)
                        if 1 < max(abs(int(c["x"]) - д[0]), abs(int(c["y"]) - д[1])) <= РАДИУС_ДОМА)
    except Exception:
        pass
    return max(0, min(int(всего), int(дома)))


def нормализовать_подмогу(c: dict, волна, st: dict):
    """Приказ подмоги -> (приказ или None, причина отказа или '').

    ЗАПРЕЩЕНО ДВА СЛУЧАЯ, и оба наблюдались вживую 4.10:
      * подмога В КЛЕТКУ САМОЙ ВОЛНЫ — «иди туда, где ты уже стоишь»;
      * подмога, посылать которую некем: дома бойцов нет.
    """
    цель = str(c.get("target") or "")
    if c.get("cmd") not in ("ATTACK", "ENGAGE") or цель != "wave":
        return c, ""
    if волна is None:
        return None, "НЕТ_ЦЕЛИ"
    # ВОЛНЫ В ПОЛЕ НЕТ — ПРИСОЕДИНЯТЬСЯ НЕ К КОМУ. Так и было все 94 раза 4.10:
    # группа стояла в клетке (5,2), и это была клетка нашей же ратуши, поэтому
    # мост честно отвечал «в поле нет своих дальше двух клеток от базы, идти не
    # к кому». Отсюда два признака, и оба из состояния: ушедших нет (`mil_away`)
    # либо группа стоит дома.
    if int(float(st.get("mil_away") or 0)) <= 0:
        return None, "СОБРАНО"
    if tuple(волна.сбор) == tuple(_дом(st)):
        return None, "СОБРАНО"
    if домашних_бойцов(st) <= 0:
        # Все уже в волне — собирать больше некого, значит волна СОБРАНА.
        return None, "СОБРАНО"
    клетка = (int(c.get("cx") or -1), int(c.get("cy") or -1))
    if клетка == tuple(волна.сбор):
        return None, "СОБРАНО"
    # ГЛАВНОЕ, И КУПЛЕНО ЖИВОЙ ПАРТИЕЙ 5.10. Цель `wave` МОСТ РАЗРЕШАЕТ САМ — в
    # клетку, где волна стоит СЕЙЧАС. В логе это видно дословно, каждые пять
    # секунд подряд: «ATTACK 9999 -> wave: к волне в клетку (8,1)» -> «урезан до
    # 34: столько сейчас свободно» -> «34 бойца ушли на cell, группа 1». Это те
    # же самые бойцы: мост считает их свободными, посылает в клетку, которую они
    # занимают, и марш начинается заново КАЖДЫЙ ТАКТ. Отряд стоит и топчется —
    # ровно это игрок и увидел глазами.
    #
    # Поэтому приказ не отвергается, а ПЕРЕНАЦЕЛИВАЕТСЯ: подмога идёт не туда,
    # где волна стоит, а туда, КУДА ОНА ИДЁТ. Тогда новобранцы догоняют её на
    # цели, а идущих никто не разворачивает. Если волна никуда не идёт, подмога
    # бессмысленна — отказ с причиной, и дальше решает переход «собрано -> бить».
    if волна.цель_клетка and tuple(волна.цель_клетка) != tuple(волна.сбор):
        return (dict(c, target="cell", cx=int(волна.цель_клетка[0]),
                     cy=int(волна.цель_клетка[1])), "")
    return None, "СОБРАНО"


class ЖиваяСтратегия:
    def __init__(self, путь: str, сеть: str = ""):
        with open(путь, encoding="utf-8") as f:
            w = json.load(f)
        self.п = w.get("итог", w)
        # СЕТЬ ТАКТИКА ВОЮЕТ (3.10, §61): волны и тактика стратегии выключаются ровно как в
        # обучении (`sim/тактик.Тактик`), решение о бое раз в 15 с даёт сеть.
        self.сеть = None
        if сеть:
            import tactic_core
            with open(сеть, encoding="utf-8") as f:
                self.сеть = tactic_core.Ядро(json.load(f)["theta"])
            self.имя_сети = os.path.basename(сеть)
            self.п = {k: v for k, v in self.п.items() if k not in ("отход", "подмога", "слабая", "возврат")}
            self.п.update(T1=1e9, T2=1e9, P1=0.0)
            self.решения = collections.Counter()
        self.имя = os.path.basename(путь)
        # Мы — живой мост: приказы волне в поле переводятся в мостовые (`_в_мостовые`).
        globals()["ЖИВОЙ_МОСТ"] = True
        import поиск_стратегии as ПС
        ПС.ПРАВИЛА_ЖИВЫЕ = True          # вживую правила моста действуют всегда
        import debut as _D               # §58: мостовой дебют — тем же порядком, что у стратегии
        _D.ПОРЯДОК_ИГРОКА = bool(self.п.get("дебют_игрока", 0))
        _D.ДЕРЕВО_ДЕБЮТА = int(self.п.get("дерево_дебют", 4) or 0)   # §170и: люди дебюта на дереве и камне (4/3 — как было)
        _D.КАМЕНЬ_ДЕБЮТА = int(self.п.get("камень_дебют", 3) or 0)
        _D.ПАЧКА_КРЕСТЬЯН = int(self.п.get("пачка_крестьян", 0) or 0)   # §170р: пачка крестьян в дебюте (0 — как было; игрок 6)
        _D.ПАЧКА_ЗАПАС = int(self.п.get("пачка_запас", 80) or 0)
        _D.БОЙЦЫ_ПОСЛЕ_ЕДЫ = int(self.п.get("бойцы_после_еды", 0) or 0)   # §170р′: бойцов дебюта не раньше еды N (0 — как было)
        _пк = self.п.get("передача_по_казарме")                             # §170т: передача стратегии по казарме (None — с пачкой; 0 — по бойцам)
        _D.ПЕРЕДАЧА_ПО_КАЗАРМЕ = None if _пк is None else int(float(_пк) or 0)
        self.стр = ПС.Стратегия(self.п)
        # §170н: исходные значения ключей, которые нация врага перестраивает по такту (возвращаются, когда условие снято)
        self._п_исход = {k: self.п.get(k) for k in ("мушк_с", "доля_мушк", "стрелки_позади", "отряд_с")}
        self.n = max(1, int(self.п.get("n", 20)))
        self.пропущено = collections.Counter()
        self.отдано = collections.Counter()
        # КОГО С КЕМ СВОДИМ (4.10). Приказ `target: group` наводится на место
        # получателя В МОМЕНТ ПРИКАЗА и в погоню не ведёт — живая партия 4.10
        # показала это первым же слиянием: получатель шёл, и пославший пришёл в
        # опустевшую клетку. Поэтому приказ ПОВТОРЯЕТСЯ каждый такт, пока клетки
        # не совпадут. Такт — пять игровых секунд, а не каждая секунда: приказ
        # идущей группе каждую секунду это перестроение, от которого волны уже
        # вставали («a unit already marching is left alone... it stalls»,
        # block_hcmd.inc).
        self.сводим = {}
        # НОМЕРА ВОЛНАМ (4.10, решение игрока). Пока волны были безымянны, адресные
        # приказы умела только рука: приказы «к своим», «держать», «вперёд» брали
        # ВСЕХ дальше одной клетки от ратуши и задевали подмогу, которая ещё идёт. Теперь
        # каждая уходящая волна получает номер, и дальше ей приказывают по нему.
        # Номер берётся СВОБОДНЫЙ по состоянию, а не по счётчику: иначе новая волна
        # заняла бы номер живой группы и перебила бы ей состав.
        self.номера = 0
        # КОНТРАКТ ВОЛНЫ (5.10). Реестр держит личность волны между тактами —
        # то, чего не было и из-за чего номер выдавался заново каждые пять
        # секунд. Он же считает простой готовой волны, меру, которой в разборе
        # 4.10 не хватило: 94 повтора приказа и 94 такта простоя — одно событие.
        self.реестр = РеестрВолн()

    def _удар_готовой(self, волна, st: dict):
        """Чем ударить собранной волне -> (приказ или None, причина).

        МЕСТНЫЙ ПЕРЕВЕС, А НЕ ОБЩИЙ. Разбор 4.10 показал, что общий счёт на
        вопрос «можно ли бить ближайшую кучу» не отвечает: у нас было 135 пехоты
        против его 114 (перевес 1,18 по партии), а рядом с волной стояли его
        кучи по 28 и 30 — против них перевес вчетверо больше, и бить их можно
        было с 7-й минуты. Поэтому сначала считается куча РЯДОМ.

        Порог не выдуман: это `штурм_при` самой стратегии (у шт_s2 — 0,92),
        то же число, которым она решает штурм в симуляторе.
        """
        порог = float(self.п.get("штурм_при", 0.92) or 0.92)
        # ПОРОГ БЛИЖНЕЙ КУЧИ ОТДЕЛЬНО (мак 5.10, §97): развилка §94 на p5 — удар по ближней куче при
        # местном перевесе 1,69 стоил 86-92 наших за 59-74 его; ключ `рядом_при` в файле стратегии
        # даёт ей свой порог. Нет ключа — как было, `штурм_при`.
        порог_рядом = float(self.п.get("рядом_при", порог) or порог)
        # ЧЬИМИ СИЛАМИ БЬЁМ. Если группа в игре уже есть — её бойцами (`count` 0
        # значит «приказ существующей группе»). Если волна ещё не родилась,
        # бойцы пойдут ИЗ ДОМА, и тогда сила — домашние, а `count` обязан быть
        # числом: иначе приказ адресуется группе, которой нет, и из дома не
        # уходит никто. Живая партия 5.10 показала это на себе — `attack: 0`
        # каждый такт при 64 бойцах дома и `mil_away` = 0 всю партию.
        дома = домашних_бойцов(st)
        _ов = self._отряд_волны(st)
        if _ов is not None:
            дома += _ов["n"]                    # отряд в поле — часть волны: удар судится с ним (`отряд_в_волне`)
            self.реестр.мера["отряд в волне: в силе удара"] += 1
        _всем = False
        if волна.подтверждена and int(волна.размер or 0) > 0:
            свои, счёт = int(волна.размер), 0
            # ШТУРМ ВСЕМ ДОМОМ (1.11, слово игрока «бот намного сильней и никуда не идёт»).
            # Живая партия 1.11 показала самый дорогой застой проекта: волна W1 родилась в
            # начале партии размером 9 (столько было свободных), и ДАЛЬШЕ РЕШЕНИЕ СУДИЛО
            # ВСЕГДА ПО ЕЁ РАЗМЕРУ — `свои=9` при 160 бойцах дома, ratio 0,04 против порога
            # 0,92, и так 77 тактов подряд. Одновременно найм стоял на паузе, потому что
            # «наших 160 ≥ 1,5 × его 78»: один и тот же бот считал себя сильным для паузы и
            # слабым для удара. Волна не росла, потому что ATTACK по `count` берёт только
            # свободных, а 160 держала стойка (`my_held` 160, свободных 3).
            # Блок умеет это с 28.10 (Д20), и стратегия этим не пользовалась: ключ файла
            # `all` — «ВЕСЬ ДОМ: блок берёт и держащих строй, снимает удержание и ведёт
            # каждый наш отряд КАК ОТРЯД в ту же цель» (`coss3_bridge._приказ`).
            # Ключ `штурм_всем` (нет/0 — как было): когда дома больше, чем в волне, судим и
            # бьём ВСЕМ домом, а приказ несёт `all` и `merge` (merge — чтобы состав группы
            # дополнялся, а не подменялся).
            if int(float(self.п.get("штурм_всем", 0) or 0)) and дома > свои:
                self.реестр.мера["штурм всем: волна усилена домом"] += 1
                self.реестр.записи.append(
                    f"ШТУРМ ВСЕМ ДОМОМ: в волне {свои}, дома {дома} — судим и бьём {дома} (ключ `all`)")
                свои, счёт, _всем = дома, дома, True
        else:
            свои, счёт = дома, дома
        if свои <= 0:
            return None, "МАЛО_СИЛ свои=0"
        if счёт > 0 and getattr(self, "_держим_дом", False):
            # ОБОРОНА (6.10): к базе идёт его группа — бойцов из дома не выводим
            return None, f"ОБОРОНА держим дом ({счёт} дома)"
        # §152 НЕ НАВСТРЕЧУ (12.10, первый бой Д4 3:49): его 10 шли к ратуше (через ~97 с), наша волна W2 (13) стояла ДОМА
        # готовой — и ушла им навстречу по местному перевесу 1,9 (группой, мимо «держим дом»), встала в (5,5) и легла по
        # частям на его стоящий строй: 12 за 4. Двойник (sim/решения/д4_первый_бой.md): «навстречу» — худшая ветка у всех
        # трёх агентов, «у ратуши» 0–2 своих; экзамен Fable/qwen — Б, стоять у ратуши. Ключ `не_навстречу` (перевес):
        # пока его группа идёт к базе (оборона, `_подход`), волна, стоящая дома, не бьёт навстречу, если её меньше, чем
        # порог × его идущих; бой ведёт движок у ратуши (строй на месте бьёт подходящих первыми). 0 — выкл.
        _нн = float(self.п.get("не_навстречу", 0) or 0)
        _пд = getattr(self, "_подход", None)
        if _нн > 0 and getattr(self, "_держим_дом", False) and _пд and int(_пд.get("его") or 0) > 0:
            _д = _дом(st)
            if _д is not None and max(abs(волна.сбор[0] - _д[0]), abs(волна.сбор[1] - _д[1])) <= 1 and свои < _нн * int(_пд["его"]):
                self.реестр.мера["не навстречу: волна ждёт у ратуши"] += 1
                return None, (f"ПОДХОД его {_пд['его']} через ~{_пд.get('сек')} с: свои {свои} < {_нн:g}×{_пд['его']} — "
                              f"навстречу не идём, ждём у ратуши")
        import coss3_map as _КМ
        кучи = _список(st, "ecells", _КМ.его_клетки)
        кучи = [к for к in кучи if int(к.get("n") or 0) > 0]
        if кучи:
            вx, вy = волна.сбор
            # БЛИЖАЙШАЯ, А ПРИ РАВНОЙ БЛИЗОСТИ — САМАЯ БОЛЬШАЯ. Без доводки по
            # размеру выбор выходил глупым: в снимке 7:01 ближайшей оказалась
            # клетка с ОДНИМ бойцом, а его двенадцать стояли в соседней, на одну
            # клетку дальше. Клетки рядом для боя это одно место: движок бьётся
            # и через границу клетки.
            дист = lambda к: max(abs(int(к["x"]) - вx), abs(int(к["y"]) - вy))
            ближе = min(дист(к) for к in кучи)
            бл = max((к for к in кучи if дист(к) <= ближе + 1),
                     key=lambda к: int(к.get("n") or 0))
            рядом = int(бл.get("n") or 0)
            # ЕГО ПОДКРЕПЛЕНИЕ У ЦЕЛИ (мак 5.10, §97 развилка): в 11:03 p5 перевес 1,97 считался против кучи
            # 36, а его 23 стояли в двух клетках и подошли за полминуты. Ключ `рядом_окно` k в файле
            # стратегии: «рядом» — все его бойцы в k клетках от выбранной кучи. Нет ключа — 0, как было.
            _окно = int(self.п.get("рядом_окно", 0) or 0)
            if _окно > 0:
                рядом = sum(int(к.get("n") or 0) for к in кучи
                            if max(abs(int(к["x"]) - int(бл["x"])), abs(int(к["y"]) - int(бл["y"]))) <= _окно)
            # ПЕРЕВЕС ПО ОГНЮ, А НЕ ПО ГОЛОВАМ (мак 5.10, §100): в 11:03 p5 из его 36 стрелков был 21, рядом ещё 23,
            # у нас 71 почти одних пик — по головам 1,97, по огню перевеса не было. Ключ `вес_стрелка` w в файле
            # стратегии: сила = пики + w·стрелки (+ конные как пики) у обеих сторон; состав волны — из `groups`
            # по её номеру, из дома — долей `mil_inf`/`mil_shooters`; его — из `ecells` (нет состава — головы).
            # Нет ключа — 0: считается по головам, как было.
            _вес = float(self.п.get("вес_стрелка", 0) or 0)
            мера_св, мера_его = float(свои), float(рядом)
            if _вес > 0:
                _г = next((г for г in _группы(st) if int(г.get("id") or 0) == int(волна.номер)), None) \
                    if (волна.подтверждена and not _всем) else None
                # ШТУРМ ВСЕМ ДОМОМ (1.11): при `штурм_всем` состав берётся ИЗ ДОМА, а не из группы.
                # Иначе правка выходит половинчатой, и это было видно в живой партии: `свои` печатались
                # 144, а решение сравнивало `мера_св` = 17 — вес ОДИННАДЦАТИ бойцов группы. Число в why
                # и число, на котором стоит решение, обязаны быть одним и тем же числом.
                if _г is not None and int(_г.get("n") or 0) > 0:
                    _стр = float(_г.get("стрелков") or 0)
                    мера_св = (float(_г.get("n") or 0) - _стр) + _вес * _стр
                else:
                    _пи, _ст = float(st.get("mil_inf") or 0) + float(st.get("mil_cav") or 0), float(st.get("mil_shooters") or 0)
                    _д = _ст / max(1.0, _пи + _ст)
                    мера_св = свои * ((1 - _д) + _вес * _д)
                _ок = _окно if _окно > 0 else 0
                мера_его = 0.0
                for к in кучи:
                    if max(abs(int(к["x"]) - int(бл["x"])), abs(int(к["y"]) - int(бл["y"]))) <= _ок:
                        _n = float(к.get("n") or 0)
                        _s = min(_n, float(к.get("стрелков") or 0))
                        мера_его += (_n - _s) + _вес * _s
            # §162 (16.10, Д6 11:25): его 90 стояли в соседней клетке (10,1), наши 95 пошли по перевесу 0,93 ≥ 0,92 — 84 легли
            # за 15 с при его ~0 (§161: на его стоящих норм 0,30–0,50; Д2, Д4 12:4). Ключ `стоящий_вес` w: его бойцы у цели
            # БЕЗ приказа движения, либо с целью не дальше клетки от себя (удержание, шаг на нас — 11:25 его 87 «идут» в нашу
            # клетку), весят ×w в местном перевесе; марш за 2+ клетки — не стоящие. Fable 3/3: стоять строем, пиками не входить
            _сw = float(self.п.get("стоящий_вес", 0) or 0)
            _стоящих, _ст = 0.0, ""
            if _сw > 1.0:
                _ок2 = _окно if _окно > 0 else 0
                for к in кучи:
                    if max(abs(int(к["x"]) - int(бл["x"])), abs(int(к["y"]) - int(бл["y"]))) <= _ок2:
                        _идут = float(к.get("идут") or 0)
                        if _идут > 0 and к.get("tx") is not None and max(abs(int(к["tx"]) - int(к["x"])), abs(int(к["ty"]) - int(к["y"]))) <= 1:
                            _идут = 0.0                     # цель рядом с собой — стоит/держит строй, не марш
                        _стоящих += max(0.0, float(к.get("n") or 0) - _идут)
                if _стоящих > 0:
                    # в тех же единицах, что мера_его (при `вес_стрелка` — средняя сила головы)
                    мера_его += (_сw - 1.0) * _стоящих * (мера_его / max(1.0, float(рядом)))
                    _ст = f" стоящих={_стоящих:.0f}×{_сw:g}"
                    self.реестр.мера["стоящий вес: перевес считан с весом"] += 1
            # §152 НЕ ГНАТЬСЯ (ключ `не_гнаться`, K клеток; см. `_тактика`): волна, стоящая ДОМА, не бьёт его кучу,
            # стоящую в K клетках от ратуши, пока нас меньше `не_гнаться_при` (4) × её — свободные встают заслоном
            # между ней и ратушей (`_тактика`), удар — когда он сам подойдёт (Д4 5:22: W2 (23) из дома на его 10 в (5,6))
            _нг = int(float(self.п.get("не_гнаться", 0) or 0))
            if _нг > 0:
                _д = _дом(st)
                if (_д is not None and max(abs(волна.сбор[0] - _д[0]), abs(волна.сбор[1] - _д[1])) <= 1
                        and max(abs(int(бл["x"]) - _д[0]), abs(int(бл["y"]) - _д[1])) <= _нг
                        and (int(бл["x"]), int(бл["y"])) != tuple(волна.сбор)
                        and свои < float(self.п.get("не_гнаться_при", 4.0) or 4.0) * max(1, рядом)):
                    self.реестр.мера["не гнаться: волна дома не бьёт"] += 1
                    return None, (f"НЕ_ГОНИМСЯ его {рядом} в {бл['x']},{бл['y']} в {max(abs(int(бл['x']) - _д[0]), abs(int(бл['y']) - _д[1]))} кл. "
                                  f"от ратуши, свои {свои} < {float(self.п.get('не_гнаться_при', 4.0) or 4.0):g}×{рядом} — заслон, не погоня")
            if (int(бл["x"]), int(бл["y"])) == tuple(волна.сбор):
                # Он в НАШЕЙ клетке: бой уже идёт, и приказ «иди сюда» был бы тем
                # самым «иди туда, где стоишь», из-за которого вся эта правка и
                # делалась. Причина названа, приказа нет.
                return None, (f"БОЙ_ИДЁТ свои={свои} рядом={рядом} "
                              f"клетка={волна.сбор[0]},{волна.сбор[1]}")
            _сил = (f" сила={мера_св:.0f}/{мера_его:.0f}" if _вес > 0 else "") + _ст
            if мера_св >= порог_рядом * мера_его:
                # `face` на ту же кучу НАЗВАН ЯВНО, хотя блок сам ставит строй
                # лицом к точке цели и вышло бы то же: приказ, который читают
                # глазами в логе и в трассе, не должен полагаться на умолчание
                # блока. Если умолчание однажды изменится, удар останется лицом
                # к врагу.
                return ({"cmd": "ATTACK", "count": счёт, "target": "cell",
                         "cx": int(бл["x"]), "cy": int(бл["y"]),
                         "face": [int(бл["x"]), int(бл["y"])],
                         "group": волна.номер,
                         **({"all": 1, "merge": 1} if _всем else {})},
                        f"МЕСТНЫЙ_ПЕРЕВЕС свои={свои} рядом={рядом} "
                        f"ratio={мера_св / max(1.0, мера_его):.2f} порог={порог_рядом:.2f}{_сил}")
            # Ближнюю кучу не берём — мимо неё не ходим. Причина НАЗВАНА, и это
            # не то же, что «цели нет»: разбор должен различать «не дошли» и
            # «не решились».
            return None, (f"МАЛО_СИЛ свои={свои} рядом={рядом} "
                          f"ratio={мера_св / max(1.0, мера_его):.2f} порог={порог_рядом:.2f}{_сил}")
        # Куч рядом нет — значит цель это его база, если она на карте известна.
        try:
            б = _КМ.база_врага(st)
        except Exception:
            б = {}
        if not б:
            return None, "НЕТ_ЦЕЛИ"
        его = float(st.get("p1_army") or 0)
        if его > 0 and свои < порог * его:
            return None, (f"МАЛО_СИЛ свои={свои} его={его:.0f} "
                          f"порог={порог:.2f}")
        return ({"cmd": "ATTACK", "count": счёт, "target": "cell",
                 "cx": int(б["cx"]), "cy": int(б["cy"]),
                 "face": [int(б["cx"]), int(б["cy"])], "group": волна.номер,
                 **({"all": 1, "merge": 1} if _всем else {})},
                f"БАЗА свои={свои} его={его:.0f} порог={порог:.2f}")

    def _выход_к(self, из: list, st: dict):
        """ВЫХОД К ЕГО КРЕСТЬЯНАМ ПО СРОКУ (21.10, §169г, ключ `выход_к` — СЛОВО ИГРОКА 21.10; задание мака в ПЛАН.md).

        Правило турнира: партия без похода проиграна обоим, а цель — его крестьяне. Д9 показала обе дыры сразу: бот выиграл
        армию (214 против 89, размен 4,86) и НЕ ВЗЯЛ ЦЕЛЬ — его крестьян убито 0, осталось 84. Все 17 волн и 2 «УДАР ПО
        ЛАГЕРЮ» шли по его бойцам; к крестьянам не пошёл никто. В Д5 бот не ударил ни разу (§160: с честным путём удар 14:39
        пропадает, R 1,12 < 1,3). Ключ закрывает обе: после срока армия идёт ТУДА, ГДЕ КРЕСТЬЯНЕ, и идёт ИЗ ДОМА.

        Ключи файла стратегии: `выход_к` — секунда, с которой правило действует (780 = 13:00; 0 — выкл); `выход_R` — порог
        прогноза для этого приказа (1,0 вместо `размен_при`); `выход_перевес` — во сколько раз наших дома должно быть
        больше его армии ВСЕЙ (`p1_army`); `выход_повтор` — через сколько секунд пробовать снова (60).

        Что правило обходит: вето волны — `_держим_дом`, `не_навстречу`, `НЕ_ГОНИМСЯ` (все три считают силу ВОЛНЫ, а не
        дома: в Д9 13:02-13:18 из дома было 188-192 при его 151 рядом, и прогноз «из дома» давал R 1,95-2,55 с его группой
        УНИЧТОЖЕНА — а приказа не было). Приказ занимает такт (`занят` в `ответ`), поэтому удар готовой волны этим тактом не
        считается. Отход (§136) и стоящие ×1,5 (§162) НЕ обходятся.

        Два отступления от задания, оба названы вслух и в ПЛАН.md:
        (1) прогноз считается ЗДЕСЬ, а не только в ручейке: иначе при невыгодном R ручеёк снял бы и этот приказ, и снятые им
            приказы такта, и такт кончился бы вовсе без атаки. Числа те же (`прогноз.новая_волна`), а в ручейке приказ
            помечен `_выход_к` и судится порогом `выход_R`, а не `размен_при`;
        (2) приказ ЗАМЕНЯЕТ новые волны этого такта (не приказы уже существующим группам): иначе армия делится на две —
            одна к крестьянам, другая к его остатку, — а это ручеёк, от которого мы и лечимся. Заменённое печатается.
        """
        срок = float(self.п.get("выход_к", 0) or 0)
        if not hasattr(self, "_вк"):
            self._вк = dict(база=None, выходов=0, последний=None)
        if self._вк["база"] is None:
            # База убитых крестьян — первый ВИДЕННЫЙ такт: счётчик партии может прийти не с нуля (так считает `goals.py`)
            self._вк["база"] = float(st.get("p1_pea_lost") or 0)
        if срок <= 0:
            return из, ""
        import coss3_map as _КМ
        import combat_math
        import прогноз as ПР
        import прокачки as _ПК
        t = float(st.get("gametime") or 0)
        if t < срок:
            return из, ""
        # §170ж (б) (30.10, Польша 13:02): выход 112 на его крестьян при его 94–120 у нашей базы и лагере 231 в 4 клетках — армия ушла
        # из боя за дом. Ключ `выход_не_при_осаде` (N, 0 — как было): пока его бойцов у нашей базы не меньше N, выхода нет.
        _осада = float(self.п.get("выход_не_при_осаде", 0) or 0)
        # `en_at_base` — счёт python по своим клеткам (в контейнере 30.10 был 0 при 37 у ратуши по счёту блока); берём больший из двух
        _у_базы = max(float(st.get("en_at_base") or 0), float(st.get("defend_n") or 0))
        if _осада > 0 and _у_базы >= _осада:
            return из, f"ВЫХОД_К: не выходим — его {_у_базы:.0f} у нашей базы (≥ {_осада:g}), сперва оборона"
        убито = max(0.0, float(st.get("p1_pea_lost") or 0) - self._вк["база"])
        # `выход_к_после_цели` (28.10, серия exit_all_vs_ai): против невозможного ИИ его крестьяне гибнут от его же голода с 4:00,
        # счётчик `p1_pea_lost` растёт без нас, и правило молчало всю партию — механизм выхода (all, отряды) стал неизмерим. Ключ 1 —
        # выходить и после взятия цели (турнир: каждый его крестьянин — очки); 0 — как было (одна цель — одно молчание).
        _после = int(self.п.get("выход_к_после_цели", 0) or 0)
        if убито > 0 and not _после:
            return из, f"ВЫХОД_К: цель взята — его крестьян убито {убито:.0f}, правило молчит"
        дома = домашних_бойцов(st)
        его_всего = float(st.get("p1_army") or 0)
        перевес = float(self.п.get("выход_перевес", 1.2) or 1.2)
        # §170 (22.10, СЛОВО ИГРОКА, вопрос мака по трассе Д10): перевес считается ПО ЗАКОНУ УРОНА, а не по головам.
        # В Д10 13:01 наш пикинёр был 11/7 против его 8/3 — наш удар 8, его 1 (12 ударов до смерти против 90), а головы
        # 185 против 195. По головам бот ждал и не вышел ни разу за партию, пока игрок докупал ступени и сравнивался;
        # экзамен Fable 3/3 — идти. Сила стороны = головы × урон за удар по пикинёру противника (`combat_math.урон`:
        # атака минус защита по типу оружия, не меньше 1). Мера сама себя защищает: двадцать с лучшей атакой против
        # двухсот дают 160 против 200 и не выходят. Нет строк родов войск — считаем по головам и говорим об этом.
        наш_п = combat_math.разобрать(st.get("fighters") or "").get("infantry17")
        его_п = combat_math.разобрать(st.get("p1_fighters") or "").get("infantry17")
        if наш_п and его_п:
            наш_удар, его_удар = combat_math.урон(наш_п, его_п), combat_math.урон(его_п, наш_п)
            сила_наша, сила_его = дома * наш_удар, его_всего * его_удар
            готовы = сила_наша >= перевес * сила_его
            мера = (f"сила {дома}×{наш_удар} = {сила_наша:.0f} против его {его_всего:.0f}×{его_удар} = {сила_его:.0f} "
                    f"(по закону урона)")
        else:
            готовы = дома >= перевес * его_всего
            мера = f"наших дома {дома} против его {его_всего:.0f} (родов войск в снимке нет — по головам)"
        if not готовы:
            self.реестр.мера["выход_к: ждём перевеса"] += 1
            return из, f"ВЫХОД_К: ждём — его крестьян убито 0 / {мера} < {перевес:g}×"
        if self._вк["последний"] is not None and t - self._вк["последний"] < float(self.п.get("выход_повтор", 60) or 60):
            return из, ""
        его_кл = [c for c in _список(st, "ecells", _КМ.его_клетки) if int(c.get("n") or 0) > 0]
        кр = [q for q in _клетки_крестьян(st, его_кл) if int(q.get("крестьян") or 0) >= 3]
        нет_крестьян = not кр
        if кр:
            q = min(кр, key=lambda q: float(q.get("бойцов_рядом") or 0))
            цель, охрана, куда = (int(q["x"]), int(q["y"])), float(q.get("бойцов_рядом") or 0), "peasants"
        else:
            б = _его_база(st)
            if б is None:
                return из, "ВЫХОД_К: ни клетки крестьян, ни его базы не вижу — цели нет"
            цель, охрана, куда = (int(б[0]), int(б[1])), 0.0, "base"
        R = None
        свои = combat_math.разобрать(st.get("fighters") or "")
        чужие = _ПК._чужие_со_строем(st)
        порог = float(self.п.get("выход_R", 1.0) or 1.0)
        остаток_при = float(self.п.get("остаток_при", 0.3) or 0.3)
        # §170у (28.10, Д20): ЛАГЕРЬ НА ПУТИ. Прогноз выхода смотрел только на охрану у цели (2 бойца) и не видел его
        # лагерь 184 в (13,9) — в четырёх клетках от нашей ратуши, прямо на дороге к (14,2): волна легла в (11,9), за семь
        # клеток до крестьян. Ключ `выход_лагерь` 1: его клетка от `выход_лагерь_от` (20) бойцов, лежащая в коридоре
        # дом→цель (до отрезка ≤ 1 клетки, ближе цели), судится тем же прогнозом; не проходит — не выходим и говорим. 0 — как было.
        if int(self.п.get("выход_лагерь", 0) or 0) and свои and чужие and дома > 0:
            _дом = (int(float(st.get("my_cx") or 0)), int(float(st.get("my_cy") or 0)))
            _от = int(self.п.get("выход_лагерь_от", 20) or 20)
            _лаг = None
            _дц = max(abs(цель[0] - _дом[0]), abs(цель[1] - _дом[1]))
            for c in его_кл:
                try:
                    _x, _y, _n = int(c.get("x")), int(c.get("y")), int(c.get("n") or 0)
                except (TypeError, ValueError):
                    continue
                if _n < _от or max(abs(_x - _дом[0]), abs(_y - _дом[1])) >= _дц:
                    continue
                if _до_отрезка((_x, _y), _дом, цель) <= 1.0 and (_лаг is None or _n > _лаг[2]):
                    _лаг = (_x, _y, _n)
            if _лаг is not None:
                _охр2 = ПР.состав_из_клеток(его_кл, (_лаг[0], _лаг[1]), 1)
                if sum(_охр2.values()) < 1:
                    _охр2 = ПР.состав_по_долям(_лаг[2], st, "p1_")
                _п2 = ПР.новая_волна(ПР.состав_по_долям(дома, st), _охр2, свои, чужие, False)
                if _п2["R"] is None or not ((_п2["R"] >= порог or _п2.get("уничтожена")) and _п2["остаток_наш"] >= остаток_при):
                    self.реестр.мера["выход_к: лагерь на пути"] += 1
                    return из, (f"ВЫХОД_К: не выходим — на пути его лагерь {_лаг[2]} в {_лаг[0]},{_лаг[1]} (R={_п2['R']}, "
                                f"порог {порог:g}; дома {дома}, цель {цель[0]},{цель[1]}; {ПР.словами(_п2)})")
        if свои and чужие and дома > 0:
            охр = ПР.состав_из_клеток(его_кл, цель, max(1, int(self.п.get("рядом_окно", 1) or 1)))
            if sum(охр.values()) < 1 and охрана > 0:
                охр = ПР.состав_по_долям(охрана, st, "p1_")
            if sum(охр.values()) >= 1:
                б = _его_база(st)
                у_базы = б is not None and max(abs(цель[0] - int(б[0])), abs(цель[1] - int(б[1]))) <= 2
                п = ПР.новая_волна(ПР.состав_по_долям(дома, st), охр, свои, чужие, у_базы)
                R = п["R"]
                if not (R is None or ((R >= порог or п.get("уничтожена")) and п["остаток_наш"] >= остаток_при)):
                    # ПОЧЕМУ ИМЕННО — отдельной строкой. 22.10, Д11: шестнадцать тактов печаталось «R=2.5 < 1», хотя R был
                    # ВЫШЕ порога, а отказывал `остаток_наш` 28-29 % против 30 %. Неверная причина в why — это хуже
                    # молчания: по ней я бы крутил порог, который ни при чём.
                    почему = ("R ниже порога" if not (R >= порог or п.get("уничтожена"))
                              else f"от волны останется {100 * п['остаток_наш']:.0f} % < {100 * остаток_при:.0f} %")
                    self.реестр.мера[f"выход_к: прогноз против ({почему.split()[0]})"] += 1
                    return из, (f"ВЫХОД_К: не выходим — {почему} (R={R}, порог {порог:g}) у клетки "
                                f"{цель[0]},{цель[1]}, охрана {sum(охр.values()):.0f}; дома {дома} ({ПР.словами(п)})")
        снято = [c for c in из if c.get("cmd") in ("ATTACK", "ENGAGE") and not c.get("group")
                 and not c.get("_оборона") and not c.get("_огонь") and not c.get("_резак")]
        из = [c for c in из if c not in снято]
        _всем = int(self.п.get("выход_всем", 0) or 0)   # §170у: all=1 — блок берёт держащих и ведёт отряды как отряды (Д20: 39 из 171)
        # `_цель` (29.10, серия exit_all_vs_ai_2): клетка цели выхода — для памяти `_помнить_выход`: она знала только приказы с cx/cy и
        # «base», выход на `peasants` без клетки не запоминался, и правило сирот через 5–20 с возвращало вышедших домой (x2: выходы
        # 12:19/13:20/14:31 → «СИРОТЫ … домой» 12:39/13:25/14:47, mil_far ≤ 7 клеток при цели в 10) — отряд до крестьян не доходил
        из.append({"cmd": "ATTACK", "count": дома, "target": куда, "_выход_к": True, "_цель": [int(цель[0]), int(цель[1])], **({"all": 1} if _всем else {})})
        self._вк["выходов"] += 1
        self._вк["последний"] = t
        self.реестр.мера["выход_к: выходов"] += 1
        строки = [(f"ВЫХОД_К (цель уже взята: его крестьян убито {убито:.0f}, ключ велит выходить дальше)" if убито > 0 else "ВЫХОД_К") +
                  f": выход {self._вк['выходов']} — {дома} из дома на {куда} {цель[0]},{цель[1]}, "
                  f"охрана {охрана:.0f}" + (f", R={R}" if R is not None else ", прогноз не считан")
                  + f" / {мера}"]   # в одной строке why: «; » разделяет правила, и мера уехала бы отдельным пунктом
        if "my_held" in st:   # блок №2 (29.10): дом по составу — счётный приказ берёт только свободных, all=1 всех
            строки.append(f"ВЫХОД_К: дома свободных {int(float(st.get('my_freewar') or 0))}, держат строй "
                          f"{int(float(st.get('my_held') or 0))}, в отрядах {int(float(st.get('my_insquad') or 0))}"
                          + ("" if _всем else " — без all=1 пойдут только свободные"))
        if нет_крестьян:
            строки.append("ВЫХОД_К: крестьян не вижу, идём на базу")
        if снято:
            строки.append("ВЫХОД_К: приказы такта заменены ("
                          + ", ".join(str(c.get("target") or c.get("cmd")) for c in снято) + " → крестьяне)")
        return из, "; ".join(строки)

    def _без_ручейка(self, из: list, st: dict, этап: str = "до"):
        """ЗАПРЕТ РУЧЕЙКА (8.10, §113, задание игрока): новая волна и подмога не идут в ожидаемый невыгодный контакт по
        частям. Перед отправкой каждого ATTACK/ENGAGE мост считает бой (`прогноз.py`: тот же закон боя, что у симулятора;
        состав, прокачки, строй врага, время прибытия): новая волна — силой тех, кто вступит вместе; подмога — подмога
        плюс ОСТАТОК волны к её прибытию. Если R (его потери / наши по цене найма) ниже `размен_при` или волна не
        доживёт до подмоги — приказ не уезжает, бойцы копятся в БЕЗОПАСНОЙ точке сбора (дом, а при его группе у дома —
        на две клетки от неё). Копим дольше `сбор_макс_с` — обязаны назвать причину и вернуть выбор: цель его крестьян без
        охраны (R ≥ порога) берётся сама, иначе в логе «СБОР_ЗАТЯНУЛСЯ» с лучшим R. Ключ `ручеёк` в файле стратегии;
        без него правило не действует (переключаемое правило моста, не маска сети — так велел разбор).
        `этап` «до» — приказы стратегии до нумерации; «удар» — только удар готовой волны (`self._приказ_удара`)."""
        if not float(self.п.get("ручеёк", 0) or 0):
            return из, ""
        import coss3_map as _КМ
        import combat_math
        import прогноз as ПР
        import прокачки as _ПК
        t = float(st.get("gametime") or 0)
        порог = float(self.п.get("размен_при", 1.0) or 1.0)
        окно = max(1, int(self.п.get("рядом_окно", 0) or 0))
        if not hasattr(self, "_сбор_с"):
            self._сбор_с, self._точка, self.прогнозы, self._отложено = None, None, [], None
        свои = combat_math.разобрать(st.get("fighters") or "")
        чужие = _ПК._чужие_со_строем(st)
        if not свои or not чужие:
            return из, ""
        его_кл = [c for c in _список(st, "ecells", _КМ.его_клетки) if int(c.get("n") or 0) > 0]
        дом = _наша_база(st)
        волна = self.реестр.активная()
        группы = {int(г.get("id") or 0): г for г in _группы(st)}
        дома = домашних_бойцов(st)

        def клетка_цели(c):
            ц = str(c.get("target") or "")
            if ц == "cell" and c.get("cx") is not None:
                return (int(c["cx"]), int(c["cy"]))
            if ц == "wave" and волна is not None:
                return tuple(волна.цель_клетка or волна.сбор)
            if ц == "base":
                б = _его_база(st)
                return None if б is None else (int(б[0]), int(б[1]))
            if ц == "army" and его_кл:
                к = max(его_кл, key=lambda q: int(q.get("n") or 0))
                return (int(к["x"]), int(к["y"]))
            if ц in ("peasants", "peasants_free"):
                # цель — его крестьяне: мост/симулятор выберут клетку без его армии; оцениваем против охраны самой
                # слабо прикрытой клетки с крестьянами (`en_pea_cells`: крестьян, бойцов_рядом)
                кр = [q for q in _клетки_крестьян(st, его_кл) if int(q.get("крестьян") or 0) >= 3]
                if кр:
                    q = min(кр, key=lambda q: float(q.get("бойцов_рядом") or 0))
                    return (int(q["x"]), int(q["y"]))
            return None

        записи, оставить, отказано = [], [], 0
        _отмена_выхода = None          # §170л (в): цель, выход к которой перестал быть выгодным, пока к ней идут наши
        for c in из:
            if c.get("_оборона"):                 # §143: удар отряда обороны по его стрелкам у ратуши считан своим прогнозом (клетка цели)
                оставить.append(c)
                continue
            if c.get("cmd") not in ("ATTACK", "ENGAGE") or (этап == "удар" and c is not getattr(self, "_приказ_удара", None)) \
                    or (этап == "до" and c is getattr(self, "_приказ_удара", None)):
                оставить.append(c)
                continue
            цель = клетка_цели(c)
            if цель is None:
                оставить.append(c)
                continue
            его = ПР.состав_из_клеток(его_кл, цель, окно)
            его = _его_с_лагерем(его, цель, st, getattr(self, 'п', {}))[0]   # §170ж
            if sum(его.values()) < 1 and str(c.get("target") or "") in ("peasants", "peasants_free"):
                охр = next((float(q.get("бойцов_рядом") or 0) for q in _клетки_крестьян(st, его_кл)
                            if (int(q.get("x", -9)), int(q.get("y", -9))) == цель), 0.0)
                его = ПР.состав_по_долям(охр, st, "p1_")
            if sum(его.values()) < 1:
                оставить.append(c)                      # у цели его нет — боя не предвидится, не ручеёк
                continue
            у_базы = _его_база(st) is not None and max(abs(цель[0] - _его_база(st)[0]), abs(цель[1] - _его_база(st)[1])) <= 2
            сч = c.get("count", 0)
            все = isinstance(сч, str) and сч.strip().lower() in ("all", "все")
            try:
                n = int(float(сч or 0))
            except (TypeError, ValueError):
                n = 0
            г = группы.get(int(c.get("group") or 0)) if c.get("group") else None
            if г is not None and not все and n <= 0:
                # приказ существующей группе — она идёт вся как есть
                сила = ПР.состав_из_клеток([г], None)
                п = ПР.новая_волна(сила, его, свои, чужие, у_базы)
                кто = f"группа {г.get('id')} ({int(г.get('n') or 0)})"
            else:
                из_дома = min(дома, n) if (n > 0 and not все) else дома
                сила = ПР.состав_по_долям(из_дома, st)
                if волна is not None and волна.подтверждена and волна.номер in группы and max(abs(цель[0] - волна.сбор[0]), abs(цель[1] - волна.сбор[1])) <= 2:
                    # подмога к действующей волне: что от неё останется к приходу; если волна не доживёт — подмога идёт
                    # как новая волна против того, что останется от него (спасти волну нельзя, но бой может быть выгодным)
                    в = ПР.состав_из_клеток([группы[волна.номер]], None)
                    п = ПР.подмога(сила, в, его, свои, чужие, ПР.сек_пути(max(abs(дом[0] - цель[0]), abs(дом[1] - цель[1]))), у_базы)
                    кто = f"подмога {из_дома:.0f} к волне {волна.id} ({int(группы[волна.номер].get('n') or 0)})"
                    if not п.get("волна_доживёт", True):
                        кто += " [волна не доживёт — считано как новая]"
                else:
                    кто = f"из дома {из_дома:.0f}"
                    # §170к (24.10, слово игрока по Д13 «армия бота в начале странно на меня пошла»): ПРОГНОЗ К ПРИХОДУ С ЕГО
                    # НАЙМОМ. Прогноз считал его бойцов у цели СЕЙЧАС: в Д12 с 3:10 по 5:27 «наших 12 против его 1 — его
                    # группа уничтожена» одобряло выход всей армией к его базе (11 клеток ≈ 153 с пути), а он за это время
                    # нанимал 0,18–0,2/с: 1 → 21 боец за 3:05–4:57. До §170д выход срывали сироты, в Д13 армия пошла. Теперь
                    # к его составу у базы прибавляется найм за секунды пути (темп — `_темп_его_найма`), по долям его армии.
                    # Только для выхода к ЕГО БАЗЕ (пополнение появляется там) и не для `выход_к` — турнирный выход судит
                    # игрок (Д10: «оставить как есть»). Ключ `прогноз_найма` 1 (файл партии); 0 — как было.
                    его_пр = его
                    if int(self.п.get("прогноз_найма", 0) or 0) and у_базы and not c.get("_выход_к"):
                        путь_с = ПР.сек_пути(max(abs(дом[0] - цель[0]), abs(дом[1] - цель[1])))
                        темп, темп_сл = self._темп_его_найма(st)
                        n_доб = темп * путь_с
                        if n_доб >= 1:
                            доб = ПР.состав_по_долям(n_доб, st, "p1_")
                            его_пр = {р: float(его.get(р) or 0) + float(доб.get(р) or 0) for р in set(его) | set(доб)}
                            кто += f" [к приходу через {путь_с:.0f} с его +{n_доб:.0f} по найму, {темп_сл}]"
                    п = ПР.новая_волна(сила, его_пр, свои, чужие, у_базы)
            self.прогнозы.append(dict(t=t, цель=list(цель), случай=п.get("случай"), R=п["R"], наших=п["наших_всего"], его=п["его_всего"],
                                      наши_потери=round(sum(п["наши_потери"].values()), 1), его_потери=round(sum(п["его_потери"].values()), 1)))
            # выгодно = размен не ниже порога И группа не гибнет целиком (`остаток_при`, 0,3): R по стоимости хвалит и
            # семёрку, которая вся ляжет, забрав двенадцать — это и есть ручеёк
            остаток_при = float(self.п.get("остаток_при", 0.3) or 0.3)
            # §169г: у приказа ВЫХОДА ПО СРОКУ (`выход_к`) свой порог — `выход_R` (1,0), а не `размен_при`. Иначе ключ
            # упирается в тот же порог, из-за которого выхода не было: в Д5 удар 14:39 пропал при R 1,12 < 1,3.
            порог_c = float(self.п.get("выход_R", порог) or порог) if c.get("_выход_к") else порог
            # выгодно: размен не ниже порога ИЛИ его группа у цели уничтожается за горизонт — и в обоих случаях наша группа не
            # гибнет целиком (`остаток_при`, 0,3). Один R мало: по стоимости 60 против 10 — проигрыш (0,86), по миссии — победа
            выгодно = п["R"] is None or ((п["R"] >= порог_c or п.get("уничтожена")) and п["остаток_наш"] >= остаток_при)
            if выгодно:
                оставить.append(c)
                if п["R"] is not None:
                    записи.append(f"РАЗМЕН_ОК {кто} → {цель[0]},{цель[1]}: {ПР.словами(п)}")
                continue
            отказано += 1
            self.реестр.мера["ручеёк: отказов"] += 1
            self._отложено = (цель, str(c.get("target") or "cell"))      # замысел не забыт: переоценивается каждый такт
            записи.append((f"ВЫХОД_К: " if c.get("_выход_к") else "")
                           + f"НЕ_ВЫГОДНО {кто} → {цель[0]},{цель[1]}: {ПР.словами(п)} < порог {порог_c:.2f}")
            _вых = getattr(self, "_выход_поля", None)
            if (int(self.п.get("отход_поля", 0) or 0) and not c.get("_выход_к") and _вых is not None
                    and tuple(_вых["цель"]) == (int(цель[0]), int(цель[1]))):
                # КАЧЕЛИ (2.11, разбор 35 прогонов): отмену выхода решал прогноз ЭТОГО приказа — «из дома N», а вышедшие в
                # поле в него не входили: drop_pol 22:20 «НЕ_ВЫГОДНО из дома 98 против его 191, R 0,64» → «ВЫХОД ОТМЕНЁН: наших
                # в поле 613, все домой». Из 118 отмен в 100 прогноз видел меньше бойцов, чем уже стояло в поле, в 111 поле + дом
                # было не меньше 1,5 × его у цели; снова к цели армия шла через 11 с (медиана). Три ключа, все 0 — как было:
                # `отход_по_всем` 1 — продолжать ли выход, судим по полю + дому (прогноз «из дома» решает только подмогу);
                # `отход_запас` k — отзываем, только если этот прогноз ниже k × порога (гистерезис; 0 — как порог);
                # `отход_не_раньше` T — первые T секунд после выхода не отзываем.
                _отменить = True
                _пв = int(float(self.п.get("отход_по_всем", 0) or 0))
                _зап = float(self.п.get("отход_запас", 0) or 0) or 1.0
                _нр = float(self.п.get("отход_не_раньше", 0) or 0)
                if _нр > 0 and t - float(_вых.get("t", t)) < _нр:
                    _отменить = False
                    self.реестр.мера["качели: отзыв рано"] += 1
                    записи.append(f"ВЫХОД ПРОДОЛЖЕН: вышли {t - float(_вых.get('t', t)):.0f} с назад < {_нр:g} с — не отзываем")
                elif _пв:
                    _поле_кл = [q for q in _список(st, "ocells", _КМ.наши_клетки) if int(q.get("n") or 0) > 0
                                and max(abs(int(q["x"]) - дом[0]), abs(int(q["y"]) - дом[1])) > 1]
                    _сп = ПР.состав_из_клеток(_поле_кл, None)
                    # приказ ГРУППЕ в поле: её бойцы уже в клетках поля — «силу» приказа второй раз не прибавляем
                    _дом_сила = {} if (г is not None and not все and n <= 0) else сила
                    _сила_все = {р: float(_сп.get(р) or 0) + float(_дом_сила.get(р) or 0) for р in set(_сп) | set(_дом_сила)}
                    _пвс = ПР.новая_волна(_сила_все, его, свои, чужие, у_базы)
                    _ок = _пвс["R"] is None or ((_пвс["R"] >= _зап * порог_c or _пвс.get("уничтожена"))
                                                 and _пвс["остаток_наш"] >= остаток_при)
                    if _ок:
                        _отменить = False
                        self.реестр.мера["качели: выход продолжен по всем"] += 1
                        записи.append(f"ВЫХОД ПРОДОЛЖЕН: поле + дом {sum(_сила_все.values()):.0f} → {цель[0]},{цель[1]}: "
                                      f"{ПР.словами(_пвс)} (порог отзыва {_зап * порог_c:.2f})")
                        # (второй круг, 2.11) «ПРОДОЛЖИТЬ» = ДЕЙСТВИЕ. Волна swing_net: прогноз «поле + дом» считал домашних, а их
                        # приказ оставался отвергнутым — в поле дрались 63 из «193», размен 0,50/0,62 против 1,18/1,42 базы.
                        # Ключ `отход_действие` 1 (0 — как было): раз считали всех — всех и посылаем: этот же приказ уходит
                        # ВЕСЬ ДОМ (`all`: свободные и отряды строем, удержание снято) в ту же цель.
                        if int(float(self.п.get("отход_действие", 0) or 0)):
                            оставить.append(dict(c, count="all", all=1, target="cell", cx=int(цель[0]), cy=int(цель[1])))
                            отказано -= 1
                            self.реестр.мера["качели: продолжение всеми"] += 1
                            записи.append(f"ВЫХОД ПРОДОЛЖЕН ДЕЛОМ: весь дом (all) → {цель[0]},{цель[1]}")
                if _отменить:
                    _отмена_выхода = (int(цель[0]), int(цель[1]))
            if c is getattr(self, "_приказ_удара", None) and волна is not None and волна.состояние == "В_БОЮ":
                волна.состояние, волна.ударов, волна.цель_клетка = "ГОТОВА", max(0, волна.ударов - 1), None
                волна.причина = f"НЕ_ВЫГОДНО R={п['R']}"
        if _отмена_выхода is not None:
            # §170л (в) (24.10, Д13): выход к цели одобрялся с 3:02 по 4:50 по его бойцам «сейчас», память §170д держала вышедших
            # в поле, а с 4:55 ручеёк говорил «НЕ_ВЫГОДНО» — но тем, кто уже шёл (21 тремя кучками), никто приказа не менял до
            # 5:56. Теперь: прогноз выхода к цели стал невыгодным → память выхода снята, все наши в поле — домой числом, волна
            # в поле — ДОМОЙ. Турнирный `выход_к` не трогается.
            self._выход_поля = None
            _наши_кл = [c for c in _список(st, "ocells", _КМ.наши_клетки) if int(c.get("n") or 0) > 0]
            _вп = [c for c in _наши_кл if max(abs(int(c["x"]) - дом[0]), abs(int(c["y"]) - дом[1])) > 1]
            n_поля = sum(int(c.get("n") or 0) for c in _вп)
            if n_поля > 0:
                ближ = min(его_кл, key=lambda c: max(abs(int(c["x"]) - дом[0]), abs(int(c["y"]) - дом[1]))) if его_кл else None
                лицо = [int(ближ["x"]), int(ближ["y"])] if ближ else [int(_отмена_выхода[0]), int(_отмена_выхода[1])]
                оставить = [c for c in оставить if not (c.get("cmd") in ("ATTACK", "ENGAGE") and not c.get("group"))]
                оставить.insert(0, {"cmd": "RETREAT", "count": int(n_поля), "target": "cell", "cx": int(дом[0]), "cy": int(дом[1]), "face": лицо})
                if волна is not None and волна.подтверждена and волна.состояние not in ("ДОМОЙ", "КОНЧЕНА"):
                    волна.состояние = "ДОМОЙ"
                    волна.цель_клетка = (int(дом[0]), int(дом[1]))
                self.реестр.мера["ручеёк: выход отменён"] += 1
                записи.append(f"ВЫХОД ОТМЕНЁН: к {_отмена_выхода[0]},{_отмена_выхода[1]} идти невыгодно — наших в поле {n_поля}, все домой лицом к {лицо[0]},{лицо[1]}")
        if отказано:
            if self._сбор_с is None:
                self._сбор_с = t
            # ТОЧКА СБОРА — ДОМ. Задание просило «безопасную точку», и первая редакция уводила бойцов на две клетки от его
            # кучи у дома; но мост и симулятор считают бойцов дальше одной клетки от ратуши ПОЛЕМ (§99), и «дома» падало до 2 —
            # переоценка выхода (ниже) не срабатывала никогда (p3: сбор с 485 с до конца партии). Поэтому копим дома:
            # бойцы без приказа дерутся с подошедшими сами, а при его группе к базе их держит оборона §105. Отдельная точка
            # сбора вне дома — когда мост научится считать её бойцов своими (просьба Windows: номер группы у STAGE).
            if у_дома := [c for c in его_кл if int(c.get("n") or 0) >= 5 and max(abs(int(c["x"]) - дом[0]), abs(int(c["y"]) - дом[1])) <= 1]:
                записи.append(f"его {sum(int(c['n']) for c in у_дома)} вплотную к дому — копим дома, встречаем на месте")
        elif any(c.get("cmd") in ("ATTACK", "ENGAGE") for c in оставить) and self._сбор_с is not None:
            # выход собранной группы одним приказом — сбор окончен
            оставить.insert(0, {"cmd": "STAGE", "off": 1})
            self.реестр.мера["ручеёк: тактов сбора"] += int(round((t - self._сбор_с) / 5.0))
            записи.append(f"СБОР_ОКОНЧЕН после {t - self._сбор_с:.0f} с, выход одним приказом")
            self._сбор_с, self._точка = None, None
        if (этап == "до" and self._сбор_с is not None and not отказано
                and not any(c.get("cmd") in ("ATTACK", "ENGAGE") for c in оставить) and дома >= 5):
            # ПОВТОРНАЯ ОЦЕНКА ВЫХОДА (задание: после накопления мост переоценивает и отправляет собранную группу одним приказом).
            # Без неё правило становилось запретом боя: стратегия считала первую волну отправленной и больше не пробовала
            # (p3: его убито 153 → 57, случайный уничтожена 51 → 20). Кандидаты — отложенная цель, ближняя его куча к дому,
            # его база; берётся лучший выгодный R.
            сила = ПР.состав_по_долям(дома, st)
            кандидаты = []
            if getattr(self, "_отложено", None):
                кандидаты.append(self._отложено[0])
            if его_кл:
                к = min((c for c in его_кл if int(c.get("n") or 0) >= 5), key=lambda c: max(abs(int(c["x"]) - дом[0]), abs(int(c["y"]) - дом[1])), default=None)
                if к is not None:
                    кандидаты.append((int(к["x"]), int(к["y"])))
            if _его_база(st) is not None:
                кандидаты.append(_его_база(st))
            лучший, лучший_любой = None, None
            остаток_при = float(self.п.get("остаток_при", 0.3) or 0.3)
            for цель in кандидаты:
                его = ПР.состав_из_клеток(его_кл, цель, окно)
                его = _его_с_лагерем(его, цель, st, getattr(self, 'п', {}))[0]   # §170ж
                if sum(его.values()) < 1:
                    continue
                у_базы = _его_база(st) is not None and max(abs(цель[0] - _его_база(st)[0]), abs(цель[1] - _его_база(st)[1])) <= 2
                п = ПР.новая_волна(сила, его, свои, чужие, у_базы)
                if п["R"] is None:
                    continue
                if лучший_любой is None or п["R"] > лучший_любой[1]["R"]:
                    лучший_любой = (цель, п)
                if (п["R"] >= порог or п.get("уничтожена")) and п["остаток_наш"] >= остаток_при and (лучший is None or п["R"] > лучший[1]["R"]):
                    лучший = (цель, п)
            # ВЫХОД ПО СРОКУ: сбор дольше `сбор_предел_с` (300) и лучшая цель не хуже `размен_мин` (0,7) — идём лучшей целью всей
            # силой, и это сказано вслух. Иначе правило — запрет боя: в p3 его 87 у базы ни разу не стали «выгодны» за партию,
            # а турнир без похода — поражение обоим (правила игрока)
            if лучший is None and лучший_любой is not None and t - self._сбор_с >= float(self.п.get("сбор_предел_с", 300) or 300) \
                    and лучший_любой[1]["R"] >= float(self.п.get("размен_мин", 0.7) or 0.7) and лучший_любой[1]["остаток_наш"] >= остаток_при:
                лучший = лучший_любой
                записи.append(f"ВЫХОД_ПО_СРОКУ: сбор {t - self._сбор_с:.0f} с ≥ предела, лучшая цель R={лучший[1]['R']} ≥ {float(self.п.get('размен_мин', 0.7) or 0.7)}")
                self.реестр.мера["ручеёк: выход по сроку"] += 1
            if лучший is not None:
                цель, п = лучший
                оставить.insert(0, {"cmd": "STAGE", "off": 1})
                оставить.append({"cmd": "ATTACK", "count": дома, "target": "cell", "cx": цель[0], "cy": цель[1], "face": [цель[0], цель[1]]})
                self.реестр.мера["ручеёк: тактов сбора"] += int(round((t - self._сбор_с) / 5.0))
                self.реестр.мера["ручеёк: выход после сбора"] += 1
                записи.append(f"СБОР_ОКОНЧЕН после {t - self._сбор_с:.0f} с: {дома} одним приказом → {цель[0]},{цель[1]}: {ПР.словами(п)}")
                self._сбор_с, self._точка, self._отложено = None, None, None
        if self._сбор_с is not None and t - self._сбор_с >= float(self.п.get("сбор_макс_с", 180) or 180) and этап == "до":
            # долгий сбор: вернуть выбор — его крестьяне без охраны (R ≥ порога) или назвать лучший R
            лучший = max((p for p in self.прогнозы if p["t"] >= t - 30 and p["R"] is not None), key=lambda p: p["R"], default=None)
            охота = None
            сила = ПР.состав_по_долям(дома, st)
            for кр in _клетки_крестьян(st, его_кл):
                if int(кр.get("крестьян") or 0) < 3:
                    continue
                кл = (int(кр["x"]), int(кр["y"]))
                охр = ПР.состав_из_клеток(его_кл, кл, 1)
                п = ПР.новая_волна(сила, охр, свои, чужие) if sum(охр.values()) >= 1 else dict(R=ПР.R_МАКС)
                if п["R"] is not None and п["R"] >= порог and (охота is None or int(кр["крестьян"]) > охота[1]):
                    охота = (кл, int(кр["крестьян"]), п["R"])
            if охота and дома >= 5 and not any(c.get("cmd") in ("ATTACK", "ENGAGE") for c in оставить):
                кл, кр_n, R = охота
                оставить.insert(0, {"cmd": "STAGE", "off": 1})
                оставить.append({"cmd": "ATTACK", "count": дома, "target": "cell", "cx": кл[0], "cy": кл[1], "face": [кл[0], кл[1]]})
                self.реестр.мера["ручеёк: перенацелено на охоту"] += 1
                записи.append(f"СБОР_ЗАТЯНУЛСЯ {t - self._сбор_с:.0f} с → ОХОТА: его крестьяне {кр_n} в {кл[0]},{кл[1]} без охраны (R={R}), идут {дома}")
                self._сбор_с, self._точка = None, None
            elif int(t) % 60 < 5:
                записи.append(f"СБОР_ЗАТЯНУЛСЯ {t - self._сбор_с:.0f} с: дома {дома}, лучшая цель за 30 с "
                              + (f"R={лучший['R']} ({лучший['случай']}, наших {лучший['наших']:.0f} против {лучший['его']:.0f})" if лучший else "не оценивалась")
                              + "; варианты: другая цель (крестьян без охраны нет), другой маршрут — не умею, состав — стрелков "
                              f"{100 * float(st.get('mil_shooters') or 0) / max(1.0, float(st.get('mil_inf') or 0) + float(st.get('mil_shooters') or 0)):.0f} %; копим дальше")
        return оставить, "; ".join(записи)

    def _огонь_рядом(self, из: list, st: dict):
        """ОГОНЬ СТРЕЛКАМИ ПО ЕГО ГРУППЕ В СОСЕДНЕЙ КЛЕТКЕ (18.10, §164, ключ `огонь_рядом` — наших стрелков не меньше; задание
        игрока «стрельба из соседней клетки к Д8»). Д7: его 96–102 (стрелков 41–46) шли СТРОЕМ (form 2) от (5,12) 11:26 до
        (11,13) 12:36 — семь клеток за 70 с, по дороге musketeernet 1.1–1.3 — и в 12:38 вошли в клетку нашей ратуши (12,13):
        139 : 51, пулями 40. Бот за это время не отдал ни одного приказа; наши 135 стояли кучей, 15 мушкетёров внутри неё.
        Д6 11:25 — зеркально (наши вошли в его стоящих — 84 за 15 с). Fable 3/3 по Д6: «Г — стрелять мушкетёрами, пики стоят:
        стрельба засчитывается как атака, а его пики либо терпят огонь, либо лезут сами». Правило: его бойцов не меньше
        `огонь_его_от` (10) в клетках не дальше `огонь_клеток` (1) от ратуши — соседних или в самой клетке ратуши (клетка 16
        единиц, выстрел мушкетёра 15: дальше соседней не достать, а идут они или стоят — стрелять всё равно) — и наших
        стрелков ≥ ключа: `ATTACK all who=musk17` в его клетку (режим атаки блока: идут на цель и бьют, кого видят, —
        мушкетёр встаёт на выстреле), лицом к ней; повтор каждые `огонь_повтор` (15) с, пока он там. В Д7 огонь открылся бы
        в 12:31 (его 26 в (11,13)) — за 7 с до удара: клетки грубые, раньше соседней клетки не достать. Пики приказа не
        получают (куча у ратуши стоит, как стояла; удержание строя — §161, отдельно). Приказ помечен `_огонь`: номер волны
        ему не даётся, цель волны по нему не пишется, MOVE того же такта без `who` (кулак §143) идёт пиками, чтобы не уводить
        стрелков. Судья — Д8 живьём: строка `ОГОНЬ: …`, в game.log `ATTACK N target=cell`, потери первых 30 с по `потери_такт`."""
        ключ = float(self.п.get("огонь_рядом", 0) or 0)
        if ключ <= 0:
            return из, ""
        _с = getattr(self, "_судья", None)          # судья удара (4.11): прогноз лагеря ниже порога — огонь не открывается
        if _с and _с.get("нет"):
            self._огонь = None
            self.реестр.мера["судья удара: огонь не открыт"] += 1
            return из, f"ОГОНЬ не открыт: судья удара — {_с['причина']} (R={_с['R'] if _с['R'] is None else format(_с['R'], '.2f')}, порог {_с['порог']:g}, его {_с['n']} в {_с['рад']:g} кл.)"
        import coss3_map as _КМ
        дом = _наша_база(st)
        стрелков = float(st.get("mil_shooters") or 0)
        t = float(st.get("gametime") or 0)
        его_от = float(self.п.get("огонь_его_от", 10) or 10)
        клеток = int(float(self.п.get("огонь_клеток", 1) or 1))
        повтор = float(self.п.get("огонь_повтор", 15) or 15)
        _ч = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        рядом, стоящих = {}, 0.0
        for к in _список(st, "ecells", _КМ.его_клетки):
            n = float(к.get("n") or 0)
            if n <= 0 or _ч((к["x"], к["y"]), дом) > клеток:
                continue
            кл = (int(к["x"]), int(к["y"]))
            рядом[кл] = рядом.get(кл, 0.0) + n
            идут = float(к.get("идут") or 0)
            if идут > 0 and к.get("tx") is not None and int(к.get("tx")) >= 0 and _ч((к["tx"], к["ty"]), кл) <= 1:
                идут = 0.0                      # цель рядом с собой — держит строй, не марш (§162)
            стоящих += max(0.0, n - идут)
        всего = sum(рядом.values())
        if всего < его_от:
            if getattr(self, "_огонь", None) is not None:
                self._огонь = None
                return из, f"ОГОНЬ кончен: его у ратуши {всего:.0f} < {его_от:g}"
            return из, ""
        if стрелков < ключ:
            return из, f"ОГОНЬ не открыт: стрелков {стрелков:.0f} < {ключ:g} при его {всего:.0f} у ратуши"
        кл = max(рядом, key=рядом.get)
        бывший = getattr(self, "_огонь", None)
        if бывший is not None and бывший.get("кл") == кл and t - бывший["t"] < повтор:
            return из, ""
        self._огонь = {"кл": кл, "t": t}
        self.реестр.мера["огонь рядом: приказ"] += 1
        for c in из:
            if c.get("cmd") == "MOVE" and not c.get("who") and str(c.get("count", "")).strip() not in ("", "0"):
                c["who"] = "infantry17"          # кулак/заслон того же такта — пиками: стрелки под огнём остаются
        приказ = {"cmd": "ATTACK", "count": "all", "who": "musk17", "target": "cell", "cx": кл[0], "cy": кл[1],
                  "face": [кл[0], кл[1]], "_огонь": True}
        где = "в клетке ратуши" if кл == tuple(дом) else f"в {_ч(кл, дом)} кл. от ратуши"
        # ПИКИ ПО ПРАВУ ОГНЯ (1.11, слово игрока «делай второе»; живая партия с обходом e14ed8d): ОГОНЬ увидел его 15 в 1 кл. от
        # ратуши на 636 с и 51 на 651 с — за 25 с до первой смерти, — послал одних стрелков, «пики стоят», при 186 праздных и
        # 38–43 наших пиках в клетке ратуши; 48 крестьян легли в клетках d = 1. Ключ `огонь_пики` N (0 — как было): вторым
        # ATTACK того же такта (политика возит второй удар, §78) — пики `who=infantry17` числом max(N, `огонь_пики_доля` (1,5)
        # × его в этой клетке) в ту же клетку. Клетки — те же, что у ОГНЯ: не дальше `огонь_клеток` (1) от ратуши, поэтому
        # приманка в двух клетках счёт не размывает. Счётный приказ берёт праздных пик; держащих у дома берёт блок
        # (оборонительная ATTACK). Помечен `_огонь`: номер волны не даётся, запрет атаки до срока его не снимает.
        _пк = int(float(self.п.get("огонь_пики", 0) or 0))
        if _пк > 0:
            _нужно = max(_пк, int(-(-float(self.п.get("огонь_пики_доля", 1.5) or 1.5) * рядом[кл] // 1)))
            пики = {"cmd": "ATTACK", "count": _нужно, "who": "infantry17", "target": "cell", "cx": кл[0], "cy": кл[1],
                    "face": [кл[0], кл[1]], "_огонь": True}
            self.реестр.мера["огонь рядом: пики"] += 1
            return [приказ, пики] + из, (f"ОГОНЬ: его {всего:.0f} (стоящих {стоящих:.0f}) {где} ({кл[0]},{кл[1]}), стрелков "
                                         f"{стрелков:.0f} — ATTACK стрелками в клетку и пиками {_нужно} (его в клетке {рядом[кл]:.0f})")
        return [приказ] + из, (f"ОГОНЬ: его {всего:.0f} (стоящих {стоящих:.0f}) {где} ({кл[0]},{кл[1]}), стрелков {стрелков:.0f} — "
                               f"ATTACK стрелками в клетку, пики стоят")

    def _отряд_в_поле(self, из: list, st: dict):
        """ОТРЯД В ПОЛЕ НЕ СТОИТ ПОД УДАРОМ (2.11, второй круг качелей). Девять случаев в пяти прогонах: наш отряд 69–217
        стоит в поле (дальше двух клеток от ратуши) в удержании без приказа, рядом — его 7–50, и за 20–130 с наших гибнет
        18–119 при его 0–29 (всего 488 против 96). Пример swing_net/1 20:36–21:37: отряд 184 в линию в (8,7), его 27–32
        из соседней клетки срезали его до 131 (74 наших против 15 за минуту). Удержание бьёт только подошедших к месту в
        строю — малая группа режет край. Ключ `отряд_отвечает` 1 (0 — как было): отряд в поле с удержанием, его в клетке
        отряда или соседней не меньше 5 и меньше `отряд_отвечает_доля` (0,5) отряда, приказа ATTACK в этом такте нет —
        ATTACK в его клетку `all` (каждый отряд строем, удержание снято) и числом 1. Ключ `отряд_отвечает_потери` 1 —
        только если с прошлого такта у нас есть убитые (его группа уже бьёт). Повтор не чаще `отряд_отвечает_повтор` (10) с.
        Помечен `_отряд`: номер волны не даётся."""
        п = self.п
        if not int(float(п.get("отряд_отвечает", 0) or 0)):
            return из, ""
        t = float(st.get("gametime") or 0)
        потери = int(float(st.get("my_mil_lost") or 0))
        было = getattr(self, "_отряд_потери", None)
        self._отряд_потери = потери
        if any(c.get("cmd") == "ATTACK" for c in из):
            return из, ""
        список = str(st.get("squads_list") or "")
        отряды = []
        for кусок in список.split(";"):
            ч = кусок.split(",")
            if len(ч) >= 6 and ч[1].strip().isdigit():
                try:
                    отряды.append((int(ч[1]), int(ч[3]), int(ч[4]), ч[5].strip() == "1"))
                except ValueError:
                    continue
        if not отряды:
            return из, ""
        n, x, y, удерж = max(отряды)
        д = _дом(st)
        if not удерж or max(abs(x - д[0]), abs(y - д[1])) <= 2:
            return из, ""
        import coss3_map as _КМ
        кучи = {}
        for к in _список(st, "ecells", _КМ.его_клетки):
            кх, ку, кn = int(к.get("x", -9)), int(к.get("y", -9)), int(к.get("n") or 0)
            if кn > 0 and max(abs(кх - x), abs(ку - y)) <= 1:
                кучи[(кх, ку)] = кучи.get((кх, ку), 0) + кn
        рядом = sum(кучи.values())
        доля = float(п.get("отряд_отвечает_доля", 0.5) or 0.5)
        # КРУПНАЯ СИЛА У СТОЯЩЕГО ОТРЯДА (3.11, слово игрока «делай»; 58 сторон бот против бота 2–3.11). Отряд в удержании без
        # набранного бонуса (37,5 с неподвижности, gc_squad_holdmode_time; под ударом бойцы шевелятся, и бонус не копится) терял
        # ≥ 5 за такт 50 раз: в 25 из них (332 бойца) рядом было его ≥ половины отряда — и правило выше молчало, отряд стоял и
        # таял. Ключ `отряд_крупным` 1 (0 — как было): при таком «рядом» наш отряд не меньше `отряд_крупным_перевес` (1,0) × его —
        # ATTACK отрядом (как в малом случае), меньше — RETREAT отрядом к ратуше. Повтор и условие потерь — те же.
        крупным = рядом >= доля * n and рядом >= 5 and int(float(п.get("отряд_крупным", 0) or 0))
        if рядом < 5 or (рядом >= доля * n and not крупным):
            return из, ""
        if int(float(п.get("отряд_отвечает_потери", 0) or 0)) and (было is None or потери <= было):
            return из, ""
        _был = getattr(self, "_отряд_at", None)
        if _был is not None and 0 <= t - _был < float(п.get("отряд_отвечает_повтор", 10) or 10):
            return из, ""
        цель = max(кучи, key=кучи.get)
        из = [c for c in из if c.get("cmd") not in ("MOVE", "RETREAT", "FACE", "ENGAGE")]
        if крупным and n < float(п.get("отряд_крупным_перевес", 1.0) or 1.0) * рядом:
            из.insert(0, {"cmd": "RETREAT", "count": n, "all": 1, "target": "cell", "cx": int(д[0]), "cy": int(д[1]),
                          "_отряд": True})
            self._отряд_at = t
            self.реестр.мера["отряд в поле: крупным — отход"] += 1
            return из, (f"ОТРЯД ОТХОДИТ: отряд {n} в ({x},{y}) в удержании, его {рядом} рядом (≥ {доля:g} × {n}, больше нашего) — "
                        f"RETREAT отрядом к ратуше ({д[0]},{д[1]})")
        if крупным:
            self.реестр.мера["отряд в поле: крупным — удар"] += 1
        из.insert(0, {"cmd": "ATTACK", "count": 1, "all": 1, "target": "cell", "cx": int(цель[0]), "cy": int(цель[1]),
                      "_отряд": True})
        self._отряд_at = t
        self.реестр.мера["отряд в поле: ответил"] += 1
        return из, (f"ОТРЯД ОТВЕЧАЕТ: отряд {n} в ({x},{y}) в удержании, его {рядом} рядом (< {доля:g} × {n}) — "
                    f"ATTACK отрядом в ({цель[0]},{цель[1]})")

    def _отряд_волны(self, st: dict):
        """ОТРЯД — ЧАСТЬ ВОЛНЫ (2.11, разбор aca2_pol/1). Ключ `отряд_в_волне` 1 (0 — как было): наш крупнейший отряд, стоящий
        в поле (дальше клетки от ратуши), считается частью волны. Иначе три правила его не видят: отряд 216 шёл строем к его
        базе, а волной числились 4–8 свободных дома — «отход при подходе» по ним звал «все домой» (15:06), «сироты» четыре
        раза отзывали «наших 321 в поле без волны» (15:21–16:59), удар судился «дома 35–72 — мало сил». Fable Б/Б/Г.
        Возвращает {"n", "x", "y"} или None."""
        if not int(float(self.п.get("отряд_в_волне", 0) or 0)):
            return None
        лучший = None
        for кусок in str(st.get("squads_list") or "").split(";"):
            ч = кусок.split(",")
            if len(ч) >= 5 and ч[1].strip().isdigit():
                try:
                    n, x, y = int(ч[1]), int(ч[3]), int(ч[4])
                except ValueError:
                    continue
                if лучший is None or n > лучший["n"]:
                    лучший = {"n": n, "x": x, "y": y}
        if лучший is None or лучший["n"] <= 0:
            return None
        д = _дом(st)
        if д is None or max(abs(лучший["x"] - д[0]), abs(лучший["y"] - д[1])) <= 1:
            return None
        return лучший

    def _резак_крестьян(self, из: list, st: dict):
        """РЕЗАК ПО КРЕСТЬЯНАМ, ПОКА АРМИЯ ЗАНЯТА, И ДОРОГА К НИМ (1.11, замысел игрока по его же приёму против нас).
        Живая Польша 6680: игрок разделил силы — 66 пик встали приманкой в (14,12), а 20 остались В КЛЕТКЕ нашей
        ратуши и за пять минут убили 60 крестьян при наших 1–12 там же. Бот так не умеет, и не хватает ему ровно
        одного звена: приманку он создаёт сам (любая волна на его базу или лагерь оттягивает его армию), а правило
        охоты (§113) посылает ВСЕХ и только когда сбор затянулся. Нужен ВТОРОЙ, МАЛЫЙ удар по крестьянам в то время,
        когда большая армия уже в поле.
        Ключ `резак_крестьян` N (0 — как было): когда наших в поле (`mil_far`) не меньше `резак_армия` (50) и у него
        есть клетка с крестьянами ≥ `резак_крестьян_от` (3) при охране рядом < `резак_охрана` (3) — уходит
        `ATTACK count=N who=musk17` в эту клетку лицом к ней. Стрелками нарочно: быстрее пики и переживают отход.
        ПРАВИЛЬНО ПОДОЙТИ (просьба игрока): из годных клеток берётся та, у которой МЕНЬШЕ ВСЕГО его бойцов по дороге —
        его `ecells` в коридоре `резак_коридор` (1 клетка) от прямой «наша ратуша → цель»; при равной дороге берётся
        клетка с большим числом крестьян. Иначе пачка идёт сквозь его строй и гибнет, не дойдя: клетка 16 единиц,
        пика бьёт в упор, и шесть мушкетёров в чужой куче не живут (`world.md`, «стрелок в упор не стреляет»).
        Повтор не чаще `резак_повтор` (60) с и только в такт, где другого ATTACK нет — слот приказа один на такт.
        Приказ помечен `_резак`: номер волны ему не даётся и цель волны по нему не пишется, иначе он подменит
        основную волну в реестре. Судья — серия в контейнере: его крестьян убито по СОБЫТИЯМ ГИБЕЛИ, а не по
        `p1_pea_lost` (тот считает и голод — поправка 50602af), при живой основной волне."""
        ключ = int(float(self.п.get("резак_крестьян", 0) or 0))
        if ключ <= 0:
            return из, ""
        if any(c.get("cmd") in ("ATTACK", "ENGAGE") for c in из):
            return из, ""                      # слот приказа один: резак идёт в такт без другого удара (молчим: это норма такта)
        t = float(st.get("gametime") or 0)
        бывший = getattr(self, "_резак", None)
        повтор = float(self.п.get("резак_повтор", 60) or 60)
        if бывший is not None and t - бывший["t"] < повтор:
            return из, ""
        в_поле = float(st.get("mil_far") or 0)
        # 4.11 (205): 0 — приманка не нужна (налётчик Турции ходит сам); прежде `or 50` подменял ноль умолчанием
        _ра = self.п.get("резак_армия")
        нужно = 50.0 if _ра is None or _ра == "" else float(_ра)
        if в_поле < нужно:
            self.реестр.мера["резак: армия дома"] += 1
            if t - float(getattr(self, "_резак_сказал", -999.0)) >= 120.0:
                self._резак_сказал = t
                return из, f"РЕЗАК ждёт: наших в поле {в_поле:.0f} < {нужно:g} — приманки нет, резать нечем прикрыть"
            return из, ""
        import coss3_map as _КМ
        его_кл = _список(st, "ecells", _КМ.его_клетки)
        дом = _наша_база(st)
        кр_от = float(self.п.get("резак_крестьян_от", 3) or 3)
        охр_до = float(self.п.get("резак_охрана", 3) or 3)
        коридор = float(self.п.get("резак_коридор", 1) or 1)

        def _по_дороге(цель):
            """Его бойцы в коридоре вокруг прямой «ратуша → цель», кроме самой клетки цели (её охрана считана выше)."""
            шагов = max(abs(int(цель[0]) - int(дом[0])), abs(int(цель[1]) - int(дом[1])))
            if шагов <= 0:
                return 0.0
            точки = [(дом[0] + (цель[0] - дом[0]) * i / float(шагов),
                      дом[1] + (цель[1] - дом[1]) * i / float(шагов)) for i in range(1, шагов + 1)]
            сумма = 0.0
            for к in его_кл:
                кx, кy = int(к["x"]), int(к["y"])
                if (кx, кy) == (int(цель[0]), int(цель[1])):
                    continue
                if any(max(abs(кx - x), abs(кy - y)) <= коридор for x, y in точки):
                    сумма += float(к.get("n") or 0)
            return сумма

        годные = []
        for кр in _клетки_крестьян(st, его_кл):
            n = float(кр.get("крестьян") or 0)
            охр = float(кр.get("бойцов_рядом") or 0)
            if n < кр_от or охр >= охр_до:
                continue
            кл = (int(кр["x"]), int(кр["y"]))
            годные.append((_по_дороге(кл), -n, кл, n, охр))
        if not годные:
            # ПОЧЕМУ МОЛЧИМ — вслух (правило 1 проекта). 1.11: по архиву я не смог отличить «цели не было» от
            # «правило не звали», потому что сетки крестьян в снимок не кладут; теперь причина в `why`.
            всего = len(_клетки_крестьян(st, его_кл))
            self.реестр.мера["резак: цели нет"] += 1
            if t - float(getattr(self, "_резак_сказал", -999)) >= 120:
                self._резак_сказал = t
                return из, (f"РЕЗАК: цели нет — клеток с его крестьянами видно {всего}, годных (≥ {кр_от:g} "
                            f"крестьян при охране < {охр_до:g}) ни одной; наших в поле {в_поле:.0f}")
            return из, ""
        годные.sort()
        дорога, _, кл, n, охр = годные[0]
        худшая = max(г[0] for г in годные)
        дорога_до = float(self.п.get("резак_дорога_до", 0) or 0)
        if дорога_до > 0 and дорога > дорога_до:
            # 1.11, копия 1 peasant_raid_vs_ai: годной была ОДНА клетка, и правило пошло сквозь 83 его бойца —
            # минимум может быть безнадёжен. Предел называется ключом; молчать нельзя (правило 1 проекта).
            self.реестр.мера["резак: отказ по дороге"] += 1
            self._резак = {"t": t, "кл": кл}
            return из, (f"РЕЗАК НЕ ИДЁТ: лучшая клетка ({кл[0]},{кл[1]}) с {n:.0f} крестьянами, но по дороге его "
                        f"{дорога:.0f} > {дорога_до:g} — пачка {ключ} не дойдёт")
        self._резак = {"t": t, "кл": кл}
        self.реестр.мера["резак: приказ"] += 1
        self.реестр.мера["резак: его по дороге"] += int(дорога)
        # 4.11 (205): род пачки — ключ `резак_who` (умолчание musk17, как было). Турецкий налётчик ставит uniq_cav17 —
        # это татарин (конный лучник 20,6 тайла); пешего лучника блок в ATTACK по роду не адресует (нет `archer` в who)
        _род = str(self.п.get("резак_who", "musk17") or "musk17")
        приказ = {"cmd": "ATTACK", "count": ключ, "who": _род, "target": "cell",
                  "cx": кл[0], "cy": кл[1], "face": [кл[0], кл[1]], "_резак": True}
        # ОТХОД РЕЗАКА (1.11, замер 3 на 3: размен 1,03 против 1,34 без правила — пачка доходила и оставалась, стачиваясь).
        # Ключ `резак_отход` N с (0 — как было): приказ получает свой номер группы РЕЗАК и `ret` N — через N игровых секунд
        # БЛОК сам ведёт живых из её состава домой (раз в секунду, без слота приказа python; лог `GROUP 96 retreat`).
        _отход = int(float(self.п.get("резак_отход", 0) or 0))
        if _отход > 0:
            приказ["group"], приказ["ret"] = self.РЕЗАК, _отход
        про_дорогу = (f"дорога чиста (его по коридору 0)" if дорога <= 0
                      else f"по дороге его {дорога:.0f}" + (f", у худшей из {len(годные)} клеток {худшая:.0f}" if худшая > дорога else ""))
        return [приказ] + из, (f"РЕЗАК: его крестьян {n:.0f} в ({кл[0]},{кл[1]}), охраны {охр:.0f}, {про_дорогу} — "
                               f"ATTACK {ключ} {_род}, пока наших в поле {в_поле:.0f}"
                               + (f", группой {self.РЕЗАК}, домой через {_отход} с" if _отход > 0 else ""))

    def _оборона(self, из: list, st: dict):
        """Реакция на угрозу базе (`угрозы.оценить`). Проверка 6: его 25 шли к нашей ратуше с 4:05, в 5:01 дома
        было 32 наших против его 25 — а в 5:56 армия ушла в поле, в 7:12 ещё 21 — на ЕГО базу; набег пришёл в
        7:00 к 7 нашим, убито 24 крестьянина. Два правила, оба по картине, а не по часам:
          * НЕ УХОДИТЬ: пока его группа идёт к базе и придёт за `оборона_окно` с (150), приказы, которые берут
            бойцов ИЗ ДОМА (ATTACK/ENGAGE/MOVE с числом), не уезжают; приказы группам по номеру — уезжают;
          * ВЕРНУТЬ ВОЛНУ: если дома наших меньше, чем его × `оборона_перевес` (1,2), а живая волна в поле —
            RETREAT ей по номеру домой, лицом к нему; волна до прихода домой не бьёт (состояние ДОМОЙ).
        Встречу у дома ведёт сам движок (бойцы без приказа бьют подошедших); удержание строя (§102) — дальше.
        Ключа нет — ничего не делает. Возвращает (команды, запись для why или '')."""
        self._держим_дом = False
        self._подход = None                  # §152: его группа, идущая к базе (для `не_навстречу` в `_удар_готовой`)
        if not float(self.п.get("оборона", 0) or 0):
            return из, ""
        try:
            import угрозы as _УГ
            уг = _УГ.оценить(st)
        except Exception:
            return из, ""
        б, д = уг["база"], уг["дом"]
        окно = float(self.п.get("оборона_окно", 150) or 150)
        волна = self.реестр.активная()
        if волна is not None and волна.состояние == "ДОМОЙ" and д is not None:
            if max(abs(волна.сбор[0] - д[0]), abs(волна.сбор[1] - д[1])) <= 1:
                волна.состояние = "ГОТОВА"          # дома: дальше решает контракт (его рядом — БОЙ_ИДЁТ)
        if not б["его"] or б["сек"] is None or б["сек"] > окно or д is None:
            _дг = getattr(self, "_дг", None) or {}
            if д is not None and _дг.get("клетка") is not None and _дг.get("удар") is None and (_дг.get("ждут") or _дг.get("держат") or
                    (int(self.п.get("стрелки_позади", 0) or 0) >= 1 and _дг.get("стрелки") is None)):
                # §170г (22.10, Д11): шаги встречи НЕ зависят от окна обороны. Живьём встреча объявлена в 9:15, его подход
                # вышел из окна раньше 20 с, и FACE не ушёл ни разу (бонус отряда 2 вместо 7). Лицо — его последняя куча.
                try:
                    из, зап3 = self._встреча_строй(из, st, _дг, _дг.get("лицо") or д, д, int(float(st.get("my_freewar") or 0)), float(st.get("gametime") or 0))
                    if зап3:
                        return из, зап3
                except Exception as e:
                    return из, f"встреча не досчитана: {type(e).__name__}"
            if д is not None and float(self.п.get("оборона_две_группы", 0) or 0) and (getattr(self, "_дг", None) or {}).get("удар") is not None:
                try:
                    из, зап2 = self._две_группы(из, st, уг, б, д)      # §143: отряд в ударе — вернуть к ратуше, когда клетка опустела
                    return из, зап2
                except Exception as e:
                    return из, f"две группы не посчитаны: {type(e).__name__}"
            return из, ""
        _лагерь = self._бой_за_лагерь(st)

        def из_дома(c):
            if c.get("cmd") not in ("ATTACK", "ENGAGE", "MOVE") or c.get("group"):
                return False
            if _лагерь and str(c.get("target") or "") == "wave":
                return False               # §124: подток к волне, бьющей лагерь у базы, — это оборона
            n = c.get("count", 0)
            return (isinstance(n, str) and n.strip().lower() in ("all", "все")) or float(n or 0) > 0
        оставить = [c for c in из if not из_дома(c)]
        снято = len(из) - len(оставить)
        self._держим_дом = True            # и удар готовой волны не возьмёт бойцов из дома (`_удар_готовой`)
        self._подход = dict(б)
        запись = (f"ОБОРОНА: его {б['его']} (стрелков {б['стрелков']}) к базе через ~{б['сек']} с, "
                  f"наших дома {б['наших_дома']}")
        if снято:
            запись += f", приказов из дома не отдано {снято}"
            self.реестр.мера["оборона: не ушли из дома"] += снято
        # §143 ОБОРОНА ДВУМЯ ГРУППАМИ (10.10, партия Д2 10:33-12:00, слова игрока 7.10 «разделить армию: одна прикрывает,
        # другая убивает мушкетёров»). Вживую наши 55 стояли в (1,13) без приказа; его 67-78 пик вошли к ним, бой 33 за 6; его
        # 38 прошли в клетку ратуши-мельницы (2,14) и за 15 с убили 41 крестьянина; его 12-25 мушкетёров шли следом и били
        # из-за спины пик. Ключ `оборона_две_группы` 1: когда его силы идут к базе (окно `оборона_окно`), свободных дома не
        # меньше `две_группы_от` (20) и нет нашего удара по лагерю —
        #   ЗАСЛОН (2/3 свободных, группа 91) — в клетку на шаг от ратуши навстречу его главной куче, лицом к ней, стоять;
        #   ОТРЯД (остальные, группа 92) — в клетку ратуши: крестьяне и мельница под ногами;
        #   и дальше каждый такт: его клетка со стрелками (≥ `две_группы_стрелков` 5, пик в ней ≤ половины отряда) в двух
        #   клетках от ратуши и прогноз отряда против неё R ≥ `две_группы_R` (1,2) — ATTACK отряда в эту клетку; клетка
        #   опустела — отряд назад в клетку ратуши. Новый подход после затишья 60 с — заслон и отряд ставятся заново.
        # Двойник: §143 ветки «заслон/две группы/у ратуши» в развилке Д2 (sim/решения/д2_осада.md); судья — живая партия.
        if float(self.п.get("оборона_две_группы", 0) or 0) and not _лагерь:
            try:
                оставить, зап2 = self._две_группы(оставить, st, уг, б, д)
                if зап2:
                    запись += "; " + зап2
            except Exception as e:
                запись += f"; две группы не посчитаны: {type(e).__name__}"
        перевес = float(self.п.get("оборона_перевес", 1.2) or 1.2)
        if (волна is not None and волна.подтверждена and волна.состояние not in ("ДОМОЙ", "КОНЧЕНА")
                and not _лагерь
                and б["наших_дома"] < перевес * б["его"]
                and max(abs(волна.сбор[0] - д[0]), abs(волна.сбор[1] - д[1])) > 1):
            цель = next((г for г in уг["группы"] if г["что"] == "база"), None)
            лицо = list(цель["куда"]) if цель else [д[0], д[1]]
            оставить = [c for c in оставить if c.get("group") != волна.номер]
            оставить.insert(0, {"cmd": "RETREAT", "count": 0, "target": "cell", "cx": int(д[0]), "cy": int(д[1]),
                                "group": волна.номер, "face": лицо})
            волна.состояние = "ДОМОЙ"
            волна.цель_клетка = (int(д[0]), int(д[1]))
            запись += f"; волна {волна.id} ({волна.размер}) ДОМОЙ лицом к {лицо[0]},{лицо[1]}"
            self.реестр.мера["оборона: волна домой"] += 1
        return оставить, запись

    # §170д (23.10): ПОДМОГА была 93 — тот же номер, что у заслона §152 (`ЗАСЛОН_ПОЛЯ`); парсер групп (§150) слил бы составы
    ЗАСЛОН, ОТРЯД, ПОДМОГА = 91, 92, 94
    КАЙТ = 95                                   # §170о: группа стрелков «залп и шаг назад»
    РЕЗАК = 96                                  # 1.11: пачка по его крестьянам с отходом блоком (`резак_отход`)
    СТОРОЖ0 = 81                                # 4.11 (204): сторожа шахт против налётов Турции — группы 81..85

    def _кайт(self, из: list, st: dict, t: float):
        """§170о (26.10, вопрос игрока «можно ли мушкетёром: выстрел, отход, выстрел — пока не перебьёт пику?»).
        По движку (unit.script): мушкетёр стреляет с 7,5 до 15 тайлов, перезарядка 3,75 с, пика достаёт на 1,9, а
        скорость у всей пехоты ОДНА (gc_obj_speed_default) — один стрелок одну пику не перекайтит: от 15 до 7,5 он
        успевает шесть залпов, дальше она сидит в мёртвой зоне. Двадцать мушкетёров за шесть залпов снимают 13 польских
        пик или 8 net — множитель перед рукопашной, не замена ей. Секундную часть ведёт блок (команда KITE, режим 5
        группы): такт python 5 с и клетка 16 тайлов для этого слишком грубы. Здесь — только ВКЛЮЧИТЬ и ОТПУСТИТЬ:
          * ключ `кайт` 1 (0 — как было); его пики (`ecells`, столбец пик) в `кайт_клеток` (2) от клетки ратуши,
            наших стрелков ≥ `кайт_от` (6) и наших пик меньше его × `кайт_пик_доля` (1,0) → KITE всем musk17 группой
            КАЙТ 95 лицом к его ближней клетке, с `кайт_зазор` (1,0 тайла к rmin), `кайт_шаг` (4,0) и `кайт_край`
            (30 тайлов от ратуши — дальше стоять); группа 95 в `groups` живьём не видна (блок перечисляет 1..16),
            поэтому состояние держится здесь;
          * его пик в радиусе нет и прошло ≥ `кайт_мин_с` (20) → MOVE группе 95 в клетку ратуши: любой другой приказ
            группе снимает режим в блоке (`kite released by MOVE`).
        Возвращает (команды, запись для why или '')."""
        п = self.п
        if int(п.get("кайт", 0) or 0) < 1:
            return из, ""
        try:
            д = (int(float(st.get("my_cx"))), int(float(st.get("my_cy"))))
        except (TypeError, ValueError):
            return из, ""
        import coss3_map as _КМ
        _ч = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        р = int(п.get("кайт_клеток", 2) or 2)
        его = [c for c in _список(st, "ecells", _КМ.его_клетки)
               if int(c.get("пик") or 0) > 0 and _ч((c["x"], c["y"]), д) <= р]
        его_пик = sum(int(c.get("пик") or 0) for c in его)
        стр = int(float(st.get("mil_shooters") or 0))
        сост = getattr(self, "_кайт_сост", None)
        if сост is None:
            if его_пик < 1 or стр < int(п.get("кайт_от", 6) or 6):
                return из, ""
            наших_пик = int(float(st.get("mil_inf") or 0))
            if наших_пик >= его_пик * float(п.get("кайт_пик_доля", 1.0) or 1.0):
                return из, ""
            бл = min(его, key=lambda c: (_ч((c["x"], c["y"]), д), -int(c.get("пик") or 0)))
            из = [c for c in из if c.get("group") != self.КАЙТ]
            из.insert(0, {"cmd": "KITE", "count": "all", "who": "musk17", "group": self.КАЙТ,
                          "face": [int(бл["x"]), int(бл["y"])],
                          "gap": float(п.get("кайт_зазор", 1.0) or 1.0), "step": float(п.get("кайт_шаг", 4.0) or 4.0),
                          "far": float(п.get("кайт_край", 30) or 30)})
            self._кайт_сост = {"t": t}
            self.реестр.мера["кайт: включён"] += 1
            return из, (f"§170о кайт: стрелков {стр} против его пик {его_пик} в {(int(бл['x']), int(бл['y']))} при наших "
                        f"пиках {наших_пик} — группа {self.КАЙТ} залп и шаг назад")
        if его_пик < 1 and t - float(сост.get("t") or 0) >= float(п.get("кайт_мин_с", 20) or 20):
            self._кайт_сост = None
            из = [c for c in из if c.get("group") != self.КАЙТ]
            из.insert(0, {"cmd": "MOVE", "count": 0, "group": self.КАЙТ, "target": "cell", "cx": int(д[0]), "cy": int(д[1])})
            self.реестр.мера["кайт: отпущен"] += 1
            return из, f"§170о кайт: его пик в {р} клетках от ратуши нет — группа {self.КАЙТ} домой в {д}, режим снят"
        return из, ""

    РАШ = 97                                    # 4.11 (214): поток пик на его базу

    def _режим_турции(self, st: dict) -> str:
        """РЕЖИМ РАЗМЕНА ПРОТИВ ТУРЦИИ (4.11 (214), слово игрока: «если противник Турция — идём в размен на базу человека
        пикой сразу, качаем её, не отвлекаемся на лучников, идём с первого юнита»). Две живые партии 4.11: сторожа шахт
        (заранее и по требованию) лучников не достают — шахты горят за 15–40 с с соседней клетки. Ключ файла `при_турции` —
        словарь ключей; как только враг распознан Турцией (`_враг_турция`, по статам — видно с первого такта), ключи
        накладываются на `self.п` и `Стратегия` пересобирается (прокачки и пороги волн она читает один раз). Один раз за
        партию. Возвращает строку для why (только в такт переключения) или ''."""
        доп = self.п.get("при_турции")
        if not isinstance(доп, dict) or getattr(self, "_турция_вкл", False) or not _враг_турция(st):
            return ""
        import поиск_стратегии as ПС
        self.п = dict(self.п)
        self.п.update(доп)
        self.стр = ПС.Стратегия(self.п)
        self._п_исход = {k: self.п.get(k) for k in ("мушк_с", "доля_мушк", "стрелки_позади", "отряд_с")}
        self._турция_вкл = True
        try:
            self.реестр.мера["турция: режим размена"] += 1
        except AttributeError:
            pass
        return ("ТУРЦИЯ: режим размена — " + ", ".join(f"{k} {v}" for k, v in доп.items()))

    def _раш(self, из: list, st: dict):
        """ПОТОК ПИК НА ЕГО БАЗУ С ПЕРВОГО ЮНИТА (4.11 (214), ключ `раш` 1; 0 — как было). Каждый такт `ATTACK count=all
        who=infantry17 target=base` группой РАШ: уходят все пики, включая только что нанятых, — ручеёк нарочно (слово
        игрока). Прочие ATTACK/ENGAGE/RETREAT такта снимаются: слот удара один, а отход вернул бы поток домой. Нет его базы
        в состоянии — молчим с причиной. Возвращает (команды, запись для why или '')."""
        if int(float(self.п.get("раш", 0) or 0)) < 1:
            return из, ""
        # 4.11 (215), живая партия 3: `en_base` мост кладёт ТОЛЬКО в снимок трассы (llm_policy, `_снимок["en_base"]`), в живом
        # состоянии его нет — правило молчало «базы не видно». База считается тем же `coss3_map.база_врага`, что и снимок.
        if _его_база(st) is None:
            import coss3_map as _КМ
            _б = _КМ.база_врага(st)
            if not _б:                                   # сетки brow нет — его ратуша из `ebuild`
                _рт = [з for з in _список(st, "ebuild", _КМ.его_здания) if str(з.get("тип")) == "center"]
                _б = {"cx": _клетка(st, _рт[0]["x"], _рт[0]["z"])[0]} if _рт else {}
            if not _б:
                self.реестр.мера["раш: базы не видно"] += 1
                return из, "РАШ: его базы не видно ни в en_base, ни по его зданиям — удар не послан"
        пик = int(float(st.get("mil_inf") or 0))
        if пик < 1:
            return из, ""
        снято = [c for c in из if c.get("cmd") in ("ATTACK", "ENGAGE", "RETREAT")]
        из = [c for c in из if c not in снято]
        self.реестр.мера["раш: приказ"] += 1
        return ([{"cmd": "ATTACK", "count": "all", "who": "infantry17", "target": "base", "group": self.РАШ, "_раш": True}] + из,
                f"РАШ: все пики ({пик}) на его базу группой {self.РАШ}" + (f", снято {len(снято)} приказов удара/отхода" if снято else ""))

    def _против_турции(self, из: list, st: dict):
        """СТОРОЖА ШАХТ ПРОТИВ НАЛЁТОВ ТУРЦИИ (4.11 (204), слово игрока: «мы же заранее видим, что лучники пошли»).
        Турецкий лучник бьёт на 16,9 тайла, татарин на 20,6 — дальше нашего мушкетёра (13,1 pol / 15 net), а скорость у
        пехоты одна: погоня всей армией кормит кайт и уводит армию от ратуши (Fable, чистый вопрос 4.11). Игрок Польшей
        отбивал такие налёты МАЛЫМИ отрядами — каждый на свой налёт. Три части:
          (1) РАСПОЗНАВАНИЕ: ключ `против_турции` 1 — только если враг Турция (в `p1_fighters` турецкие sid: лучника там
              нет — роли archer блок не перечисляет, — но есть tatar/jannisary/pikemantur); 2 — при любой нации (проба);
          (2) ПРОГНОЗ НАЛЁТА по `ecells`: его клетка со стрелками или конными, которая СТОИТ у нашей шахты (`obuild`
              mine*) или ИДЁТ к ней (`идут` > 0, цель tx,ty) — в `налёт_клеток` (1) от шахты; шахты в `дом_клеток` (2) от
              ратуши не сторожим — там оборона дома; налёт больше `налёт_предел` (40) его бойцов — это удар, не налёт,
              его ведёт обычная оборона;
          (3) СТОРОЖА ПО ТРЕБОВАНИЮ (с (212)): заранее не собираются; на налёт — свободный номер из `сторожей` (3), 81..,
              и MOVE count=`сторож_n` (12, не больше праздных вне отрядов, не меньше `сторож_мин` 4) `сторож_who`
              (infantry17) прямо в клетку шахты (не ATTACK: тот гонится); ПОВОДОК — его стрелки в клетке шахты или соседней → MOVE в
              их клетку (подойти и прогнать), дальше — назад к шахте, не чаще `сторож_повтор` (10) с; налёта нет
              `сторож_держать` (30) с — домой. Основная армия не трогается.
        Группы 81..85 в `groups` живьём не видны (блок перечисляет 1..16) — состояние держится здесь, как у кайта.
        Возвращает (команды, запись для why или '')."""
        п = self.п
        ключ = int(float(п.get("против_турции", 0) or 0))
        if ключ <= 0:
            return из, ""
        t = float(st.get("gametime") or 0)
        с = getattr(self, "_тур", None)
        if с is None:
            с = self._тур = {"сторожа": {}, "сказал": -999.0, "собраны": False}

        def _сказать(текст):
            if t - с["сказал"] >= 120.0:
                с["сказал"] = t
                return текст
            return ""

        if ключ == 1 and not _враг_турция(st):
            return из, ""
        try:
            дом = _наша_база(st)
        except (TypeError, ValueError, KeyError):
            return из, ""
        import coss3_map as _КМ
        _ч = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        дом_кл = int(float(п.get("дом_клеток", 2) or 2))
        шахты = []
        for з in _список(st, "obuild", _КМ.наши_здания):
            if str(з.get("тип", "")).startswith("mine"):
                кл = _клетка(st, з["x"], з["z"])
                if _ч(кл, дом) > дом_кл and кл not in шахты:
                    шахты.append(кл)
        if not шахты:
            self.реестр.мера["турция: шахт вне дома нет"] += 1
            return из, _сказать(f"ТУРЦИЯ: сторожить нечего — шахт дальше {дом_кл} клеток от ратуши нет")
        n = int(float(п.get("сторож_n", 12) or 12))
        всего_ст = max(1, min(5, int(float(п.get("сторожей", 3) or 3))))
        who = str(п.get("сторож_who", "infantry17") or "infantry17")
        приказы, слова = [], []
        # Номера групп-сторожей. ЗАРАНЕЕ НЕ СОБИРАЮТСЯ (4.11 (212), живая партия игрока за Турцию): сбор ждал 76 свободных
        # вне отрядов — их не было, армия стояла строем обороны, — сторожа встали на 8:43, а три дальние шахты сгорели в
        # 5:48, 6:58 и 7:43, хотя налёт оборона видела за 83 с. Теперь пачка набирается В МОМЕНТ налёта: counted MOVE
        # блока заменяет состав группы свежими праздными (block_hcmd: «a counted MOVE REPLACES the roll»).
        for i in range(всего_ст):
            с["сторожа"].setdefault(self.СТОРОЖ0 + i, {"шахта": None, "t": -999.0, "тихо": -999.0})
        своб = float(st.get("my_free_nosq") if st.get("my_free_nosq") is not None else st.get("my_freewar") or 0)
        # (2) НАЛЁТЫ ПО ШАХТАМ
        р = int(float(п.get("налёт_клеток", 1) or 1))
        предел = float(п.get("налёт_предел", 40) or 40)
        налёт = {}                                   # шахта -> {"n": его бойцов, "клетки": [(x,y), ...]}
        for к in _список(st, "ecells", _КМ.его_клетки):
            дальних = int(к.get("стрелков") or 0) + int(к.get("конных") or 0)
            if дальних < 1:
                continue
            где = (int(к["x"]), int(к["y"]))
            куда = (int(к.get("tx", -1)), int(к.get("ty", -1))) if int(к.get("идут") or 0) > 0 else где
            for ш in шахты:
                if _ч(где, ш) <= р or (куда[0] >= 0 and _ч(куда, ш) <= р):
                    з = налёт.setdefault(ш, {"n": 0, "клетки": []})
                    з["n"] += int(к.get("n") or 0)
                    з["клетки"].append(где)
        удар = {ш for ш, з in налёт.items() if з["n"] > предел}
        for ш in удар:
            self.реестр.мера["турция: удар, не налёт"] += 1
            слова.append(f"у шахты {ш} его {налёт[ш]['n']} > {предел:g} — это удар, ведёт оборона")
        налёт = {ш: з for ш, з in налёт.items() if ш not in удар}
        # (3б) ПОСЫЛ ПО ТРЕБОВАНИЮ: на каждую шахту под налётом без сторожа — свободный номер и MOVE count=n праздных
        #      `сторож_who` прямо в клетку шахты; пачка не меньше `сторож_мин` (4), иначе причина вслух
        мин_n = int(float(п.get("сторож_мин", 4) or 4))
        занятые = {д["шахта"] for д in с["сторожа"].values() if д["шахта"] is not None}
        for ш, з in sorted(налёт.items(), key=lambda kv: -kv[1]["n"]):
            if ш in занятые:
                continue
            свободные = [г for г, д in с["сторожа"].items() if д["шахта"] is None]
            if not свободные:
                self.реестр.мера["турция: сторожей не хватило"] += 1
                слова.append(f"налёт на шахту {ш} ({з['n']} его) — все {всего_ст} номера сторожей заняты")
                continue
            сколько = int(min(n, своб))
            if сколько < мин_n:
                self.реестр.мера["турция: праздных нет"] += 1
                слова.append(f"налёт на шахту {ш} ({з['n']} его в {з['клетки'][0]}) — праздных вне отрядов {своб:.0f} "
                             f"< {мин_n}, послать некого")
                continue
            г = свободные[0]
            с["сторожа"][г].update(шахта=ш, t=t, тихо=t)
            занятые.add(ш)
            своб -= сколько
            приказы.append({"cmd": "MOVE", "count": сколько, "who": who, "group": г, "target": "cell",
                            "cx": ш[0], "cy": ш[1]})
            self.реестр.мера["турция: сторож послан"] += 1
            слова.append(f"налёт на шахту {ш}: его {з['n']} в {з['клетки'][0]} — {сколько} {who} группой {г} к шахте")
        # (3в) ПОВОДОК И ВОЗВРАТ
        повтор = float(п.get("сторож_повтор", 10) or 10)
        держать = float(п.get("сторож_держать", 30) or 30)
        for г, д in с["сторожа"].items():
            ш = д["шахта"]
            if ш is None or д["t"] == t:
                continue
            з = налёт.get(ш)
            if з is None:
                if t - д["тихо"] >= держать:
                    д.update(шахта=None, t=t)
                    приказы.append({"cmd": "MOVE", "count": 0, "group": г, "target": "cell",
                                    "cx": int(дом[0]), "cy": int(дом[1])})
                    self.реестр.мера["турция: сторож домой"] += 1
                    слова.append(f"у шахты {ш} тихо {держать:g} с — сторож {г} домой")
                continue
            д["тихо"] = t
            if t - д["t"] < повтор:
                continue
            рядом = [к for к in з["клетки"] if _ч(к, ш) <= 1]
            цель = min(рядом, key=lambda к: _ч(к, ш)) if рядом else ш
            д["t"] = t
            приказы.append({"cmd": "MOVE", "count": 0, "group": г, "target": "cell", "cx": цель[0], "cy": цель[1]})
            self.реестр.мера["турция: поводок " + ("прогнать" if рядом else "к шахте")] += 1
        if not приказы:
            return из, ("ТУРЦИЯ: " + "; ".join(слова)) if слова else ""
        занятые_гр = {c["group"] for c in приказы}
        из = приказы + [c for c in из if c.get("group") not in занятые_гр]
        return из, ("ТУРЦИЯ: " + "; ".join(слова)) if слова else ""

    def _встреча_строй(self, из: list, st: dict, сост: dict, его_кл, д, своб: int, t: float):
        """§170б: шаги встречи в чистой клетке после постановки кулака — по одному приказу движения за такт.
        Порядок: удержание тому, кто дошёл (FACE по номеру группы, hold 1, через `встреча_сек` после его MOVE) →
        стрелки позади (`стрелки_позади` 1: MOVE всех мушкетёров группой ЗАСЛОН в клетку ратуши) → пополнение
        (+15 свободных с постановки: MOVE новых группой ПОДМОГА в ту же клетку, затем своё удержание)."""
        п = self.п
        з = сост["клетка"]
        # §170д (23.10, Д12 12:20): он уже в нашей клетке — «лицом к (4,13)» из (4,13) бессмысленно; лицо — прежнее
        if tuple(int(v) for v in его_кл) == tuple(int(v) for v in з) and сост.get("лицо"):
            его_кл = сост["лицо"]
        лицо = [int(его_кл[0]), int(его_кл[1])]
        сост["лицо"] = (лицо[0], лицо[1])
        сек = float(п.get("встреча_сек", 20) or 20)
        из = [c for c in из if not (c.get("cmd") in ("MOVE", "FACE") and c.get("group") in (self.ЗАСЛОН, self.ОТРЯД, self.ПОДМОГА))]
        # §170д (23.10, Д12): отряд собрался (FORMATION 11:45) через две минуты ПОСЛЕ FACE 9:44 — сборка отряда снимает
        # стойку, повторного FACE не было, бонус 2 весь бой. Отрядов в снимке прибавилось — все держащие ждут заново,
        # без выдержки: FACE уходит следующим тактом после FORMATION
        отр = int(float(st.get("squads") or 0))
        было = сост.get("отрядов")
        if было is not None and отр > было and сост.get("держат"):
            сост["ждут"] = list(сост.get("ждут", [])) + [(г, t - сек) for г, _t in сост["держат"]]
            сост["заново"] = set(сост.get("заново") or ()) | {г for г, _t in сост["держат"]}
            сост["держат"] = []
            self.реестр.мера["оборона: удержание заново после отряда"] += 1
        сост["отрядов"] = отр
        готовые = [(г, t0) for г, t0 in сост.get("ждут", []) if t - t0 >= сек]
        if готовые:
            г, t0 = готовые[0]
            сост["ждут"] = [x for x in сост["ждут"] if x[0] != г]
            сост.setdefault("держат", []).append((г, t))
            из.insert(0, {"cmd": "FACE", "count": 0, "group": г, "face": лицо, "hold": 1})
            self.реестр.мера["оборона: удержание в чистой"] += 1
            заново = ""
            if г in (сост.get("заново") or ()):
                сост["заново"].discard(г)
                заново = " заново после сборки отряда"
            return из, f"ВСТРЕЧА: группа {г} в {з} держит строй лицом к {tuple(лицо)} (FACE hold{заново})"
        if int(п.get("стрелки_позади", 0) or 0) >= 1 and сост.get("стрелки") is None and float(st.get("mil_shooters") or 0) >= 1:
            сост["стрелки"] = t
            из.insert(0, {"cmd": "MOVE", "count": "all", "who": "musk17", "group": self.ЗАСЛОН, "target": "cell",
                          "cx": int(д[0]), "cy": int(д[1]), "face": лицо})
            self.реестр.мера["оборона: стрелки позади"] += 1
            return из, f"ВСТРЕЧА: стрелки {int(float(st.get('mil_shooters') or 0))} в клетку ратуши {tuple(д)} позади пик"
        if своб >= сост.get("своб", своб) + 15:
            n = своб - сост["своб"]
            сост["своб"] = своб
            сост.setdefault("ждут", []).append((self.ПОДМОГА, t))
            из.insert(0, {"cmd": "MOVE", "count": n, "who": "infantry17", "group": self.ПОДМОГА, "target": "cell",
                          "cx": int(з[0]), "cy": int(з[1]), "face": лицо})
            self.реестр.мера["оборона: подмога в чистую"] += 1
            return из, f"ВСТРЕЧА: пополнение {n} в {з} группой {self.ПОДМОГА}"
        return из, ""

    def _две_группы(self, из: list, st: dict, уг: dict, б: dict, д: tuple):
        """§143: заслон навстречу + отряд в клетке ратуши; отряд бьёт его стрелков у ратуши по прогнозу. См. `_оборона`."""
        import прогноз as _ПР
        import combat_math as _CM
        import прокачки as _ПК
        import coss3_map as _КМ
        п = self.п
        t = float(st.get("gametime") or 0)
        _ч = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        сост = getattr(self, "_дг", None)
        его_кл_все = [c for c in _список(st, "ecells", _КМ.его_клетки) if int(c.get("n") or 0) > 0]
        if сост is not None and сост["удар"] is not None:
            # отряд в ударе: клетка его стрелков опустела — назад в клетку ратуши (и когда подхода к базе уже нет)
            у = сост["удар"]
            if sum(int(c.get("n") or 0) for c in его_кл_все if _ч((c["x"], c["y"]), у) <= 1) < 3:
                сост["удар"], сост["t"] = None, t
                из = [c for c in из if c.get("group") != self.ОТРЯД]
                из.insert(0, {"cmd": "MOVE", "group": self.ОТРЯД, "target": "cell", "cx": int(д[0]), "cy": int(д[1])})
                self.реестр.мера["оборона: отряд назад к ратуше"] += 1
                return из, f"ДВЕ ГРУППЫ: стрелков в {у} нет — отряд назад в клетку ратуши"
            return из, ""
        if сост is not None and t - сост["t"] > 60 and not б["его"]:
            self._дг = сост = None             # затишье: следующий подход ставит группы заново
        if not б["его"]:
            return из, ""
        # направление — его главная куча, чья цель в трёх клетках от ратуши (глаза `угрозы` зовут «базой» лишь две клетки:
        # в Д2 его 80 пик шли на (1,11), три клетки от ратуши (2,14), и считались «полем» до самого удара)
        к_базе = [г for г in уг["группы"] if _ч(г["куда"], д) <= 3]
        if not к_базе:
            return из, ""
        главная = max(к_базе, key=lambda г: г["n"])
        его_кл = tuple(главная["откуда"])
        записи = []
        своб = int(float(st.get("my_freewar") or 0))
        если_мало = int(п.get("две_группы_от", 20) or 20)
        # §148 (11.10, Д4 живьём): кулак собрался ОДИН раз за партию — в 6:42 на его ЧЕТЫРЁХ (все 38 в клетку ратуши), а
        # дальше `сост` жил до конца: его 63 шли с 7:33, стояли лагерем 60-100 в (4,4) с 10:00 и вошли 168 в 12:32 — ни
        # одной новой строки, новонанятые (38 → 96) приказа не получили. Порог `две_группы_его_от` (10): меньше — не повод;
        # и группы ставятся ЗАНОВО, когда свободных дома прибавилось на 15 против постановки (новые бойцы — в кулак; рост
        # его подхода поводом не берём: кулак уже стоит, а повтор снимал бы удар отряда по стрелкам, selftest_две_группы (г)).
        его_от = int(п.get("две_группы_его_от", 10) or 0)
        if сост is not None and своб >= сост.get("своб", своб) + 15 and сост.get("клетка") is None:
            self.реестр.мера["оборона: группы заново"] += 1
            сост = None
        if сост is None:
            if б["его"] < его_от:
                return из, f"две группы: его {б['его']} < {его_от}"
            if своб < если_мало:
                return из, f"две группы: свободных {своб} < {если_мало}"
            dx, dy = его_кл[0] - д[0], его_кл[1] - д[1]
            з = (int(д[0] + (dx > 0) - (dx < 0)), int(д[1] + (dy > 0) - (dy < 0)))
            # `две_группы_заслон` — доля свободных в заслоне (0,67); 0 — заслона нет, все одним кулаком в клетке ратуши
            # (Fable на вопросах Д2 10:33/11:04: «Б» — стоять всем в клетке мельницы, не раскалываться; sim/решения/д2_осада.md)
            доля = float(п.get("две_группы_заслон", 0.67) or 0)
            n_з = int(своб * доля)
            из = [c for c in из if c.get("group") not in (self.ЗАСЛОН, self.ОТРЯД, self.ПОДМОГА)]
            # §170б (22.10, Д10 216:77 и экзамен Fable 3/3 «В»): ВСТРЕЧА В ЧИСТОЙ КЛЕТКЕ. Куча в клетке ратуши стояла среди
            # построек и 34 праздных крестьян; его фронт облепил её снаружи, внутренние до врага не доставали (бьющих у него
            # ~2×, ранено 188 из 227). Ключ `встреча_чистая` 1 (при `две_группы_заслон` 0): кулак — не в клетку ратуши, а в
            # клетку на шаг от неё навстречу его главной куче (та же `з`, что у заслона), лицом к ней; через `встреча_сек` —
            # FACE по номеру группы с удержанием (блок: fStandGround, через 37,5 с стояния fHoldMode = +7/+7 строя, если есть
            # отряд §81 `отрядов`); стрелки при `стрелки_позади` 1 — отдельным MOVE в клетку ратуши (клетка позади, §13т:
            # стрелок в клетке контакта не стреляет). ОДИН приказ движения за такт (исполнитель хранит одно `движение`):
            # шаги идут по тактам — пики, стрелки, удержание. Пополнение (+15 свободных) — не заново всех (это снимало бы
            # удержание каждые 40 с), а группой ПОДМОГА 93 в ту же клетку и своё удержание через `встреча_сек`.
            чистая = int(п.get("встреча_чистая", 0) or 0) >= 1 and n_з < 1
            куда = з if чистая else (int(д[0]), int(д[1]))
            if n_з >= 1:
                из.insert(0, {"cmd": "MOVE", "count": n_з, "group": self.ЗАСЛОН, "target": "cell", "cx": з[0], "cy": з[1],
                              "face": [int(его_кл[0]), int(его_кл[1])]})
            из.insert(1 if n_з >= 1 else 0, {"cmd": "MOVE", "count": "all", "group": self.ОТРЯД, "target": "cell", "cx": int(куда[0]), "cy": int(куда[1]),
                                              "face": [int(его_кл[0]), int(его_кл[1])]})
            self._кулак_t = t                  # §154: минуту после кулака заслон §152 не ставится и не переставляется
            self._дг = сост = {"t": t, "заслон": з if n_з >= 1 else None, "отряд_в": "дом", "удар": None,
                               "его": int(б["его"]), "своб": своб}
            if чистая:
                сост.update({"клетка": (int(з[0]), int(з[1])), "ждут": [(self.ОТРЯД, t)], "стрелки": None, "держат": [],
                             "лицо": (int(его_кл[0]), int(его_кл[1]))})
            self.реестр.мера["оборона: две группы" if n_з >= 1 else ("оборона: встреча в чистой" if чистая else "оборона: кулак у ратуши")] += 1
            return из, ((f"ДВЕ ГРУППЫ: его {б['его']} (стрелков {б['стрелков']}) идут от {его_кл}; заслон {n_з} в {з} лицом к "
                         f"{его_кл}, отряд {своб - n_з} в клетке ратуши {tuple(д)}") if n_з >= 1 else
                        (f"ВСТРЕЧА В ЧИСТОЙ: его {б['его']} (стрелков {б['стрелков']}) идут от {его_кл}; все {своб} в клетку {з} на шаг от ратуши лицом к {его_кл}"
                         if чистая else
                         f"КУЛАК У РАТУШИ: его {б['его']} (стрелков {б['стрелков']}) идут от {его_кл}; все {своб} в клетку ратуши {tuple(д)} лицом к {его_кл}"))
        сост["t"] = t
        if сост.get("клетка") is not None:
            из, зап = self._встреча_строй(из, st, сост, его_кл, д, своб, t)
            if зап:
                return из, зап
        # отряд: его стрелки у ратуши
        отряд = next((g for g in _группы(st) if int(g.get("id") or 0) == self.ОТРЯД), None)
        if отряд is None:
            return из, ""
        мин_стр = int(п.get("две_группы_стрелков", 5) or 5)
        n_отр = int(float(отряд.get("n") or 0))
        цели = [c for c in его_кл_все if int(c.get("стрелков") or 0) >= мин_стр and _ч((c["x"], c["y"]), д) <= 2
                and int(c.get("пик") or 0) <= n_отр / 2]
        if not цели:
            return из, ""
        ц = max(цели, key=lambda c: int(c.get("стрелков") or 0))
        цк = (int(ц["x"]), int(ц["y"]))
        свои_х, чужие_х = _CM.разобрать(st.get("fighters") or ""), _ПК._чужие_со_строем(st)
        сила = {"infantry17": float(отряд.get("пик") or 0), "musk17": float(отряд.get("стрелков") or 0), "dragoon17": float(отряд.get("конных") or 0)}
        его = _ПР.состав_из_клеток(его_кл_все, цк, 0)
        его = _его_с_лагерем(его, цк, st, п)[0]   # §170ж
        пр = _ПР.новая_волна(сила, его, свои_х, чужие_х) if свои_х and чужие_х else {}
        R = пр.get("R")
        порог = float(п.get("две_группы_R", 1.2) or 1.2)
        if R is not None and R >= порог:
            из = [c for c in из if c.get("group") != self.ОТРЯД]
            из.insert(0, {"cmd": "ATTACK", "group": self.ОТРЯД, "target": "cell", "cx": цк[0], "cy": цк[1], "_оборона": True})
            сост["удар"] = цк
            self.реестр.мера["оборона: отряд на стрелков"] += 1
            return из, f"ДВЕ ГРУППЫ: отряд {n_отр} бьёт его стрелков {ц.get('стрелков')} (пик {ц.get('пик')}) в {цк}, прогноз {_ПР.словами(пр)}"
        return из, f"две группы: его стрелки {ц.get('стрелков')} в {цк}, отряд {n_отр} не бьёт — прогноз {_ПР.словами(пр) if пр else 'нет'} < {порог:g}"

    def _бой_за_лагерь(self, st: dict) -> bool:
        """§124: волна послана на его лагерь у нашей базы не больше 240 с назад и жива — её бой и есть оборона базы."""
        t0 = getattr(self, "_лагерь_удар", None)
        if t0 is None:
            return False
        волна = self.реестр.активная() if hasattr(self, "реестр") else None
        if волна is None or волна.состояние in ("ДОМОЙ", "КОНЧЕНА") or float(st.get("gametime") or 0) - t0 > 240:
            self._лагерь_удар = None
            return False
        return True

    def _судья_удара(self, st: dict, записи: list):
        """СУДЬЯ УДАРА (4.11 вечер, ключ `судья_удара` 1; 0 — как было). Один прогноз на всё, что бьёт у дома. Его бойцы в клетках
        не дальше `судья_клеток` (4 — радиус рефлекса блока) от ратуши, не меньше `судья_его_от` (10): бой ВСЕХ дома (свободные
        вне отрядов + держащие + отряд) против них по закону двойника (`прогноз.новая_волна`, статы обеих сторон с прокачками). R
        ниже порога (`судья_R`, иначе `лагерь_R`) — «не бьём». ПРИМАНКА (`судья_приманка` 1): его число в радиусе за последние
        `судья_окно` (60) с прыгало не меньше чем на `судья_приманка_доля` (0,3) от наибольшего — он выманивает (партия 2: 53→38→51,
        партия 1: 53→25→50 — и каждый раз наши шли кусками и гибли), тоже «не бьём». Решение — в `self._судья`; по нему ОГОНЬ §164
        не открывается, DEFEND уходит 0/0, ATTACK/ENGAGE в клетки радиуса снимаются, стойка дома ставится в тот же такт. Его в радиусе
        меньше `судья_его_от` — судьи нет, всё как было (и DEFEND возвращается по ключам)."""
        п = self.п
        if not int(float(п.get("судья_удара", 0) or 0)):
            return
        t = float(st.get("gametime") or 0)
        рад = float(п.get("судья_клеток", 4) or 4)
        его_от = float(п.get("судья_его_от", 10) or 10)
        порог = float(п.get("судья_R", 0) or 0) or float(п.get("лагерь_R", 0) or 0)
        import coss3_map as _КМ
        дом = _дом(st)
        _ч = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        кл = [c for c in _список(st, "ecells", _КМ.его_клетки) if float(c.get("n") or 0) > 0 and _ч((c["x"], c["y"]), дом) <= рад]
        n = int(round(sum(float(c.get("n") or 0) for c in кл)))
        окно = float(п.get("судья_окно", 60) or 60)
        ист = getattr(self, "_судья_ист", None)
        if ист is None or (ист and t < ист[-1][0]):
            ист = self._судья_ист = []
        ист.append((t, n))
        del ист[:max(0, len(ист) - 60)]
        окно_зн = [m for t0, m in ист if t - t0 <= окно]
        if n < его_от:
            if (self._судья_был or {}).get("нет"):
                записи.append(f"СУДЬЯ УДАРА: его в {рад:g} кл. от ратуши {n} < {его_от:g} — судьи нет, рефлекс по ключам")
            return
        R, прогн = None, ""
        try:
            import прогноз as _ПР
            import combat_math as _CM
            import прокачки as _ПК
            свои_х, чужие_х = _CM.разобрать(st.get("fighters") or ""), _ПК._чужие_со_строем(st)
            его = _ПР.состав_из_клеток(кл, None)
            if st.get("my_free_nosq") is not None and st.get("my_held_idle") is not None:
                наших = int(float(st.get("my_free_nosq") or 0)) + int(float(st.get("my_held_idle") or 0)) + int(float(st.get("my_insquad") or 0))
            else:
                наших = int(float(st.get("my_freewar") or 0)) + int(float(st.get("my_held") or 0))
            сила = _ПР.состав_по_долям(наших, st)
            пр = _ПР.новая_волна(сила, его, свои_х, чужие_х) if (свои_х and чужие_х and наших > 0) else {}
            R = пр.get("R")
            прогн = _ПР.словами(пр) if пр else "прогноза нет"
        except Exception as e:
            наших = 0
            прогн = f"прогноз не посчитан: {type(e).__name__}"
        приманка = False
        if int(float(п.get("судья_приманка", 1) or 0)) and len(окно_зн) >= 3:
            # V-образно: до провала было больше и СЕЙЧАС снова больше провала не меньше чем на долю — он отошёл и вернулся
            # (партия 2: 53→38→51). Простая убыль (53→36 — он гибнет или уходит) приманкой не считается.
            _доля_п = float(п.get("судья_приманка_доля", 0.3) or 0.3)
            _i = min(range(len(окно_зн) - 1), key=lambda k: окно_зн[k])     # провал — не последняя точка
            _mn, _до = окно_зн[_i], max(окно_зн[:_i + 1])
            приманка = _до > 0 and n > 0 and (_до - _mn) / _до >= _доля_п and (n - _mn) / n >= _доля_п
        мало = R is not None and порог > 0 and R < порог
        нет = мало or приманка
        причина = ("прогноз мал" if мало else "") + (" и " if мало and приманка else "") + ("приманка" if приманка else "")
        if R is None and not приманка and (self._судья_был or {}).get("нет"):
            нет, причина = True, "прогноза нет — решение прежнее"      # без прогноза судья своего слова не меняет
        self._судья = {"t": t, "R": R, "порог": порог, "n": n, "центр": (int(кл[0]["x"]), int(кл[0]["y"])) if кл else дом, "рад": рад,
                       "нет": нет, "наших": наших, "причина": причина}
        if порог <= 0 and not приманка:
            записи.append("СУДЬЯ УДАРА молчит: нет ключа лагерь_R/судья_R, прогноз не судится")
        if нет:
            self.реестр.мера["судья удара: не бьём"] += 1
            записи.append(f"СУДЬЯ УДАРА: его {n} в {рад:g} кл. от ратуши, наших дома {наших}, R={R if R is None else format(R, '.2f')} "
                          f"{'<' if мало else '≥'} {порог:g}{' (приманка: ' + '→'.join(str(x) for x in окно_зн[-4:]) + ')' if приманка else ''} — "
                          f"{причина}: огонь не открывать, рефлекс блока снять, удары в радиус снять, дом держит строй [{прогн}]")
        elif (self._судья_был or {}).get("нет"):
            записи.append(f"СУДЬЯ УДАРА: его {n} в {рад:g} кл., наших {наших}, R={R if R is None else format(R, '.2f')} ≥ {порог:g} — удар снова годится [{прогн}]")

    def _пачка_удара(self, из: list, st: dict) -> tuple:
        """ПАЧКА УДАРА (4.11 вечер, вопрос игрока «что делать, чтобы армия не ходила праздно по одному-трое», ключ `пачка_удара` N;
        0 — как было). Откуда одиночки: приказы «всем домом» (`all`/9999 — РАТУША своими, ВЫХОД ПРОДОЛЖЕН ДЕЛОМ, ОГОНЬ, штурм всем)
        повторяются каждые 5–10 с, а `all` берёт КАЖДОГО бойца, даже только что вышедшего из казармы (не только праздных): в живой
        партии 1 с 8:43 по 11:09 ATTACK 9999 шёл раз в 10 с, и каждый новый рекрут один шагал в его 35–100 у ратуши (праздных в
        такт 0–1: рекрут уводился раньше, чем становился праздным). Правило: повтор `all`-приказа в ту же клетку (не дальше 1 от
        прошлой) снимается, пока домашних бойцов не прибавилось на N с прошлого ушедшего приказа и дома их меньше N; новая цель,
        прибавка ≥ N или дома ≥ N (перенацеливание большого дома) — уходит как было. Приказы группе и счётные не трогаются: их
        пачку держит ПОДТОК (`пачка`)."""
        N = int(float(self.п.get("пачка_удара", 0) or 0))
        if N <= 0:
            return из, ""
        t = float(st.get("gametime") or 0)
        дома = int(домашних_бойцов(st))
        посл = getattr(self, "_пачка_посл", None)
        if посл is not None and t < float(посл.get("t") or 0):
            посл = self._пачка_посл = None
        _чб = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        снято, прошло = [], None
        for c in из:
            if c.get("cmd") not in ("ATTACK", "ENGAGE"):
                continue
            всем = str(c.get("count", "")).strip().lower() in ("all", "9999") or int(c.get("all") or 0) == 1
            if not всем or c.get("target") != "cell" or c.get("cx") is None or c.get("cy") is None:
                continue
            кл = (int(c["cx"]), int(c["cy"]))
            та_же = посл is not None and _чб(кл, посл["кл"]) <= 1
            прибавка = дома - int(посл["дома"]) if посл is not None else дома
            if та_же and прибавка < N and дома < N:
                снято.append(c)
            else:
                прошло = {"t": t, "кл": кл, "дома": дома}
        if прошло is not None:
            self._пачка_посл = прошло
        if not снято:
            return из, ""
        self.реестр.мера["пачка удара: повтор all снят"] += len(снято)
        return ([c for c in из if c not in снято],
                f"пачка удара: дома {дома} ({дома - int(посл['дома']):+d} с прошлого приказа {t - float(посл['t']):.0f} с назад) < {N} — "
                f"повтор all-приказа в ({снято[0]['cx']},{снято[0]['cy']}) снят, рекруты копятся")

    def _судья_снять(self, из: list, st: dict) -> tuple:
        """Судья удара сказал «не бьём» — ATTACK/ENGAGE в клетки не дальше `судья_клеток` от ратуши и приказы ОГНЯ снимаются.
        Зовётся ПОСЛЕДНИМ в `ответ()`: подмога волне (РАЗМЕН_ОК), выход, ратуша своими и прочие шлют удары позже места DEFEND
        (в повторе партии 1 ATTACK all → (1,12) в 8:53 прошёл мимо снятия, стоявшего у DEFEND)."""
        _с = getattr(self, "_судья", None)
        if not (_с and _с.get("нет")):
            return из, ""
        _д0 = _дом(st)
        _чб = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        _снять = []
        for c in из:
            if c.get("cmd") not in ("ATTACK", "ENGAGE"):
                continue
            if c.get("_огонь"):
                _снять.append(c)
            elif c.get("target") == "cell" and c.get("cx") is not None and c.get("cy") is not None:
                try:
                    if _чб((c["cx"], c["cy"]), _д0) <= float(_с.get("рад") or 4):
                        _снять.append(c)
                except (TypeError, ValueError):
                    pass
        if not _снять:
            return из, ""
        self.реестр.мера["судья удара: удары сняты"] += len(_снять)
        return ([c for c in из if c not in _снять],
                f"судья удара: сняты {len(_снять)} ATTACK/ENGAGE в радиус {_с.get('рад', 4):g} ({_с['причина']}): "
                + ", ".join(f"{c.get('count')}→({c.get('cx')},{c.get('cy')})" for c in _снять[:3]))

    def _тактика(self, из: list, st: dict):
        """§124 ТАКТИКА ПО АНАЛИЗУ ПРОТИВНИКА (8.10, слова игрока). Два правила, каждое ключом файла стратегии:

          * УДАР ПО ЛАГЕРЮ (`удар_по_лагерю`): анализ (`анализ_врага.py`) видит его лагерь у нашей базы; свободных дома не
            меньше `лагерь_перевес` (2,0) × лагеря; его ближнее подкрепление к лагерю придёт не раньше нас — один приказ всех
            свободных в клетку лагеря, даже если оборона держит дом (игрок: «если успею — снесу 14»; партия А: лагерь
            стоял с 4:45, к 7:40 — осада). Не бьём — причина в лог.
          * ПОДТОК (`подток`, `пачка` 8): пока волна в поле, одиночные досылки к ней снимаются, бойцы копятся дома и
            уходят к волне пачкой одним приказом (игрок: «контролить дотекание, группа бьёт сильнее несобранной»).
        Возвращает (команды, запись для why или '')."""
        п, записи = self.п, []
        t = float(st.get("gametime") or 0)
        # СУДЬЯ УДАРА (4.11 вечер, слово игрока после двух живых партий Польша против Польши, ключ `судья_удара` 1): один прогноз
        # на все удары у дома. Партия 1: «ЛАГЕРЬ не бьём R=0,08» и в тот же такт ОГОНЬ (§164) слал 38/72/69/51 пик в его клетку —
        # 125:18. Партия 2 (огонь выключен): python не отдал ни одного удара, а рефлекс обороны блока (DEFEND 1: его ≥ 20 в 4 клетках
        # от ратуши → стойка снята, «искать жертву») отпустил 80 пик самих бежать в его 50 с ударом 18 против 8 — 84:8 за 30 с.
        # Здесь прогноз лагеря (`лагерь_R`) записывается в `self._судья`; по нему ниже ОГОНЬ не открывается, DEFEND уходит 0/0
        # (рефлекс и оборонительная ATTACK блока сняты), стойка дома ставится сразу; R ≥ порога или лагеря нет — всё как было.
        self._судья_был = getattr(self, "_судья", None)
        self._судья = None
        if float(п.get("удар_по_лагерю", 0) or 0):
            try:
                import анализ_врага as _АВ
                import прогноз as _ПР
                лагеря = [н for н in _АВ.текущий(st)["находки"] if н["вид"] == "лагерь"]
            except Exception:
                лагеря = []
            волна = self.реестр.активная()
            _д0 = _дом(st)
            _волна_дома = волна is not None and max(abs(волна.сбор[0] - _д0[0]), abs(волна.сбор[1] - _д0[1])) <= 1
            if лагеря and (волна is None or not волна.подтверждена or _волна_дома):
                л = max(лагеря, key=lambda н: н["n"])
                своб = int(float(st.get("my_freewar") or 0))
                д = _дом(st)
                от = max(abs(д[0] - л["центр"][0]), abs(д[1] - л["центр"][1]))
                # §162 (16.10, Д6 10:45): «дойдём за ~14 с» на 2 клетки — живьём 95 дошли за 35 с (первые 48 за 25): путь
                # от центра клетки до центра, плюс ~5 с на сбор; до 16.10 считалось (от − 1) клеток
                наш_сек = от * _ПР.СЕК_НА_КЛЕТКУ + 5.0
                # ХВОСТ «ЗОВ УДАРА» (1.11): удар по лагерю идёт `count all` — блок берёт и держащих, и отряды, а прогноз и
                # перевес считались по одним свободным («наших 8 против его 37 — не бьём» при 151–171 держащих, 31.10, три копии).
                # Ключ `лагерь_всеми` 1: для лагеря не дальше `без_атаки_радиус` (5) от ратуши наших = праздные вне отрядов +
                # держащие праздные + отряд (поля блока 2779+; без них — свободные + my_held). 0 — как было.
                if int(float(п.get("лагерь_всеми", 0) or 0)) and от <= float(п.get("без_атаки_радиус", 5) or 5):
                    _fn, _hi = st.get("my_free_nosq"), st.get("my_held_idle")
                    if _fn is not None and _hi is not None:
                        _всеми = int(float(_fn or 0)) + int(float(_hi or 0)) + int(float(st.get("my_insquad") or 0))
                    else:
                        _всеми = своб + int(float(st.get("my_held") or 0))
                    if _всеми > своб:
                        записи.append(f"лагерь всеми: наших {своб} свободных → {_всеми} с держащими и отрядом (удар идёт all)")
                        self.реестр.мера["тактика: лагерь всеми"] += 1
                        своб = _всеми
                # (а) ГАРНИЗОН (1.11, живая Польша 6680, ПЛАН 55): удар `all` уводил весь дом, и в клетку ратуши вошли его 20 —
                # 49 крестьян за 30 с при наших 1–6 в ней. Ключ `лагерь_гарнизон` N (0 — как было): у лагеря в `без_атаки_радиус`
                # удар идёт ЧИСЛОМ (всех − N), а не `all`: счётный приказ отряды не берёт, держащих берёт блок (оборонительная
                # ATTACK) только до числа — дома остаются не меньше N. Прогноз и перевес считаются по уходящим.
                _гарн = int(float(п.get("лагерь_гарнизон", 0) or 0))
                if _гарн > 0 and от <= float(п.get("без_атаки_радиус", 5) or 5):
                    записи.append(f"лагерь гарнизон: дома остаются {_гарн}, в удар {max(0, своб - _гарн)} из {своб}")
                    своб = max(0, своб - _гарн)
                else:
                    _гарн = 0
                # (б) ГАРНИЗОН СВОБОДНЫМИ (2.11, разбор капли: storm_pol 17:02–22:19 и живая №9 1.11). При гарнизоне удар шёл
                # ЧИСЛОМ «всех − N», а в «всех» сидел отряд строем: прогноз считал 167 (189 в отряде + 8 свободных − 30), блок
                # счётным приказом брал одних свободных — пять минут каждые 5 с уходило по 2–14, отряд 189 стоял, его лагерь
                # 37 → 74. «Все, кроме N» блок не умеет (`all` уводит каждый отряд целиком). Ключ `гарнизон_свободными` 1
                # (0 — как было): отряды уходят ЦЕЛИКОМ (`all`), гарнизон — из бойцов вне отряда: числом уходят только они
                # сверх N. Прогноз — по тем, кто действительно уйдёт. qwen3 3/3 выбрала «распустить строй, потом числом» —
                # распускать блок не умеет (это правка .inc), а строй на марше игрок ценит (15.10).
                _отряд_all, _числом = False, 0
                if _гарн > 0 and int(float(п.get("гарнизон_свободными", 0) or 0)):
                    _в_отряде = int(float(st.get("my_insquad") or 0))
                    if _в_отряде > 0:
                        if st.get("my_free_nosq") is not None and st.get("my_held_idle") is not None:
                            _вне = int(float(st.get("my_free_nosq") or 0)) + int(float(st.get("my_held_idle") or 0))
                        else:
                            _вне = int(float(st.get("my_freewar") or 0)) + int(float(st.get("my_held") or 0))
                        _числом = max(0, _вне - _гарн)
                        своб = _в_отряде + _числом
                        _отряд_all = True
                        записи.append(f"гарнизон свободными: отряд {_в_отряде} уходит целиком (all), вне отряда {_вне} — "
                                      f"в удар {_числом}, дома {_вне - _числом}; в удар всего {своб}")
                        self.реестр.мера["лагерь: гарнизон свободными"] += 1
                перевес = float(п.get("лагерь_перевес", 2.0) or 2.0)
                поток = л.get("поток_сек")
                # ПО ПРОГНОЗУ (`лагерь_R`): вместо числа — бой по закону двойника с составом и прокачками обеих сторон
                прогн = ""
                R = None
                if п.get("лагерь_R"):
                    try:
                        import combat_math as _CM
                        import прокачки as _ПК
                        import coss3_map as _КМ
                        свои_х, чужие_х = _CM.разобрать(st.get("fighters") or ""), _ПК._чужие_со_строем(st)
                        его_кл = [c for c in _список(st, "ecells", _КМ.его_клетки) if int(c.get("n") or 0) > 0]
                        его = _ПР.состав_из_клеток(его_кл, tuple(л["центр"]), 1)
                        его = _его_с_лагерем(его, tuple(л["центр"]), st, п)[0]   # §170ж: не меньше самого лагеря
                        # §162 (16.10, Д6 10:45): лагерь 23 в 2 кл., к нему 67 через ~42 с — прогноз считал бой с 23 (R 3,4),
                        # живьём 95 шли 35 с, его 23 отошли, и наши встали рядом с его 90 (дальше — 11:25). Ключ
                        # `лагерь_с_подходом`: в его силу входят идущие к лагерю, которые успеют к бою — их путь не дольше
                        # нашего пути плюс длины боя. Fable 3/3 на 10:45: «его 23 — приманка», не выходить
                        подход_n = 0
                        if float(п.get("лагерь_с_подходом", 0) or 0):
                            _ц = tuple(л["центр"])
                            _чб = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
                            идущие = [c for c in его_кл if int(c.get("идут") or 0) > 0 and c.get("tx") is not None
                                      and _чб((c["tx"], c["ty"]), _ц) <= 1 and _чб((c["x"], c["y"]), _ц) >= 2
                                      and _чб((c["x"], c["y"]), _ц) * _ПР.СЕК_НА_КЛЕТКУ <= наш_сек + _ПР.ДЛИНА_БОЯ_С]
                            if идущие:
                                _дп = _ПР.состав_из_клеток(идущие, None)
                                подход_n = int(round(sum(_дп.values())))
                                его = {k: float(его.get(k) or 0) + float(_дп.get(k) or 0) for k in set(его) | set(_дп)}
                        сила = _ПР.состав_по_долям(своб, st)
                        пр = _ПР.новая_волна(сила, его, свои_х, чужие_х) if свои_х and чужие_х else {}
                        R = пр.get("R")
                        прогн = (f", прогноз {_ПР.словами(пр)}" + (f" (с подходом {подход_n})" if подход_n else "")) if пр else ""
                        годится = R is not None and R >= float(п["лагерь_R"])
                    except Exception as e:
                        годится, прогн = False, f", прогноз не посчитан: {type(e).__name__}"
                else:
                    годится = своб >= перевес * л["n"]
                _нг = int(float(п.get("не_гнаться", 0) or 0))
                _нг_при = float(п.get("не_гнаться_при", 4.0) or 4.0)
                # §160 (14.10, Д5 14:39): «не гнаться» — про ОСТАТОК после боя (Д4: его 10), а не про лагерь в 77: при
                # `не_гнаться_до` (0 — без предела) правило держит только кучи не больше этого числа; лагерь крупнее судит
                # перевес/прогноз. В Д5 §152 с пределом 0 запирало бы удар 105 на 77 (R 2,07, двойник 7:36) — 4×77 = 308
                _нг_до = int(float(п.get("не_гнаться_до", 0) or 0))
                if годится and _нг > 0 and от <= _нг and своб < _нг_при * max(1, int(л["n"])) and (_нг_до <= 0 or int(л["n"]) <= _нг_до):
                    # §152 НЕ ГНАТЬСЯ (12.10, Д4 5:16): его 10 (остаток после боя, 4 из них уцелевшие) стояли в (5,6) в 4 кл.
                    # от ратуши, наших 33 дома — удар по лагерю всеми, полторы минуты у пустой клетки, а его 4 пришли к
                    # крестьянам. Двойник: погоня — больше всех своих у всех трёх агентов, «встать между» — меньше всех;
                    # экзамен — Г, 23 в (4,4) между ним и ратушей. Заслон делается ниже (`_заслон_поля`), удар — по ключу
                    # `не_гнаться_при` (4): при таком перевесе остаток сносится
                    годится, прогн = False, f", §152 не гонимся{прогн}"
                    записи.append(f"НЕ ГОНИМСЯ за его {л['n']} в {л['центр']} ({от} кл. от ратуши): наших {своб} < {_нг_при:g}×{л['n']}")
                    self.реестр.мера["не гнаться: лагерь не бьём"] += 1
                if годится and _гарн and своб <= 0:
                    годится, прогн = False, f", после гарнизона {_гарн} в удар некого{прогн}"
                if годится and (поток is None or поток >= наш_сек):
                    из = [c for c in из if c.get("cmd") not in ("ATTACK", "ENGAGE", "MOVE", "RETREAT")]
                    # при `гарнизон_свободными` число — только вне отряда сверх гарнизона (не меньше 1: ноль — приказ группе)
                    из.insert(0, {"cmd": "ATTACK", "count": (max(1, _числом) if _отряд_all else своб) if _гарн else "all",
                                  "target": "cell", "cx": int(л["центр"][0]), "cy": int(л["центр"][1]),
                                  **({"_гарнизон": _гарн} if _гарн else {}), **({"all": 1} if _отряд_all else {})})
                    self._держим_дом = False
                    self._лагерь_удар = t          # бой за лагерь у базы — это и есть оборона: волну не отзывать, подток к ней
                    self._лагерь_кл, self._лагерь_встали = (int(л["центр"][0]), int(л["центр"][1])), False
                    self.реестр.мера["тактика: удар по лагерю"] += 1
                    записи.append(f"УДАР ПО ЛАГЕРЮ его {л['n']} в {л['центр']}: наших {своб}, дойдём за ~{наш_сек:.0f} с"
                                  + (f", его подход через ~{поток} с" if поток is not None else ", подхода нет") + прогн)
                else:
                    записи.append(f"ЛАГЕРЬ его {л['n']} в {л['центр']} не бьём: "
                                  + (f"его подход через ~{поток} с раньше нас (~{наш_сек:.0f} с)" if годится
                                     else (f"прогноз мал{прогн}" if п.get("лагерь_R") else f"наших {своб} < {перевес:g}×{л['n']}")))
        self._судья_удара(st, записи)              # судья удара (4.11): по его клеткам в радиусе, не только по «лагерю» анализа
        # §130 НЕ ВХОДИТЬ В РАСТУЩИЙ ЛАГЕРЬ (8.10, партия Г): волна W4 ушла в 9:32 по местному перевесу 37 против 22, за 40 с
        # пути его отступившие стали лагерем 30 + подход 9, и в 10:30-11:00 мы потеряли там 32 против его 10 — а у нашей
        # базы в 8:30 и 13:00 те же его силы теряли 33 и 36 против наших 7 и 6. Прогноз по приходу в 10:13 давал остаток
        # наших 0,28, в 10:28 R 1,0. Ключ `лагерь_отход` (порог R): волна (не наш удар по лагерю) в клетке лагеря или
        # рядом, прогноз с его лагерем и идущими к нему ниже порога или наших останется меньше 0,3 — домой лицом к лагерю.
        _порог_отх = float(п.get("лагерь_отход", 0) or 0)
        волна = self.реестр.активная()
        if (_порог_отх > 0 and волна is not None and волна.подтверждена and волна.состояние not in ("ДОМОЙ", "КОНЧЕНА")
                and not self._бой_за_лагерь(st)):
            try:
                import анализ_врага as _АВ
                import прогноз as _ПР
                import combat_math as _CM
                import прокачки as _ПК
                import coss3_map as _КМ
                лагеря = [н for н in _АВ.текущий(st)["находки"] if н["вид"] == "лагерь"]
                гк = (int(волна.сбор[0]), int(волна.сбор[1]))
                л = next((н for н in лагеря if max(abs(гк[0] - н["центр"][0]), abs(гк[1] - н["центр"][1])) <= 1), None)
                д = _дом(st)
                if л is not None and max(abs(гк[0] - д[0]), abs(гк[1] - д[1])) > 1:
                    _ч = lambda a, b: max(abs(a[0] - b[0]), abs(a[1] - b[1]))
                    его_кл = [c for c in _список(st, "ecells", _КМ.его_клетки) if int(c.get("n") or 0) > 0]
                    наши_кл = [c for c in _список(st, "ocells", _КМ.наши_клетки) if int(c.get("n") or 0) > 0]
                    у = _ПР.состав_из_клеток(его_кл, гк, 1)
                    идут = [(_ПР.сек_пути(_ч((int(c["x"]), int(c["y"])), гк)), _ПР.состав_из_клеток([c])) for c in его_кл
                            if c.get("tx") is not None and int(c.get("tx")) >= 0 and _ч((int(c["tx"]), int(c["ty"])), гк) <= 1
                            and _ч((int(c["x"]), int(c["y"])), гк) >= 2]
                    сила = _ПР.состав_из_клеток([c for c in наши_кл if _ч((int(c["x"]), int(c["y"])), гк) <= 2])
                    свои_х, чужие_х = _CM.разобрать(st.get("fighters") or ""), _ПК._чужие_со_строем(st)
                    пр = _ПР.бой_по_приходу([(0, сила)], [(0, у)] + идут, свои_х, чужие_х) if свои_х and чужие_х else {}
                    R, ост = пр.get("R"), пр.get("остаток_наш")
                    if R is not None and (R < _порог_отх or (ост is not None and ост < 0.3)):
                        из = [c for c in из if not (c.get("cmd") in ("ATTACK", "ENGAGE") and c.get("group") == волна.номер)
                              and not (c.get("cmd") == "ATTACK" and str(c.get("target") or "") == "wave")]
                        из.insert(0, {"cmd": "RETREAT", "count": 0, "target": "cell", "cx": int(д[0]), "cy": int(д[1]),
                                      "group": волна.номер, "face": [int(л["центр"][0]), int(л["центр"][1])]})
                        волна.состояние = "ДОМОЙ"
                        волна.цель_клетка = (int(д[0]), int(д[1]))
                        self.реестр.мера["тактика: отход от лагеря"] += 1
                        записи.append(f"ОТХОД ОТ ЛАГЕРЯ: волна {волна.id} в {гк} у его лагеря {л['n']}"
                                      + (f" (+{sum(sum(c.values()) for _, c in идут):.0f} идут)" if идут else "")
                                      + f", прогноз R={R} остаток наших {ост} — домой, бой у базы")
            except Exception as e:
                записи.append(f"отход от лагеря не посчитан: {type(e).__name__}")
        # §136 ОТХОД ПРИ ПОДХОДЕ (10.10, партия Д живьём): анализ 15 тактов подряд, за 75 с до удара, видел его 43-49 (16
        # стрелков), идущих к нашей волне W4 (14) в (12,5); волна стояла ГОТОВА «МАЛО_СИЛ 0,23», подмога отвергалась как
        # невыгодная, отхода не было — 14:35-14:50 потеряли 28 против его 3. Правило §130 требует ЕГО ЛАГЕРЬ рядом с волной;
        # здесь лагеря нет — есть подход. Ключ `отход_при_подходе` (порог R): волна в поле (не дома, не наш удар по лагерю),
        # к её клетке идут его силы, прогноз боя по приходу (его у клетки + идущие против наших в двух клетках) ниже порога
        # или наших останется меньше 0,3 — RETREAT домой лицом к ближнему подходу. 0 — выкл.
        _порог_подх = float(п.get("отход_при_подходе", 0) or 0)
        волна = self.реестр.активная()
        if (_порог_подх > 0 and волна is not None and волна.подтверждена and волна.состояние not in ("ДОМОЙ", "КОНЧЕНА")
                and not self._бой_за_лагерь(st)):
            try:
                import прогноз as _ПР
                import combat_math as _CM
                import прокачки as _ПК
                import coss3_map as _КМ
                гк = (int(волна.сбор[0]), int(волна.сбор[1]))
                _ов = self._отряд_волны(st)
                if _ов is not None:
                    гк = (int(_ов["x"]), int(_ов["y"]))   # голова волны — отряд в поле, а не горстка у дома (`отряд_в_волне`)
                д = _дом(st)
                _ч = lambda a, b: max(abs(a[0] - b[0]), abs(a[1] - b[1]))
                if д is not None and _ч(гк, д) > 1:
                    его_кл = [c for c in _список(st, "ecells", _КМ.его_клетки) if int(c.get("n") or 0) > 0]
                    наши_кл = [c for c in _список(st, "ocells", _КМ.наши_клетки) if int(c.get("n") or 0) > 0]
                    # §136а (10.10, вторая партия Д): W1 (42) шла на его базу и с 8:25 стояла в двух клетках от его 81,
                    # стоящих без приказа; в 8:45 он шагнул на неё — 36 против 6 за десять секунд. Правило требовало
                    # МАРША издалека — а он стоял. Теперь его силы в двух клетках от волны считаются стоящими у неё,
                    # марш — из трёх и дальше; повод — либо то, либо другое.
                    # §170л (24.10, Д13, слово игрока «я пошёл к твоей армии — почему маленький отряд пошёл дальше в атаку»):
                    # подходом считалась его группа с точкой назначения в ОДНОЙ клетке от волны. В Д13 4:35 его 19 шли из (12,12)
                    # в (11,11) навстречу нашим кучкам (7,7)/(8,8) — точка не у волны, правило молчало до 5:56, когда его 25 уже
                    # стояли в двух клетках от головной четвёрки; потери 4 и 5 в 5:31/6:01. Ключ `отход_поля` 1: (а) подход —
                    # его группа, чья точка назначения БЛИЖЕ к волне, чем она сама (идёт на нас); (б) отход — ВСЕМ нашим в поле
                    # (дальше клетки от дома) числом, не только группе волны: в Д13 21 боец шёл тремя кучками по диагонали, волна
                    # «видела» четверых; прогноз — по тем, кто у головной клетки (кучки вступают в бой не вместе); (в) память выхода §170д гаснет — сироты не удержат никого.
                    _оп = int(п.get("отход_поля", 0) or 0)
                    идущие = [c for c in его_кл
                              if c.get("tx") is not None and int(c.get("tx")) >= 0 and _ч((int(c["x"]), int(c["y"])), гк) >= 3
                              and (_ч((int(c["tx"]), int(c["ty"])), гк) <= 1
                                   or (_оп and _ч((int(c["tx"]), int(c["ty"])), гк) < _ч((int(c["x"]), int(c["y"])), гк)))]
                    у = _ПР.состав_из_клеток(его_кл, гк, 2)
                    if идущие or sum(у.values()) > 0:
                        идут = [(_ПР.сек_пути(_ч((int(c["x"]), int(c["y"])), гк)), _ПР.состав_из_клеток([c])) for c in идущие]
                        # прогноз — по тем, кто у головной клетки (кучки по диагонали в бой вступают не вместе); отход — всем в поле
                        в_поле = [c for c in наши_кл if _ч((int(c["x"]), int(c["y"])), д) > 1]
                        сила = _ПР.состав_из_клеток([c for c in наши_кл if _ч((int(c["x"]), int(c["y"])), гк) <= 2])
                        свои_х, чужие_х = _CM.разобрать(st.get("fighters") or ""), _ПК._чужие_со_строем(st)
                        пр = _ПР.бой_по_приходу([(0, сила)], [(0, у)] + идут, свои_х, чужие_х) if свои_х and чужие_х else {}
                        R, ост = пр.get("R"), пр.get("остаток_наш")
                        n_идут = sum(int(c.get("n") or 0) for c in идущие)
                        n_у = int(sum(у.values()))
                        if R is not None and (R < _порог_подх or (ост is not None and ост < 0.3)):
                            ближ = min(идущие or [c for c in его_кл if _ч((int(c["x"]), int(c["y"])), гк) <= 2],
                                       key=lambda c: (_ч((int(c["x"]), int(c["y"])), гк), -int(c.get("n") or 0)))
                            из = [c for c in из if not (c.get("cmd") in ("ATTACK", "ENGAGE") and c.get("group") == волна.номер)
                                  and not (c.get("cmd") == "ATTACK" and str(c.get("target") or "") == "wave")
                                  and not (_оп and c.get("cmd") in ("ATTACK", "ENGAGE") and not c.get("group"))]
                            n_поля = sum(int(c.get("n") or 0) for c in в_поле)
                            if _оп and n_поля > 0:
                                # §170л (б): домой ВСЕ в поле числом (RETREAT числом берёт первых N дальше клетки от ратуши —
                                # это и есть все кучки); память выхода — прочь, чтобы сироты вернули отставших
                                из.insert(0, {"cmd": "RETREAT", "count": int(n_поля), "target": "cell", "cx": int(д[0]), "cy": int(д[1]),
                                              "face": [int(ближ["x"]), int(ближ["y"])]})
                                self._выход_поля = None
                            else:
                                из.insert(0, {"cmd": "RETREAT", "count": 0, "target": "cell", "cx": int(д[0]), "cy": int(д[1]),
                                              "group": волна.номер, "face": [int(ближ["x"]), int(ближ["y"])]})
                            волна.состояние = "ДОМОЙ"
                            волна.цель_клетка = (int(д[0]), int(д[1]))
                            self.реестр.мера["тактика: отход при подходе"] += 1
                            записи.append(f"ОТХОД ПРИ ПОДХОДЕ: у волны {волна.id} ({волна.размер}) в {гк} его {n_у} в двух клетках"
                                          + (f", наших в поле {n_поля} — все" if _оп else "")
                                          + (f", идут ещё {n_идут} (ближние через ~{min(с for с, _ in идут):.0f} с)" if идут else "")
                                          + f", прогноз R={R} остаток наших {ост} — "
                                          f"домой лицом к {ближ['x']},{ближ['y']}, бой у базы")
            except Exception as e:
                записи.append(f"отход при подходе не посчитан: {type(e).__name__}")
        # §125 НЕ ГНАТЬСЯ (игрок: лагерь под ударом «отвёл бы к потоку»; «вынести, чуть отойти, получить подкрепление»):
        # лагерь снят или ушёл — волна встаёт в его клетке лицом к его базе, к ней идёт подток; следующий удар — контракт
        # волны при местном перевесе (`рядом_при`), а не погоня в его поток
        if self._бой_за_лагерь(st) and not getattr(self, "_лагерь_встали", True):
            try:
                import coss3_map as _КМ
                лк = self._лагерь_кл
                его_там = sum(int(c.get("n") or 0) for c in _список(st, "ecells", _КМ.его_клетки)
                              if max(abs(int(c["x"]) - лк[0]), abs(int(c["y"]) - лк[1])) <= 1)
            except Exception:
                его_там = 99
            волна = self.реестр.активная()
            if его_там < 3 and волна is not None and волна.подтверждена:
                eb = _его_база(st)
                из = [c for c in из if not (c.get("cmd") in ("ATTACK", "ENGAGE") and c.get("group") == волна.номер)]
                из.insert(0, {"cmd": "RETREAT", "count": 0, "target": "cell", "cx": лк[0], "cy": лк[1], "group": волна.номер,
                              "face": [int(eb[0]), int(eb[1])] if eb else [лк[0], лк[1]]})
                self._лагерь_встали = True
                self.реестр.мера["тактика: встали на лагере"] += 1
                записи.append(f"ЛАГЕРЬ СНЯТ: волна {волна.id} встаёт в {лк}, не гонимся (его рядом {его_там}), подток к ней")
        try:
            из, _з = self._сироты_и_заслон(из, st)
            if _з:
                записи.append(_з)
        except Exception as e:
            записи.append(f"сироты/заслон не посчитаны: {type(e).__name__}")
        if float(п.get("подток", 0) or 0):
            пачка = int(float(п.get("пачка", 8) or 8))
            волна = self.реестр.активная()
            своб = int(float(st.get("my_freewar") or 0))
            _д1 = _дом(st)
            if (волна is not None and волна.подтверждена and волна.состояние not in ("ДОМОЙ", "КОНЧЕНА")
                    and max(abs(волна.сбор[0] - _д1[0]), abs(волна.сбор[1] - _д1[1])) > 1):        # волна в поле, не дома
                досылки = [c for c in из if c.get("cmd") == "ATTACK" and str(c.get("target") or "") == "wave"]
                if своб < пачка:
                    if досылки:
                        из = [c for c in из if c not in досылки]
                        self.реестр.мера["подток: досылок снято"] += len(досылки)
                        записи.append(f"ПОДТОК: копим пачку {своб}/{пачка}, досылок по одному не отдано {len(досылки)}")
                elif not getattr(self, "_держим_дом", False) or self._бой_за_лагерь(st):
                    if not досылки:
                        из.append({"cmd": "ATTACK", "count": "all", "target": "wave"})
                    self.реестр.мера["подток: пачек"] += 1
                    записи.append(f"ПОДТОК: пачка {своб} к волне {волна.id}")
        return из, "; ".join(записи)

    ЗАСЛОН_ПОЛЯ = 93

    def _сироты_и_заслон(self, из: list, st: dict):
        """§152 (12.10, первый бой Д4). Два ключа файла стратегии, оба 0 — выкл.

        `без_волны_домой` (N бойцов): наши в поле (дальше клетки от ратуши) БЕЗ волны — волны нет, она дома, идёт домой или
        кончена, — это сироты: Д4 4:09 отзыв W2 по номеру пересобрал группу из одного (§150), 12 остались в (5,5) без приказа и
        в 4:36 пошли по частям на его 10 (двойник: «ждать» 2–4 к 5:30 и 4–6 к 8:00, «к своим» 0–1 и 2–3; Fable — Б, домой).
        Сирот не меньше N — RETREAT числом домой лицом к его ближней куче, не чаще раза в 30 с. Не трогаем: бой за лагерь
        (§124), отряд §143 в ударе, свой заслон (ниже).

        `не_гнаться` (K клеток): его куча стоит в K клетках от ратуши, подхода к базе нет (иначе §143), наших свободных дома
        не меньше 5 и меньше `не_гнаться_при` (4) × неё — свободные ВСТАЮТ ЗАСЛОНОМ (группа 93) в клетке между ней и
        ратушей (на 2 клетки от ратуши к ней, при куче в 2 клетках — на 1), лицом к ней; удар по лагерю и удар готовой
        волны из дома по этой куче сняты (`_тактика`, `_удар_готовой`). Куча ушла дальше K или снята — заслон домой.
        Приказ повторяется при смене клетки или когда свободных прибавилось на `пачка` (8)."""
        п = self.п
        n_мин = int(float(п.get("без_волны_домой", 0) or 0))
        _нг = int(float(п.get("не_гнаться", 0) or 0))
        if n_мин <= 0 and _нг <= 0:
            return из, ""
        import coss3_map as _КМ
        t = float(st.get("gametime") or 0)
        д = _дом(st)
        if д is None:
            return из, ""
        _ч = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        его_кл = [c for c in _список(st, "ecells", _КМ.его_клетки) if int(c.get("n") or 0) > 0]
        наши_кл = [c for c in _список(st, "ocells", _КМ.наши_клетки) if int(c.get("n") or 0) > 0]
        группы = _группы(st)
        # ЖИВЬЁМ ГРУППЫ 93 В `groups` НЕ БЫВАЕТ (§152а, 12.10): блок состояния перечисляет группы 1..16
        # (`block_hstate.inc`, `for hgid := 1 to 16`), приказ же группе любого номера блок команд берёт — состав помнит
        # парсер `br_hgrp` (§150). То же для 91/92 кулака §143. Заслон узнаём по СВОЕЙ памяти `_заслон_поля` (клетка,
        # время, его куча) и по нашим бойцам в этой клетке и рядом; `MOVE … face` уходит ходом без удержания, бойцы
        # заслона стоят без приказа и в `my_freewar` СЧИТАЮТСЯ — свободных дома считаем по своим клеткам у ратуши.
        if not hasattr(self, "_заслон_поля"):
            self._заслон_поля = None
        прежде = self._заслон_поля
        заслон_гр = next((г for г in группы if int(г.get("id") or 0) == self.ЗАСЛОН_ПОЛЯ and int(г.get("n") or 0) > 0), None)
        заслон_кл = ((int(заслон_гр["cx"]), int(заслон_гр["cy"])) if заслон_гр is not None
                     else (tuple(прежде["кл"]) if прежде is not None else None))
        заслон_n = (int(заслон_гр["n"]) if заслон_гр is not None else
                    sum(int(c.get("n") or 0) for c in наши_кл if заслон_кл is not None and _ч((c["x"], c["y"]), заслон_кл) <= 1))
        if заслон_гр is None and прежде is not None and заслон_n == 0 and t - прежде["t"] > 60:
            self._заслон_поля = прежде = заслон_кл = None     # минуту в клетке никого: заслон распался или погиб
        заслон = {"n": заслон_n, "cx": заслон_кл[0], "cy": заслон_кл[1]} if заслон_кл is not None else None
        # §170г (22.10, Д11): кулак встречи §170б — тот же заслон для правила сирот: его бойцы шагают в соседнюю клетку
        # навстречу вошедшему (Д11 11:00: 122 в (4,2) при клетке встречи (3,2)) — без этого они «сироты», и RETREAT домой
        # уводил бы их из боя 90:6 в самый его разгар
        _дгс = getattr(self, "_дг", None) or {}
        if заслон is None and _дгс.get("клетка") is not None and _дгс.get("удар") is None:
            _вк = tuple(_дгс["клетка"])
            заслон = {"n": sum(int(c.get("n") or 0) for c in наши_кл if _ч((c["x"], c["y"]), _вк) <= 1), "cx": _вк[0], "cy": _вк[1]}
        волна = self.реестр.активная()
        # волна в поле (и идущая домой тоже: её бойцы уже под приказом) — сирот не ищем: приказ числом взял бы и её
        волна_в_поле = (волна is not None and волна.подтверждена and волна.состояние != "КОНЧЕНА"
                        and _ч(волна.сбор, д) > 1)
        # отряд в поле при живой волне — это и есть волна, его бойцы не сироты (`отряд_в_волне`)
        _ов = self._отряд_волны(st)
        if _ов is not None and волна is not None and волна.состояние != "КОНЧЕНА" and not волна_в_поле:
            волна_в_поле = True
            self.реестр.мера["отряд в волне: не сирота"] += 1
        # §170д (23.10, Д12 и Д11): одобренный ВЫХОД из дома (ATTACK/ENGAGE в клетку дальше дома, не кулак встречи) и через
        # 5 с «СИРОТЫ: наших 7 в поле без волны (5,13)» — RETREAT тех же бойцов: группа волны в `groups` оставалась дома
        # (7 человек), вышедшие «все» в ней не числились. Д12 3:25/4:00/4:42/5:02/5:27 (его 3–28 бойцов, дорога к крестьянам),
        # Д11 3:14 и 3:49. Выход помним на время пути до цели (+30 с); бойцы между домом и целью — не сироты.
        # (память пишет `_помнить_выход` в конце `ответ`: ручеёк §113 выпускает ATTACK ПОСЛЕ этого правила)
        выход = getattr(self, "_выход_поля", None)
        if выход is not None and (t > выход["до"] or (волна is not None and волна.состояние == "ДОМОЙ")):
            self._выход_поля = выход = None
        записи = []
        сироты_отданы = False
        # --- сироты домой. Пока заслон стоит (память жива) — не отдаём: RETREAT числом берёт первых N дальше клетки
        # от ратуши и увёл бы сам заслон (отбор блока, §150)
        if n_мин > 0 and not волна_в_поле and not self._бой_за_лагерь(st) and (getattr(self, "_дг", None) or {}).get("удар") is None:
            сироты = [c for c in наши_кл if _ч((c["x"], c["y"]), д) > 1
                      and not (заслон is not None and _ч((c["x"], c["y"]), (заслон["cx"], заслон["cy"])) <= 1)
                      and not (выход is not None and _ч((c["x"], c["y"]), выход["цель"]) < _ч(д, выход["цель"]))]
            n = sum(int(c.get("n") or 0) for c in сироты)
            в_пути = (sum(int(c.get("n") or 0) for c in наши_кл if _ч((c["x"], c["y"]), д) > 1) - n) if выход is not None else 0
            if в_пути > 0 and n < n_мин:
                записи.append(f"сироты: наших {в_пути} в поле идут к цели выхода {выход['цель']} — не трогаем")
            if n >= n_мин and t - getattr(self, "_сироты_gt", -1e9) >= 30 and заслон is None:
                ближ = min(его_кл, key=lambda c: _ч((c["x"], c["y"]), д)) if его_кл else None
                лицо = [int(ближ["x"]), int(ближ["y"])] if ближ else [int(д[0]), int(д[1])]
                из = [c for c in из if c.get("cmd") not in ("ATTACK", "ENGAGE") or c.get("group")]
                из.insert(0, {"cmd": "RETREAT", "count": int(n), "target": "cell", "cx": int(д[0]), "cy": int(д[1]), "face": лицо})
                self._сироты_gt = t
                сироты_отданы = True
                self.реестр.мера["сироты домой"] += 1
                _где = ", ".join("%s,%s:%s" % (c["x"], c["y"], c["n"]) for c in сироты[:4])
                записи.append(f"СИРОТЫ: наших {n} в поле без волны ({_где}) — домой лицом к {лицо[0]},{лицо[1]}")
            elif n >= n_мин and заслон is not None:
                записи.append(f"сироты {n} в поле, но заслон стоит — не трогаем")
        # --- заслон между его кучей и ратушей
        if _нг > 0:
            _поз = getattr(self, "_подход", None)
            рядом = [c for c in его_кл if 2 <= _ч((c["x"], c["y"]), д) <= _нг]
            # свободных ДОМА: `my_freewar` считает и стоящий заслон (он без приказа) — берём меньшее из него и наших у ратуши
            своб = min(int(float(st.get("my_freewar") or 0)),
                       sum(int(c.get("n") or 0) for c in наши_кл if _ч((c["x"], c["y"]), д) <= 1))
            _при = float(п.get("не_гнаться_при", 4.0) or 4.0)
            if рядом:
                self._заслон_нет_с = None   # 1.11: куча снова видна — отсчёт «домой» заново
            if рядом and not _поз and not self._бой_за_лагерь(st) and not getattr(self, "_держим_дом", False):
                куча = max(рядом, key=lambda c: (int(c.get("n") or 0), -_ч((c["x"], c["y"]), д)))
                n_его = sum(int(c.get("n") or 0) for c in его_кл if _ч((c["x"], c["y"]), (куча["x"], куча["y"])) <= 1)
                dx, dy = int(куча["x"]) - д[0], int(куча["y"]) - д[1]
                дист = max(abs(dx), abs(dy))
                # §154 (13.10, первый бой Д5 6:32-7:47): заслон ставился на 2 клетки от ратуши — при его куче в 3 клетках
                # это ВПЛОТНУЮ к ней (6:10 его 24 в (5,10), наши 36 в (5,11)/(4,11)); глаза считали заслон «в поле» (дома
                # 7-12 при 49), он ударил в него 24 на 36 — 21 : 24, а кулак §143 в 6:52 (свободных +16 — это заслон
                # дошёл) и повтор заслона в 7:02 (его куча сдвинулась в клетку боя) дёргали бьющихся MOVE: 13 : 4 на
                # отходе. Двойник (sim/решения/д5_первый_бой.md): «навстречу 36» (2 клетки) худшая у всех трёх агентов,
                # заслон на 1 клетку и «ждать дома» лучше; живьём второй бой 9:09 — его 25 вошли в клетку ратуши: 18 : 25.
                # Ключ `заслон_от_ратуши` (1): клетка заслона не дальше его от ратуши и не ближе 2 клеток к его куче
                # (куча в 2 клетках — заслона нет, бьёт движок/кулак); 0 — заслон не ставится вовсе, остаются вето.
                # В рукопашной (наша клетка = его клетка с ≥ 3) и минуту после кулака заслон не ставится и не переставляется.
                _от = int(float(п.get("заслон_от_ратуши", 1) or 0))
                k = min(_от, дист - 2)
                кл = (int(д[0] + round(k * dx / дист)), int(д[1] + round(k * dy / дист))) if k >= 1 else None
                _его_кл = {(int(c["x"]), int(c["y"])) for c in его_кл if int(c.get("n") or 0) >= 3}
                в_бою = any((int(c["x"]), int(c["y"])) in _его_кл for c in наши_кл)
                после_кулака = t - getattr(self, "_кулак_t", -1e9) < 60
                # §170г: пока встреча §170б ждёт удержания или держит строй, заслон §152 его не переставляет — любой MOVE
                # снимает fStandGround, и 37,5 с стояния до fHoldMode начинаются заново (Д11 10:16: MOVE 122 в ту же клетку)
                _дгв = getattr(self, "_дг", None) or {}
                if _дгв.get("клетка") is not None and (_дгв.get("ждут") or _дгв.get("держат")):
                    после_кулака = True
                # «всего» — свободные в клетках у ратуши и у заслона без двойного счёта (заслон на 1 клетку — он же дом)
                _клетки = [c for c in наши_кл if _ч((c["x"], c["y"]), д) <= 1
                           or (заслон_кл is not None and _ч((c["x"], c["y"]), заслон_кл) <= 1)]
                всего = min(int(float(st.get("my_freewar") or 0)), sum(int(c.get("n") or 0) for c in _клетки))
                # приказ один раз на клетку: повтор только когда куча сдвинулась (тогда числом — все: заслон без приказа
                # и свободные дома, отбор блока «первые N без приказа» берёт и тех и других); в такт с сиротами не отдаём —
                # файл приказа один
                надо = (кл is not None and всего >= 5 and всего < _при * max(1, n_его) and not сироты_отданы
                        and not в_бою and not после_кулака
                        and (прежде is None or tuple(прежде["кл"]) != кл))
                if кл is None and _от >= 1 and своб >= 5 and not сироты_отданы and прежде is None:
                    записи.append(f"его {n_его} в {куча['x']},{куча['y']} ({дист} кл. от ратуши) — заслон не ставим, вплотную; не гонимся")
                elif кл is None and _от < 1 and своб >= 5 and not сироты_отданы:
                    записи.append(f"его {n_его} в {куча['x']},{куча['y']} ({дист} кл. от ратуши) — заслон выключен, не гонимся")
                elif (в_бою or после_кулака) and кл is not None and всего >= 5 and всего < _при * max(1, n_его) and (прежде is None or tuple(прежде["кл"]) != кл):
                    записи.append(f"его {n_его} в {куча['x']},{куча['y']}: {'рукопашная' if в_бою else 'кулак только что'} — заслон не переставляем")
                    self.реестр.мера["не гнаться: заслон не трогаем в бою"] += 1
                if надо:
                    из = [c for c in из if c.get("group") != self.ЗАСЛОН_ПОЛЯ]
                    _мз = {"cmd": "MOVE", "count": всего, "group": self.ЗАСЛОН_ПОЛЯ, "target": "cell", "cx": кл[0], "cy": кл[1],
                           "face": [int(куча["x"]), int(куча["y"])]}
                    if int(п.get("заслон_слияние", 0) or 0):
                        _мз["merge"] = 1   # пункт 2 (31.10): повторный заслон добавляет людей к группе, а не заменяет её состав
                    из.insert(0, _мз)
                    self._заслон_поля = {"кл": кл, "t": t, "его": (int(куча["x"]), int(куча["y"]))}
                    self.реестр.мера["не гнаться: заслон"] += 1
                    записи.append(f"ЗАСЛОН: его {n_его} стоят в {куча['x']},{куча['y']} ({дист} кл. от ратуши) — {всего} свободных в "
                                  f"{кл[0]},{кл[1]} лицом к нему, не гонимся")
                elif кл is not None and прежде is None and своб >= 5 and not сироты_отданы and всего >= _при * max(1, n_его):
                    записи.append(f"его {n_его} в {куча['x']},{куча['y']}: наших {всего} ≥ {_при:g}×{n_его} — заслон не нужен, бьём по правилам")
                elif прежде is not None:
                    _пк = tuple(прежде["кл"])
                    записи.append(f"заслон {заслон_n} в {_пк[0]},{_пк[1]} стоит против его {n_его} в {куча['x']},{куча['y']}")
            elif прежде is not None and not рядом:
                # ХВОСТ «ПОВТОР ЗАСЛОНА» (1.11): его куча мигала в ecells — заслон уходил домой и через такт вставал заново
                # (MOVE 15/28/45 на одну клетку за 74 с, 31.10 «вкл 3»), а каждый MOVE снимает стойку. Ключ `заслон_домой_сек` N:
                # домой только когда кучи нет N секунд подряд; 0 — как было (сразу).
                _ждать = float(п.get("заслон_домой_сек", 0) or 0)
                _нет_с = getattr(self, "_заслон_нет_с", None)
                if _нет_с is None:
                    self._заслон_нет_с = t
                    _нет_с = t
                if _ждать > 0 and t - _нет_с < _ждать:
                    записи.append(f"заслон {заслон_n} ждёт: его у ратуши не видно {t - _нет_с:.0f} с из {_ждать:.0f}")
                else:
                    из = [c for c in из if c.get("group") != self.ЗАСЛОН_ПОЛЯ]
                    из.insert(0, {"cmd": "RETREAT", "count": 0, "group": self.ЗАСЛОН_ПОЛЯ, "target": "cell", "cx": int(д[0]), "cy": int(д[1])})
                    self._заслон_поля = None
                    self.реестр.мера["не гнаться: заслон домой"] += 1
                    записи.append(f"ЗАСЛОН ДОМОЙ: его у ратуши больше нет, группа {self.ЗАСЛОН_ПОЛЯ} ({заслон_n}) в клетку ратуши")
                    self._заслон_нет_с = None
        return из, "; ".join(записи)

    def итог_волн(self) -> dict:
        """Меры волн за эпизод. `простой_готовой` важнее числа приказов: она
        прямо меряет, сколько тактов боеспособная волна стояла без решения."""
        р = self.реестр
        return {"волн": р.счёт,
                "простой_готовой_тактов": р.простой_готовой,
                "простой_подряд": р.подряд,
                "первый_удар": р.первый_удар,
                "мера": dict(р.мера)}

    def _нация_врага(self, st: dict) -> dict:
        """§170н (25.10, вопрос игрока про Польшу; ключи, 0 — как было). Нации врага python не знает — но блок пишет
        статы его бойцов (`p1_fighters`) и наших (`fighters`), и всё ниже считается из них, для любой нации.
        (1) `качество_врага` 1: его войска в состоянии пересчитаны в наши пики (`_веса_качества`): R, выход, прогноз
            найма и местный перевес по клеткам считают качество, а не головы. net против net — веса 1,0, ничего не меняется.
        (2) `стрелки_против_брони` 1: если его пика не держит пулю (`dbullet` ≤ `стрелки_против_брони_до` 1, у Польши 0 против
            наших 4), мушкетёры с `стрелки_раньше_с` (240) и долей `стрелки_раньше_доля` (0,33) вместо `мушк_с`/`доля_мушк` файла.
        (3) `конюшня_его` 1: его конюшня стоит (`p1_stable` ≥ 1) — `стрелки_позади` 1, отряд собирается сейчас (`отряд_с` = gt),
            а шахты дальше `шахты_ближе` (40) от ратуши не закладываются (в `привести`). Крестьян MOVE блока не берёт — их отвод
            остаётся заданием на блок."""
        п = self.п
        if not any(int(п.get(k, 0) or 0) for k in ("качество_врага", "стрелки_против_брони", "конюшня_его")):
            return st                                 # ключей нет — как было, ничего не трогаем
        отд = getattr(self.стр, "отдано", None)        # счётчики `Стратегии` рождаются в её первом вызове; заглушкам тестов они не нужны
        if отд is None:
            отд = collections.Counter()
            try:
                if not hasattr(self.стр, "пропущено"):
                    self.стр.пропущено = collections.Counter()
                self.стр.отдано = отд
            except Exception:
                pass
        gt = float(st.get("gametime") or 0)
        веса = _веса_качества(st) if int(п.get("качество_врага", 0) or 0) else None
        if веса and any(abs(веса[k] - 1.0) > 0.02 for k in ("пик", "стрелков", "конных")):
            было = float(st.get("p1_army") or 0)
            st = _состояние_по_качеству(st, веса)
            отд[f"§170н качество врага: его {было:.0f} голов = {float(st.get('p1_army') or 0):.0f} наших "
                f"(пика {веса['пик']:.2f}, стрелок {веса['стрелков']:.2f}, конный {веса['конных']:.2f})"] += 1
        # (2) стрелки против брони 0
        его_б = _разбор_бойцов(st.get("p1_fighters")).get("infantry17") if int(п.get("стрелки_против_брони", 0) or 0) else None
        if его_б is not None and float(его_б.get("dbullet") or 0) <= float(п.get("стрелки_против_брони_до", 1) or 0):
            с_раньше = float(п.get("стрелки_раньше_с", 240) or 0)
            доля_р = float(п.get("стрелки_раньше_доля", 0.33) or 0)
            исх_с = self._п_исход.get("мушк_с")
            п["мушк_с"] = min(float(исх_с), с_раньше) if исх_с is not None else с_раньше
            п["доля_мушк"] = max(float(self._п_исход.get("доля_мушк") or 0), доля_р)
            отд[f"§170н стрелки против брони {его_б.get('dbullet', 0)}: мушкетёры с {п['мушк_с']:.0f} с, доля {п['доля_мушк']:.2f}"] += 1
        else:
            for k in ("мушк_с", "доля_мушк"):
                if self._п_исход.get(k) is None:
                    п.pop(k, None)
                else:
                    п[k] = self._п_исход[k]
        # (3) его конюшня
        if int(п.get("конюшня_его", 0) or 0) and float(st.get("p1_stable") or 0) >= 1:
            п["стрелки_позади"] = 1
            исх_о = self._п_исход.get("отряд_с")
            п["отряд_с"] = min(float(исх_о), gt) if исх_о is not None else gt
            отд[f"§170н его конюшня: стрелки позади, отряд с {п['отряд_с']:.0f} с, шахты не дальше {float(п.get('шахты_ближе', 40) or 0):.0f}"] += 1
        else:
            for k in ("стрелки_позади", "отряд_с"):
                if self._п_исход.get(k) is None:
                    п.pop(k, None)
                else:
                    п[k] = self._п_исход[k]
        return st

    def _учесть_его_армию(self, st: dict) -> None:
        """§170к: история его армии (t, бойцов) за последние 120 с — по ней темп найма."""
        t = float(st.get("gametime") or 0)
        n = float(st.get("p1_army") or 0) or sum(float(st.get("p1_" + k) or 0) for k in ("inf", "shoot", "cav"))
        ист = getattr(self, "_его_армия_ист", None)
        if ист is None:
            ист = self._его_армия_ист = []
        if ист and t < ист[-1][0]:           # новая партия или откат времени — история чужая
            ист.clear()
        ист.append((t, n))
        while ист and t - ист[0][0] > 120:
            ист.pop(0)

    def _темп_его_найма(self, st: dict) -> tuple[float, str]:
        """§170к: бойцов в секунду, которых он добавит, пока мы идём. Большее из замеренного за 30–120 с и пола по
        казармам (`найм_казармы` 0,2/с на казарму с военной очередью `en_train`: в Д12 и его, и наш темп ровно 0,18–0,2
        с одной казармы). Замер один отстаёт: его найм разгоняется, когда казарма достроена."""
        t = float(st.get("gametime") or 0)
        n = float(st.get("p1_army") or 0) or sum(float(st.get("p1_" + k) or 0) for k in ("inf", "shoot", "cav"))
        замер = 0.0
        for t0, n0 in getattr(self, "_его_армия_ист", []):
            if t - t0 >= 30:
                замер = max(замер, (n - n0) / (t - t0))
                break
        очередь = str(st.get("en_train") or "")
        военная = any(x and not x.startswith("pea") for x in очередь.split(","))
        пол = float(self.п.get("найм_казармы", 0.2) or 0) * float(st.get("p1_ba17") or 0) if военная else 0.0
        темп = max(замер, пол)
        return темп, f"темп {темп:.2f}/с ({'замер' if замер >= пол else 'казарм ' + str(int(float(st.get('p1_ba17') or 0)))})"

    def _стойка_дома(self, из: list, st: dict, t: float) -> tuple:
        """Ключ `стойка_дома` K (с), 0/нет — как было (30.10 вечер). Раз в K с свободные бойцы дома (`my_freewar` ≥
        `стойка_дома_от`, 20) идут MOVE по числу группой ЗАСЛОН (91) в клетку рядом с ратушей со стороны врага, через
        `встреча_сек` (20) та же группа получает FACE hold лицом к его ближайшей куче (или базе). Зачем: в контейнерах
        против ИИ `my_held` 0 всю партию (винда 30.10: «рефлексу нечего отпускать»), и ни рефлекс (п. 1), ни оборонительная
        ATTACK блока (п. 2) судимы быть не могут — строй у дома делает судью возможным. Молчит при `defend_on` 1 и когда
        группе 91 уже есть приказ в этом такте."""
        п = self.п
        K = float(п.get("стойка_дома", 0) or 0)
        if K <= 0:
            return из, ""
        _с = getattr(self, "_судья", None)          # судья удара (4.11): при «не бьём» `defend_on` блока застыл на 1 — стойка нужна
        _судья_нет = bool(_с and _с.get("нет"))
        if int(float(st.get("defend_on") or 0)) == 1 and not _судья_нет:
            return из, ""
        if any(c.get("group") == self.ЗАСЛОН for c in из):
            return из, ""
        сост = getattr(self, "_стойка", None)
        if сост is None or t < float(сост.get("t0") or 0):
            сост = self._стойка = {"move_t": None, "done_t": None, "t0": t}
        if _судья_нет and not (getattr(self, "_судья_был", None) or {}).get("нет"):
            сост["move_t"], сост["done_t"] = None, None      # переход в «не бьём» — стойка в этот же такт, не через K с
            self.реестр.мера["судья удара: стойка сразу"] += 1
        д = _дом(st)
        лицо = _куда_смотреть(st)
        if not лицо:
            eb = st.get("en_base")
            if isinstance(eb, (list, tuple)) and len(eb) >= 2:
                try:
                    лицо = (int(eb[0]), int(eb[1]))
                except (TypeError, ValueError):
                    лицо = None
        if not лицо:
            return из, ""
        лицо = (int(лицо[0]), int(лицо[1]))
        sx = (лицо[0] > int(д[0])) - (лицо[0] < int(д[0]))
        sy = (лицо[1] > int(д[1])) - (лицо[1] < int(д[1]))
        клетка = (int(д[0]) + sx, int(д[1]) + sy)
        сек = float(п.get("встреча_сек", 20) or 20)
        if сост["move_t"] is not None and сост["done_t"] is None:
            if t - сост["move_t"] >= сек:
                сост["done_t"] = t
                из.insert(0, {"cmd": "FACE", "count": 0, "group": self.ЗАСЛОН, "face": [лицо[0], лицо[1]], "hold": 1})
                self.реестр.мера["стойка дома: FACE hold"] += 1
                return из, f"§170ж стойка дома: группа {self.ЗАСЛОН} в {клетка} держит строй лицом к {лицо} (FACE hold)"
            return из, ""
        if сост["done_t"] is not None and t - сост["done_t"] < K:
            return из, ""
        своб = int(float(st.get("my_freewar") or 0))
        if своб < int(п.get("стойка_дома_от", 20) or 20):
            return из, ""
        сост["move_t"] = t
        сост["done_t"] = None
        _мв = {"cmd": "MOVE", "count": 9999, "group": self.ЗАСЛОН, "target": "cell", "cx": int(клетка[0]), "cy": int(клетка[1])}
        if int(п.get("стойка_слияние", 0) or 0):
            # пункт 2 списка улучшений блока (31.10): состав группы 91 не заменять (merge) и держать по приходу (arrive) —
            # блок сам ставит стойку, когда люди пришли; FACE через 20 с остаётся для направления взгляда
            _мв["merge"] = 1
            _мв["arrive"] = 1
        из.insert(0, _мв)
        self.реестр.мера["стойка дома: MOVE"] += 1
        return из, f"§170ж стойка дома: свободных {своб} — MOVE группой {self.ЗАСЛОН} в {клетка} (FACE hold через {сек:.0f} с)"

    def _оборона_всем(self, из: list, st: dict) -> tuple:
        """§170ж (в) (30.10, Польша 12:47–13:08): ATTACK у дома шёл числом (9999), а 77 держали строй — блок отвечал «attack skipped 77
        holding soldiers (order them by group number to release)», и в бой пошли 27. Ключ `оборона_всем` 1: ATTACK в клетку не дальше
        `без_атаки_радиус` (5) от ратуши при держащих > 0 получает `all` 1 — блок берёт держащих и ведёт отряды, как при выходе §170у."""
        if not int(self.п.get("оборона_всем", 0) or 0):
            return из, ""
        # Рефлекс обороны блока (30.10, hcmd DEFENCE): пока `defend_on` 1, блок сам снял удержание и пустил всех в поиск врага —
        # FACE с hold этого такта не шлём, иначе через 5 с мы же вернём строй в стойку под ударом.
        _с = getattr(self, "_судья", None)          # судья удара (4.11): рефлекс снят DEFEND 0, а `defend_on` блока застыл — FACE hold нужен
        if int(float(st.get("defend_on") or 0)) == 1 and not (_с and _с.get("нет")):
            _снять = [c for c in из if c.get("cmd") == "FACE" and c.get("hold")]
            if _снять:
                из = [c for c in из if c not in _снять]
                self.реестр.мера["оборона: FACE снят при рефлексе"] += len(_снять)
                return из, f"§170ж рефлекс обороны блока: его {int(float(st.get('defend_n') or 0))} у ратуши — FACE/hold не шлём ({len(_снять)})"
        держат = float(st.get("my_held") or 0)
        if держат <= 0:
            return из, ""
        _д = _дом(st)
        _рад = float(self.п.get("без_атаки_радиус", 5) or 5)
        n = 0
        for c in из:
            if (c.get("cmd") == "ATTACK" and c.get("target") == "cell" and not c.get("who") and not c.get("group") and not c.get("all")
                    and not c.get("_гарнизон")            # (а) 1.11: удар с гарнизоном не превращать во «весь дом»
                    and c.get("cx") is not None and c.get("cy") is not None):
                try:
                    близко = max(abs(int(c["cx"]) - int(_д[0])), abs(int(c["cy"]) - int(_д[1]))) <= _рад
                except (TypeError, ValueError):
                    близко = False
                if близко:
                    c["all"] = 1
                    n += 1
        if not n:
            return из, ""
        self.реестр.мера["оборона всем"] += n
        return из, f"§170ж оборона всем: держащих {держат:.0f} — ATTACK у дома с all ({n})"

    def _конюшня(self, из: list, st: dict) -> tuple:
        """КОНЮШНЯ И КОННИЦА (1.11, слово игрока: сравнить тремя контейнерами «казарма века и её юниты / третья казарма / конюшня»).
        Расчёт 1.11 (`sim/век_казарма_конюшня.py`): рейтар Нидерландов 300 hp — 5,6–6,3 пики, 2,5 в минуту; рейтар Польши
        (`uniq_cav17`) 190 hp — 2,4–2,8 пики, 7,3 в минуту; конюшня 2500 дерева / 100 камня / 600 золота, нужна кузница.
        Ключ `конюшня_с` T (0 — как было): с T — BUILD stable `конюшен` (1); в стоящей конюшне бесконечный TRAIN роли `конница`
        (`reitar` — рейтар Нидерландов и крылатый гусар Польши, `uniq_cav17` — рейтар Польши; умолчание `reitar`), пока в её
        очереди (`ba_queues` `s<n>:…`) нет бесконечного заказа. Конница идёт в общие приказы армии (`who` пусто — все рода)."""
        п = self.п
        с = float(п.get("конюшня_с", 0) or 0)
        t = float(st.get("gametime") or 0)
        if с <= 0 or t < с:
            return из, ""
        надо = int(п.get("конюшен", 1) or 1)
        роль = str(п.get("конница", "reitar") or "reitar")
        стоит = float(st.get("stables") or 0)
        новые, речь = [], []
        if стоит < надо:
            новые.append({"cmd": "BUILD", "role": "stable", "total": надо})
            цена = _цена_здания(st, "stable") or {"wood": 2500, "stone": 100, "gold": 600}
            нехватка = [f"{r} {float(st.get(r) or 0):.0f}/{v:.0f}" for r, v in цена.items() if float(st.get(r) or 0) < v]
            речь.append(f"BUILD stable {надо} (есть {стоит:.0f})" + (f", не хватает: {', '.join(нехватка)}" if нехватка else ""))
        if стоит >= 1:
            очереди = [к.strip() for к in str(st.get("ba_queues") or "").split(",") if к.strip().startswith("s")]
            if not очереди or any(":none" in к or ":inf" not in к for к in очереди):
                новые.append({"cmd": "TRAIN", "role": роль, "total": -1})
                речь.append(f"TRAIN {роль} -1 (очереди конюшен: {', '.join(очереди) or 'нет'})")
        self.реестр.мера["конюшня"] += 1
        return новые + из, ("КОНЮШНЯ: " + "; ".join(речь)) if речь else ""

    def _лучники(self, из: list, st: dict) -> tuple:
        """ПЕШИЕ ЛУЧНИКИ (4.11 (207), слово игрока: «самым быстрым налётчиком могут оказаться пешие лучники — делай»).
        Турецкий archertur — казарма после кузницы (country.script:3056), 65 hp, стрела 20 на 16,9 тайла, 45 еды/4 золота.
        Ключ `лучники_с` T (0 — как было): с T секунд бесконечный TRAIN archer (роль 34) не чаще раза в 60 с — блок кладёт
        заказ только в казармы, где бесконечного заказа ЭТОГО юнита нет, пики не снимаются. Нет кузницы — игра откажет, блок
        скажет вслух. Водить их отдельно — `who=archer` (block_hcmd hawho, с той же правки); у других наций роли archer
        нет (у Алжира есть, у Польши и Нидерландов нет) — TRAIN ответит «no such object»."""
        с = float(self.п.get("лучники_с", 0) or 0)
        t = float(st.get("gametime") or 0)
        if с <= 0 or t < с:
            return из, ""
        if t - float(getattr(self, "_лучники_t", -999.0)) < 60.0:
            return из, ""
        self._лучники_t = t
        self.реестр.мера["лучники: заказ"] += 1
        return [{"cmd": "TRAIN", "role": "archer", "total": -1}] + из, "ЛУЧНИКИ: TRAIN archer -1 (казармы, где его заказа нет)"

    # Цены зданий пути в век [код] `sim/параметры.json` (unit.script): церковь tem, депо art; `ba2` — в `build_cost` нет
    ВЕК_ЗДАНИЯ = {"temple": {"wood": 1000, "stone": 1200, "iron": 500}, "artdepo": {"wood": 100, "stone": 1000, "coal": 1400}}

    def _путь_в_век(self, из: list, st: dict) -> tuple:
        """ПУТЬ В XVIII ВЕК (1.11, слово игрока: век на турнире разрешён, партия может идти дольше 15 минут — «к этому нужно быть
        готовым»). `cen.1` требует академию, церковь и депо (`country.script:3438`), стоит у Нидерландов 33 000 еды / 4800 золота /
        1800 железа / 1800 угля, у Польши 30 000 / 4800 / 2200 / 2200; казарма века `ba2` (пика XVIII века — 1,25 с, 30 еды, без
        железа, 48 в минуту) закладывается только ПОСЛЕ него (`century18` в требовании, `country.script:2937`), стройка ~8,7 мин при
        20 строителях. Расчёт 1.11 (`sim/век_казарма_конюшня.py`): одна `ba2` даёт 35–53 «пик в минуту» против 13–20 у казармы XVII века.
        Ключ `век_с` T (0 — как было): с секунды T
          * до `cen.1`: академия, церковь, депо (по одному); угольная шахта, если угля меньше нужного, и на ней `век_угля` (6);
            шахта железа, если железа меньше нужного, и на ней `век_железа` (5); при готовых церкви и депо — UPGRADE cen.1 каждый
            такт, пока не начат (блок сам проверяет цену и говорит «не хватает»);
          * `век_копить` (1): пока `cen.1` не начат, НЕвоенные UPGRADE снимаются (ступени казарм, мельница, кузница идут) — еда
            копится на 30 000, найм идёт; при нехватке угля/железа и полной шахте — следующая, до `век_шахт` (2);
          * после `cen.1`: `ba18` числом `век_ba2` (1), в ней бесконечный TRAIN pikeman18.
        Всё, что не сделано, — вслух в `why`: чего ждём и сколько не хватает. Судья — контейнер с `CENTURY18=0` на горизонте 1800."""
        п = self.п
        с = float(п.get("век_с", 0) or 0)
        t = float(st.get("gametime") or 0)
        if с <= 0 or t < с:
            return из, ""
        import combat_math as _CM
        import coss3_map as _КМ

        def ч(k):
            try:
                return float(st.get(k) or 0)
            except (TypeError, ValueError):
                return 0.0
        здания = _список(st, "obuild", _КМ.наши_здания)

        def есть(тип, готово=False):
            return sum(1 for b in здания if b.get("тип") == тип and (b.get("готово") or not готово))
        взято = {x.strip() for x in str(st.get("upg_done") or "").split(",") if x.strip()}
        идёт = {x.strip() for x in str(st.get("upg_doing") or "").split(",") if x.strip()}
        цены = _CM.цены_апгрейдов(st.get("upg_avail")) or _CM.цены_апгрейдов(st.get("upg_shown"))
        речь = []
        if "cen.1" not in взято:
            if "cen.1" not in цены and "cen.1" not in идёт:
                self.реестр.мера["век: cen.1 нет в списке"] += 1
                return из, "ВЕК: cen.1 нет среди доступных прокачек (век закрыт настройкой century18 или у нации его нет)"
            ц = цены.get("cen.1") or {}
            нужно = {"food": ц.get("food", 0), "gold": ц.get("gold", 0), "iron": ц.get("iron", 0) + (0 if есть("temple") else 500),
                     "coal": ц.get("coal", 0) + (0 if есть("artdepo") else 1400)}
            новые = []
            if ч("academies") < 1:
                новые.append({"cmd": "BUILD", "role": "academi", "total": 1})
            if not есть("temple"):
                новые.append({"cmd": "BUILD", "role": "temple", "total": 1})
            if not есть("artdepo") and ч("academies") >= 1:
                новые.append({"cmd": "BUILD", "role": "artdepo", "total": 1})
            # 1.11, century_net/1: одна шахта железа на пятерых (мест в шахте 5) давала ~480 в минуту, а две казармы пик Нидерландов
            # (20 железа на пику) ели столько же — железо стояло на 1550 с 13:00 до 21:00 при нужных 1800. Пока ресурса не хватает
            # и шахта полна (на ней ≥ 5 × шахт − 1), закладывается следующая, до `век_шахт` (2); людей — 5 на шахту, не меньше ключа.
            for рес, шахта, счёт, ключ, умолч in (("coal", "minecoal", "mines_coal", "век_угля", 6), ("iron", "mineiron", "mines_iron", "век_железа", 5)):
                if ч(рес) >= нужно[рес]:
                    continue
                if ч(счёт) < 1:
                    новые.append({"cmd": "BUILD", "role": шахта, "total": 1})
                else:
                    if ч("on_" + рес) >= 5 * ч(счёт) - 1 and ч(счёт) < int(п.get("век_шахт", 2) or 2):
                        новые.append({"cmd": "BUILD", "role": шахта, "total": int(ч(счёт)) + 1})
                    из = [c for c in из if not (c.get("cmd") == "BALANCE" and c.get("role") == рес)]
                    новые.append({"cmd": "BALANCE", "role": рес, "total": max(int(п.get(ключ, умолч) or умолч), 5 * int(ч(счёт))),
                                  "_важно": True})
                речь.append(f"{рес} {ч(рес):.0f}/{нужно[рес]:.0f}")
            # 1.11, century_net/1: `век_копить` снимал ВСЕ прокачки с 9:00 — у бота их осталось 7, у ИИ к 18:00 стало 15; его пика
            # 13 / 8 против нашей 11 / 5, бои 16:48–30:08 с разменом 0,08 и 0,13, армия 296 → 0, век не взят (еда 26 087 из 33 000).
            # Копим только на НЕвоенном: ступени казарм (`bar.*`, `ba2.*`), мельница и кузница идут как шли — «не отстать от
            # противника» важнее срока века. Снимаются академия и прочее.
            # `век_хоз_акад` 1 (1.11, century_net/2-ban: ИИ обогнал бота к 20:00 ровно на шесть прокачек академии, и все шесть —
            # хозяйство: aca.1/2/3 еда +40/+50/+50 %, aca.4 поля +200 %, aca.8 дерево +100 %, aca.23 камень +100 %; копилка их снимала
            # и сама же душила еду). Хозяйственные академии не снимаются и просятся каждый такт, пока не куплены (цену проверяет блок).
            ХОЗ_АКАД = ("aca.1", "aca.2", "aca.3", "aca.4", "aca.8", "aca.10", "aca.22", "aca.23")
            if int(п.get("век_хоз_акад", 0) or 0) and ч("academies") >= 1:
                for _а in ХОЗ_АКАД:
                    if _а not in взято and _а not in идёт and not any(c.get("cmd") == "UPGRADE" and c.get("role") == _а for c in из):
                        новые.append({"cmd": "UPGRADE", "role": _а})
            if int(п.get("век_копить", 1) or 0) and "cen.1" not in идёт:
                военные = ("bar.", "ba2.", "mil.", "bla.") + (ХОЗ_АКАД if int(п.get("век_хоз_акад", 0) or 0) else ())
                def _оставить(c):
                    и = str(c.get("upg") or c.get("role") or "")
                    return и.startswith(("bar.", "ba2.", "mil.", "bla.")) or и in военные
                снято = [c.get("upg") or c.get("role") for c in из if c.get("cmd") == "UPGRADE" and not _оставить(c)]
                из = [c for c in из if not (c.get("cmd") == "UPGRADE" and not _оставить(c))]
                if снято:
                    self.реестр.мера["век: прокачек снято"] += len(снято)
                    речь.append("копим: снято UPGRADE " + ",".join(str(x) for x in снято))
            # ПАУЗА НАЙМА ПРИ ПЕРЕВЕСЕ (1.11, century_pol/2-ban: армия 445–539 пик, размен 2,67, а еды 4–6 тысяч с 15 до 23 мин при
            # нужных 30 000 — прокорм армии ~50 еды/с; cen.1 только на 29:45, ba2 не успела). Ключ `век_перевес` K (0 — как было): пока
            # cen.1 не начат, его армия видна и наших бойцов ≥ K × его, заказы пик снимаются и бесконечный снимается `TRAIN
            # infantry17 0` (не чаще раза в 30 с). Перевес упал ниже K — найм возвращается сам (ярус 1 поддерживает очередь).
            _пер = float(п.get("век_перевес", 0) or 0)
            _наша = ч("mil_inf") + ч("mil_shooters") + ч("mil_cav")
            _его = ч("p1_army")
            if _пер > 0 and _его > 0 and _наша >= _пер * _его and ч("food") < нужно["food"] and "cen.1" not in идёт:
                из = [c for c in из if not (c.get("cmd") == "TRAIN" and c.get("role") in ("infantry17", 23) and int(c.get("total") or 0) != 0)]
                if "pikeman" in str(st.get("ba_queues") or "") and t - float(getattr(self, "_век_пики_сняты", -1000)) >= 30:
                    новые.append({"cmd": "TRAIN", "role": "infantry17", "total": 0})
                    self._век_пики_сняты = t
                self.реестр.мера["век: найм на паузе"] += 1
                речь.append(f"найм пик на паузе: наших {_наша:.0f} ≥ {_пер:g} × его {_его:.0f}")
            if есть("temple", True) and есть("artdepo", True) and "cen.1" not in идёт:
                нехватка = [f"{r} {ч(r):.0f}/{v:.0f}" for r, v in ц.items() if v and ч(r) < v]
                # 1.11, century_eco_pol/1: в 27:51 «хватает», а UPGRADE хозяйственной академии и ступени казарм стояли в списке РАНЬШЕ
                # cen.1 — блок купил их первыми, к 28:06 золота 59, век не взят до конца при еде 40 222. Когда хватает — cen.1 ПЕРВЫМ,
                # прочие UPGRADE этого такта снимаются.
                if not нехватка:
                    из = [c for c in из if c.get("cmd") != "UPGRADE"]
                    новые = [c for c in новые if c.get("cmd") != "UPGRADE"]
                    новые.insert(0, {"cmd": "UPGRADE", "role": "cen.1"})
                else:
                    новые.append({"cmd": "UPGRADE", "role": "cen.1"})
                речь.insert(0, "UPGRADE cen.1" + (f" — не хватает: {', '.join(нехватка)}" if нехватка else " — хватает"))
            else:
                речь.insert(0, "строим: " + ", ".join(f"{б} {'готова' if есть(б, True) else ('строится' if есть(б) else 'нет')}"
                                                      for б in ("temple", "artdepo")))
            self.реестр.мера["век: до cen.1"] += 1
            return новые + из, "ВЕК (до cen.1): " + "; ".join(речь)
        # век взят: казарма века и пика XVIII века
        надо_ba2 = int(п.get("век_ba2", 1) or 1)
        новые = []
        if ч("ba18") < надо_ba2:
            новые.append({"cmd": "BUILD", "role": "ba18", "total": надо_ba2})
            речь.append(f"BUILD ba18 {надо_ba2} (есть {ч('ba18'):.0f})")
            # 1.11, century_eco_net/1: век взят 26:47, а `ba2` (1700 дерева / 2950 камня / 4000 золота) ждала золото до ~29:00 —
            # прокачки после века его съедали. Пока `ba2` не заложена, копилка держит и её цену: прочие UPGRADE снимаются, кроме
            # ступеней казарм, мельницы и кузницы (как до века).
            _ц2 = {"wood": 1700, "stone": 2950, "gold": 4000}
            if int(п.get("век_копить", 1) or 0) and not any(b.get("тип") == "ba18" for b in здания) and any(ч(r) < v for r, v in _ц2.items()):
                снято = [c.get("role") for c in из if c.get("cmd") == "UPGRADE"
                         and not str(c.get("role") or c.get("upg") or "").startswith(("bar.", "ba2.", "mil.", "bla."))]
                из = [c for c in из if not (c.get("cmd") == "UPGRADE"
                                            and not str(c.get("role") or c.get("upg") or "").startswith(("bar.", "ba2.", "mil.", "bla.")))]
                if снято:
                    речь.append("копим на ba2: снято UPGRADE " + ",".join(str(x) for x in снято))
        if ч("ba18") >= 1 and "pikeman18:inf" not in str(st.get("ba18_queues") or ""):
            новые.append({"cmd": "TRAIN", "role": "pikeman18", "total": -1})
            речь.append("TRAIN pikeman18 -1")
        self.реестр.мера["век: после cen.1"] += 1
        return новые + из, ("ВЕК взят: " + "; ".join(речь)) if речь else ""

    def _ратуша_своими(self, из: list, st: dict) -> tuple:
        """(б) КЛЕТКА РАТУШИ СВОИМИ (1.11, живая Польша 6680, ПЛАН 55). Наша армия 172–213 выиграла бой у его лагеря в соседней
        клетке (87 его против 3 наших), а его 20–23 пики стояли В КЛЕТКЕ РАТУШИ 683–730 с, где наших было 1–6, — 49 крестьян.
        `наших_дома` (4 клетки) этого не видит: 242 «дома». Ключ `ратуша_своими` N (0 — как было): его в клетке ратуши
        (`ecells`) ≥ N и наших там (`ocells`) < `ратуша_перевес` (1,2) × его → ATTACK в клетку ратуши: свободными числом
        `ратуша_доля` (1,5) × его, если их хватает; иначе `all` 1 — весь дом, отряды отрядами, держащие тоже, — но только
        когда в двух клетках от ратуши нет другого боя, где его больше `ратуша_бой_доля` (0,25) наших (не срывать идущий бой;
        живьём на 683 с у лагеря его 66 при наших 172 — бой, через 5 с его 87 легли). Свободных меньше половины порога — ждём. Повтор не
        чаще `ратуша_повтор` (10) с. Приказ движения этого такта один — остальные ATTACK/ENGAGE/MOVE/RETREAT/FACE снимаются."""
        п = self.п
        порог = float(п.get("ратуша_своими", 0) or 0)
        if порог <= 0:
            return из, ""
        try:
            import coss3_map as _КМ
            д = _дом(st)
            его_кл = _список(st, "ecells", _КМ.его_клетки)
            наши_кл = _список(st, "ocells", _КМ.наши_клетки)
        except Exception as e:
            return из, f"ратуша своими не посчитана: {type(e).__name__}"

        def _в(кл, x, y):
            return sum(int(float(c.get("n") or 0)) for c in кл if int(c.get("x", -1)) == x and int(c.get("y", -1)) == y)

        # (в) ЗОНА РАТУШИ И РЕЙД НА ПОДХОДЕ (2.11, разбор разделения армии: 10 живых партий, 327 из 333 наших крестьян легли в
        # клетке ратуши или СОСЕДНЕЙ — 162 и 165). Человек делит армию: большая группа стоит лагерем в 3–6 клетках, малая
        # (29–51) режет крестьян у ратуши. Правило смотрело одну клетку: №10 1.11 — его 51 в соседней (12,2), правило молчит,
        # 13 крестьян за минуту при 165 праздных; №7 31.10 — рейд 30 шёл (11,14) → (12,14) к ратуше, бот бил лагерь 88, потом
        # 49 крестьян за полминуты. Экзамен вслепую: подход — Fable Б ×3 (всем по рейду, 88 — приманка), qwen3 В/Б/Б; рейд —
        # Fable Д/Б/Д (правило на соседние клетки, всем домом), qwen3 В/Б. Ключ `ратуша_радиус` R (0 — как было, одна клетка):
        # цель — клетка в R от ратуши, где его больше всего; ключ `ратуша_подход` 1 (0 — как было): его идущие, чья цель в
        # зоне, а сами не дальше R+1, считаются в зоне — удар в их клетку, пока они не дошли до крестьян.
        _рад = int(float(п.get("ратуша_радиус", 0) or 0))
        _подх = int(float(п.get("ратуша_подход", 0) or 0))
        _ч = lambda x, y: max(abs(x - д[0]), abs(y - д[1]))
        кандидаты = {}
        for c in его_кл:
            x, y, n = int(c.get("x", -1)), int(c.get("y", -1)), int(float(c.get("n") or 0))
            if n <= 0:
                continue
            if _ч(x, y) <= _рад:
                кандидаты[(x, y)] = кандидаты.get((x, y), 0) + n
            elif _подх and _ч(x, y) <= _рад + 1 and int(float(c.get("идут") or 0)) > 0 and c.get("tx") is not None \
                    and int(c.get("tx")) >= 0 and _ч(int(c["tx"]), int(c["ty"])) <= _рад:
                кандидаты[(x, y)] = кандидаты.get((x, y), 0) + int(float(c.get("идут") or 0))
        _цель = max(кандидаты, key=кандидаты.get) if кандидаты else (int(д[0]), int(д[1]))
        его = кандидаты.get(_цель, 0) if кандидаты else _в(его_кл, д[0], д[1])
        наших = _в(наши_кл, _цель[0], _цель[1])
        if его < порог or наших >= float(п.get("ратуша_перевес", 1.2) or 1.2) * его:
            return из, ""
        _где = "в клетке ратуши" if _цель == (int(д[0]), int(д[1])) else f"в {_ч(*_цель)} кл. от ратуши ({_цель[0]},{_цель[1]})"
        if _цель != (int(д[0]), int(д[1])):
            self.реестр.мера["оборона: зона ратуши"] += 1
        t = float(st.get("gametime") or 0)
        _был = getattr(self, "_ратуша_at", None)
        if _был is not None and 0 <= t - _был < float(п.get("ратуша_повтор", 10) or 10):
            return из, f"РАТУША: его {его} {_где}, наших {наших} — приказ отдан {t - _был:.0f} с назад"
        нужно = int(-(-float(п.get("ратуша_доля", 1.5) or 1.5) * его // 1))
        своб = int(float(st.get("my_freewar") or 0))
        приказ = {"cmd": "ATTACK", "target": "cell", "cx": int(_цель[0]), "cy": int(_цель[1]), "_оборона": True}
        if своб >= нужно:
            приказ["count"] = нужно
            как = f"свободными {нужно}"
        else:
            бой, _доля_боя = [], float(п.get("ратуша_бой_доля", 0.25) or 0.25)
            for c in его_кл:
                x, y = int(c.get("x", -1)), int(c.get("y", -1))
                if (x, y) == tuple(д) or (x, y) == tuple(_цель) or max(abs(x - д[0]), abs(y - д[1])) > 2:
                    continue
                n_его = int(float(c.get("n") or 0))
                if n_его >= порог and n_его > _доля_боя * _в(наши_кл, x, y) and _в(наши_кл, x, y) > 0:
                    бой.append((x, y, n_его))
            if бой:
                if своб < порог / 2:
                    return из, (f"РАТУША: его {его} {_где}, наших {наших}; свободных {своб}, армия в бою {бой[0][:2]} "
                                f"(его {бой[0][2]}) — не срываем")
                приказ["count"] = своб
                как = f"свободными {своб} (армия в бою {бой[0][:2]}: его {бой[0][2]})"
            else:
                приказ["count"], приказ["all"] = "all", 1
                как = f"всем домом (свободных {своб} < {нужно})"
        из = [c for c in из if c.get("cmd") not in ("ATTACK", "ENGAGE", "MOVE", "RETREAT", "FACE")]
        из.insert(0, приказ)
        self._ратуша_at = t
        self.реестр.мера["оборона: клетка ратуши своими"] += 1
        return из, f"РАТУША: его {его} {_где if _цель != (int(д[0]), int(д[1])) else f'в клетке ратуши {д[0]},{д[1]}'}, наших {наших} — ATTACK {как}"

    def _без_атаки(self, из: list, st: dict) -> tuple:
        """§170ё (30.10, russia_noattack_6011, слово игрока «только оборона до 12:00»): ЗАПРЕТ АТАКИ ДО СРОКА.
        Пять ключей волны (T1/T2 720, P1 0, штурм_при 1e9) не держат: ручеёк «РАЗМЕН_ОК из дома», подток «пачка N к волне»,
        удар готовой волны и лагерь шлют ATTACK мимо них (копия 1: волны 66/62/46/38 до 12:00). Ключ `без_атаки_до` (секунды,
        0 — как было): до этого времени ATTACK/ENGAGE снимаются, кроме обороны у дома — `_оборона`, `_огонь`, target home и
        клетка цели не дальше `без_атаки_радиус` (5) от ратуши. Возвращает (из, строка why или "")."""
        _бз = float(self.п.get("без_атаки_до", 0) or 0)
        gt = float(st.get("gametime") or 0)
        if _бз <= 0 or gt >= _бз:
            return из, ""
        _д = _дом(st)
        _рад = float(self.п.get("без_атаки_радиус", 5) or 5)

        # 4.11 (208): `без_атаки_резак` 1 — пачка РЕЗАК идёт и до срока (турецкий налётчик: армия дома до 12:00, а налёт
        # лучниками с 4-й минуты); проба tur_arch 4.11 — запрет снимал каждый налёт до 720 с. 0 — как было
        _рез_можно = int(float(self.п.get("без_атаки_резак", 0) or 0)) >= 1

        def _дома(c):
            if c.get("_оборона") or c.get("_огонь") or c.get("target") == "home":
                return True
            if _рез_можно and c.get("_резак"):
                return True
            if c.get("target") == "cell" and c.get("cx") is not None and c.get("cy") is not None:
                try:
                    return abs(int(c["cx"]) - int(_д[0])) <= _рад and abs(int(c["cy"]) - int(_д[1])) <= _рад
                except (TypeError, ValueError):
                    return False
            return False

        _снято = [c for c in из if c.get("cmd") in ("ATTACK", "ENGAGE") and not _дома(c)]
        if not _снято:
            return из, ""
        из = [c for c in из if c not in _снято]
        self.реестр.мера["без атаки: снято"] += len(_снято)
        return из, (f"§170ё без атаки до {_бз:.0f} с: снято {len(_снято)} ("
                    + ", ".join(f"{c.get('cmd')} {c.get('count', c.get('group', ''))}→{c.get('target')}" for c in _снято[:3]) + ")")

    def ответ(self, st: dict) -> dict:
        """Ответ в форме модели: {"commands": [...], "why": "..."}.

        Правила хозяйства и порядок команд (`привести`) применяет сама `Стратегия` — и в
        симуляторе, и здесь (3.10, §57): поиск оптимизирует ровно то, что исполняется вживую."""
        _тр_режим = self._режим_турции(st)               # 4.11 (214): враг Турция — ключи `при_турции` ДО дебюта
        if not self.стр.я.дебют.готов(st):
            # дебют ведёт мост (`debut.py` той же длины); команды дебюта стратегии — в числовой
            # форме Command и мосту модельным путём непонятны
            return {"commands": [], "why": f"стратегия {self.имя}: ждёт конца дебюта"}
        self._учесть_его_армию(st)        # §170к: темп его найма для прогноза к приходу
        # счётчики `Стратегии` копятся всю партию — строка такта печатает ТОЛЬКО разность (§163, ниже)
        _было_проп = collections.Counter(getattr(self.стр, "пропущено", None) or {})
        _было_отд = collections.Counter(getattr(self.стр, "отдано", None) or {})
        st = self._нация_врага(st)        # §170н: его войска в наших пиках, стрелки против брони 0, его конюшня
        из = self.стр(st)
        why = f"стратегия {self.имя}: {len(из)} команд"
        из = [_мостовая_цель(c) for c in из]
        if self.сеть is not None:
            # признаки — тем же переводом живого снимка, что у тени (§44); приказ сети — первым
            import shadow_tactic, tactic_core
            с = shadow_tactic.из_моста(st)
            р = self.сеть.решить(с)
            if р is not None:
                имя = tactic_core.РЕШЕНИЯ[р[0]]
                self.решения[имя] += 1
                # ПРИКАЗЫ ВОЛНЕ ОТ СЕТИ ПЕРЕВОДЯТСЯ, А НЕ ОТБРАСЫВАЮТСЯ (3.10). Здесь
                # стояло `if not cmd.startswith("_")`, и это съедало ровно те решения, из-за
                # которых приказы и делались: в прогоне `smoke_net/1` сеть трижды сказала
                # «держать» при волне В ПОЛЕ (540, 572, 680 с), а в игру не ушло ничего —
                # внутренние команды отсекались ДО перевода. Переводим живым состоянием
                # `st`, а не `с`: `_в_мостовые` читает `obuild`, `ocells` и `mil_away`, а
                # `с` — уже пересчитанная в форму симулятора сводка.
                бой = []
                for c in self.сеть.команды(р[0], с, живой=True):
                    cmd = str(c.get("cmd", ""))
                    if cmd.startswith("_"):
                        пер = _лицом_к_врагу(_в_мостовые(c, cmd, st), st)
                        if пер is None:
                            self.пропущено[f"сеть: {cmd}"] += 1
                            continue
                        self.пропущено[f"сеть: {cmd} -> {пер['cmd']}"] += 1
                        бой.append(_мостовая_цель(пер))
                        continue
                    бой.append(_мостовая_цель(c))
                if бой:
                    # Приказ сети вытесняет собственные ATTACK/RETREAT стратегии, и ENGAGE
                    # тоже: файл приказа один, двум командам одного рода в такте не уехать.
                    из = бой + [c for c in из
                                if c["cmd"] not in ("ATTACK", "RETREAT", "ENGAGE")]
                    из = из[:ПОТОЛОК_КОМАНД]
                why += f"; сеть {self.имя_сети}: {имя}"
                if self.пропущено:
                    why += " (" + ", ".join(f"{k} ×{v}" for k, v in
                                            self.пропущено.most_common(3)) + ")"
        # РЕЕСТР ВОЛН СВЕРЯЕТСЯ С ИГРОЙ ДО ВСЕГО ОСТАЛЬНОГО: кто ещё жив, где
        # стоит, кого уже нет. Иначе приказ уйдёт волне, которой в игре нет.
        # getattr, а не прямое поле: объект иногда собирают через __new__ (так
        # делают проверки `selftest_groups`, `selftest_wave_orders`), и
        # отсутствие реестра не имеет права ронять такт — ровно та же оговорка,
        # что уже стоит у памяти слияний ниже.
        if not hasattr(self, "реестр"):
            self.реестр = РеестрВолн()
        self.реестр.записи.clear()
        self.реестр.обновить(st)
        # --- РУКИ: ОБОРОНА ДОМА ПО ГЛАЗАМ (6.10, ключ `оборона` в файле стратегии) ---------------
        из, _об = self._оборона(из, st)
        if _об:
            self.реестр.записи.append(_об)
        из, _кт = self._кайт(из, st, float(st.get("gametime") or 0))   # §170о: стрелки «залп и шаг назад» — ключ `кайт`
        if _кт:
            self.реестр.записи.append(_кт)
        из, _тр = self._против_турции(из, st)              # 4.11 (204): сторожа шахт против налётов Турции — ключ `против_турции`
        if _тр:
            self.реестр.записи.append(_тр)
        self._приказ_удара = None
        из, _тк = self._тактика(из, st)                     # §124: удар по лагерю и подток — после обороны, до ручейка
        if _тк:
            self.реестр.записи.append(_тк)
        из, _вк = self._выход_к(из, st)                     # §169г: выход к его крестьянам по сроку — ДО ручейка и удара волны
        if _вк:
            self.реестр.записи.append(_вк)
        из, _рч = self._без_ручейка(из, st, "до")           # §113: запрет ручейка — приказы стратегии до нумерации
        if _рч:
            self.реестр.записи.append(_рч)
        из, _ог = self._огонь_рядом(из, st)                 # §164: стрелки бьют его стоящий строй у ратуши — после ручейка, без номера волны
        if _ог:
            self.реестр.записи.append(_ог)
        из, _рез = self._резак_крестьян(из, st)             # 1.11: малая пачка по его крестьянам, пока армия в поле — без номера волны
        if _рез:
            self.реестр.записи.append(_рез)
        из, _оп = self._отряд_в_поле(из, st)                # 2.11: отряд в поле в удержании бьёт малую группу рядом — без номера волны
        if _оп:
            self.реестр.записи.append(_оп)
        из, _рш = self._раш(из, st)                         # 4.11 (214): пики с первого юнита на его базу — ключ `раш`
        if _рш:
            self.реестр.записи.append(_рш)
        if _тр_режим:
            self.реестр.записи.append(_тр_режим)
        # НОМЕР УХОДЯЩЕЙ ВОЛНЕ. Только ATTACK с числом бойцов: это и есть «волна
        # ушла», и ровно она становится группой. Приказы уже существующим группам
        # (count 0) номера не трогают.
        for c in из:
            if c["cmd"] == "ATTACK" and not c.get("group") and not c.get("_огонь") and not c.get("_отряд"):
                # `count` бывает СЛОВОМ «all» — так стратегия и сеть просят всех
                # свободных («подмога»). Живая партия проверки 5 показала цену
                # недосмотра: номер получила ОДНА волна из 81, потому что
                # int(float("all")) падал и число считалось нулём. Остальные
                # восемьдесят ушли безымянными, и адресовать их было нечем.
                _сч = c.get("count", 0)
                if isinstance(_сч, str) and _сч.strip().lower() in ("all", "все"):
                    _сколько = 1          # «все свободные» — это заведомо больше нуля
                else:
                    try:
                        _сколько = int(float(_сч or 0))
                    except (TypeError, ValueError):
                        _сколько = 0
                if _сколько > 0:
                    # ПРИСОЕДИНЕНИЕ, А НЕ РОЖДЕНИЕ. Пока волна жива, уходящие
                    # бойцы входят в неё под её же номером: именно выдача нового
                    # номера каждый такт выжгла 16 из 16 в партии 4.10.
                    _в = self.реестр.активная()
                    if _в is not None:
                        c["group"] = _в.номер
                        self.отдано["вошли в волну"] += 1
                        self.реестр.мера["вошли в волну"] += 1
                        continue
                    _в = self.реестр.родить(st, str(c.get("target") or ""))
                    _ном = _в.номер if _в is not None else 0
                    if _ном:
                        c["group"] = _ном
                        self.номера += 1
                        # В `why` про рождение группы НЕ ПИШЕМ, и это куплено прогоном
                        # `smoke_hard4` 4.10: там стратегия просила подмогу к волне
                        # каждый такт, мост 17 раз отказывал честно («в поле нет своих
                        # дальше двух клеток от базы, идти не к кому»), а моё `why` все
                        # 17 раз сообщало «волна становится группой 1» — группы не было
                        # ни одной. Номер здесь только НАЗНАЧАЕТСЯ приказу; родилась
                        # группа или нет, знает отправка, и она об этом говорит сама
                        # («волна N: ... , группа M»). Намерение видно в трассе: поле
                        # `group` лежит в самой команде.
                        self.отдано["номер волне"] += 1
                    else:
                        why += "; номера групп кончились (16), волна без номера"
        # --- ВАЛИДАТОР ПРИКАЗОВ: ПОДМОГА В СВОЮ ЖЕ КЛЕТКУ ЗАПРЕЩЕНА ----------
        #
        # 4.10 таких приказов было 94 из 95. Отбросить их недостаточно: тогда
        # вместо бессмысленного приказа получится молчание, из которого потом
        # нельзя понять, почему бот снова простоял. Поэтому отказ ведёт к ЯВНОМУ
        # переходу состояния ниже, и у него всегда есть названная причина.
        волна = self.реестр.активная()
        _оставить, _отказы = [], collections.Counter()
        for c in из:
            _пр, _прич = нормализовать_подмогу(c, волна, st)
            if _пр is not None:
                _оставить.append(_пр)
            else:
                _отказы[_прич] += 1
                self.реестр.мера[f"подмога отвергнута: {_прич}"] += 1
        из = _оставить

        # КУДА ВОЛНА ПОСЛАНА — ЗАПОМИНАЕМ С ЛЮБОГО ПРИКАЗА, не только своего.
        # Удар на T1 отдаёт сама стратегия, и без этого волна не знала бы своей
        # цели: тогда подмога к ней снова пошла бы в клетку, где она стоит, а
        # это и есть топтание на месте из партии 5.10.
        if волна is not None:
            for c in из:
                if (c.get("cmd") in ("ATTACK", "ENGAGE") and not c.get("_огонь")
                        and c.get("target") == "cell"
                        and c.get("cx") is not None and c.get("cy") is not None):
                    волна.цель_клетка = (int(c["cx"]), int(c["cy"]))
                    break

        # --- ЯВНЫЙ ПЕРЕХОД «СОБРАНО -> АТАКОВАТЬ ИЛИ НАЗВАТЬ ПРИЧИНУ» --------
        if волна is not None:
            # ПРИШЛА И СТОИТ — ЗНАЧИТ ПОРА ПЕРЕСПРОСИТЬ СЕБЯ. Это CONTINUE/REGROUP
            # из автомата: без него волна остаётся в В_БОЮ до конца партии.
            # Живая партия 5.10: W1 ушла в 1:29, дошла до клетки (7,6) и стояла
            # там с 1:29 до 8:07, растя с 21 до 27, пока его кучи стояли в
            # (3,2), (2,3) и (4,4) — то есть «стоящая армия» вернулась, просто
            # после удара. Признак «дошла» — своя клетка совпала с клеткой
            # приказа; признак «стоит» — тот же, что у сбора: не растёт.
            if (волна.состояние == "В_БОЮ" and волна.цель_клетка
                    and tuple(волна.сбор) == tuple(волна.цель_клетка)
                    and волна.не_растёт >= ТАКТОВ_БЕЗ_РОСТА):
                волна.состояние = "ГОТОВА"
                волна.цель_клетка = None
                self.реестр.мера["волна дошла и переспрашивает"] += 1
                self.реестр.записи.append(
                    f"WAVE_ARRIVED {волна.id} cell={волна.сбор[0]},{волна.сбор[1]} "
                    f"size={волна.размер} t={_мин(st.get('gametime'))}")
            # ДВА ПРИЗНАКА «СОБРАНО», и второй куплен разбором 4.10 на живых
            # снимках. Первый: подмогу отвергли — посылать больше некого.
            # Второй: подмога законна и уезжает каждый такт, а волна НЕ РАСТЁТ.
            # Ровно так и было с 11:02 до 14:58: 59 бойцов, приказы подмоги
            # уходят честно, рост нулевой, удара нет. Без второго признака волна
            # остаётся в СБОРЕ вечно, и вся эта правка не сработала бы.
            _почему = ""
            if _отказы.get("СОБРАНО"):
                _почему = "подмогу отвергли"
            elif волна.не_растёт >= ТАКТОВ_БЕЗ_РОСТА:
                _почему = f"не растёт {волна.не_растёт} тактов"
            if _почему and волна.состояние == "СБОР":
                волна.состояние = "ГОТОВА"
                self.реестр.мера[f"собрано: {_почему.split()[0]}"] += 1
                self.реестр.записи.append(
                    f"WAVE_READY {волна.id} size={волна.размер} "
                    f"t={_мин(st.get('gametime'))} ({_почему})")
            занят = any(c["cmd"] in ("ATTACK", "RETREAT", "ENGAGE") for c in из)
            if волна.состояние == "ГОТОВА" and not занят:
                приказ, причина = self._удар_готовой(волна, st)
                if приказ is not None:
                    из.append(приказ)
                    self._приказ_удара = приказ
                    волна.состояние = "В_БОЮ"
                    волна.ударов += 1
                    волна.причина = ""
                    волна.цель_клетка = (int(приказ.get("cx", -1)),
                                         int(приказ.get("cy", -1)))
                    if self.реестр.первый_удар is None:
                        self.реестр.первый_удар = float(st.get("gametime") or 0)
                    self.реестр.мера["удар готовой волны"] += 1
                    self.реестр.подряд = 0
                    self.реестр.записи.append(
                        f"ORDER_ATTACK {волна.id} target={приказ.get('target')} "
                        f"reason={причина}")
                else:
                    # НЕТ ПРИКАЗА — НО ЕСТЬ ПРИЧИНА. Ровно эта запись и была
                    # нужна в разборе 4.10 вместо 94 одинаковых приказов.
                    волна.причина = причина
                    self.реестр.простой_готовой += 1
                    self.реестр.подряд += 1
                    self.реестр.мера[f"простой готовой: {причина}"] += 1
                    self.реестр.записи.append(
                        f"NO_ACTION {волна.id} reason={причина} "
                        f"тактов подряд {self.реестр.подряд}")

        if getattr(self, "_приказ_удара", None) is not None:
            из, _рч = self._без_ручейка(из, st, "удар")       # §113: и удар готовой волны — тем же прогнозом
            if _рч:
                self.реестр.записи.append(_рч)
        # ПОВТОР ПРИКАЗА СЛИЯНИЯ. Сам приказ мог прийти этим тактом (тогда он уже
        # в `из`) или тактами раньше; пока клетки разные, его надо повторять, иначе
        # получатель уйдёт, а пославший встанет в пустой клетке.
        # getattr, а не прямое поле: объект иногда собирают через __new__ (так делают
        # проверки), и отсутствие памяти не имеет права ронять такт.
        if not hasattr(self, "сводим"):
            self.сводим = {}
        for c in из:
            if c.get("target") == "group" and c.get("group") and c.get("gid"):
                self.сводим[int(c["group"])] = int(c["gid"])
        if self.сводим:
            места = {int(г["id"]): (int(г["cx"]), int(г["cy"]))
                     for г in _группы(st) if int(г.get("n") or 0) > 0}
            for a in list(self.сводим):
                b = self.сводим[a]
                if a not in места or b not in места or места[a] == места[b]:
                    # слились, дошли или группы больше нет — повторять нечего
                    self.сводим.pop(a, None)
                    continue
                уже = any(c.get("group") == a and c.get("target") == "group" for c in из)
                занят = any(c["cmd"] in ("ATTACK", "RETREAT", "ENGAGE") for c in из)
                if уже or занят:
                    # файл приказа один на такт: повторим следующим, а не затрём бой
                    why += f"; слияние {a}->{b} отложено (приказ такта занят)"
                    break
                из.append({"cmd": "RETREAT", "count": 0, "target": "group",
                           "group": a, "gid": b})
                why += f"; повтор слияния {a}->{b}"
                break
        # §170ё: запрет атаки до срока — последним, после всех, кто шлёт ATTACK (волна, ручеёк, подток, лагерь, выход)
        # Выключатель рефлекса обороны блока (30.10): ключ `рефлекс_обороны` -1/нет — блок как есть (включён по умолчанию); 0/1 —
        # DEFEND шлётся первым тактом и раз в 60 с (блок помнит, повтор — на случай потери файла). Плечо A/B: тот же файл, ключ 0.
        # Стойка дома (30.10 вечер, ключ `стойка_дома`): строй у ратуши для контейнерного судьи пункта 2 — до ворот и до DEFEND.
        из, _сд_why = self._стойка_дома(из, st, float(st.get("gametime") or 0))
        if _сд_why:
            why += "; " + _сд_why
        # a2 — выключатель оборонительной ATTACK блока (30.10 вечер, пункт 2): ключ `оборона_числом` -1/нет — как есть
        # (в блоке включено), 0/1 — явно; шлётся тем же DEFEND (a1 рефлекс, a2 оборонительная ATTACK).
        _рф = self.п.get("рефлекс_обороны", None)
        _оч = self.п.get("оборона_числом", None)
        _рф = int(float(_рф)) if _рф is not None else -1
        _оч = int(float(_оч)) if _оч is not None else -1
        # СУДЬЯ УДАРА (4.11 вечер): прогноз лагеря у дома ниже порога — DEFEND 0/0 СРАЗУ (рефлекс обороны и оборонительная ATTACK
        # блока сняты: иначе блок сам отпускает держащих «искать жертву» в его строй), при смене решения — в тот же такт, не раз в 60 с.
        # Возврат: лагеря нет или R ≥ порога — DEFEND по ключам (нет ключей — 1/1, как блок по умолчанию).
        _с = getattr(self, "_судья", None)
        _судья_нет = bool(_с and _с.get("нет"))
        _было_нет = bool(getattr(self, "_defend_судья", False))
        if _судья_нет:
            _рф_ш, _оч_ш = 0, 0
        else:
            _рф_ш, _оч_ш = (_рф if _рф >= 0 else 1), (_оч if _оч >= 0 else (1 if _было_нет else -1))
        if _рф >= 0 or _оч >= 0 or _судья_нет or _было_нет:
            _t = float(st.get("gametime") or 0)
            _смена = (_рф_ш, _оч_ш) != getattr(self, "_defend_last", None)
            if _смена or getattr(self, "_defend_at", None) is None or _t - self._defend_at >= 60.0 or _t < self._defend_at:
                self._defend_at = _t
                self._defend_last = (_рф_ш, _оч_ш)
                из.append({"cmd": "DEFEND", "count": _рф_ш, "atk": _оч_ш})
                why += f"; DEFEND {_рф_ш}/{_оч_ш} (рефлекс обороны блока / оборонительная ATTACK)"
                if _судья_нет:
                    why += f" — судья удара: {_с['причина']} (R={_с['R'] if _с['R'] is None else format(_с['R'], '.2f')}, порог {_с['порог']:g}, его {_с['n']} в {_с['рад']:g} кл.)"
                    self.реестр.мера["судья удара: DEFEND 0"] += 1
                elif _было_нет:
                    why += " — судья удара: удар снова годится или лагеря нет, рефлекс возвращён"
                    self.реестр.мера["судья удара: DEFEND возвращён"] += 1
            self._defend_судья = _судья_нет
        из, _бз_why = self._без_атаки(из, st)
        if _бз_why:
            why += "; " + _бз_why
        из, _ов_why = self._оборона_всем(из, st)
        if _ов_why:
            why += "; " + _ов_why
        из, _рс_why = self._ратуша_своими(из, st)         # (б) 1.11: последним из приказов движения — его в клетке ратуши
        if _рс_why:
            why += "; " + _рс_why
        # 1.11: при двух и больше ратушах (ключ `ратуш`) крестьяне заказываются КАЖДЫЙ такт — ярус 1 молчит, когда `pea` уже есть в
        # `train_now`, и вторая ратуша стояла бы пустой, как вторая казарма в Д2/Д4 (§147); блок кладёт бесконечный заказ только туда,
        # где его нет. Еда ниже 500 — найм стоит сам (движок), просить незачем.
        if (int(self.п.get("ратуш", 0) or 0) >= 2 and float(st.get("centers") or 0) >= 2 and float(st.get("food") or 0) >= 500
                and not any(c.get("cmd") == "TRAIN" and c.get("role") == "peasant" for c in из)):
            из.append({"cmd": "TRAIN", "role": "peasant", "total": -1})
        из, _кон_why = self._конюшня(из, st)              # 1.11: конюшня и конница (ключ `конюшня_с`)
        if _кон_why:
            why += "; " + _кон_why
        из, _лк_why = self._лучники(из, st)               # 4.11 (207): пешие лучники Турции (ключ `лучники_с`)
        if _лк_why:
            why += "; " + _лк_why
        из, _век_why = self._путь_в_век(из, st)           # 1.11: XVIII век (ключ `век_с`)
        if _век_why:
            why += "; " + _век_why
        из, _сж_why = self._судья_снять(из, st)           # судья удара (4.11): последним — после всех, кто шлёт удары
        if _сж_why:
            why += "; " + _сж_why
        из, _пч_why = self._пачка_удара(из, st)           # пачка удара (4.11): повтор `all` не уводит рекрутов по одному
        if _пч_why:
            why += "; " + _пч_why
        # ТОЛЬКО ЭТОГО ТАКТА (18.10, §163). `пропущено`/`отдано` у `Стратегии` копятся всю партию (так их читают
        # селфтесты и симулятор), а строка такта печатала НАКОПЛЕННОЕ: в Д7 «TRAIN peasant -1 (§147б: ждём mil.1) ×3»
        # стояло в 108 тактах с 4:13 до 13:16, хотя пауза §155 длилась 21 с (4:08 `TRAIN peasant 0` → 4:29 `-1` по
        # `upg_doing`), и винда прочла фантом как восемь минут без найма. Здесь — разность с началом такта, и события
        # правил (`отдано`: пауза, снятие, ворота) теперь тоже вслух — иначе их по трассе не проверить.
        _проп = collections.Counter(getattr(self.стр, "пропущено", None) or {}) - _было_проп
        if _проп:
            why += "; живая игра не умеет: " + ", ".join(f"{k} ×{v}" for k, v in _проп.most_common(4))
        _отд = collections.Counter(getattr(self.стр, "отдано", None) or {}) - _было_отд
        _отд = collections.Counter({k: v for k, v in _отд.items() if not (k.isascii() and k.isupper())})  # не счёт команд
        if _отд:
            # записи с номером параграфа — вперёд: по ним винда проверяет правила, и их не должно вытеснять «BALANCE food (переходник)»
            _пор = sorted(_отд.items(), key=lambda kv: ("§" not in kv[0], -kv[1], kv[0]))[:16]   # 29.10 (Д26): при 8 терялись §170щ/§170э — правила работали «молча»
            why += "; правила: " + ", ".join((f"{k} ×{v}" if v > 1 else k) for k, v in _пор)
        # СТРОКА ТАКТА ПРО ВОЛНУ. Одна запись вместо 94 одинаковых приказов:
        # разбор 4.10 пришлось вести руками по номерам приказов именно потому,
        # что состояние волны нигде не писалось.
        _в = self.реестр.активная()
        if _в is not None:
            why += (f" | wave={_в.id} status={_в.состояние} size={_в.размер}"
                    f" cell={_в.сбор[0]},{_в.сбор[1]}")
            if _в.причина:
                why += f" reason={_в.причина}"
        if _отказы:
            why += " | подмога отвергнута: " + ", ".join(
                f"{k} ×{v}" for k, v in _отказы.most_common(3))
        if self.реестр.записи:
            why += " | " + "; ".join(self.реестр.записи)
        # ГЛАЗА (6.10, `угрозы.py`): картина угроз в каждой строке такта — по ней разбор видит, ЗНАЛ ли
        # бот о набеге, когда принимал решение. Решений по ней пока нет: это слой реакции, следующий шаг.
        try:
            import угрозы as _УГ
            why += " | глаза: " + _УГ.оценить(st)["строка"]
        except Exception as e:                   # молчаливый отброс неотличим от бездействия — причину вслух
            why += f" | глаза упали: {e!r}"[:160]
        # АНАЛИЗ ПРОТИВНИКА (7.10, §118, `анализ_врага.py`): что он ГОТОВИТ — лагерь у нашей базы, стрелки без пик, отрыв.
        # Картина, не решение: по ней разбор видит, за сколько до потерь мост знал о его ходе.
        try:
            import анализ_врага as _АВ
            _ав = _АВ.текущий(st)
            if _ав["находки"]:
                why += " | анализ: " + _ав["строка"]
        except Exception as e:
            why += f" | анализ упал: {e!r}"[:160]
        # ЧАСТОКОЛ НА ПУТИ (1.11): живой путь приказов кончается здесь, а не в `привести` —
        # её зовёт только симулятор. Без этой строки правило в живой игре не работало вовсе.
        стена_в_приказах(из, st, self.п, self.реестр)
        self._помнить_выход(из, st)
        return {"commands": из, "why": why}

    def _помнить_выход(self, из: list, st: dict) -> None:
        """§170д: окончательный список приказов такта содержит ATTACK/ENGAGE в клетку дальше дома (не кулак встречи) —
        помним цель и срок пути (+30 с): правило сирот §152 не возвращает идущих к ней (Д12 3:25→3:30, Д11 3:14→3:19)."""
        import прогноз as _ПР
        д = _дом(st)
        if д is None:
            return
        t = float(st.get("gametime") or 0)
        _ч = lambda a, b: max(abs(int(a[0]) - int(b[0])), abs(int(a[1]) - int(b[1])))
        for c in из:
            if c.get("cmd") not in ("ATTACK", "ENGAGE") or c.get("group") in (self.ЗАСЛОН, self.ОТРЯД, self.ПОДМОГА):
                continue
            if c.get("cx") is not None and c.get("cy") is not None:
                ц = (int(c["cx"]), int(c["cy"]))
            elif c.get("_цель") is not None:              # §170к: выход на peasants несёт клетку цели сам (29.10)
                ц = (int(c["_цель"][0]), int(c["_цель"][1]))
            elif str(c.get("target") or "") == "base" and _его_база(st) is not None:
                ц = tuple(int(v) for v in _его_база(st))
            else:
                continue
            if _ч(ц, д) > 1:
                self._выход_поля = {"t": t, "цель": ц, "до": t + _ПР.сек_пути(_ч(ц, д)) + 30}
                self.реестр.мера["сироты: выход запомнен"] += 1


def _мостовая_цель(c: dict) -> dict:
    """`peasants_free` есть только в симуляторе (крестьяне без его армии); у моста — `peasants`,
    которая тоже ищет клетку с крестьянами и отбрасывает охраняемые (`клетка_охоты`)."""
    if c.get("cmd") == "ATTACK" and c.get("target") == "peasants_free":
        c = dict(c, target="peasants")
    # клетка: симулятор пишет `aim: [x, y]`, мост ждёт `cx`, `cy` (`to_commands`)
    if c.get("cmd") == "ATTACK" and c.get("target") == "cell" and isinstance(c.get("aim"), (list, tuple)):
        c = dict(c, cx=int(c["aim"][0]), cy=int(c["aim"][1]))
        c.pop("aim", None)
    return c


def _его_база(st: dict):
    v = st.get("en_base")
    if isinstance(v, str):
        v = [x for x in v.replace(";", ",").split(",") if x.strip()]
    try:
        return (int(float(v[0])), int(float(v[1])))
    except (TypeError, ValueError, IndexError):
        return None


def _клетки_крестьян(st: dict, его_кл: list) -> list:
    """Его крестьяне по клеткам: живое поле `en_pea_cells` [{x, y, крестьян, бойцов_рядом}], иначе сетка `prow0..15`
    (симулятор), охрана — его бойцы в 1 клетке по `ecells`. Общее для правила ручейка (§113)."""
    v = st.get("en_pea_cells")
    if isinstance(v, list) and v:
        return [q for q in v if isinstance(q, dict)]
    import coss3_map
    из = []
    for y in range(16):
        ряд = st.get(f"prow{y}")
        if not isinstance(ряд, str):
            continue
        for x, ch in enumerate(ряд):
            n = coss3_map.счёт(ch) if ch != "+" else 62
            if n >= 1:
                охр = sum(int(c.get("n") or 0) for c in его_кл if max(abs(int(c["x"]) - x), abs(int(c["y"]) - y)) <= 1)
                из.append(dict(x=x, y=y, крестьян=n, бойцов_рядом=охр))
    return из


def _враг_турция(st: dict) -> bool:
    """Враг — Турция? По ОТПЕЧАТКУ СТАТОВ в `p1_fighters` (4.11 (205), проба tur_raid_pol): у ЧУЖИХ бойцов блок sid не
    пишет — только `роль=hp..,atk..`, и поиск `=tatar,` молчал всю партию. Здоровье ролей Турции из unit.script:
    пикинёр 95, янычар 65, лёгкая пехота 55, татарин 185 (он же дальность 2062). Турция — если сошлись три роли из
    четырёх: hp ступенями почти не растёт, а одна случайная совпадает у других наций. sid, если вдруг пришёл, — тоже."""
    сырое = str(st.get("p1_fighters") or "")
    if any(sid in сырое for sid in ("=tatar,", "=jannisary,", "=pikemantur,")):
        return True
    б = _разбор_бойцов(сырое)
    отпечаток = {"infantry17": 95, "musk17": 65, "uniq_inf17": 55, "uniq_cav17": 185}
    сошлось = sum(1 for р, hp in отпечаток.items() if int(float((б.get(р) or {}).get("hp", -1) or -1)) == hp)
    return сошлось >= 3


def _наша_база(st: dict) -> tuple:
    if st.get("my_cx") is not None and st.get("my_cy") is not None:
        return (int(float(st["my_cx"])), int(float(st["my_cy"])))
    return _дом(st)


def клетка_сбора(st: dict, от_его: int = 4):
    """§74: на прямой от нашей ратуши к его — в `от_его` клетках (Чебышёв) от его ратуши."""
    е, н = _его_база(st), _наша_база(st)
    if е is None:
        return None
    dx, dy = н[0] - е[0], н[1] - е[1]
    d = max(abs(dx), abs(dy))
    if d <= от_его:
        return н
    return (е[0] + round(dx * от_его / d), е[1] + round(dy * от_его / d))


def _сбор(из: list, st: dict, п: dict, стр, пропущено, отдано) -> list:
    """СБОР ВОЛН (4.10, §74; задание Windows в ПЛАН.md). Волну стратегии (ATTACK) мост не
    отдаёт сразу: сперва стоячий STAGE в клетку сбора (4 клетки от его ратуши), и когда там
    `сбор_доля` наших бойцов И (наших не меньше его армии ИЛИ ждём `сбор_ждать` с) — STAGE off и
    ENGAGE на цель волны. Проверка 3: волна входила в его базу кусками 24 → 15+15 → 25 → 29 → 35.
    Общее для симулятора и моста (§57). Выключено, пока у стратегии нет рычага `сбор` ≥ 0,5."""
    if float(п.get("сбор", 0) or 0) < 0.5:
        return из
    t = float(st.get("gametime") or 0)
    с = getattr(стр, "_сбор_сост", None)
    волны = [c for c in из if c.get("cmd") == "ATTACK"]
    из = [c for c in из if c.get("cmd") != "ATTACK"]
    if any(c.get("cmd") == "RETREAT" for c in из):
        return из              # отход стратегии главнее; сбор не сбрасывается — вернувшиеся свободны,
                               # и STAGE снова ведёт их в клетку сбора (перегруппировка)
    if с is None and волны:
        кл = клетка_сбора(st, int(п.get("сбор_клеток", 4)))
        if кл is None:
            return из + волны[:1]
        цель = волны[0].get("target") or "army"
        с = {"клетка": кл, "цель": "army" if цель == "wave" else цель, "aim": волны[0].get("aim"), "t0": None}
        стр._сбор_сост = с
        отдано["STAGE (сбор)"] += 1
        return [{"cmd": "STAGE", "cx": int(кл[0]), "cy": int(кл[1]), "keep": 0}] + из
    if с is None:
        return из
    if волны:
        пропущено["ATTACK -> копим в сборе"] += len(волны)
    кл = с["клетка"]
    собрано = sum(float(c.get("n") or 0) for c in _список(st, "ocells", __import__("coss3_map").наши_клетки)
                  if abs(int(c.get("x", -9)) - кл[0]) <= 1 and abs(int(c.get("y", -9)) - кл[1]) <= 1)
    всего = sum(float(st.get(k) or 0) for k in ("mil_inf", "mil_shooters", "mil_cav"))
    if собрано >= 1 and с["t0"] is None:
        с["t0"] = t
    вс = st.get("враг_слот")
    его = float(st.get(f"p{int(вс)}_army" if вс is not None else "p1_army") or 0)
    ждём = t - с["t0"] if с["t0"] is not None else 0.0
    if всего > 0 and собрано >= float(п.get("сбор_доля", 0.8)) * всего and \
            (собрано >= его or ждём >= float(п.get("сбор_ждать", 120))):
        стр._сбор_сост = None
        # count обязателен: без него мост бракует ENGAGE («нужно число бойцов > 0», selftest_сбор)
        удар = {"cmd": "ENGAGE", "count": 200, "target": с["цель"]}
        if с["цель"] == "cell" and с.get("aim"):
            удар.update(cx=int(с["aim"][0]), cy=int(с["aim"][1]))
        отдано["ENGAGE (сбор)"] += 1
        return [{"cmd": "STAGE", "off": 1}, удар] + из
    return из


def _сзади(из: list, st: dict, п: dict, стр, пропущено, отдано) -> list:
    """СТРЕЛКИ ПОЗАДИ ВОЛНЫ (4.10, §87) — прикрытие §82 на НЫНЕШНЕМ блоке, без правок: пока волна в поле,
    через такт стрелки получают RETREAT who=musk17 в клетку на шаг от волны к нашей базе. RETREAT берёт
    бойцов дальше одной клетки от ратуши (идущих тоже), `who` — род, цель-клетка — ход без боя; там они стоят без
    приказа и, по замеру §82, бьют из соседней клетки. Одна команда волне за такт — поэтому в такты без
    своего ATTACK/RETREAT/ENGAGE. Проверка 4: стрелки шли с волной под приказом — 2 убитых на 12 своих."""
    if float(п.get("мушк_сзади", 0) or 0) < 0.5:
        return из
    стр._сзади_такт = not getattr(стр, "_сзади_такт", False)
    if not стр._сзади_такт or any(c.get("cmd") in ("ATTACK", "RETREAT", "ENGAGE", "MOVE", "STAGE") for c in из):
        return из
    if float(st.get("mil_shooters") or 0) < 3 or float(st.get("wave_n") or 0) < 5 or st.get("wave_cx") is None:
        return из
    wx, wy = int(float(st["wave_cx"])), int(float(st["wave_cy"]))
    нx, нy = _наша_база(st)
    кл = (wx + (нx > wx) - (нx < wx), wy + (нy > wy) - (нy < wy))
    отдано["RETREAT стрелков позади (§87)"] += 1
    # `target: cell` обязателен: без него разбор моста ставит цель base и клетку (-1,-1) — проверено to_commands
    return [{"cmd": "RETREAT", "count": 200, "who": "musk17", "target": "cell", "cx": int(кл[0]), "cy": int(кл[1])}] + из


def _шаг_к(откуда: tuple, куда: tuple, шагов: int = 1) -> tuple:
    x, y = откуда
    for _ in range(шагов):
        x += (куда[0] > x) - (куда[0] < x)
        y += (куда[1] > y) - (куда[1] < y)
    return (int(x), int(y))


def _прикрытие(из: list, st: dict, п: dict, стр, пропущено, отдано) -> list:
    """ПРИКРЫТИЕ (4.10, §93; манёвр §82 второй сессии — «пики бьют, стрелки позади», +9…+14 из 100 в
    эпизодах). Волна стратегии уходит ДВУМЯ группами: пики — её ATTACK (`who=infantry17`), стрелки —
    отдельный ATTACK в клетку на два шага от нашей ратуши к нему (два ATTACK за такт мост возит).
    Дальше в такты без своего ATTACK группе стрелков — RETREAT по номеру в клетку на шаг позади
    пикинёров (ход без боя; бьют из соседней клетки, §82). Через такт подмога «к волне» уступает
    место этому приказу: пару ATTACK + RETREAT группе мост в один файл пока не кладёт."""
    if float(п.get("прикрытие", 0) or 0) < 0.5:
        return из
    дом = _наша_база(st)
    его = _его_база(st) or дом
    if float(st.get("mil_shooters") or 0) >= 3:
        новые = []
        for c in из:
            if (c.get("cmd") == "ATTACK" and c.get("target") not in ("wave", "home") and not c.get("who")
                    and not c.get("group") and str(c.get("count")) not in ("0", "0.0")):
                кл = _шаг_к(дом, его, 2)
                новые.append(dict(c, who="infantry17"))
                новые.append({"cmd": "ATTACK", "count": "all", "who": "musk17", "target": "cell",
                              "cx": кл[0], "cy": кл[1]})
                отдано["ATTACK стрелков прикрытием (§93)"] += 1
                continue
            новые.append(c)
        из = новые
    # подтянуть стрелков за пикинёрами
    группы = [г for г in _группы(st) if int(г.get("n") or 0) > 0 and (int(г["cx"]), int(г["cy"])) != дом]
    пики = [г for г in группы if int(г.get("пик") or 0) >= int(г.get("стрелков") or 0) and int(г["n"]) >= 5]
    стрелки = [г for г in группы if int(г.get("стрелков") or 0) > int(г.get("пик") or 0) and int(г["n"]) >= 3]
    if not (пики and стрелки):
        return из
    P = max(пики, key=lambda г: int(г["n"]))
    M = max(стрелки, key=lambda г: int(г["n"]))
    цель = _шаг_к((int(P["cx"]), int(P["cy"])), дом, 1)
    if (int(M["cx"]), int(M["cy"])) == цель:
        return из
    стр._прикр_такт = not getattr(стр, "_прикр_такт", False)
    атаки = [c for c in из if c.get("cmd") in ("ATTACK", "RETREAT", "ENGAGE")]
    if атаки and not (стр._прикр_такт and all(c.get("cmd") == "ATTACK" and c.get("target") == "wave" for c in атаки)):
        return из
    if атаки:
        пропущено["подмога уступила такт прикрытию"] += 1
        из = [c for c in из if c not in атаки]
    отдано["RETREAT стрелков за пиками (§93)"] += 1
    return [{"cmd": "RETREAT", "count": 0, "group": int(M["id"]), "target": "cell",
             "cx": цель[0], "cy": цель[1]}] + из


def _цена_здания(st: dict, роль: str) -> dict:
    """{ресурс: цена} следующей постройки `роль` из `build_cost` состояния (вживую; в двойнике поля нет — {})."""
    for кусок in str(st.get("build_cost") or "").split():
        имя, _, хвост = кусок.partition("=")
        if имя != роль:
            continue
        цена = {}
        for поле in хвост.split(","):
            буквы = поле.rstrip("0123456789")
            цифры = поле[len(буквы):]
            if буквы and цифры.isdigit() and int(цифры) > 0:
                цена[буквы] = int(цифры)
        return цена
    return {}


def _разбор_бойцов(строка) -> dict:
    """`fighters`/`p1_fighters` состояния → {роль: {hp, atk, wkind, pause, dpike, dsword, dbullet, ...}}.
    Форма: `infantry17=pikeman,hp90,atk8,wkind1,pause0,... musk17=...` (у врага без sid); нечисловые куски пропускаются."""
    из = {}
    for кусок in str(строка or "").split():
        роль, _, хвост = кусок.partition("=")
        if not хвост:
            continue
        з = {}
        for поле in хвост.split(","):
            буквы = поле.rstrip("0123456789")
            цифры = поле[len(буквы):]
            if буквы and цифры.isdigit():
                з[буквы] = int(цифры)
        if з:
            из[роль.strip()] = з
    return из


_ЗАЩИТА_ОТ = {1: "dpike", 2: "dsword", 3: "dbullet"}


def _веса_качества(st: dict) -> dict | None:
    """§170н (25.10, вопрос игрока «как оборонятся, если он выберет Польшу»): ВЕС ЕГО БОЙЦА В НАШИХ ПИКАХ по статам обеих
    сторон из состояния (`fighters` / `p1_fighters` — их пишет блок для нации каждого). Урон в движке = урон − защита по виду
    оружия (`miscext2.script:380`), плоско. Вес = (ударов, чтобы убить его) / (ударов, чтобы убить нашего), голова к голове своей
    роли: его пика против нашей пики, его стрелок против нашего с поправкой на темп стрельбы, его конный против нашего конного.
    net против net даёт 1,0 везде; польская пика (брони 0) — 0,62, мушкетёр — 1,16, крылатый гусар против драгуна — 1,43.
    Нет полей — None."""
    наши, его = _разбор_бойцов(st.get("fighters")), _разбор_бойцов(st.get("p1_fighters"))
    if not наши or not его or "infantry17" not in наши or "infantry17" not in его:
        return None
    def ударов(кто: dict, кем: dict) -> float:
        """сколько ударов `кем` убивают `кто`"""
        урон = max(1.0, float(кем.get("atk") or 1) - float(кто.get(_ЗАЩИТА_ОТ.get(int(кем.get("wkind") or 1), "dpike")) or 0))
        return float(кто.get("hp") or 1) / урон
    def вес(его_р: dict, наш_р: dict, наш_мера: dict) -> float:
        w = ударов(его_р, наш_р) / max(0.01, ударов(наш_мера, его_р))
        return max(0.3, min(4.0, w))
    веса = {"пик": вес(его["infantry17"], наши["infantry17"], наши["infantry17"])}
    if "musk17" in его and "musk17" in наши:
        w = вес(его["musk17"], наши["musk17"], наши["musk17"])
        if float(его["musk17"].get("pause") or 0) > 0 and float(наши["musk17"].get("pause") or 0) > 0:
            w *= float(наши["musk17"].get("pause")) / float(его["musk17"].get("pause"))
        веса["стрелков"] = max(0.3, min(4.0, w))
    else:
        веса["стрелков"] = 1.0
    # конный — против нашего конного той же роли (голова к голове своей роли: net против net даёт 1,0), без него — против пики
    _наш_к = наши.get("dragoon17") or наши["infantry17"]
    веса["конных"] = вес(его["dragoon17"], _наш_к, _наш_к) if "dragoon17" in его else 1.0
    веса["его_пуля_по_нашей_пике"] = max(0.0, float(его.get("musk17", {}).get("atk") or 0) - float(наши["infantry17"].get("dbullet") or 0))
    веса["наша_пуля_по_его_пике"] = max(0.0, float(наши.get("musk17", {}).get("atk") or 0) - float(его["infantry17"].get("dbullet") or 0))
    веса["его_броня_от_пули"] = float(его["infantry17"].get("dbullet") or 0)
    return веса


def _состояние_по_качеству(st: dict, веса: dict) -> dict:
    """Копия состояния, где его войска пересчитаны в наши пики: `p1_inf/shoot/cav/army` и клетки `ecells`
    (столбцы пик/стрелков/конных, n — их сумма плюс остаток). Исходные головы — в `p1_army_головы`."""
    из = dict(st)
    wп, wс, wк = веса["пик"], веса["стрелков"], веса["конных"]
    inf, sh, cv = (float(st.get(k) or 0) for k in ("p1_inf", "p1_shoot", "p1_cav"))
    из["p1_army_головы"] = float(st.get("p1_army") or 0) or (inf + sh + cv)
    из["p1_inf"], из["p1_shoot"], из["p1_cav"] = round(inf * wп, 1), round(sh * wс, 1), round(cv * wк, 1)
    из["p1_army"] = round(из["p1_inf"] + из["p1_shoot"] + из["p1_cav"], 1)
    сырое = st.get("ecells")
    if isinstance(сырое, str) and сырое.strip() and сырое.strip() != "none":
        куски = []
        for кусок in сырое.split(";"):
            ч = кусок.split(",")
            if len(ч) in (9, 10):
                try:
                    n, pk, shc, cvc = (int(ч[i]) for i in (2, 3, 4, 5))
                    pk2, sh2, cv2 = int(round(pk * wп)), int(round(shc * wс)), int(round(cvc * wк))
                    n2 = pk2 + sh2 + cv2 + max(0, n - pk - shc - cvc)
                    ч[2], ч[3], ч[4], ч[5] = str(n2), str(pk2), str(sh2), str(cv2)
                except ValueError:
                    pass
            куски.append(",".join(ч))
        из["ecells"] = ";".join(куски)
    return из


def _цена_прокачки(st: dict, имя: str) -> dict:
    """{буква: цена} прокачки `имя` из `upg_shown`/`upg_aca` состояния (`mil.1=f750g250i0` → {"f": 750, "g": 250}); нет — {}."""
    for поле in ("upg_shown", "upg_aca"):
        for кусок in str(st.get(поле) or "").split(","):
            к, _, хвост = кусок.partition("=")
            if к.strip() != имя:
                continue
            цена, буква, цифры = {}, "", ""
            for ch in хвост + "x":
                if ch.isdigit():
                    цифры += ch
                else:
                    if буква and цифры and int(цифры) > 0:
                        цена[буква] = int(цифры)
                    буква, цифры = ch, ""
            return цена
    return {}


def _переброс(из: list, st: dict, п: dict, стр, отдано) -> list:
    """§170п (26.10, слово игрока по Д15 «крестьяне ходили туда-сюда: одни шли, не доходили, разворачивались, шли обратно
    на поле, а другие шли с поля на ресурс, и так по кругу»): ОДНО ПЕРЕМЕЩЕНИЕ ЗА ТАКТ, СРОК, МЁРТВАЯ ЗОНА.

    Механизм по записи Д15 6:25–7:17 и коду блока (`block_hcmd.inc`, наземный BALANCE): каждый приказ файла исполняется
    отдельно и по порядку; если на ресурсе меньше цели, второй проход снимает людей с ЛЮБОГО другого ресурса по индексу
    объекта — не глядя, выше ли тот своей цели и не получил ли человек приказ в этом же такте. В 6:41 стратегия просила
    дерево 28 (нужда + §166 «золото лежит» +10 + бригада §167), еду 13, камень 3 при 29 на земле: `wood 28` при 13 забрал
    с поля первых по индексу, следом `food 13` при 5 забрал с дерева первых по индексу — тех, кого только что послали. Они
    развернулись на полпути; через 5 с файл пришёл снова. Урезание суммы в мосту (18.09, `распределить_balance`) резало
    44 → 30, но при сумме, равной земле, блок всё равно берёт у кого попало, а выпущенные из шахты и идущие ему ещё не
    видны свободными. Факт: дерево 13→18→19→14→14→13→10→8, еда 5→9→8→9→9→10→11 за 50 с; 142 человеко-перемещения за
    7:57 партии (счёт винды), рубщик 0,70/с в покое против 0,56/с при переброске.

    Правило (ключ `переброс_раз` = срок в секундах, 0 — как было; `переброс_порог` 3 человека; `переброс_авария_еды` 500):
      * цель, равная текущему числу, не шлётся (блок и так ничего не делает);
      * прибавка в пределах праздных — не перемещение, идёт всегда (блок берёт праздных первыми, никого не снимает);
        в шахту блок берёт только праздных — прибавка шахте тоже свободна;
      * всё остальное — ПЕРЕМЕЩЕНИЕ: снять лишних с ресурса, добрать за счёт чужих, выпустить из шахты. Перемещение
        меньше `переброс_порог` человек не шлётся (в Д15 половина ходьбы была по одному-двум); за такт уходит ОДНО
        перемещение — самое большое по людям (при равенстве еда, дерево, камень, золото), остальные ждут; после него
        `переброс_раз` секунд перемещений нет вовсе (отбирать обратно некому — вот и нет круга);
      * цель наземного ресурса не выше видимой земли (на еде + дереве + камне + праздные), а не «крестьяне минус шахтёры»;
      * авария по еде (еда ниже `переброс_авария_еды`, движок стопорит найм) ломает срок и зону: еда добирается сразу.
    Срок держит стратегия, а не блок: блок про время не знает. Корень всё равно в блоке (второй проход должен брать только
    у того, кто выше своей цели в том же файле, и не трогать получивших приказ в этом такте) — задание винде в ПЛАН.
    Судья — мера «человеко-перемещений за партию» (`разбор_еды.py`): Д15 142 за 8 минут, цель ≤ 40 за полную; живьём
    3–6 строк `GATHER took off` за партию, не дюжина и не ноль."""
    срок = float(п.get("переброс_раз", 0) or 0)
    if срок <= 0:
        return из
    порог = max(1, int(п.get("переброс_порог", 3) or 0))
    авария = float(п.get("переброс_авария_еды", 500) or 0)
    t = float(st.get("gametime") or 0)
    сост = getattr(стр, "_переброс_сост", None)
    if сост is None or t < float(сост.get("t", 0)):
        сост = {"t": -1e9, "что": ""}
        стр._переброс_сост = сост
    на = {r: int(float(st.get("on_" + r) or 0)) for r in ("food", "wood", "stone", "gold", "iron", "coal")}
    праздных = int(float(st.get("idle_pea") or 0)) if st.get("idle_pea") not in (None, "") else 0
    видно = на["food"] + на["wood"] + на["stone"] + праздных
    # §170ф (29.10, после balance_sink_vs_ai): сток блока сажает каждого праздного, «праздных 0» стало вечным — и это правило
    # отказывало каждому заполнению «доноров нет» (камень 3→5 ждал с 2:02 до 2:50, золотая шахта 4:07 против 3:27 базы).
    # Люди, посаженные блоком СВЕРХ его целей (`tgt_*`/`sink_pea` из состояния), свободны так же, как праздные: прибавка в их
    # пределах — не перемещение, и чужими они не считаются. Ключ `сток_излишек` 1; 0 — как было.
    _земные = ("food", "wood", "stone")
    изл = {r: 0 for r in _земные}
    if float(п.get("сток_излишек", 0) or 0) and st.get("tgt_wood") not in (None, ""):
        for r in _земные:
            _tg = st.get("tgt_" + r)
            _tg = -1 if _tg in (None, "") else int(float(_tg))
            изл[r] = на[r] if _tg < 0 else max(0, на[r] - _tg)
    излишек = sum(изл.values())
    еда = float(st.get("food") or 0)
    порядок = {"food": 0, "wood": 1, "stone": 2, "gold": 3, "iron": 4, "coal": 5}
    свободно = праздных + излишек
    # §170ч (29.10, сток-2 x2): шахта просила 10 при 5, §170м снижал цель камня 23 → 18, а срок держал это снятие 63 с — в
    # шахту идут только праздные и доноры сверх цели, и донора не было. Ключ `шахта_без_срока` 1: снятия, парные к заполнению
    # шахты в этом же такте, идут без срока (заполнения земли ждут как прежде).
    шахта_ждёт = False
    _без_срока = int(float(п.get("шахта_без_срока", 0) or 0))
    итог = []           # команды, уходящие без вопросов (не BALANCE, свободные прибавки)
    кандидаты = []      # (людей, порядок, индекс в `из`, роль, цель, причина)
    for i, c in enumerate(из):
        if c.get("_по_срокам"):
            итог.append((i, c))      # §170щ: пара «выпуск из шахты + заполнение» посчитана правилом — без срока и мёртвой зоны
            continue
        роль = c.get("role") if c.get("cmd") == "BALANCE" else None
        if роль not in порядок or c.get("total") in (None, "", "all"):
            итог.append((i, c))
            continue
        цель = int(float(c.get("total") or 0))
        было = на[роль]
        if цель == было:
            отдано[f"§170п {роль} {цель}: уже столько — не шлём"] += 1
            continue
        if роль in ("gold", "iron", "coal"):
            if цель > было:
                итог.append((i, c))      # в шахту идут только праздные — не перемещение
                шахта_ждёт = True
            else:
                кандидаты.append((было - цель, порядок[роль], i, роль, цель, "выпустить из шахты"))
            continue
        if цель > было:
            if роль == "food" and еда < авария:
                кандидаты.append((10 ** 6, 0, i, роль, min(цель, видно), f"АВАРИЯ еды {еда:.0f} < {авария:.0f}"))
                continue
            if цель - было <= свободно:
                if цель - было > праздных and излишек > 0:
                    отдано[f"§170ф излишек стока {излишек} засчитан свободными: {роль} {было}→{цель} без срока"] += 1
                свободно -= цель - было
                итог.append((i, c))      # прибавка праздными — не перемещение
                continue
            кандидаты.append((цель - было, порядок[роль], i, роль, min(цель, видно), "добрать за счёт чужих"))
        else:
            кандидаты.append((было - цель, порядок[роль], i, роль, цель, "снять лишних"))
    # РЕШЕНИЕ ТАКТА (27.10, симулятор Д16 с потолком еды): снятия и ОДНО заполнение идут ОДНИМ тактом, снятия первыми в файле.
    # Прежде шло одно перемещение за такт: «снять с еды 3» и «добрать на камень 29» попадали в разные такты, второй проход блока
    # забирал на камень пахарей по индексу (на еде 0), а вернуть их еде ворота не давали 50 с — еда 2094 → 279 за минуту, найм
    # встал, партия обвалилась. Теперь заполнение берёт людей только из праздных и снятых этим же тактом (блок берёт праздных
    # первыми) и не глубже видимой земли за вычетом чужих целей (отправленных, иначе текущих чисел): чужих пахарей не трогаем.
    # Авария еды — без допусков. Заполнения без доноров не шлются и говорят об этом.
    выбран = []
    if кандидаты:
        ждать = срок - (t - float(сост["t"]))
        земные = ("food", "wood", "stone")
        снятия = [k for k in кандидаты if k[5] in ("снять лишних", "выпустить из шахты") and k[0] >= порог]
        сняли = sum(k[0] for k in снятия)
        отправлено = {c.get("role"): int(float(c.get("total") or 0)) for _, c in итог
                      if c.get("cmd") == "BALANCE" and c.get("role") in земные}
        for k in снятия:
            отправлено[k[3]] = k[4]
        # §170ъ (29.10, Д22): «видно» — только земля и праздные, и выпущенные из шахты в этом же такте в бюджет заполнения не
        # попадали: wood 0→3 «доноров нет (чужим оставить 37 из 37)» при 15 шахтёрах, которых python сам выпускал. Ключ
        # `выпущенные_в_бюджет` 1: выпущенные этим тактом из шахт прибавляются к видимой земле. 0 — как было.
        _из_шахт = sum(k[0] for k in снятия if k[5] == "выпустить из шахты") if int(float(п.get("выпущенные_в_бюджет", 0) or 0)) else 0
        заполнения = []
        for людей, пор, i, роль, цель, причина in кандидаты:
            if причина in ("снять лишних", "выпустить из шахты"):
                continue
            if людей >= 10 ** 6:
                заполнения.append((людей, пор, i, роль, min(цель, видно), причина))
                continue
            чужие = sum(отправлено.get(o, на[o] - изл[o]) for o in земные if o != роль)
            цель2 = min(цель, видно + _из_шахт - чужие, на[роль] + праздных + излишек + сняли)
            if цель2 - на[роль] >= порог:
                if _из_шахт > 0 and цель2 > min(цель, видно - чужие, на[роль] + праздных + излишек + сняли):
                    отдано[f"§170ъ выпущенные из шахт {_из_шахт} в бюджете заполнения {роль} {на[роль]}→{цель2}"] += 1
                заполнения.append((цель2 - на[роль], пор, i, роль, цель2, причина))
            else:
                отдано[f"§170п {роль} {на[роль]}→{цель}: доноров нет (праздных {праздных}, излишек стока {излишек}, снято этим тактом {сняли}, чужим оставить {чужие} из {видно}) — не шлём"] += 1
        заполнения.sort(key=lambda k: (-k[0], k[1]))
        авария = [k for k in заполнения if k[0] >= 10 ** 6]
        мелкие = [k for k in кандидаты if k[0] < порог]
        for k in мелкие:
            отдано[f"§170п мёртвая зона: {k[3]} {на[k[3]]}→{k[4]} — меньше {порог} человек, не шлём"] += 1
        if авария:
            выбран = [авария[0]]
        elif ждать > 0 and _без_срока and шахта_ждёт and снятия:
            выбран = list(снятия)
            отдано[f"§170ч снятие для шахты без срока: {', '.join(f'{k[3]} {на[k[3]]}→{k[4]}' for k in снятия)} (ждать было {ждать:.0f} с)"] += 1
            for k in заполнения[:1]:
                отдано[f"§170п срок: {k[3]} {на[k[3]]}→{k[4]} ждёт ещё {ждать:.0f} с после «{сост['что']}»"] += 1
        elif ждать > 0:
            for k in заполнения[:1] + снятия[:2]:
                отдано[f"§170п срок: {k[3]} {на[k[3]]}→{k[4]} ждёт ещё {ждать:.0f} с после «{сост['что']}»"] += 1
        elif заполнения:
            выбран = снятия + [заполнения[0]]
        elif снятия:
            снятия.sort(key=lambda k: (-k[0], k[1]))
            выбран = [снятия[0]]
        for k in заполнения[1:]:
            отдано[f"§170п по одному за такт: {k[3]} {на[k[3]]}→{k[4]} ждёт"] += 1
    if выбран:
        for n, (людей, _, i, роль, цель, причина) in enumerate(выбран):
            c = dict(из[i]); c["total"] = цель
            # снятия — раньше заполнения в файле: блок исполняет приказы по порядку и берёт праздных первыми
            итог.append((-10 ** 6 + n if причина in ("снять лишних", "выпустить из шахты") else 10 ** 6 + n, c))
        сост["t"] = t
        сост["что"] = ", ".join(f"{k[3]} {на[k[3]]}→{k[4]}" for k in выбран)
        отдано[f"§170п перемещение: {сост['что']} (видно {видно}, праздных {праздных}; {выбран[-1][5]}), дальше {срок:.0f} с без перемещений"] += 1
    итог.sort(key=lambda x: x[0])
    return [c for _, c in итог]


def _железо_нужно(п: dict, st: dict) -> bool:
    """Ключ `шахта_железа` (31.10, вопрос игрока «бот Польшей против Польши»): нет/1 — как было, шахта железа закладывается
    после казармы безусловно; 0 — не закладывать; 2 — ПО ЦЕНЕ ИЗ СОСТОЯНИЯ: закладывать, только если пика (`infantry17` в
    `fighters`) стоит железа > 0. Нидерландам (пика 20 железа) ключ 2 ничего не меняет; польской пике (0 железа по live-ценам
    29.10) шахта и 5–8 человек в ней не нужны. Нет поля `fighters` — как было (True).
    1.11: КЛЮЧ СУДИЛ ТОЛЬКО ПО ПИКЕ, И ВЕТКА КОНЮШНИ НА ЭТОМ ВСТАЛА. В `branch_stable_pol` стояли `конюшня_с` 600 и
    `конница` uniq_cav17 (рейтар Польши, 2 железа), а пика польская железа не стоит — шахты не было ни одной, железо
    231 на 15:00 дошло до 0 на 23:20 (81 такт в нуле), и найм конницы встал на 56 бойцах. Поэтому при ключе 2 теперь
    спрашивается И КОННИЦА: если стратегия собирается строить конюшню (`конюшня_с`), то роль из `конница` берётся из
    `fighters` и её цена в железе решает так же, как цена пики."""
    try:
        к = п.get("шахта_железа", None)
        к = int(float(к)) if к is not None else 1
    except (TypeError, ValueError):
        к = 1
    if к == 0:
        return False
    if к != 2:
        return True
    # 4.11 (202), пара bot2_wsave: ОФИЦЕР СТОИТ 30 ЖЕЛЕЗА (unit.script, SetObjBasePrice(objbase, 50, 0, 0, 150, 30, 0)).
    # При ключе 2 польская пика железа не стоит — шахты не было ни в одной из 12 сторон, 360 стартового железа кончались к
    # 15–19 мин, офицер гибнул в бою, и TRAIN officer игра отвергала до конца партии («REFUSED by the game» при 2–3 тыс.
    # золота): отряд больше не собирался, и в обеих проигранных копиях армия дралась толпой. Ключ `железо_на_отряд` N
    # (0 — как было): при отрядах в стратегии (`отрядов` ≥ 1) шахта железа нужна, когда железа меньше N. Порог, а не сразу:
    # без него шахта шла в 1:50 и забирала людей у второй казармы, а железо нужно к 15-й минуте (200 — около 10:00).
    _жн = float(п.get("железо_на_отряд", 0) or 0)
    if _жн > 0 and int(float(п.get("отрядов", 0) or 0)) >= 1 and float(st.get("iron") or 0) < _жн:
        return True
    б = _разбор_бойцов(st.get("fighters"))
    if п.get("конюшня_с") is not None:                       # 1.11: конюшня в планах — спрашиваем и конницу
        кон = б.get(str(п.get("конница", "reitar") or "reitar"))
        if кон and int(кон.get("iron", 0) or 0) > 0:
            return True
    пика = б.get("infantry17")
    if not пика:
        return True
    return int(пика.get("iron", 0) or 0) > 0


def _стены_врага(st: dict) -> list:
    """ЕГО СТЕНЫ ПО КЛЕТКАМ, терпимо к обеим формам поля `ewalls`.

    С живого моста приходит строка `x,y,слабых,крепких,ворот,строится,hp%мин` через «;»;
    из трассы и симулятора — уже разобранный список списков той же семёркой. Разбирать
    тут, а не полагаться на одну форму: 1.11 на этом терялись данные."""
    сырое = st.get("ewalls")
    if сырое is None:
        return []
    поля = ("x", "y", "частокол", "камень", "ворот", "строится", "hp")
    если_список = isinstance(сырое, (list, tuple))
    из = []
    if если_список:
        for к in сырое:
            try:
                ч = [int(v) for v in (к if isinstance(к, (list, tuple)) else [])]
            except (TypeError, ValueError):
                continue
            if len(ч) == 7:
                из.append(dict(zip(поля, ч)))
        return из
    строка = str(сырое).strip()
    if not строка or строка == "none":
        return []
    for кусок in строка.split(";"):
        части = кусок.split(",")
        if len(части) != 7:
            continue
        try:
            ч = [int(v) for v in части]
        except ValueError:
            continue
        из.append(dict(zip(поля, ч)))
    return из


def _частокол_на_пути(st: dict, цель, п: dict):
    """КУДА БИТЬ СТЕНУ (1.11, слово игрока: «атаку армии на частокол направить»).

    Ключ `частокол_бить` (нет/0 — как было; 1 — включено). Задача: армия встала перед
    частоколом и не прошла — значит приказ надо давать НЕ по цели за стеной, а по самой
    стене, потому что `ATTACK target cell` игра исполняет по клетке и бойцы ломают то,
    что там стоит. Пушек в мосте нет ни одной роли, так что ломать можно только руками.

    Выбор клетки, и каждое слово здесь — мера:
      * клетка стены должна стоять НА ПУТИ: обход `расст(армия→стена) + расст(стена→цель)`
        не длиннее прямого `расст(армия→цель)` больше чем на `частокол_обход` (2 клетки).
        Иначе это не преграда, а стена в стороне, и бить её незачем;
      * из оставшихся берём с наименьшим `hp` — это процент САМОГО СЛАБОГО звена клетки,
        и стену ломают именно там (`coss3_map.его_стены`). Клетка, которая ещё строится,
        стоит на 1 % и выигрывает сама;
      * при равном hp предпочитаем клетку с воротами (`ворот` > 0): ворота тоньше стены;
      * цель, которая САМА клетка стены, не перенацеливаем — мы уже бьём стену.

    Отдаёт `(клетка, словами)` или `None`, если бить нечего или ключ выключен."""
    if not int(float(п.get("частокол_бить", 0) or 0)):
        return None
    стены = [с for с in _стены_врага(st) if (с["частокол"] + с["камень"]) > 0]
    if not стены:
        return None
    цx, цy = int(цель[0]), int(цель[1])
    # ЗДЕСЬ БЫЛА МОЯ ОШИБКА (1.11, нашла живая партия). Стояла защита «цель САМА клетка стены — не
    # перенацеливаем, уже бьём стену», и она срабатывала ровно в том случае, ради которого всё делалось:
    # у запечатанной базы стена обёрнута ВОКРУГ цели, и клетка с 23 крестьянами несла ещё и 4 звена
    # частокола. Правило выходило молча, бот стоял, все 12 клеток стены остались на hp 100.
    # Теперь клетка стены целью не мешает: выбираем слабейшее звено кольца и бьём ОБЪЕКТ (цель `wall`).
    def _ч(k, по_умолчанию=0):
        v = st.get(k)
        return int(v) if isinstance(v, (int, float)) else по_умолчанию
    аx = _ч("my_army_cx", _ч("my_cx", -1))
    аy = _ч("my_army_cy", _ч("my_cy", -1))
    if аx < 0 or аy < 0:
        return None
    def рас(x1, y1, x2, y2):
        return max(abs(x1 - x2), abs(y1 - y2))
    прямо = рас(аx, аy, цx, цy)
    запас = float(п.get("частокол_обход", 2) or 2)
    годные = []
    for с in стены:
        обход = рас(аx, аy, с["x"], с["y"]) + рас(с["x"], с["y"], цx, цy)
        if обход - прямо <= запас:
            годные.append((с, обход))
    if not годные:
        return None
    с, обход = min(годные, key=lambda z: (z[0]["hp"], 0 if z[0]["ворот"] > 0 else 1, z[1]))
    словами = (f"ЧАСТОКОЛ НА ПУТИ: бью стену в {с['x']},{с['y']} вместо цели {цx},{цy} — "
               f"звеньев {с['частокол'] + с['камень']}"
               + (f", ворота" if с["ворот"] > 0 else "")
               + (f", СТРОИТСЯ" if с["строится"] > 0 else "")
               + f", слабейшее звено {с['hp']} %; обход {обход} против прямого {прямо}")
    return (с["x"], с["y"]), словами


def стена_в_приказах(из: list, st: dict, п: dict, реестр=None, отдано=None) -> list:
    """ПЕРЕНАЦЕЛИТЬ УДАРЫ НА СТЕНУ — общее для живой игры и симулятора (1.11).

    Зовётся из ДВУХ воронок, и это не лишнее: `привести` — выход СИМУЛЯТОРА, а живая игра
    возвращает приказы из `ЖиваяСтратегия.ответ`. 1.11 правило стояло только в `привести`,
    селфтест звал её же и был зелёным — а в живой партии лог игры показал `target=cell`:
    хук сидел в воронке, которой живая игра не пользуется. Одна функция на оба пути.
    """
    for c in из:
        if str(c.get("cmd") or "") != "ATTACK":
            continue
        # И `base` ТОЖЕ, не только `cell` (1.11, слово игрока «армия подходит, но забор не ломает»).
        # Лог игры показал, что почти все удары идут целью `base`: 'ATTACK 22 target=base', 'ATTACK 20
        # target=base'. При ней блок сам ищет БЛИЖАЙШЕЕ здание врага — а им и оказывается частокол —
        # и ИДЁТ к нему приказом движения. Армия подходит к забору и стоит. Клетку базы берём из
        # `en_base` (x, y, зданий), как её пишет блок состояния.
        _ц = None
        _т = str(c.get("target") or "")
        if _т == "cell" and c.get("cx") is not None:
            _ц = (c["cx"], c["cy"])
        elif _т == "base":
            _б = st.get("en_base")
            if isinstance(_б, (list, tuple)) and len(_б) >= 2:
                try:
                    _ц = (int(_б[0]), int(_б[1]))
                except (TypeError, ValueError):
                    _ц = None
        if _ц is None:
            continue
        ст = _частокол_на_пути(st, _ц, п)
        if ст is None:
            continue
        (сx, сy), словами = ст
        c["cx"], c["cy"] = сx, сy
        c["target"] = "wall"
        if c.get("face") is not None:
            c["face"] = [сx, сy]
        if отдано is not None:
            отдано["ATTACK -> частокол"] += 1
        if реестр is not None and isinstance(getattr(реестр, "записи", None), list):
            реестр.записи.append(словами)
            реестр.мера["частокол: удар перенацелен на стену"] += 1
    return из


def привести(сырые: list, st: dict, п: dict, стр, пропущено, отдано) -> list:
    """Команды стратегии → то, что уходит в игру за такт (3.10, §57; общее для симулятора и моста).

    Внутренние команды симулятора (`_ЗАПАС`, `_ВПЕРЁД`, …) отбрасываются — мост их не умеет, и
    симулятор не должен на них рассчитывать; одна волна за такт; доли еды/дерева/камня от людей
    на земле; золото и железо явно; одна закладка за такт; порядок и потолок."""
    из, атака = [], 0
    for c in сырые:
        cmd = str(c.get("cmd") or "")
        if cmd.startswith("_"):
            # ЧЕТЫРЕ ПРИКАЗА ВОЛНЕ В ПОЛЕ (3.10, задание игрока) переводятся в мостовые,
            # а не отбрасываются — но ТОЛЬКО на живом мосте: симулятор исполняет их сам и
            # точнее (`sim.py`, `_К_СВОИМ` сводит две группы навстречу), а здесь они
            # становятся тем, что игра действительно умеет. Что именно умеет и чем это
            # отличается от симулятора — в `_в_мостовые`, и то же говорится вслух в `why`.
            переведено = _лицом_к_врагу(
                _в_мостовые(c, cmd, st), st) if ЖИВОЙ_МОСТ else None
            if переведено is None:
                пропущено[cmd] += 1
                continue
            пропущено[f"{cmd} -> {переведено['cmd']}"] += 1
            отдано[переведено["cmd"]] += 1
            из.append(переведено)
            continue
        c = dict(c)
        if cmd == "UPGRADE" and "upg" in c:
            c["role"] = c.pop("upg")
        if cmd == "RETREAT":
            c.setdefault("count", 200)
        if cmd == "ATTACK":
            # ЧАСТОКОЛ НА ПУТИ (1.11) — общей функцией, см. `стена_в_приказах`
            стена_в_приказах([c], st, п, getattr(стр, "реестр", None), отдано)
            # ВТОРОЙ УДАР БОЛЬШЕ НЕ РЕЖЕТСЯ (4.10). Прежде за такт уезжал один:
            # файл приказа нёс одну команду. Партия проверки 5 показала цену —
            # стратегия просила два удара В КАЖДОМ ТАКТЕ (по базе и подмогу к
            # волне), и один из них пропадал каждый такт. С §78 файл возит список,
            # и `to_commands` отправляет оба одним файлом; третий и дальше по-
            # прежнему не возим, и мост говорит об этом вслух.
            атака += 1
            if атака > 2:
                пропущено["ATTACK третий за такт"] += 1
                continue
        отдано[cmd] += 1
        из.append(c)
    из = _сбор(из, st, п, стр, пропущено, отдано)
    из = _сзади(из, st, п, стр, пропущено, отдано)
    из = _прикрытие(из, st, п, стр, пропущено, отдано)
    # ЕДА И ЗОЛОТО ЯВНО (3.10, контейнер Windows `smoke_strategy/1`: стратегия ни разу не дала
    # BALANCE food — еда 993 -> 0 к 2:33, крестьян 18 -> 3). Ярус 1 шлёт на еду только
    # ПРОСТАИВАЮЩИХ (4 и больше) — в симуляторе их много, вживую почти нет, а мостовой дебют
    # короткий (n бойцов) и кончается раньше созревания поля. Здесь доля еды из стратегии
    # (`еда_до` до 7:00, `еда_после` после) и 5 на шахту золота выставляются каждый такт.
    gt = float(st.get("gametime") or 0)
    крест = float(st.get("peasants") or 0)
    доля = float(п.get("еда_до", 2 / 3)) if gt < 420 else float(п.get("еда_после", 1 / 3))
    # ДОЛИ ОТ ЛЮДЕЙ НА ЗЕМЛЕ (3.10, третий прогон: на еде 9 из 35 при цели 17 — 20 человек в
    # шахтах, на земле 15, а еда+дерево+камень просили 29, и мост резал все три
    # пропорционально, `llm_policy.распределить_balance`). Земля — как у моста: крестьяне
    # минус шахтёры минус строители. Еда первой (доля деревни, но не больше земли), дерево и
    # камень — из остатка; сумма не превышает землю, и мосту резать нечего.
    земля = max(0, int(крест - float(st.get("on_mine") or 0) - float(st.get("on_build") or 0)))
    # 3.10 (§64, контейнер smoke_net): «еда первой» отдавала еде всю землю — с 4:00 до 7:00 на
    # дереве и камне 0-3 человека, камня 20, вторая шахта золота к 9:00, вторая казарма к 11:30,
    # а еды к 10:00 лежало 5 тысяч без дела. Теперь сперва МИНИМУМ дерева и камня стратегии
    # (ярус 1 так и задуман: «держать на дереве не меньше стольких»), еде — остальное.
    # `COSS3_WOOD_FIRST=0` — как было.
    # …но только когда еды запасено (`ЗАПАС_ЕДЫ_ДЕРЕВУ`, 1000): без порога «дерево первым» в
    # начале снимало с еды всех, и деревня гибла (симулятор: армия к 10:00 — 4)
    # рычаг стратегии `дерево_при_еде` (§65) — порог запаса еды; от 5900 — никогда (как «еда
    # первой»); без рычага — выключатель окружения, как раньше
    порог = п.get("дерево_при_еде")
    if порог is not None:
        дерево_первым = float(порог) < 5900 and float(st.get("food") or 0) >= float(порог)
    else:
        дерево_первым = ДЕРЕВО_ПЕРВЫМ and float(st.get("food") or 0) >= ЗАПАС_ЕДЫ_ДЕРЕВУ
    мин_дер = мин_кам = 0
    # ДЕРЕВО ПО НУЖДЕ (8.10, партии В и Г): вторая казарма — 500 дерева, 500 камня, 2500 золота; золото на неё
    # набиралось к 7:20-7:30, а дерево при трёх рубщиках (`дерево` 3) — к 7:58 (В) и 9:53 (Г), при еде 6-11 тысяч
    # без дела. Игрок: «дерево с начала рубят 5-7». В Г упирался и камень: 500 набралось к 10:08, закладка 10:23.
    # Ключи `дерево_нужда`/`камень_нужда` N: пока ресурса меньше `дерево_до`/`камень_до` (по умолчанию 600), на нём
    # не меньше N; 0 или нет ключа — как было. Двойник это правило не судит: у него казарма ждёт золота (§129).
    # §153 (13.10, партия Д5): НУЖДА ПО ЦЕНЕ ЗАКЛАДКИ. Потолок `дерево_до`/`камень_до` 600 гасил нужду, когда закладка
    # стоила больше: академия (1050 дерева, 1230 камня) ждала при трёх рубщиках с 8:34 до 14:04, дерево 700-1300 «уже
    # хватает». Ключ `нужда_по_закладке` 1: пока ждёт закладка (память прошлого такта, цена из `build_cost`), порог
    # нужды по ресурсу — не меньше её цены. 0 — как было.
    _цз = getattr(стр, "_закладка_цена", None) if int(п.get("нужда_по_закладке", 0) or 0) else None
    # §166 (18.10, партия Д7, задание игрока «почини камень — бот держит 20–380 всю партию»): НУЖДА ПО ПЛАНУ И ПО
    # НЕДОСТАЧЕ. В Д7 на камне 3–6 человек всю партию, камень 20–380 до 11:00, еда при этом лежала 1100–4800 (на еде 8–32);
    # игрок: камень 980 к 2:03 и 1780 к 3:03 (~10 человек две минуты), академия и казарма 2 из этого запаса. Потолок нужды
    # `камень_до` 600 (или цена ОДНОЙ ждущей закладки, §153) гасил бригаду задолго до того, что нужно плану: казарма 2 (500)
    # + академия (1230) + шахты (100 каждая) = 1830. Ключ `нужда_по_плану` 1 (только вживую — есть `build_cost`): потолок
    # нужды по ресурсу — не меньше суммы цен всего, что лестница ещё поставит (казарма до `казарм` в пределах
    # `казарма_потолок_золота`, академия при `эко` ≥ 2, шахты золота до `шахт_золота`, шахта железа). Ключ `нужда_макс` N
    # (10): бригада растёт с недостачей — к `*_нужда` по человеку на каждые `нужда_шаг` (500) недостачи до потолка, не выше
    # N; дерево и камень вместе не больше `нужда_доля` (0,75) земли — остальное еде (игрок: ~10 из 23 на камне). Порог
    # еды прежний (`нужда_при_еде` 1200, в Д7 пройден в 5:26) с гистерезисом ниже. Двойник камня не добывает — ключ молчит.
    _план = {"wood": 0.0, "stone": 0.0}
    if int(п.get("нужда_по_плану", 0) or 0) and st.get("build_cost"):
        _чс = lambda k: float(st.get(k) or 0)
        _кц = _цена_здания(st, "ba17") or {"wood": 500, "stone": 500, "gold": 2500}
        _кпз0 = float(п.get("казарма_потолок_золота", 0) or 0)
        if _чс("ba17") < int(п.get("казарм", 1)) and (_кпз0 <= 0 or float(_кц.get("gold") or 0) <= _кпз0):
            for _r in _план:
                _план[_r] += float(_кц.get(_r) or 0)
        if getattr(стр, "академия", False) and _чс("academies") < 1 and _чс("ba17") >= 1:
            _ац = _цена_здания(st, "academi") or {"wood": 1050, "stone": 1230}
            for _r in _план:
                _план[_r] += float(_ац.get(_r) or 0)
        _шц = _цена_здания(st, "minegold") or {"wood": 100, "stone": 100}
        _шахт = max(0, int(п.get("шахт_золота", 2)) - int(_чс("mines_gold"))) + (1 if _чс("mines_iron") < 1 and _чс("ba17") >= 1 and _железо_нужно(п, st) else 0)
        for _r in _план:
            _план[_r] += _шахт * float(_шц.get(_r) or 0)
    # §170з (24.10, партия Д13 на блоке №2 — винда: «бюджет камня надо считать с ценой академии, иначе задание №2 и
    # „камень с первой минуты" тянут в разные стороны»): БЮДЖЕТ С АКАДЕМИЕЙ. План §166 академию считал (до 1930–2130 камня
    # с 1:25), но в людей это не превращалось в двух местах, и пока блок людей с ресурса не снимал, лишние на камне добывали
    # «бесплатно» (Д11/Д12 — 12 на камне до конца); с блоком №2 `камень` 4 стал настоящим потолком: Д13 камень 80/20/360/1180
    # по минутам 4/6/8/10, академия к 10:01 не куплена (1230), бой 71:17. (а) Ворота еды `нужда_при_еде` 1200 держали нужду
    # выключенной с 1:25 до 4:27 (еда 400–750, на камне трое; игрок — восемь с первой минуты) и снова после mil.1 (еда 213 в
    # 4:00). Пока академия в плане и не построена, нужда по дереву и камню действует от еды `еда_найма` (600 — где стоит найм),
    # гистерезис тот же (0,7 → 420); пол пахарей §168а (6) и ожидание еды закладками §145 остаются. (б) Переброс §167 мерил
    # недостачу до ближайшей закладки: при закладке шахты (100 камня) или казармы (500) камень считался «набранным» и бригада
    # уходила на дерево, на камне 3 (Д12 4:27, 6:37–9:19), хотя академии нужно 1230. Теперь ближайшая покупка — закладка И
    # академия вместе (по каждому ресурсу большее). Ключ `бюджет_с_академией` 1 (файл Д13); 0 — как было. Судья — Д14 живьём.
    _ац_ждёт = {}
    if int(п.get("бюджет_с_академией", 0) or 0) and getattr(стр, "академия", False) \
            and float(st.get("academies") or 0) < 1 and float(st.get("ba17") or 0) >= 1:
        _ац_ждёт = dict(_цена_здания(st, "academi") or {"wood": 1050, "stone": 1230})
    _нужда_макс = int(п.get("нужда_макс", 0) or 0)
    _нужда_шаг = float(п.get("нужда_шаг", 500) or 500)
    def _по_нужде(ключ, ресурс):
        n = int(п.get(ключ, 0))
        до = float(п.get(ключ + "_до", 600) or 600)
        if _цз and float(_цз.get(ресурс) or 0) > до:
            до = float(_цз[ресурс])
        if _план.get(ресурс, 0) > до:
            до = _план[ресурс]
        if int(п.get(ключ + "_нужда", 0) or 0) > n and float(st.get(ресурс) or 0) < до:
            n = int(п[ключ + "_нужда"])
            if _нужда_макс > n:
                n = min(_нужда_макс, n + int((до - float(st.get(ресурс) or 0)) // _нужда_шаг))
                if n > int(п[ключ + "_нужда"]):
                    отдано[f"§166 нужда {ресурс}: до {до:.0f} по плану, недостача {до - float(st.get(ресурс) or 0):.0f} → {n}"] += 1
        return n
    дер_n, кам_n = _по_нужде("дерево", "wood"), _по_нужде("камень", "stone")
    if _нужда_макс > 0:
        _доля_н = float(п.get("нужда_доля", 0.75) or 0)
        _потолок_н = int(земля * _доля_н) if _доля_н > 0 else None
        _бд, _бк = int(п.get("дерево_нужда", 0) or 0) or int(п.get("дерево", 0)), int(п.get("камень_нужда", 0) or 0) or int(п.get("камень", 0))
        while _потолок_н is not None and дер_n + кам_n > _потолок_н and (дер_n > _бд or кам_n > _бк):
            if дер_n - _бд >= кам_n - _бк and дер_n > _бд:
                дер_n -= 1
            else:
                кам_n -= 1
    нужда_активна = дер_n > int(п.get("дерево", 0)) or кам_n > int(п.get("камень", 0))
    # НУЖДА НЕ МИГАЕТ (10.10, §133, смоук партии Д против невозможного): `дерево_первым` ждёт еды
    # ≥ `дерево_при_еде` (2788), а еда в 5:00-8:00 ходила 2416-3201 вокруг порога — и рубщики с ним:
    # 7 → 0 → 7 → 0 (`on_wood` ноль на 6:02 и 6:32 при дереве 246 и 146). Пока нужда действует,
    # её порог еды свой — `нужда_при_еде` (1200: прокорм 80 голов — 8 в секунду, 8 пахарей дают 32);
    # 0 — как было (мигает с общим порогом).
    нужда_при_еде = float(п.get("нужда_при_еде", 1200) or 0)
    if _ац_ждёт and нужда_при_еде > 0:
        # §170з (а): бюджет с академией не ждёт запаса еды 1200 — только еды найма
        _еда_н = float(п.get("еда_найма", 600) or 600)
        if _еда_н < нужда_при_еде:
            нужда_при_еде = _еда_н
    # §170м (в) (25.10, Д14/Д15, слово игрока «все три части»): НУЖДА СПИТ, ПОКА mil.1 НЕ КУПЛЕНА. В Д14 порог 600 (§170з) будил
    # нужду ровно под ценой mil.1 с порогом моста (750 + 800 до 5:00): мост отверг её 44 раза, еды 1550 не бывало, mil.1 — 7:04;
    # в Д13 нужда спала за 1200 и mil.1 взята в 4:11. Ключ `нужда_после_mil1` 1: пока mil.1 не куплена и не идёт, порог нужды
    # не ниже её цены (из `upg_shown`, 750) плюс пол еды моста (пока он действует: до 5:00 при бойцах < 20). 0 — как было.
    if int(п.get("нужда_после_mil1", 0) or 0) and нужда_при_еде > 0 and _нужда_макс > 0:
        _взято_м = str(st.get("upg_done") or "") + "," + str(st.get("upg_doing") or "")
        if "mil.1" not in [x.strip() for x in _взято_м.split(",")]:
            _бойцов_м = float(st.get("mil_inf") or 0) + float(st.get("mil_shooters") or 0) + float(st.get("mil_cav") or 0)
            _пол_м = ПОЛ_ЕДЫ if (gt <= 300 and _бойцов_м < 20) else 0.0
            _спит_до = float(_цена_прокачки(st, "mil.1").get("f") or 750) + _пол_м
            if нужда_при_еде < _спит_до:
                нужда_при_еде = _спит_до
                отдано[f"§170м нужда спит до mil.1: порог еды {_спит_до:.0f} (цена + пол {_пол_м:.0f}), еда {float(st.get('food') or 0):.0f}"] += 1
    # §166: ГИСТЕРЕЗИС — раз включённая нужда держится, пока еда не упала ниже `нужда_гистерезис` (0,7) × порога: иначе
    # бригада 8–9 снимает еду ниже 1200 за минуту, нужда гаснет, люди идут на еду, еда растёт — и так по кругу (§133).
    _порог_н = нужда_при_еде
    if _нужда_макс > 0 and getattr(стр, "_нужда_вкл", False):
        _порог_н = нужда_при_еде * float(п.get("нужда_гистерезис", 0.7) or 0.7)
    if нужда_активна and not дерево_первым and нужда_при_еде > 0 and float(st.get("food") or 0) >= _порог_н:
        дерево_первым = True
    # §170м (б) (25.10, Д14): еда ниже гистерезиса — НЕ «все на еду». В Д14 нужда гасла на 420, §145 слал BALANCE food 19–21,
    # бригада 10–14 шла с дерева на поле и через 30–60 с обратно: шесть циклов 3:34–7:14, дерево 94 → 490 за четыре минуты.
    # Ключ `добор_до_пола` (2): нужда остаётся, пол пахарей растёт на столько за такт, пока еда ниже гистерезиса; еда дошла до
    # порога включения — добор снят. Блок снимает людей сам (№2), поэтому добор идёт через `цель_еды`, а не отдельным приказом.
    _добор_п = int(п.get("добор_до_пола", 0) or 0)
    if _добор_п > 0 and _нужда_макс > 0:
        _еда_м = float(st.get("food") or 0)
        if (нужда_активна and getattr(стр, "_нужда_вкл", False) and not дерево_первым and нужда_при_еде > 0
                and _еда_м < _порог_н and float(st.get("mills") or 0) >= 1):
            дерево_первым = True
            стр._пол_добор = int(getattr(стр, "_пол_добор", 0) or 0) + _добор_п
            отдано[f"§170м добор до пола: еда {_еда_м:.0f} < {_порог_н:.0f}, пол +{стр._пол_добор}"] += 1
        elif not нужда_активна or _еда_м >= нужда_при_еде:
            стр._пол_добор = 0
    стр._нужда_вкл = bool(дерево_первым and нужда_активна)
    if _ац_ждёт and стр._нужда_вкл and float(st.get("food") or 0) < float(п.get("нужда_при_еде", 1200) or 0):
        отдано[f"§170з бюджет с академией: нужда от еды {нужда_при_еде:.0f} при еде {float(st.get('food') or 0):.0f} (академия не куплена)"] += 1
    # §167 (18.10, по образцу игрока в Д7, задание «допиши переброс бригады по моему образцу»): ВСЯ БРИГАДА НА ОДИН РЕСУРС.
    # Игрок держал на дереве и камне вместе 10–14 человек всю партию и перебрасывал их целиком туда, где ближайшая покупка:
    # 1:28–3:08 карьер (камень 1880 под академию и казарму, на дереве 5), 3:08 карьер пуст; 8:38–9:29 после академии снова
    # все на камне (дерево 0–3), 9:54 все на дереве (13 в секунду), камень не растёт до конца. Бот держал 7 и 6 постоянно и
    # не перебрасывал. Ключ `переброс` 1 (при `нужда_макс` > 0): пока нужда включена, недостача по ресурсу считается до
    # ближайшей покупки — цены ждущей закладки прошлого такта (`_цз`), а если она по обоим набрана — до плана (§166); вся
    # бригада (дерево + камень после потолка доли) идёт на ресурс с большей недостачей, на другом остаётся `переброс_мин`
    # (3, как у игрока на дереве); набран — бригада уходит на другой. Снятие с ресурса — явным BALANCE (ниже), иначе блок
    # людей не отпустит. Золото при нужде (§166б) идёт туда же.
    _пб_цель = None
    _смена = False   # §169в: такт смены цели переброса — бригада идёт целиком, бюджет без снятия не режет
    if int(п.get("переброс", 0) or 0) and _нужда_макс > 0 and дерево_первым and нужда_активна:
        _зап = {"wood": float(st.get("wood") or 0), "stone": float(st.get("stone") or 0)}
        _нед = {r: max(0.0, max(float((_цз or {}).get(r) or 0), float(_ац_ждёт.get(r) or 0)) - _зап[r]) for r in _зап}
        _до_чего = "закладки и академии" if _ац_ждёт else "закладки"
        # §170ю (29.10, Д26): НЕДОСТАЧА ПО КАЗАРМЕ, ПОКА ОНА ЖДЁТ. `_цз` — закладка прошлого такта, а лестница через такт меняла
        # её: казарма (500/500) ↔ шахта 3 (100/100) ↔ ничего (условие шахты «на золоте ≥ 9» мигало с 7 на 10). Недостачи прыгали
        # 290/300 → 0/0 → план, бригада то делилась по §170э, то шла целиком на дерево по §167: камень 0 ↔ 10 семь раз за две
        # минуты (4:37–6:09), снятий 45 человек. Ключ `недостача_по_казарме` 1: пока вторая казарма нужна, недостачи дерева и
        # камня считаются не ниже её цены, какая бы закладка ни ждала в этот такт. 0 — как было.
        if int(п.get("недостача_по_казарме", 0) or 0) and 1 <= float(st.get("ba17") or 0) < int(п.get("казарм", 1)):
            _цк = _цена_здания(st, "ba17") or {"wood": 500, "stone": 500, "gold": 2500}
            _нед_к = {r: max(0.0, float(_цк.get(r) or 0) - _зап[r]) for r in _зап}
            if max(_нед_к.values()) > 0:
                _нед = {r: max(_нед[r], _нед_к[r]) for r in _зап}
                _до_чего = "казармы" + (" и академии" if _ац_ждёт else "")
        if max(_нед.values()) <= 0:
            _нед = {r: max(0.0, _план.get(r, 0.0) - _зап[r]) for r in _зап}
            _до_чего = "плана"
        if max(_нед.values()) > 0:
            _пб_цель = max(_нед, key=_нед.get)
            # §168а (20.10, Д8): цель ЛИПКАЯ — пока по прежней цели недостача есть, не перескакиваем: в Д8 цель ходила
            # stone → wood → stone каждые 20 с (недостачи до казармы 160 и 186 почти равны), люди шли туда-сюда и ничего не доносили
            _прежн = getattr(стр, "_переброс_цель", None)
            if _прежн in _нед and _нед[_прежн] > 0:
                _пб_цель = _прежн
            _другой = "wood" if _пб_цель == "stone" else "stone"
            _бриг = дер_n + кам_n
            _мин_др = min(int(п.get("переброс_мин", 3) or 0), _бриг)
            # §170э (29.10, Д25): закладке не хватало ОБОИХ — дерева 126 и камня 180, — а бригада 19 ушла целиком на камень
            # (большая недостача) и держалась там сроком §170п: камень 1120 при цене 500, дерево 374 до 8:01, казарма 8:26 против
            # 6:05 у игрока. Ключ `переброс_по_долям` 1: пока закладке (не плану) не хватает обоих, бригада делится по недостачам,
            # на каждом не меньше `переброс_мин`; одного не хватает — как было, вся бригада туда. 0 — как было.
            if (int(п.get("переброс_по_долям", 0) or 0) and _до_чего != "плана" and _нед["wood"] > 0 and _нед["stone"] > 0
                    and _бриг >= 2 * _мин_др and _мин_др > 0):
                дер_n = int(round(_бриг * _нед["wood"] / (_нед["wood"] + _нед["stone"])))
                дер_n = max(_мин_др, min(_бриг - _мин_др, дер_n))
                кам_n = _бриг - дер_n
                отдано[f"§170э переброс по долям до {_до_чего}: дерево {дер_n} (недостача {_нед['wood']:.0f}), камень {кам_n} (недостача {_нед['stone']:.0f})"] += 1
            elif _пб_цель == "stone":
                дер_n, кам_n = _мин_др, _бриг - _мин_др
                отдано[f"§167 переброс бригады {_бриг} на {_пб_цель}: недостача {_нед[_пб_цель]:.0f} до {_до_чего}, {_другой} {_мин_др}"] += 1
            else:
                кам_n, дер_n = _мин_др, _бриг - _мин_др
                отдано[f"§167 переброс бригады {_бриг} на {_пб_цель}: недостача {_нед[_пб_цель]:.0f} до {_до_чего}, {_другой} {_мин_др}"] += 1
            if _пб_цель != getattr(стр, "_переброс_цель", None):
                стр._переброс_счёт = 0
            # §169в: окно переброса `переброс_такты` (2) — столько тактов подряд бригада просится целиком (второй проход блока
            # берёт по индексу, и одного такта может не хватить: в Д7 5:52 → 5:57 на дереве так и стояли 7); дальше бюджет
            _смена = getattr(стр, "_переброс_счёт", 0) < int(п.get("переброс_такты", 2) or 0)
            стр._переброс_счёт = getattr(стр, "_переброс_счёт", 0) + 1
    стр._переброс_цель = _пб_цель
    _кд_приказ = 0
    if дерево_первым:
        мин_дер = min(дер_n, земля)
        мин_кам = min(кам_n, земля - мин_дер)
        цель_еды = max(0, min(int(крест * доля), земля - мин_дер - мин_кам))
        # §168а (20.10, Д8): ПОЛ ПАХАРЕЙ. Бригада по нужде (§166/§167) и снятые с золота оставляли на еде 0–4: еда 1347 → 795 за
        # 40 с, нужда гасла (гистерезис 840), всех гнали на еду (BALANCE food 30), еда до 1200 — и снова на камень; период 40–60 с,
        # камень 40 → 340 → 240 за партию при 107 тактах нужды. Ключ `еда_пахарей_мин` (6 при `нужда_макс` > 0): на еде не меньше,
        # бригада ужимается — сперва ресурс не-цели переброса, потом цель.
        _пол_пах = int(п.get("еда_пахарей_мин", 6 if _нужда_макс > 0 else 0) or 0)
        # §170м (а) (25.10, Д14, слово игрока): ПОЛ ПАХАРЕЙ — ПРОКОРМ, НЕ КОНСТАНТА. Шестеро без mil.1 дают ≈ 4 еды/с, а ратуша
        # без паузы берёт 100 еды за крестьянина (≈ 6/с) плюс пики по 25: еда при шести падала 2,2/с, при двадцати росла 6–10.
        # Ключ `пол_прокормом` 1: пол = ⌈(едят × головы + найм) / сбор⌉ + 1, где едят 0,034/с на голову (`едят`), найм
        # `найм_еды` (5/с), пока в `train_now` бесконечная очередь и еды ≥ 500 (ниже движок найм стопорит), сбор на пахаря
        # `сбор_пахаря` 0,7 без mil.1 и `сбор_пахаря_mil1` 1,3 с ней (замер Д14/Д15); не выше земли без `переброс_мин`.
        # Добор §170м (б) прибавляется сюда же. 0 — как было (6).
        _пп = int(п.get("пол_прокормом", 0) or 0)
        _пол_добор = int(getattr(стр, "_пол_добор", 0) or 0)
        if (_пп or _пол_добор) and _пол_пах > 0 and float(st.get("mills") or 0) >= 1:
            _пол_новый = _пол_пах
            _что = ""
            if _пп:
                _голов = крест + float(st.get("mil_inf") or 0) + float(st.get("mil_shooters") or 0) + float(st.get("mil_cav") or 0)
                _очередь_inf = "inf" in str(st.get("train_now") or "")
                _найм = float(п.get("найм_еды", 5.0) or 0) if (_очередь_inf and float(st.get("food") or 0) >= 500) else 0.0
                _mil1_есть = "mil.1" in [x.strip() for x in str(st.get("upg_done") or "").split(",")]
                _сбор_п = float(п.get("сбор_пахаря_mil1", 1.3) if _mil1_есть else п.get("сбор_пахаря", 0.7)) or 0.7
                _расход = float(п.get("едят", 0.034) or 0) * _голов + _найм
                _пол_новый = max(_пол_пах, int(-(-_расход // _сбор_п)) + 1)
                _что = f"расход {_расход:.1f}/с при {_голов:.0f} головах{' и найме' if _найм else ''}, сбор {_сбор_п}"
            _пол_новый = min(_пол_новый + _пол_добор, max(_пол_пах, земля - int(п.get("переброс_мин", 3) or 0)))
            if _пол_новый != _пол_пах:
                отдано[f"§170м пол пахарей прокормом: {_пол_новый}" + (f" ({_что}" if _что else " (") + (f", добор +{_пол_добор})" if _пол_добор else ")")] += 1
                _пол_пах = _пол_новый
        if _пол_пах > 0 and float(st.get("mills") or 0) >= 1 and цель_еды < min(_пол_пах, земля):
            цель_еды = min(_пол_пах, земля)
            _лишн = max(0, мин_дер + мин_кам + цель_еды - земля)
            _поряд = ("wood", "stone") if _пб_цель == "stone" else ("stone", "wood") if _пб_цель == "wood" else ("stone", "wood")
            for _r in _поряд:
                if _лишн <= 0:
                    break
                if _r == "wood":
                    _c = min(_лишн, мин_дер); мин_дер -= _c; _лишн -= _c
                else:
                    _c = min(_лишн, мин_кам); мин_кам -= _c; _лишн -= _c
            отдано[f"§168а пол пахарей {цель_еды}: бригада дерево {мин_дер}, камень {мин_кам}"] += 1
        стр._пол_последний = _пол_пах   # §170с читает пол после обеих ветвей
        # §169в (20.10 ночь, партия Д9 — винда: «пол пахарей пробит, на еде 2–5 в 5:15–7:00»): БЮДЖЕТ БЕЗ СНЯТИЯ. Кейс Д9
        # воспроизводит живые приказы такт в такт. Блок (`block_hcmd.inc`, наземный BALANCE) только ДОБИРАЕТ до числа:
        # приказ ниже текущего и `BALANCE 0` — пустые, людей с ресурса он снимает лишь вторым проходом ЧУЖОГО приказа, и
        # берёт первых попавшихся по индексу, не глядя, кто лишний. Отсюда два механизма пробоя: (1) после ужатия пола
        # ярус слал прежнее `wood 3` при `мин_дер` 1 — сумма приказов 19 при земле 17, и камень с едой каждый такт
        # перетягивали одного человека (5:10–5:50: еда 4–6, камень 9–10, дерево 1–3); (2) после переброса на дерево
        # (5:55) трое на камне с приказом `stone 0` остались навсегда, а дерево 9 и еда 6 при земле 15 тянули друг у друга
        # 30 с (6:00–6:25: еда 2–6, дерево 5–9). Правило (ключ `пол_без_снятия` 1): людей не-цели сверх её минимума считаем
        # занятыми (снять их мы не можем), земля — только те, кого блок видит (на еде, дереве, камне и праздные, без
        # идущих), и цель переброса получает остаток: еда + цель + не-цель ≤ видимой земле. Тогда ни в один такт не короток
        # больше чем один ресурс, и он добирает из праздных или из не-цели — тянуть обратно некому. Цена: не-цель
        # дренируется только попутно (когда её людей заберёт чужой приказ), переброс целиком медленнее. 0 — как было;
        # ставить 0, когда блок научится брать вторым проходом у того, кто выше своей цели в том же файле (задание винде).
        _без_снятия = int(п.get("пол_без_снятия", 1 if _пол_пах > 0 else 0) or 0)
        if _без_снятия and _пол_пах > 0 and float(st.get("mills") or 0) >= 1 and (мин_дер > 0 or мин_кам > 0) and not _смена:
            _на = {r: float(st.get("on_" + r) or 0) for r in ("food", "wood", "stone")}
            _видно = земля
            if st.get("idle_pea") not in (None, ""):
                _видно = min(земля, int(_на["food"] + _на["wood"] + _на["stone"] + float(st.get("idle_pea") or 0)))
            _ц = _пб_цель or ("stone" if мин_кам >= мин_дер else "wood")
            _н = "wood" if _ц == "stone" else "stone"
            _мин_н = мин_дер if _н == "wood" else мин_кам
            _занято_н = max(_мин_н, int(_на[_н]))
            _бюджет = max(0, _видно - цель_еды - _занято_н)
            _было_ц = мин_кам if _ц == "stone" else мин_дер
            if _было_ц > _бюджет:
                if _ц == "stone":
                    мин_кам = _бюджет
                else:
                    мин_дер = _бюджет
                отдано[f"§169в бюджет без снятия: {_ц} {_было_ц} → {_бюджет} (видно {_видно}, еда {цель_еды}, {_н} занято {_занято_н})"] += 1
        стр._пол_строго = bool(_без_снятия and _пол_пах > 0 and float(st.get("mills") or 0) >= 1)
        if _смена and стр._пол_строго:
            отдано[f"§169в такт переброса на {_пб_цель}: бригада целиком, бюджет не режет"] += 1
    else:
        цель_еды = min(int(крест * доля), земля)
        стр._пол_строго = False
        # §170и (24.10, слово игрока 23.10 «камень с первой минуты», Д13 на блоке №2): ДЕБЮТ КАМНЯ ДЕРЖИТСЯ И ПОСЛЕ СКРИПТА.
        # Скрипт дебюта (debut.py) сажает `камень_дебют` на камень при готовой казарме, но кончается на n бойцах (~2:10), а нужда
        # §166 включается от еды 600 (§170з) — в Д12 только в 3:15 (еда 2:15–3:10 — 411–523). Между ними ярус просил `камень` 4,
        # и блок №2 снял бы восьмёрку. Пока gt < `камень_дебют_до` (180) и нужда спит, камню — не меньше `камень_дебют`, в
        # пределах земли без пола пахарей; еда получает остаток. 0 или нет ключа — как было.
        _кд = int(п.get("камень_дебют", 0) or 0)
        _кд_до = float(п.get("камень_дебют_до", 180) or 0)
        _кд_приказ = 0
        if _кд > int(п.get("камень", 0)) and gt < _кд_до:
            _пол_д = int(п.get("еда_пахарей_мин", 6 if _нужда_макс > 0 else 0) or 0) if float(st.get("mills") or 0) >= 1 else 0
            _кд_n = max(0, min(_кд, земля - _пол_д))
            if _кд_n > int(п.get("камень", 0)):
                цель_еды = max(0, min(цель_еды, земля - _кд_n - min(int(п.get("дерево", 0)), max(0, земля - _кд_n - _пол_д))))
                из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == "stone")]
                из.append({"cmd": "BALANCE", "role": "stone", "total": _кд_n, "_важно": True})
                _кд_приказ = _кд_n
                отдано[f"§170и дебют камня: stone {_кд_n} до {_кд_до:.0f} с (нужда спит, еда {float(st.get('food') or 0):.0f})"] += 1
    # §170с (27.10, Д17 — чистый замер экономики): ЕДА ЛЕЖИТ — ПОТОЛОК ЦЕЛИ ЕДЫ, в ОБЕИХ ветвях (нужда и сон нужды). Цель еды
    # выше считается долей крестьян минус бригада по нужде, а при спящей нужде — просто долей: когда нужда по дереву и камню
    # молчит, на еду идут все до доли — в Д17 `food 0→46` в 12:46 при 6456 еды, `46→50`, `50→54` при 10 876 и 19 685; к 15:00 еды
    # 24 332 при 54 на еде, академия (1050 дерева) уехала на 12:36 при дереве 486 в 8:00. Каждый возврат нужды — полные качели
    # бригады (170 переходов за 15:02 против 55 в Д16, все законные ходы §170п). В симуляторе Д16 качели шли и при потолке в
    # одной ветви: после покупки еда падала ниже порога нужды, нужда спала, вторая ветвь слала всех на еду.
    # Ключ `еда_лежит` (порог запаса; 0 — как было): при еде ≥ порога цель еды = пол пахарей (§168а/§170м, последний
    # посчитанный) + `еда_лежит_сверх` (2); лишние — на дерево или камень, ЛИПКО (адресат меняется, когда другого стало меньше
    # на 30 %, иначе при пересечении запасов он менялся каждый такт и переходы в симуляторе утроились); выключается с гистерезисом
    # при еде < порога/2. Возврат шахтёров «золото лежит» при потолке идёт туда же, не на еду.
    # ПОРОГ — НАД ЦЕНОЙ ПОКУПКИ: еда «лежит» только сверх цены той ступени, которую стратегия купила бы следующей (цены из
    # `upg_avail`, как у оценщика `прокачки.оценить`): симулятор с голым порогом 2000 терял 3–5 прокачек из 15 (академические стоят
    # еды тысячами) и 10–20 бойцов армии к 15:00. Порог такта = `еда_лежит` + цена еды ЖЕЛАННОЙ ступени; гистерезис — минус
    # половина ключа. 28.10 (Д18): было «max цены по ВСЕМ доступным» — в живом ценнике лежит bar.pikeman.2.5 за 17 890 еды, порог
    # был 19 890 при пике партии 10 361, и правило не исполнилось ни разу (87 тактов с едой ≥ 2000, 0 ≥ порога). Желанная — тот же
    # выбор, что у покупки (`_ступень_по_ценности`: ценность, `ступень_до`, `ступень_род_доля`, `цена_снята_при`), только без
    # оглядки на карман; нет желанной (до `прокачка_с`, ценника нет, всё куплено) — порог равен ключу.
    _лежит = float(п.get("еда_лежит", 0) or 0)
    стр._еда_лежит_вкл = bool(getattr(стр, "_еда_лежит_вкл", False)) if _лежит > 0 else False
    if _лежит > 0 and float(st.get("mills") or 0) >= 1:
        _еда_ст = float(st.get("food") or 0)
        import combat_math as _CM
        _цены_дост = _CM.цены_апгрейдов(st.get("upg_avail")) or _CM.цены_апгрейдов(st.get("upg_shown")) or {}
        _желанная = None
        try:
            _взято_ф = {x.strip() for k in ("upg_done", "upg_doing", "upg_now") for x in str(st.get(k) or "").split(",") if x.strip()}
            if hasattr(стр, "_ступень_по_ценности"):
                _желанная = стр._ступень_по_ценности(st, _взято_ф, float(st.get("gametime") or 0), по_карману=False)
        except Exception:
            _желанная = None
        _цена_пр = float(((_цены_дост.get(_желанная) if _желанная else None) or {}).get("food") or 0)   # цена еды желанной ступени
        for _c in из:   # и просимые в этом такте (mil.1, bla.*, aca.* — их просит не ценность, а план §169в)
            if _c.get("cmd") == "UPGRADE" and _c.get("role"):
                _цф = float((_цены_дост.get(str(_c["role"])) or {}).get("food") or _цена_прокачки(st, str(_c["role"])).get("f") or 0)
                if _цф > _цена_пр:
                    _цена_пр, _желанная = _цф, str(_c["role"])
        # 28.10 (Д19): живьём ценник `upg_avail` ПОЛНЫЙ (220 позиций), желанная — следующая ступень лестницы (2.3 за 4200, 2.4 за 9305,
        # 2.5 за 17 890) или просимая aca.24 (4200), и порог всё время выше еды: ноль исполнений в двух партиях при пике 11 777. Это
        # свойство замысла «копим на ступень», не ошибка. Ключ `еда_лежит_просто` 1 — порог равен ключу, на ступени не копим (сим: −3…−5
        # ступеней пикинёра и −10…−20 бойцов к 15:00, еда вдвое ниже); 0 — как было.
        if int(float(п.get("еда_лежит_просто", 0) or 0)):
            _цена_пр, _желанная = 0.0, None
        _порог_ф = _лежит + _цена_пр
        if _еда_ст >= _порог_ф:
            стр._еда_лежит_вкл = True
        elif _еда_ст < _порог_ф - _лежит * float(п.get("еда_лежит_гист", 0.5) or 0.5):   # гистерезис: доля ключа (0,5 — как было)
            стр._еда_лежит_вкл = False
        if стр._еда_лежит_вкл:
            _пол_ц = int(getattr(стр, "_пол_последний", 0) or 0) if дерево_первым else 0
            if _пол_ц <= 0:
                _пол_ц = int(getattr(стр, "_пол_последний", 0) or 0) or int(п.get("еда_пахарей_мин", 6) or 6)
            _сверх = int(п.get("еда_лежит_сверх", 2) or 0)
            _потолок = max(0, min(земля, _пол_ц + _сверх))
            _д, _к = float(st.get("wood") or 0), float(st.get("stone") or 0)
            _куда = getattr(стр, "_еда_лежит_куда", None)
            if _куда not in ("wood", "stone"):
                _куда = "wood" if _д <= _к else "stone"
            elif _куда == "wood" and _к < 0.7 * _д:
                _куда = "stone"
            elif _куда == "stone" and _д < 0.7 * _к:
                _куда = "wood"
            стр._еда_лежит_куда = _куда
            if цель_еды > _потолок:
                _изл = цель_еды - _потолок
                цель_еды = _потолок
                if _куда == "wood":
                    мин_дер += _изл
                else:
                    мин_кам += _изл
                if not дерево_первым:
                    # нужда спит — приказов дерева/камня по минимумам ниже не будет, кладём сами
                    _ц = int(float(st.get("on_" + _куда) or 0)) + _изл
                    из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == _куда)]
                    из.append({"cmd": "BALANCE", "role": _куда, "total": _ц, "_важно": True})
                отдано[f"§170с еда лежит {_еда_ст:.0f} {'≥' if _еда_ст >= _порог_ф else 'держится до ' + format(_порог_ф - _лежит * float(п.get('еда_лежит_гист', 0.5) or 0.5), '.0f') + ' <'} {_порог_ф:.0f} ({_лежит:.0f} + {('прокачка ' + str(_желанная)) if _желанная else 'без желанной прокачки'} {_цена_пр:.0f}): цель еды {цель_еды} (пол {_пол_ц} + {_сверх}), лишние {_изл} на {_куда} (дерево {_д:.0f}, камень {_к:.0f}{'' if дерево_первым else ', нужда спит'})"] += 1
    if дерево_первым and (дер_n > int(п.get("дерево", 0)) or кам_n > int(п.get("камень", 0))):
        # по нужде еда уступает: команда яруса 1 на еду не урезана землёй, и мост резал бы все три
        # пропорционально (`llm_policy.распределить_balance`) — прибавка дереву размылась бы обратно к ~4
        for c in из:
            if c["cmd"] == "BALANCE" and c.get("role") == "food":
                c["total"] = min(int(c.get("total") or 0), цель_еды)
    # §169в: при поле пахарей еда добирается строго (без слабины в одного): иначе на еде стояло 5 при поле 6
    _слабина = 0 if getattr(стр, "_пол_строго", False) else 1
    if float(st.get("mills") or 0) >= 1 and (float(st.get("on_food") or 0) < цель_еды - _слабина or (_слабина == 0 and цель_еды > 0)):
        из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == "food")]
        из.append({"cmd": "BALANCE", "role": "food", "total": цель_еды, "_важно": True})
        отдано["BALANCE food (переходник)"] += 1
    остаток = земля - (цель_еды if float(st.get("mills") or 0) >= 1 else 0)
    for роль in ("wood", "stone"):
        for c in из:
            if c["cmd"] == "BALANCE" and c.get("role") == роль:
                c["total"] = max(0, min(int(c.get("total") or 0), остаток))
        остаток -= min(дер_n if роль == "wood" else кам_n, max(остаток, 0))
    из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") in ("wood", "stone") and c["total"] <= 0)]
    if not дерево_первым and _кд_приказ > 0:
        # §170и: цикл остатка выше вычитает число нужды по дереву (10), хотя нужда спит, — камню оставался 1, и §135 добивал его
        # до троих (кейс Д9 2:10). Камню — ровно дебютное число, дереву — остаток земли после еды и камня.
        for c in из:
            if c["cmd"] == "BALANCE" and c.get("role") == "stone":
                c["total"] = _кд_приказ
            elif c["cmd"] == "BALANCE" and c.get("role") == "wood":
                c["total"] = max(0, min(int(c.get("total") or 0), земля - цель_еды - _кд_приказ))
        if not any(c["cmd"] == "BALANCE" and c.get("role") == "stone" for c in из):
            из.append({"cmd": "BALANCE", "role": "stone", "total": _кд_приказ, "_важно": True})
    if дерево_первым:
        for роль, ключ, мин in (("wood", "on_wood", мин_дер), ("stone", "on_stone", мин_кам)):
            if getattr(стр, "_пол_строго", False):
                # §169в: при поле приказ яруса не выше минимума после ужатия (в Д9 5:35 шёл `wood 3` при `мин_дер` 1 —
                # сумма 19 при земле 17); и все три наземных приказа идут каждый такт — блоку с преимуществом лишних
                # (задание винде) нужны цели всех трёх, старому блоку приказ не выше текущего пуст
                for c in из:
                    if c["cmd"] == "BALANCE" and c.get("role") == роль and int(c.get("total") or 0) != мин:
                        c["total"], c["_важно"] = мин, True
                if мин > 0 and not any(c["cmd"] == "BALANCE" and c.get("role") == роль for c in из):
                    из.append({"cmd": "BALANCE", "role": роль, "total": мин, "_важно": True})
                continue
            if мин > 0 and float(st.get(ключ) or 0) < мин and not any(c["cmd"] == "BALANCE" and c.get("role") == роль for c in из):
                из.append({"cmd": "BALANCE", "role": роль, "total": мин, "_важно": True})
            elif мин > int(п.get({"wood": "дерево", "stone": "камень"}[роль], 0)):
                # по нужде: команда яруса 1 несёт прежнее `дерево`/`камень` — поднять до минимума
                for c in из:
                    if c["cmd"] == "BALANCE" and c.get("role") == роль and int(c.get("total") or 0) < мин:
                        c["total"], c["_важно"] = мин, True
        if _пб_цель:
            # §167: другой ресурс — ровно минимум, даже если там стоят больше (иначе бригада не переедет)
            for роль, ключ, мин in (("wood", "on_wood", мин_дер), ("stone", "on_stone", мин_кам)):
                if роль != _пб_цель and float(st.get(ключ) or 0) > мин:
                    из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == роль)]
                    из.append({"cmd": "BALANCE", "role": роль, "total": мин, "_важно": True})
    # СТРОЙКА ЯВНО (3.10, контейнер `smoke_strategy` второй прогон: армия встала на 17 — железо
    # кончилось к 4:57, шахты железа не было ни одной; вторая казарма и шахты золота 2-3 тоже
    # не встали). Ярус 1 ставит закладку, только пока ничего не строится, а стратегия каждый
    # такт просит академию — вживую что-то строится всегда; и потолок 7 срезал стройки в
    # хвосте списка. Здесь — ОДНА закладка за такт, самая нужная по порядку: шахта железа →
    # шахта золота → казармы → дом → академия. BUILD декларативный (total — сколько должно
    # стоять), повтор безопасен.
    из = [c for c in из if c["cmd"] not in ("BUILD", "BUILDERS")]
    def ч(k):
        return float(st.get(k) or 0)
    # §169б (20.10, партия Д9): ключ `железо_людей` ДОЕЗЖАЛ ТОЛЬКО ДО BALANCE. Ярус 1 клал шахту железа с BUILDERS 3, но
    # строка выше снимает все BUILD/BUILDERS яруса, а лестница ниже клала её заново с BUILDERS 5 — в Д9 пятеро строителей
    # вошли в шахту в 2:15 и стояли там до конца (on_iron 5 все 12 минут), а блок на `BALANCE iron 3` отвечал «5 already
    # work that mine»: из шахты он не выводит (ветка шахт в block_hcmd только досылает). Поэтому людей в шахте железа
    # задаёт ЧИСЛО СТРОИТЕЛЕЙ закладки и достройки §165 — они же в ней остаются. Цена — стройка шахты втроём дольше
    # (Д9: пятеро за ~40 с). 5 или нет ключа — как было.
    _жл = int(п.get("железо_людей", 5) or 5)
    def _строителей(роль):
        return _жл if роль == "mineiron" else 5
    есть_дер_кам = ч("wood") >= 100 and ч("stone") >= 100
    закладка = None
    # КАЗАРМА РАНЬШЕ ШАХТ (10.10, §133, смоук партии Д): шахты золота 2-3 стоят здесь выше казармы и
    # берут по 100 дерева и 100 камня, как только набралось, — за 5:01-8:08 рубщики принесли 308 дерева,
    # 200 ушли в две шахты, казарма (500/500/2500) не встала вовсе. Ключ `казарма_раньше_шахт` 1: пока
    # ждёт казарма, (а) если на неё хватает — она первой; (б) шахты 2-3 закладываются только сверх
    # резерва дерева и камня под казарму. Первые шахты (железа и золота) не трогаем. Цена — из
    # `build_cost` состояния (вживую), иначе 500/500/2500 (двойник). 0 или нет ключа — как было.
    казарма_ждёт = ч("ba17") >= 1 and ч("ba17") < int(п.get("казарм", 1))
    # КОНЮШНЯ ВМЕСТО ВТОРОЙ КАЗАРМЫ (1.11, слово игрока: «вместо второй казармы поставить конюшню и только потом вторую казарму,
    # академию и третью казарму, и делать крылатых гусар»). Ключ `казарма2_после_конюшни` 1 (0 — как было): пока конюшни нет,
    # вторая казарма не ждётся — дерево и золото идут в конюшню (`_конюшня`, ключ `конюшня_с`).
    if казарма_ждёт and int(п.get("казарма2_после_конюшни", 0) or 0) and ч("stables") < 1:
        отдано["казарма 2 ждёт конюшню (казарма2_после_конюшни)"] += 1
        казарма_ждёт = False
    цена_каз = _цена_здания(st, "ba17") or {"wood": 500, "stone": 500, "gold": 2500}
    # §153 (13.10, партия Д5): ТРЕТЬЯ КАЗАРМА НЕДОСТУПНА ПО ЦЕНЕ. Ключ `казарм` 3 пришёл из поиска на двойнике, а
    # живьём каждая следующая казарма впятеро дороже (`costpercent` 500: третья — 2500/2500/12 500). В Д5 закладка
    # `ba17 3` стояла первой в лестнице 80 тактов подряд (9:30-15:15), движок отвечал NOT ENOUGH RESOURCES, а академия,
    # что в лестнице ниже, не заказывалась ни разу; золото 8378 легло. Ключ `казарма_потолок_золота` (5000): казарма
    # дороже по золоту не ждётся — лестница идёт дальше. Цена — из `build_cost` (только вживую). 0 — как было.
    _кпз = float(п.get("казарма_потолок_золота", 0) or 0)
    if казарма_ждёт and _кпз > 0 and st.get("build_cost") and float(цена_каз.get("gold", 0)) > _кпз:
        отдано[f"казарма {int(ч('ba17')) + 1} недоступна: золото {цена_каз.get('gold', 0):.0f} > {_кпз:.0f}"] += 1
        казарма_ждёт = False
    раньше = bool(int(п.get("казарма_раньше_шахт", 0) or 0)) and казарма_ждёт
    цена_шахты = _цена_здания(st, "minegold") or {"wood": 100, "stone": 100}
    хватает_каз = all(ч(r) >= v for r, v in цена_каз.items())
    # §170я (29.10, Д27, просьба винды «правило на порядок оплаты»): КАЗАРМА ПЕРВАЯ В ОПЛАТЕ. В 6:26 золото 2429/2500, дерево 734,
    # камень 620 — казарма через такт; лестница в этот такт заложила шахту 4 (−100 дерева), а оценщик купил bla.1 (−400 дерева):
    # дерево 290, казарма оплачена 7:08 вместо 6:31. Ключ `казарма_первой_в_оплате` 1: пока вторая казарма ждёт и золота не хватает
    # меньше `казарма_близко` (400 ≈ минута трёх шахт), новых закладок за дерево/камень не ставим (шахты 2+, дома, академия ждут) и
    # прокачки за дерево/камень (bla.*, aca.*, tow.*) откладываем; еда/золото/железо (mil.*, bar.*) идут. 0 — как было.
    # (без `not хватает_каз`: в Д27 6:31 золота уже хватало, казарму заказали тем же тактом, но блок исполнил UPGRADE bla.1 раньше BUILD —
    # прокачки за дерево ждут и такт оплаты)
    _каз_близко = (int(п.get("казарма_первой_в_оплате", 0) or 0) and казарма_ждёт
                   and float(цена_каз.get("gold", 2500)) - ч("gold") <= float(п.get("казарма_близко", 400) or 400))
    # РЕЗЕРВ ТОЛЬКО КОГДА ЗОЛОТО БЛИЗКО (10.10, §134, второй смоук Д): резерв 500/500 задержал шахту 2 с 4:49 до 5:53
    # (ждал камня 600), а казарму держало ЗОЛОТО — 1561 из 2500 к 7:15 при одной шахте (7,6/с на пятерых). Шахта
    # стоит 100/100 и при нужде 7/6 окупается деревом и камнем за 20 с, золото же без неё копится минутами. Резерв
    # нужен лишь когда золота не хватает меньше `резерв_при_золоте` (600 — около минуты одной шахты): тогда дерево и
    # камень могут стать последним, чего ждёт казарма. 0 — резерв всегда, как в §133.
    резерв_при_золоте = float(п.get("резерв_при_золоте", 600) or 0)
    золота_нет = max(0.0, float(цена_каз.get("gold", 2500)) - ч("gold"))
    резерв_нужен = раньше and ч("mines_gold") >= 1 and (резерв_при_золоте <= 0 or золота_нет <= резерв_при_золоте)
    резерв_ок = (not резерв_нужен
                 or (ч("wood") >= цена_шахты.get("wood", 100) + цена_каз.get("wood", 500)
                     and ч("stone") >= цена_шахты.get("stone", 100) + цена_каз.get("stone", 500)))
    # 4.11 (218), живая Польша против Польши 2: при `академия_после` 1 академию так и не заложили — ветка стояла ПОСЛЕ ранней
    # казармы и шахт золота, и до неё очередь не дошла (вторая казарма встала в 7:21, академии к 10:00 нет). Ключ
    # `академия_первой` 1 (0 — как было): условие `академия_после` проверяется ПЕРВЫМ.
    _ак_после = int(float(п.get("академия_после", 0) or 0))
    # (218а) живая партия 3: академия первой, ждущая 950 дерева при 258, держала единственную закладку такта — шахт золота
    # 0 к 3:10 (в партии 2 к 3:02 уже 1). Первой она идёт, только когда на неё ХВАТАЕТ дерева и камня; иначе — прежний порядок.
    _ц_ак = _цена_здания(st, "academi") or {"wood": 950, "stone": 800}
    _ак_по_карману = all(ч(r) >= v for r, v in _ц_ак.items() if r in ("wood", "stone", "gold", "food"))
    if (int(float(п.get("академия_первой", 0) or 0)) and _ак_после > 0 and стр.академия and ч("academies") < 1
            and ч("ba17") >= _ак_после and gt >= getattr(стр, "академия_с", 0) and _ак_по_карману):
        закладка = ("academi", 1)
        отдано[f"академия первой после казармы {_ак_после} (ключ академия_первой)"] += 1
    elif раньше and хватает_каз:
        закладка = ("ba17", int(ч("ba17")) + 1)
        отдано["BUILD ba17 раньше шахт"] += 1
    elif ч("ba17") >= 1 and ч("mines_iron") < 1 and есть_дер_кам and _железо_нужно(п, st):
        закладка = ("mineiron", 1)
    elif (ч("mines_gold") < int(п.get("шахт_золота", 2)) and ч("on_gold") >= 5 * ч("mines_gold") - 1
          and есть_дер_кам and резерв_ок and not _каз_близко):
        закладка = ("minegold", int(ч("mines_gold")) + 1)
    # АКАДЕМИЯ ПОСЛЕ N-Й КАЗАРМЫ (2.11, слово игрока через Windows (139): «как человек построил академию сразу после второй
    # казармы?»). Академия стояла в лестнице ниже всех казарм: при `казарм` 3 она ждала третью казарму (12 500 золота), сама
    # золота не требуя (950 дерева, 800 камня). Во всех 14 контейнерных копиях 2.11 — 13:22–17:03, в живой партии 2.11 (14:00)
    # её не было вовсе: офицеров 0, отрядов 0, `отряд_с` 660 недостижим. Ключ `академия_после` N (0 — как было): когда казарм
    # уже N, а академии нет, — академия закладывается раньше следующей казармы.
    elif (int(float(п.get("академия_после", 0) or 0)) > 0 and стр.академия and ч("academies") < 1
          and ч("ba17") >= int(float(п.get("академия_после", 0) or 0)) and gt >= getattr(стр, "академия_с", 0)):
        закладка = ("academi", 1)
        отдано[f"академия после казармы {int(float(п.get('академия_после', 0)))} (ключ академия_после)"] += 1
    elif казарма_ждёт:
        закладка = ("ba17", int(ч("ba17")) + 1)
        if _каз_близко:
            отдано[f"§170я казарма первой в оплате: золота {ч('gold'):.0f}/{float(цена_каз.get('gold', 2500)):.0f}, закладки за дерево и камень ждут"] += 1
        elif раньше and not резерв_ок:
            отдано["шахта ждёт резерва под казарму"] += 1
    # ДОМА ЗАРАНЕЕ (1.11, century_net/2-ban: население 454/475 к 20:00 и 590/600 к 29:50, первые дома только к 20:00). Ключ `дома_доля`
    # D (0 — как было, запас 5 мест): дом закладывается, когда свободных мест меньше max(5, D × предела).
    _дом_запас = max(5.0, float(п.get("дома_доля", 0) or 0) * ч("my_farm"))
    _цр = _цена_здания(st, "center") or {"wood": 2100, "stone": 2100}
    _цм = _цена_здания(st, "mill") or {"wood": 60, "stone": 300}
    # КОНЮШНЯ В ЛЕСТНИЦЕ (1.11, branch_stable_net: правило `_конюшня` слало BUILD stable с 10:00, но вне лестницы — дерево уходило на
    # академию, вторую ратушу и дома, конюшня встала только в 23:50, конницы 12). При `конюшня_с` конюшня — закладка лестницы
    # (выше домов, ратуш и мельниц), значит бригада §135 ставит людей на дерево под её цену, а прочие закладки ждут.
    if (закладка is None and float(п.get("конюшня_с", 0) or 0) > 0 and gt >= float(п.get("конюшня_с", 0) or 0)
            and ч("stables") < int(п.get("конюшен", 1) or 1) and ч("smiths") >= 1):
        закладка = ("stable", int(ч("stables")) + 1)
        отдано["закладка stable (конюшня_с)"] += 1
    if закладка is None and ч("my_farm") - ч("my_farmused") <= _дом_запас and есть_дер_кам:
        закладка = ("house", int(ч("houses")) + 1)
    elif закладка is None and стр.академия and ч("ba17") >= 1 and ч("academies") < 1 and gt >= getattr(стр, "академия_с", 0):
        закладка = ("academi", 1)
    # ХОЗЯЙСТВО ВШИРЬ (1.11, century_net/2-ban: ИИ ставит вторую ратушу в 15:00, третью к концу, вторую мельницу ~25:00 — крестьян
    # 131 / 178 / 233 против наших 104 / 126 / 147 к 20 / 25 / 30 мин; советы игроков: 2–3 ратуши, крестьяне без остановки, мельница
    # на 80–100 человек). Ключи (0 — как было): `ратуш` N с `ратуш_с` T — ратуши до N, когда хватает на цену из `build_cost`;
    # `мельниц` N при `мельница_пахарей` P (25) — следующая мельница, когда на еде не меньше P × мельниц.
    elif (закладка is None and int(п.get("ратуш", 0) or 0) > ч("centers") and gt >= float(п.get("ратуш_с", 0) or 0)
          and all(ч(r) >= v for r, v in _цр.items())):
        закладка = ("center", int(ч("centers")) + 1)
    elif (закладка is None and int(п.get("мельниц", 0) or 0) > ч("mills") and ч("mills") >= 1
          and ч("on_food") >= float(п.get("мельница_пахарей", 25) or 25) * ч("mills") and all(ч(r) >= v for r, v in _цм.items())):
        закладка = ("mill", int(ч("mills")) + 1)
    # ЕДА ПЕРВОЙ, ПОКА НАЙМ СТОИТ (10.10, §145, третья партия Д живьём): движок не выпускает никого при еде ниже 500,
    # а лестница этого не знала. В Д3 поле созрело в 2:10 при еде 376, и с 2:20 еда получала ОСТАТОК земли: шахта
    # золота 2 заложена в 3:25 (пятеро строителей с еды), 3 — в 4:55, бригада §135а держала по трое на дереве и
    # камне; на еде 5 → 1 → 0, еда 400-480 до 5:00, крестьян 24 и ни одного найма после 5:00 (в Д2 при той же еде
    # 16-20 пахарей пробивали порог доставками — 29 к 5:00), mil.1 (750 еды) не куплена, еда 0 к 8:36, армия 14
    # против его 84 — партия решилась к 5:00. Правило: пока еды меньше `еда_найма` (600; 0 — выкл) и поле созрело,
    # закладываются только мельница и ПЕРВЫЕ шахты железа и золота (остальные ждут еды — найм всё равно стоит), а
    # бригада §135а держится только под первую шахту золота; земля без них достаётся еде сама (`цель_еды` — min
    # доли и земли). Начатая стройка не бросается: закладка декларативна, и без неё блок достраивает (Д3 4:00 —
    # шахта 2 строилась при закладке ba17 и встала в 4:15). Двойник правило не судит: без дохода дерева и камня его
    # шахты 2-3 и так встают после 8:00 (§142). Судья — партия Д живьём.
    # §170н (3): при его конюшне дальние шахты не закладываются — конница режет шахтёров и строителей по дороге
    if (закладка and int(п.get("конюшня_его", 0) or 0) and float(st.get("p1_stable") or 0) >= 1
            and закладка[0] in ("minegold", "mineiron", "minecoal")):
        _рес_ш = закладка[0][4:]
        _дист_ш = float(st.get(f"ore_{_рес_ш}_dist") or 0)
        _ближе = float(п.get("шахты_ближе", 40) or 0)
        if _ближе > 0 and _дист_ш > _ближе:
            отдано[f"§170н его конюшня: {закладка[0]} в {_дист_ш:.0f} от ратуши дальше {_ближе:.0f} — не закладываем"] += 1
            закладка = None
    еда_найма = float(п.get("еда_найма", 600) or 0)
    голод = (еда_найма > 0 and ч("mills") >= 1 and ч("food") < еда_найма
             and float(st.get("food_ready") or 0) > 0)
    if голод and закладка:
        первые = {"mill": True, "mineiron": ч("mines_iron") < 1, "minegold": ч("mines_gold") < 1}
        if not первые.get(закладка[0], False):
            отдано[f"закладка {закладка[0]} ждёт еды {еда_найма:.0f}: еда {ч('food'):.0f}, найм стоит"] += 1
            закладка = None
    if закладка:
        из += [{"cmd": "BUILDERS", "total": _строителей(закладка[0])}, {"cmd": "BUILD", "role": закладка[0], "total": закладка[1]}]
        отдано[f"BUILD {закладка[0]} (переходник)"] += 1
    # ДОСТРОЙКА (18.10, §165, партия Д7, задание игрока «бригада не доходит до участка»). Блок добирает бригаду к начатой
    # стройке (80e997c: до свободных точек участка) ТОЛЬКО в такт, когда к нему приходит BUILD этого типа. Лестница выше
    # даёт одну закладку за такт: в Д7 участок шахты золота 3 стоял с 7:07 по 9:19 с `wip minegold/5/0/0` — пятеро послано
    # в 7:12–7:18 («sent 5 more»), никто не дошёл (его 23 резали крестьян в соседней клетке), а дальше лестница просила
    # `ba17 2` (золота 2500 нет), BUILD minegold не уходил, и блок молчал 2 мин 7 с; в 9:24 лестница вернулась к шахте —
    # 9:44 на участке 5, 10:24 готова (всего 197 с вместо 30–40). Правило: по каждому участку из `wip` (роль/точек/на
    # месте/процент), где на месте меньше min(точек, 5) и процент < 100, — BUILDERS 5 и декларативный BUILD роли с total =
    # построенных + участков (построенные в счётчиках состояния БЕЗ участков — Д7 7:23 `mines_gold 2` при трёх объектах; в
    # блоке `hchave` участок считает — ветка добора, не новая закладка). Своя закладка этой роли уже есть — не дублируем.
    # Двойник: `wip` в нём нет — правило молчит. Судья — Д8: `BUILD <роль> crew: points N, on it M, sent K` в game.log.
    if st.get("wip") and st.get("build_cost"):
        _счёт = {"minegold": "mines_gold", "mineiron": "mines_iron", "minecoal": "mines_coal", "ba17": "ba17", "ba18": "ba18",
                 "academi": "academies", "house": "houses", "mill": "mills", "smith": "smiths", "store": "my_stores",
                 "stable": "stables", "market": "markets", "tower": "towers"}
        _участки = collections.Counter()
        _надо = {}
        for _кусок in str(st.get("wip") or "").split(","):
            _ч2 = _кусок.strip().split("/")
            if len(_ч2) < 3 or not _ч2[0]:
                continue
            try:
                _точек, _на_месте = int(_ч2[1]), int(_ч2[2])
                _проц = int(_ч2[3]) if len(_ч2) > 3 and _ч2[3] != "" else 0
            except ValueError:
                continue
            _участки[_ч2[0]] += 1
            _бр = _строителей(_ч2[0])   # §169б: шахта железа — не больше `железо_людей`
            if _проц < 100 and _на_месте < min(_точек if _точек > 0 else _бр, _бр):
                _надо.setdefault(_ч2[0], (_точек, _на_месте))
        for _роль, (_точек, _на_месте) in _надо.items():
            if any(c["cmd"] == "BUILD" and c.get("role") == _роль for c in из):
                continue
            _total = int(ч(_счёт.get(_роль, ""))) + _участки[_роль]
            из += [{"cmd": "BUILDERS", "total": _строителей(_роль)}, {"cmd": "BUILD", "role": _роль, "total": _total}]
            отдано[f"§165 достройка {_роль}: на участке {_на_месте} из {_точек} — BUILD {_роль} {_total}"] += 1
    try:   # §153: цена ждущей закладки — нужде следующего такта
        стр._закладка_цена = (_цена_здания(st, закладка[0]) or {}) if закладка else None
    except Exception:
        pass
    # ЗАКЛАДКА ЖДЁТ РЕСУРСА, НА КОТОРОМ НИКОГО — ТРОЕ ТУДА (10.10, §135, партия Д живьём): после созревания
    # поля (2:09) ярус 1 снял всех с камня (камень 40), первая шахта золота ждала 100 камня до 5:00 — в В и Г
    # она встала в 2:50-3:00, потому что камень успел дойти до 160 до того же снятия. Нужда §129 (7/6) была
    # заперта порогом еды 1200 до 4:30. Правило: пока хотят шахту (железа или золота) или ждёт закладка
    # лестницы, и дерева/камня меньше цены, а на этом ресурсе НОЛЬ человек — туда `людей_под_закладку`
    # (3), еда уступает столько же (иначе BALANCE food вторым проходом блока отберёт их обратно). 0 — выкл.
    людей = int(п.get("людей_под_закладку", 3) or 0)
    # §142 (10.10): В ДВОЙНИКЕ ПРАВИЛО МОЛЧИТ. Двойник дерево и камень только тратит (рубщиков у него нет), и бригада
    # «держится, пока ресурса меньше цены» держалась вечно: BALANCE wood 3 / stone 3 каждый такт, еда −6, с 2:35 на еде
    # ноль, еда 0 к 5:00, армия 9 за всю партию (хронология_сим после §135а). Признак живой партии — `build_cost`
    # в состоянии (цены зданий отдаёт только мост); селфтесты идут по живым кейсам, в них он есть.
    if людей > 0 and not дерево_первым and st.get("build_cost"):   # при нужде §129 бригаду 7/6 держит она сама
        хотят = []
        if закладка:
            хотят.append(закладка[0])
        if ч("ba17") >= 1 and ч("mines_iron") < 1 and "mineiron" not in хотят and _железо_нужно(п, st):
            хотят.append("mineiron")
        if (ч("mines_gold") < int(п.get("шахт_золота", 2)) and ч("on_gold") >= 5 * ч("mines_gold") - 1
                and резерв_ок and "minegold" not in хотят):
            хотят.append("minegold")
        # §149 (11.10, Д4 2:17 и Д3 2:20 живьём): первая шахта золота уже заложена и ОПЛАЧЕНА (`wip minegold`), камень 60,
        # а бригада держала троих на камне «под шахту» до её готовности (2:17-2:53) — на еде 5-7 из 20, найм стоял.
        # Бригада не под то, что уже строится.
        в_стройке = {_ч_.split("/")[0].strip() for _ч_ in str(st.get("wip") or "").split(",") if _ч_.strip()}
        if в_стройке:
            было, хотят = хотят, [р for р in хотят if р not in в_стройке]
            for р in было:
                if р not in хотят:
                    отдано[f"бригада под {р}: уже строится"] += 1
        if голод:   # §145: при еде ниже `еда_найма` бригада — только под первую шахту золота, остальное еде
            было, хотят = хотят, [р for р in хотят if р == "minegold" and ч("mines_gold") < 1]
            for р in было:
                if р not in хотят:
                    отдано[f"бригада под {р} ждёт еды {еда_найма:.0f}"] += 1
        умолч = {"ba17": {"wood": 500, "stone": 500, "gold": 2500}, "academi": {"wood": 1050, "stone": 1230},
                 "stable": {"wood": 2500, "stone": 100, "gold": 600}}
        # §135а (10.10, вторая партия Д): условие «на ресурсе ноль» МИГАЛО через такт — такт А: трое на камень, еда −3;
        # такт Б: на камне трое, правило молчит, еда просит прежнее, второй проход BALANCE food блока забирает троих
        # обратно; 2:20-6:00 дерево 402 и камень 60 стояли на месте, на еде 7-10 вместо 13-15, еда ниже 500, найм стоял.
        # Теперь бригада ДЕРЖИТСЯ, пока ресурса меньше цены, и еда уступает её каждый такт; снимается, когда ресурс
        # набран или стратегия сама просит на него не меньше.
        держим = set()
        # §157 (14.10, экзамен по хозяйству Д5, `sim/решения/экзамен_д5_хозяйство*.txt`): БРИГАДА С ДЕРЕВА, КОГДА ДЕРЕВО
        # ЛЕЖИТ. Д5 4:00: дерева 950 без строек, камня 80 из 100 под шахту золота, на еде 14 (mil.1 ждёт 750), золото 277
        # тает — бот брал троих с еды. Fable 3/3 (чисто и грязно): «пятерых с дерева на камень, еду не трогать: дерево
        # избыток, еда и золото узкие места». Ключ `бригада_с_дерева` N (5): пока другого ресурса земли не меньше его
        # порога нужды (`дерево_до`/`камень_до`, 600) и цены закладки, бригада под недостающий — с него, числом N (не
        # больше, чем там стоит), еда не уступает; дереву приказом остаток. 0 — как было (трое с еды).
        _сд = int(п.get("бригада_с_дерева", 0) or 0)
        for роль in хотят:
            цена = _цена_здания(st, роль) or умолч.get(роль) or {"wood": 100, "stone": 100}
            for рес in ("wood", "stone"):
                if рес in держим or ч(рес) >= цена.get(рес, 0):
                    continue
                своё = max([int(c.get("total") or 0) for c in из if c["cmd"] == "BALANCE" and c.get("role") == рес] or [0])
                if своё >= людей:
                    continue
                держим.add(рес)
                другой = "stone" if рес == "wood" else "wood"
                _до_др = float(п.get(("дерево" if другой == "wood" else "камень") + "_до", 600) or 600)
                _мин_др = мин_дер if другой == "wood" else мин_кам
                if (_сд > 0 and ч(другой) >= max(_до_др, float(цена.get(другой) or 0)) and ч("on_" + другой) >= 1
                        and not any(c["cmd"] == "BALANCE" and c.get("role") == другой for c in из)):
                    n = min(_сд, int(ч("on_" + другой)) + int(ч("on_" + рес)))
                    if ч("on_" + рес) < n:
                        из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == рес)]
                        из.append({"cmd": "BALANCE", "role": рес, "total": n, "_важно": True})
                    _ост = max(int(_мин_др), int(ч("on_" + другой)) - max(0, n - int(ч("on_" + рес))))
                    if ч("on_" + другой) > _ост:
                        из.append({"cmd": "BALANCE", "role": другой, "total": _ост, "_важно": True})
                    for c in из:                 # еда не уступает, но и не просит сверх земли: земля − бригада − другой
                        if c["cmd"] == "BALANCE" and c.get("role") == "food":
                            c["total"] = max(0, min(int(c.get("total") or 0), земля - n - _ост))
                    отдано[f"BALANCE {рес} {n} с {другой} ({ч(другой):.0f} лежит): закладка {роль} ждёт {рес} (§157)"] += 1
                    continue
                if ч("on_" + рес) < людей:       # команда — только когда людей там меньше; еда уступает всегда
                    из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == рес)]
                    из.append({"cmd": "BALANCE", "role": рес, "total": людей, "_важно": True})
                for c in из:
                    if c["cmd"] == "BALANCE" and c.get("role") == "food":
                        c["total"] = max(0, int(c.get("total") or 0) - людей)
                отдано[f"BALANCE {рес} {людей}: закладка {роль} ждёт {рес}"] += 1
        # §156 (14.10, подсказка игрока «как созрело — сразу сбор еды»): БРИГАДА ПЛЮС ЕДА БОЛЬШЕ ЗЕМЛИ — ХОДИЛИ
        # ТУДА-СЮДА. Д5 2:12-4:43 и Д4 2:12-2:53 живьём: еда 13 − 3 = 10, камень 3, на дереве 5 с дебюта, строителей 5 —
        # 23 на 20 крестьян; дерево никто не просил, и блок брал троих под камень с еды, а в следующий такт под еду —
        # с камня: трое два-три минуты ходили между полем и карьером, на еде 7 вместо 10. Пока бригада держит ресурс,
        # остальной земле (дереву/камню без бригады) — не больше остатка: земля − еда − бригада.
        if держим:
            _еда = max([int(c.get("total") or 0) for c in из if c["cmd"] == "BALANCE" and c.get("role") == "food"]
                       or [min(int(ч("on_food")), max(0, цель_еды - людей * len(держим)))])
            свободно = max(0, земля - _еда - людей * len(держим))
            for рес2, мин2 in (("wood", мин_дер), ("stone", мин_кам)):
                if рес2 in держим or any(c["cmd"] == "BALANCE" and c.get("role") == рес2 for c in из):
                    continue
                _цель2 = max(int(мин2), свободно)
                if ч("on_" + рес2) > _цель2:
                    из.append({"cmd": "BALANCE", "role": рес2, "total": _цель2, "_важно": True})
                    отдано[f"BALANCE {рес2} {_цель2}: земля {земля} − еда {_еда} − бригада {людей * len(держим)} (§156)"] += 1
    # 20.10: ключ `железо_людей` (см. tier1 и §169б выше). Было `on_iron < _жл`, потому что блок из шахты не выводил.
    # 21.10, Д10 (§169е): блок выводит с §169д, и это условие стало последней дырой — шахту железа заложили ТРОЕ по ключу
    # (`BUILD euriro ... by 3 workers`), но `on_iron` стоял 5 всю партию, и ни одного `BALANCE iron` не ушло: просить было
    # «не нужно», выводить — нечего. Теперь как у золота, `!=`: число в шахте равно ключу, лишние выходят.
    if ч("mines_iron") >= 1 and int(ч("on_iron")) != int(_жл):
        из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == "iron")]
        из.append({"cmd": "BALANCE", "role": "iron", "total": _жл, "_важно": True})
    шахт = float(st.get("mines_gold") or 0)
    # §153 (13.10, партия Д5): ЗОЛОТО ЛЕЖИТ — ШАХТЁРЫ ЕДЕ. С 9:00 золото росло на 1300 в минуту при нуле трат (15 на
    # золоте, 8378 к 15:00), а ступени пик стоят ЕДЫ (1.3 — 3100, 1.4 — 6700, 2.4 — 9305) и ждали её по две минуты.
    # Ключ `золото_до` (3000): пока золота не меньше, на золоте держим `золото_мин` (5), снятых — еде (еда поднимается
    # на столько же). 0 — как было (5 на шахту всегда).
    _зд = float(п.get("золото_до", 0) or 0)
    # §166б (18.10, Д7): ЗОЛОТО ЛЕЖИТ ПРИ НУЖДЕ — ШАХТЁРЫ КАМНЮ/ДЕРЕВУ, НЕ ЕДЕ. В Д7 земли было 13–15 (30–38 крестьян, 10–15
    # в шахтах, 5–10 на стройке), на еде уже 2–5 — бригаду камня расти неоткуда, а золото лежало 1600–4800 (10–15 на золоте).
    # Ключ `золото_до_нужды` G (1500): пока нужда по плану включена и по ресурсу недостача до плана, а золота не меньше
    # max(G, цена ждущей казармы по золоту) — на золоте `золото_мин` (5), снятые идут на недостающий ресурс (камень первым).
    # Правило выше §153 (≥ `золото_до` — еде): при нужде камень важнее еды, которая и так лежит. 0 — выкл.
    _здн = float(п.get("золото_до_нужды", 0) or 0)
    _нужда_рес = None
    if _здн > 0 and _нужда_макс > 0 and getattr(стр, "_нужда_вкл", False):
        _пц = getattr(стр, "_переброс_цель", None)
        for _рес in ([_пц] if _пц else []) + ["stone", "wood"]:
            if _план.get(_рес, 0) > ч(_рес):
                _нужда_рес = _рес
                break
    _порог_з = max(_здн, float(цена_каз.get("gold") or 0) if казарма_ждёт else 0)
    # §170м (г) (25.10, Д15, винда: «третий раз порог без цены покупки»): ПОРОГ ЗОЛОТА — ЦЕНА ТОГО, ЧТО ПРОСЯТ СЕЙЧАС, С ЗАПАСОМ.
    # В Д15 6:27 золото 2501 ≥ цены казармы 2500 — §166б снял 10 шахтёров из 15 на дерево за 15 с до покупки; после неё (6:45,
    # золото 212) блок наполняет шахты только свободными, и на золоте стояло 5 до 7:12. Ключ `золото_по_цене` 1: порог = цена
    # ждущей казармы или просимой в этом такте прокачки (золото из `upg_shown`) плюс `золото_запас` (300), не ниже ключа; и
    # ниже порога при недоборе в шахтах бригада отдаёт недостающих (блок добирает шахты из свободных). 0 — как было.
    _зпц = int(п.get("золото_по_цене", 0) or 0)
    if _зпц:
        _цена_ж = float(цена_каз.get("gold") or 0) if казарма_ждёт else 0.0
        for c in из:
            if c["cmd"] == "UPGRADE" and c.get("role"):
                _цена_ж = max(_цена_ж, float(_цена_прокачки(st, str(c["role"])).get("g") or 0))
        if _цена_ж > 0:
            _порог_з = max(_здн, _цена_ж + float(п.get("золото_запас", 300) or 0))
    # §170ц (29.10, серии сток-2/held): `_снято` считалось от ЧИСЛА ШАХТ, и пока золото лежало, правило каждый такт снова
    # прибавляло к цели камня «выпущенных», которые давно вышли: stone 5 → 20 → 36 за два такта (x1 сток-2: 33 на камне при
    # нужде 9, held x2: 29). Ключ `золото_лежит_по_факту` 1: выпускаются только те, кто СЕЙЧАС на золоте сверх минимума.
    _по_факту = int(float(п.get("золото_лежит_по_факту", 0) or 0))
    if шахт >= 1 and _нужда_рес and ч("gold") >= _порог_з:
        _зм = int(п.get("золото_мин", 5) or 5)
        _снято = max(0, int(5 * шахт) - _зм)
        if _по_факту:
            _снято = max(0, int(ч("on_gold")) - _зм)
        из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == "gold")]
        if int(ч("on_gold")) != _зм:
            из.append({"cmd": "BALANCE", "role": "gold", "total": _зм, "_важно": True})
        # §168а (20.10, Д8): снятые с золота — ресурсу не сверх `нужда_доля` земли (земля + снятые), остальное еде; в Д8
        # «stone 25» при земле 23 оставлял еду пустой
        _к_рес, _к_еде = _снято, 0
        if _снято > 0:
            _доля_з = float(п.get("нужда_доля", 0.75) or 0)
            _бриг_сейчас = sum(int(c.get("total") or 0) for c in из if c["cmd"] == "BALANCE" and c.get("role") in ("wood", "stone"))
            _бриг_сейчас = max(_бриг_сейчас, int(ч("on_wood") + ч("on_stone")))
            if _доля_з > 0:
                _к_рес = max(0, min(_снято, int((земля + _снято) * _доля_з) - _бриг_сейчас))
                _к_еде = _снято - _к_рес
        if _к_рес > 0:
            _к = next((c for c in из if c["cmd"] == "BALANCE" and c.get("role") == _нужда_рес), None)
            _цель = max(int(ч("on_" + _нужда_рес)), int((_к or {}).get("total") or 0)) + _к_рес
            if _к is None:
                из.append({"cmd": "BALANCE", "role": _нужда_рес, "total": _цель, "_важно": True})
            else:
                _к["total"], _к["_важно"] = max(int(_к.get("total") or 0), _цель), True
        _рп = (getattr(стр, "_еда_лежит_куда", None) or "wood") if getattr(стр, "_еда_лежит_вкл", False) else "food"   # §170с: при потолке еды — не на еду
        if _к_еде > 0 and ч("mills") >= 1:
            _еда = next((c for c in из if c["cmd"] == "BALANCE" and c.get("role") == _рп), None)
            _цель_е = max(int(ч("on_" + _рп)), int((_еда or {}).get("total") or 0)) + _к_еде
            if _еда is None:
                из.append({"cmd": "BALANCE", "role": _рп, "total": _цель_е, "_важно": True})
            else:
                _еда["total"], _еда["_важно"] = max(int(_еда.get("total") or 0), _цель_е), True
        отдано[f"§166 золото лежит (≥ {_порог_з:.0f}) при нужде {_нужда_рес}: на золоте {_зм}, {_нужда_рес} +{_к_рес}" + (f", {'еде' if _рп == 'food' else _рп} +{_к_еде}" if _к_еде else "") + (" (§170ц по факту)" if _по_факту else "")] += 1
    elif шахт >= 1 and _зд > 0 and ч("gold") >= max(_зд, _порог_з if _зпц else 0):
        _зм = int(п.get("золото_мин", 5) or 5)
        _снято = max(0, int(5 * шахт) - _зм)
        if _по_факту:
            _снято = max(0, int(ч("on_gold")) - _зм)
        из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == "gold")]
        if int(ч("on_gold")) != _зм:
            из.append({"cmd": "BALANCE", "role": "gold", "total": _зм, "_важно": True})
        _рп = (getattr(стр, "_еда_лежит_куда", None) or "wood") if getattr(стр, "_еда_лежит_вкл", False) else "food"   # §170с: при потолке еды — не на еду
        if _снято > 0 and ч("mills") >= 1:
            _еда = next((c for c in из if c["cmd"] == "BALANCE" and c.get("role") == _рп), None)
            _цель = max(int(ч("on_" + _рп)), int((_еда or {}).get("total") or 0)) + _снято
            if _еда is None:
                из.append({"cmd": "BALANCE", "role": _рп, "total": _цель, "_важно": True})
            else:
                _еда["total"], _еда["_важно"] = max(int(_еда.get("total") or 0), _цель), True
        отдано[f"золото лежит (≥ {_зд:.0f}): на золоте {_зм}, {'еде' if _рп == 'food' else _рп} +{_снято}"] += 1
    elif шахт >= 1 and float(st.get("on_gold") or 0) < 5 * шахт and getattr(стр, "_щ_до", 0.0) > gt:
        # §170щ (29.10, Д26) выпустил шахтёров сам — минуту не возвращаем, иначе качели: щ −3 → м +3 → щ −3 (Д26 4:42–6:04, золото 10→7→10)
        отдано[f"§170м возврат шахтёров отложен: §170щ выпустил их до {getattr(стр, '_щ_до', 0.0):.0f} с"] += 1
    elif шахт >= 1 and float(st.get("on_gold") or 0) < 5 * шахт:
        из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == "gold")]
        из.append({"cmd": "BALANCE", "role": "gold", "total": int(5 * шахт), "_важно": True})
        if _зпц and дерево_первым:
            # §170м (г): шахтёры возвращаются первыми — бригада отдаёт недостающих, сперва ресурс не-цели переброса
            _нехват = int(5 * шахт - float(st.get("on_gold") or 0))
            _мин_б = int(п.get("переброс_мин", 3) or 0)
            _пц_г = getattr(стр, "_переброс_цель", None)
            _отдано_б = []
            for _р in ([r for r in ("wood", "stone") if r != _пц_г] + ([_пц_г] if _пц_г in ("wood", "stone") else [])):
                if _нехват <= 0:
                    break
                _к = next((c for c in из if c["cmd"] == "BALANCE" and c.get("role") == _р), None)
                _сейчас = int(ч("on_" + _р))
                _цель_р = int(_к.get("total") or 0) if _к else _сейчас
                _срез = min(_нехват, max(0, min(_цель_р, _сейчас) - _мин_б))
                if _срез > 0:
                    if _к is None:
                        из.append({"cmd": "BALANCE", "role": _р, "total": _сейчас - _срез, "_важно": True})
                    else:
                        _к["total"], _к["_важно"] = min(_цель_р, _сейчас) - _срез, True
                    _нехват -= _срез
                    _отдано_б.append(f"{_р} −{_срез}")
            if _отдано_б:
                # 28.10 (Д18): в этой ветви золото ни с чем не сравнивается — прежний текст «золото 3201 < 1500» врал каждый такт
                отдано[f"§170м возврат шахтёров: в шахтах не хватает {int(5 * шахт - float(st.get('on_gold') or 0))} (золото {ч('gold'):.0f}), бригада {', '.join(_отдано_б)}"] += 1
    # §170щ (29.10, слово игрока «бот проиграл человеку по скорости постройки второй казармы»): ЗАКЛАДКА ПО СРОКАМ. В шести живых
    # партиях Д17–Д22 игрок ставил вторую казарму в 5:40–6:55, бот — в 7:19–9:07. Д22: золото 2500 у бота в 6:05 — одновременно с
    # игроком, но дерево ≥ 500 только в 7:36 и камень в 7:26: с 3:00 до 6:40 на дереве 0–4, на камне 0–6, в шахтах 10–25, а золото
    # переросло до 4079 (лишние 1500 = две минуты двадцати шахтёров), пока закладка ждала дерева. Игрок наоборот: камень 1300 к 2:30,
    # дерево 506 к 3:01, потом золото. Правило (ключ `закладка_по_срокам` 1; 0 — как было): пока казарма ждёт и шахта золота есть,
    # считаются сроки до её цены по темпам на человека (балансовые медианы `sim/темпы.json`: дерево 1,03, камень 1,22, золото 1,66 в
    # секунду); если золото поспеет раньше дерева или камня — шахтёры сверх `золото_мин` (5) идут на отстающий ресурс столько, чтобы
    # сроки сравнялись (BALANCE gold ниже + BALANCE wood/stone выше тем же тактом; §170п принимает выпущенных за доноров — §170ъ).
    # Обратная сторона (золото отстаёт) не трогается: шахты и так полны, лишних мест нет.
    # 29.10 вечер (Д26): прежний счёт брал СРОК ЗОЛОТА как данность и снимал шахтёров под него — а золото было отстающим
    # (1054/2500 за 109 с против дерева за 85 с): три шахтёра ушли на камень, золото стало поспевать за 136 с, §170м вернул их,
    # и так 4:42–6:04 (золото 10→7→10→6), шахты недобирали 3 человек полторы минуты, строка пряталась за потолком правил.
    # Теперь МИНИМАКС: перебираем, сколько шахтёров сверх `золото_мин` отдать (по одному — тому из дерева/камня, чей срок
    # дольше), и берём число, при котором ХУДШИЙ из трёх сроков наименьший; выигрыш меньше `срок_выигрыш` (5 с) не
    # трогаем. Золото отстаёт — шахтёры не трогаются вовсе (срок золота после снятия только растёт).
    # smoke5999 (29.10 ночь): при 10/0/0 правило сняло четверых «на дерево и камень», хотя бригада §166/§167 тем же тактом слала туда 13 —
    # люди ещё шли, а шахты полторы минуты стояли на 6; и повторялось, пока первые не дошли. Теперь считаем дерево/камень по ЦЕЛИ python
    # этого такта (не меньше стоящих), и не чаще раза в 60 с (`_щ_до`).
    if (int(float(п.get("закладка_по_срокам", 0) or 0)) and казарма_ждёт and ч("mines_gold") >= 1 and ч("on_gold") > 5
            and not (getattr(стр, "_щ_до", 0.0) > gt)):
        _тр = {"wood": 1.03, "stone": 1.22, "gold": 1.66}
        _нед = {r: max(0.0, float(цена_каз.get(r) or 0) - ч(r)) for r in ("wood", "stone", "gold")}
        _на = {r: max(0, int(ч("on_" + r))) for r in ("wood", "stone", "gold")}
        for _r in ("wood", "stone"):
            _цп = next((c for c in из if c.get("cmd") == "BALANCE" and c.get("role") == _r), None)
            if _цп is not None and str(_цп.get("total") or "").lstrip("-").isdigit():
                _на[_r] = max(_на[_r], int(_цп["total"]))
        _пол_ср = 60.0                                            # меньше минуты не различаем: доставка идёт партиями по 20–40 с

        def _срок_р(r, n):
            if _нед[r] <= 0:
                return 0.0
            if n <= 0:
                return 1e9
            return max(_пол_ср, _нед[r] / (_тр[r] * n))

        _t_з = _срок_р("gold", _на["gold"])
        _своб = _на["gold"] - int(п.get("золото_мин", 5) or 5)
        _дер, _кам = _на["wood"], _на["stone"]
        _база = max(_t_з, _срок_р("wood", _дер), _срок_р("stone", _кам))
        _лучш, _k, _кд, _кк = _база, 0, 0, 0
        for _кандидат in range(1, max(0, _своб) + 1):
            if _срок_р("wood", _дер) >= _срок_р("stone", _кам):
                _дер += 1
            else:
                _кам += 1
            _м = max(_срок_р("gold", _на["gold"] - _кандидат), _срок_р("wood", _дер), _срок_р("stone", _кам))
            if _м < _лучш - 1e-9:
                _лучш, _k, _кд, _кк = _м, _кандидат, _дер - _на["wood"], _кам - _на["stone"]
        _выигрыш = float(п.get("срок_выигрыш", 5) or 5)
        if _k > 0 and _база - _лучш >= _выигрыш and _лучш < 1e9:
            из = [c for c in из if not (c["cmd"] == "BALANCE" and c.get("role") == "gold")]
            из.append({"cmd": "BALANCE", "role": "gold", "total": _на["gold"] - _k, "_важно": True, "_по_срокам": True})
            for _r, _д in (("wood", _кд), ("stone", _кк)):
                if _д <= 0:
                    continue
                _ц = next((c for c in из if c["cmd"] == "BALANCE" and c.get("role") == _r), None)
                _цель = max(int(_на[_r]), int((_ц or {}).get("total") or 0)) + _д
                if _ц is None:
                    из.append({"cmd": "BALANCE", "role": _r, "total": _цель, "_важно": True, "_по_срокам": True})
                else:
                    _ц["total"], _ц["_важно"], _ц["_по_срокам"] = _цель, True, True
            стр._щ_до = gt + 60.0
            отдано[f"§170щ закладка по срокам: сроки золото {_t_з:.0f} с, дерево {_срок_р('wood', _на['wood']):.0f} с, камень "
                   f"{_срок_р('stone', _на['stone']):.0f} с при {_на['gold']}/{_на['wood']}/{_на['stone']} — из шахт {_k}: "
                   f"дерево +{_кд}, камень +{_кк}, худший срок {_база:.0f} → {_лучш:.0f} с"] += 1
    # §170я (б): прокачки за дерево/камень ждут оплаты казармы (bla.1 — 400 дерева, aca.1 — 200, aca.4 — 1000; bar.*/mil.* — еда и золото)
    if _каз_близко:
        _отлож = [c for c in из if c.get("cmd") == "UPGRADE" and str(c.get("role") or "").split(".")[0] in ("bla", "aca", "tow", "cen")]
        if _отлож:
            из = [c for c in из if c not in _отлож]
            отдано[f"§170я казарма первой в оплате: отложены прокачки {', '.join(str(c.get('role')) for c in _отлож)}"] += 1
    # §170я (г) (3.11, слово игрока «делай»; бот против бота, зеркало bot2_aca_mirror): КОПИТЬ НА КАЗАРМУ И ЗОЛОТЫЕ ПРОКАЧКИ ТОЖЕ.
    # Третья казарма стоит 12 500 золота; (б) держит только прокачки за дерево/камень и лишь за 400 до цены. В копиях 1 и 2
    # ранней академии золото с 13:58 по 19:50 уходило на шесть ступеней пики (bar.*) и aca.3 — держалось на 8–10 тыс., порог
    # 400 не наступал, казарма встала в 22:12 / 21:48; в копии 3 цепочка пики запоздала (1.3 в 12:15), золото дошло до цены
    # и казарма встала в 14:50 — армия к 30:00 846 против 296 / 375. Ключ `казарма_копить` D (0 — как было): пока ждёт казарма
    # номер `казарма_копить_с`+1 и выше (по умолчанию третья) и золота уже не меньше D × её цены — откладываются ВСЕ прокачки.
    _копить = float(п.get("казарма_копить", 0) or 0)
    if (_копить > 0 and казарма_ждёт and ч("ba17") >= int(float(п.get("казарма_копить_с", 2) or 2))
            and ч("gold") >= _копить * float(цена_каз.get("gold", 2500))):
        _отлож = [c for c in из if c.get("cmd") == "UPGRADE" and not c.get("_по_врагу")]   # ступени по врагу (4.11) копилка не держит
        # 4.11 (218), живая Польша против Польши: копилка держала 2916 золота с 7:21, пика бота 1+1 против 3+3 у игрока
        # (удар 6 против 17) — размен 7:1. Ключ `копить_кроме_пики` 1 (0 — как было): ступени пики (bar.pikeman*) не копятся.
        if int(float(п.get("копить_кроме_пики", 0) or 0)):
            _отлож = [c for c in _отлож if not str(c.get("role") or "").startswith("bar.pikeman")]
        if _отлож:
            из = [c for c in из if c not in _отлож]
            отдано[f"§170я копим на казарму {int(ч('ba17')) + 1}: золота {ч('gold'):.0f}/{float(цена_каз.get('gold', 2500)):.0f}, "
                   f"отложены прокачки {', '.join(str(c.get('role')) for c in _отлож)}"] += 1
            отдано["копим на казарму: прокачки отложены"] += 1
    # §170я (в) (29.10, разность прокачек Д25–Д27 с игроком): ПУЛИ ТОЛЬКО ПРИ СТРЕЛКАХ. Бот брал aca.13 (+10 % урона пули, 4000 золота)
    # в 11:56–12:53 при 14–17 мушкетёрах на 140–170 пик; игрок академию почти не трогал и к концу имел bar.pikeman 1.4–1.5 и 2.4, бот
    # нет. Ключ `пули_при_стрелках` (доля, 0 — как было): aca.12–aca.15 не покупаются, пока стрелков меньше этой доли бойцов.
    _доля_пуль = float(п.get("пули_при_стрелках", 0) or 0)
    if _доля_пуль > 0:
        _бойц = ч("mil_inf") + ч("mil_shooters") + ч("mil_cav")
        if _бойц > 0 and ч("mil_shooters") / _бойц < _доля_пуль:
            _пули = [c for c in из if c.get("cmd") == "UPGRADE" and str(c.get("role") or "") in ("aca.12", "aca.13", "aca.14", "aca.15")]
            if _пули:
                из = [c for c in из if c not in _пули]
                отдано[f"§170я пули при стрелках: {', '.join(str(c.get('role')) for c in _пули)} ждут — стрелков {ч('mil_shooters'):.0f} из {_бойц:.0f} (< {_доля_пуль:.0%})"] += 1
    # КРЕСТЬЯНЕ ЖДУТ mil.1 (14.10, §147б, ключ `пауза_крестьян`; блок `TRAIN <роль> 0` в игре с a62ec11, verified
    # 691d570, python его не звал). mil.1 (+140 % к еде, 750 еды и 250 золота) в Д4 куплена в 6:32 вместо ~4:00, в Д5 в
    # 4:28: бесконечный заказ крестьян берёт 100 еды и 50 золота каждые 12 с (8,3 еды/с), и при 8-14 пахарях еда ходила
    # 377-650 с 3:24 до 6:27 (Д4) — амбар не доходил до 750, хотя стратегия просила mil.1 каждый такт с 3:59. Игрок берёт
    # mil.1 к 3:00-5:30 — главный рычаг еды (2.10: 30/30 против 3/30). Правило: пока стратегия просит mil.1, она не
    # куплена и не исследуется, мельница есть, пахарей ≥ `пауза_пахарей_от` (8) и еды < 750 — `TRAIN peasant 0` (блок
    # снимает бесконечный заказ, в game.log `infinite order cancelled`; повтор, пока `peaeng` в `train_now`, раз в 15 с),
    # а заказ яруса 1 `TRAIN peasant -1` не пропускается. Пауза кончается, когда mil.1 в `upg_doing`/`upg_done`, или
    # через `пауза_не_дольше` (120 с: золота нет, игра не берёт) — тогда заказ возвращается сразу, новая пауза не раньше
    # чем через столько же. Ключ 1 — пауза только когда покупку пропустит пол еды моста (`ПОЛ_ЕДЫ`: до 5:00 при бойцах
    # < 20 mil.1 берётся лишь при еде ≥ пол + 750), иначе пауза копила бы еду, которую не дадут потратить; 2 — без
    # оглядки на пол. Мост при паузе свой `TRAIN peasant` (--auto-train) не ставит. Двойник: `sim.py` снимает заказ по
    # `TRAIN … 0`; выбор 1/2 — `sim/решения/д4_mil1.md`.
    _пк = int(float(п.get("пауза_крестьян", 0) or 0))
    _пауза = getattr(стр, "_крестьяне_пауза", None)
    if _пк >= 1 or _пауза is not None:
        _взято = set(str(st.get("upg_done") or "").split(","))
        _идёт = set(str(st.get("upg_doing") or "").split(","))
        _куплена = "mil.1" in _взято or "mil.1" in _идёт
        _просят = any(c["cmd"] == "UPGRADE" and c.get("role") == "mil.1" for c in из)
        _очередь = str(st.get("train_now") or "")
        _бойцов = ч("mil_inf") + ч("mil_shooters") + ч("mil_cav")
        _пол_мешает = ПОЛ_ЕДЫ > 0 and gt <= 300 and _бойцов < 20 and ч("food") < ПОЛ_ЕДЫ + 750
        _не_дольше = float(п.get("пауза_не_дольше", 120) or 120)
        _пахарей_от = float(п.get("пауза_пахарей_от", 8) or 0)
        _надо = (_пк >= 1 and _просят and not _куплена and ч("mills") >= 1 and ч("food") < 750
                 and ч("on_food") >= _пахарей_от and (_пк >= 2 or not _пол_мешает))
        _конец = None
        if _пауза is not None:
            if _куплена or not _просят:
                _конец = "mil.1 куплена" if _куплена else "mil.1 не просят"
            elif gt - _пауза["с"] > _не_дольше:
                _конец = f"дольше {_не_дольше:.0f} с"
            elif _пк < 1 or ч("mills") < 1:
                _конец = "ключ снят" if _пк < 1 else "мельницы нет"
        if _пауза is not None and _конец:
            стр._крестьяне_пауза, стр._пауза_снята_t = None, gt
            _пауза = None
            отдано[f"§147б крестьяне снова ({_конец})"] += 1
            if "pea" not in _очередь and not any(c["cmd"] == "TRAIN" and c.get("role") == "peasant" for c in из):
                из.append({"cmd": "TRAIN", "role": "peasant", "total": -1, "_важно": True})
        elif _пауза is None and _надо and gt - getattr(стр, "_пауза_снята_t", -1e9) >= _не_дольше:
            стр._крестьяне_пауза = _пауза = {"с": gt, "приказ_t": -1e9}
            отдано[f"§147б пауза крестьян под mil.1: еда {ч('food'):.0f} < 750, пахарей {int(ч('on_food'))}, бойцов {int(_бойцов)}"] += 1
        if _пауза is not None:
            _сняли = len(из)
            из = [c for c in из if not (c["cmd"] == "TRAIN" and c.get("role") == "peasant" and int(c.get("total") or 0) != 0)]
            if _сняли > len(из):
                пропущено["TRAIN peasant -1 (§147б: ждём mil.1)"] += _сняли - len(из)
            if "pea" in _очередь and gt - _пауза["приказ_t"] >= 15:
                из.append({"cmd": "TRAIN", "role": "peasant", "total": 0, "_важно": True})
                _пауза["приказ_t"] = gt
                отдано["TRAIN peasant 0 (§147б: крестьяне ждут mil.1)"] += 1
    # ПОТОЛОК КОМАНД ЗА ТАКТ — 12 (решение игрока 3.10). Порядок всё равно нужен:
    # волна и прокачки — вперёд, затем стройка (BUILDERS сразу перед своим BUILD),
    # найм, люди; повтор BALANCE по ресурсу — последний.
    #
    # Семь стояло как «мост читает не больше семи», и это ОКАЗАЛОСЬ НЕВЕРНО: предела в
    # семь нет ни в python (`coss3_bridge.send` пишет `count` и столько пар, сколько
    # дали), ни в блоке (`block_hcmd.inc:84,91` — `for hcn := 0 to hccount-1`). Семь
    # живёт только в тексте промпта для МОДЕЛИ (`llm_policy.py:346`), а стратегия
    # моделью не идёт. Чего семь стоило, измерено контейнером 3.10: после того как
    # встала академия (749 с), стратегия просит по семь `aca.*` за такт, вес UPGRADE
    # равен 1, и в окно не проходило НИЧЕГО — ни еды, ни найма, ни стройки в 89 тактах
    # подряд (срезано 1032 команды), а между 7:00 и 12:30 еда доходила в 8 тактах из 64.
    пары, прочее = [], []
    for i, c in enumerate(из):
        if c["cmd"] == "BUILD":
            пред = из[i - 1] if i and из[i - 1]["cmd"] == "BUILDERS" else None
            пары.append([пред, c] if пред else [c])
        elif c["cmd"] != "BUILDERS":
            прочее.append(c)
    # §170б: MOVE и FACE — приказы движения, как ATTACK/RETREAT: без веса они шли последними и первыми попадали под потолок
    вес = {"ATTACK": 0, "RETREAT": 0, "STAGE": 0, "ENGAGE": 0, "MOVE": 0, "FACE": 0, "UPGRADE": 1, "FORMATION": 1, "SEED": 3, "TRAIN": 4, "BALANCE": 5}
    балансы = {}
    for c in прочее:
        if c["cmd"] == "BALANCE":
            балансы[c.get("role")] = c
    if getattr(стр, "_пол_строго", False) and "food" in балансы:
        # §169в: еда — ПОСЛЕДНИМ наземным приказом файла: блок исполняет приказы по порядку и вторым проходом берёт у кого
        # попало; в такт переброса дерево/камень отнимут у еды, и еда последней заберёт своё обратно в том же такте
        балансы["food"] = балансы.pop("food")
    прочее = [c for c in прочее if c["cmd"] != "BALANCE"] + list(балансы.values())
    прочее.sort(key=lambda c: вес.get(c["cmd"], 6))
    важные = [c for c in прочее if c.get("_важно")]
    прочее = [c for c in прочее if not c.get("_важно")]
    for c in важные:
        c.pop("_важно", None)
    # еда и золото — сразу после волны и прокачек, раньше строек: их не срезает потолок
    из = [c for c in прочее if вес.get(c["cmd"], 6) <= 1] + важные + [x for пара in пары for x in пара] + \
        [c for c in прочее if вес.get(c["cmd"], 6) > 1]
    if getattr(стр, "_пол_строго", False):
        # §169в: еда — после последнего наземного приказа (дерево/камень без `_важно` стоят ниже важных)
        _е = [i for i, c in enumerate(из) if c["cmd"] == "BALANCE" and c.get("role") == "food"]
        _з = [i for i, c in enumerate(из) if c["cmd"] == "BALANCE" and c.get("role") in ("wood", "stone")]
        if _е and _з and _е[-1] < _з[-1]:
            _еда = из.pop(_е[-1])
            из.insert(max(i for i, c in enumerate(из) if c["cmd"] == "BALANCE" and c.get("role") in ("wood", "stone")) + 1, _еда)
    # §170п: одно перемещение за такт, срок, мёртвая зона — после всех правил и упорядочения, до потолка
    из = _переброс(из, st, п, стр, отдано)
    # §170яя (29.10 ночь, smoke5999/Д27, мера винды «дрожание целей»): ГИСТЕРЕЗИС ЦЕЛЕЙ. Дерево меняло цель в 10–11 % тактов на ±1
    # (§169в «бюджет без снятия» режет по видимым людям, а они меняются каждый такт: 3 → 4 → 5 → 4). Ключ `цель_гистерезис` 1: цель по
    # дереву/камню/золоту/еде, отличающаяся от последней ПОСЛАННОЙ на 1 и моложе 30 с, не шлётся (блок держит прежнюю); приказы
    # `_по_срокам` и понижения ниже стоящих проходят всегда. 0 — как было.
    if int(п.get("цель_гистерезис", 0) or 0):
        _посл = getattr(стр, "_посл_цель", None)
        if _посл is None:
            _посл = стр._посл_цель = {}
        _ост = []
        for c in из:
            if c.get("cmd") == "BALANCE" and c.get("role") in ("wood", "stone", "gold", "food") and not c.get("_по_срокам"):
                try:
                    _ц = int(c.get("total"))
                except (TypeError, ValueError):
                    _ост.append(c); continue
                _п = _посл.get(c["role"])
                _стоит = int(float(st.get("on_" + c["role"]) or 0))
                if _п is not None and abs(_ц - _п[0]) == 1 and gt - _п[1] < 30 and _ц >= _стоит:
                    отдано[f"§170яя гистерезис: {c['role']} {_п[0]}→{_ц} моложе 30 с — держим {_п[0]}"] += 1
                    continue
                _посл[c["role"]] = (_ц, gt)
            _ост.append(c)
        из = _ост
    if len(из) > ПОТОЛОК_КОМАНД:
        пропущено[f"сверх {ПОТОЛОК_КОМАНД} команд"] += len(из) - ПОТОЛОК_КОМАНД
        из = из[:ПОТОЛОК_КОМАНД]
    return из
